def _resolve_local_apply_waiting_prerequisite_delay_seconds() -> int:
    """Resolve the bounded fallback delay for waiting_prerequisite items.

    Defaults to 8 s. Honors the `SOURCING_LOCAL_APPLY_WAITING_PREREQUISITE_DELAY_SECONDS`
    env override and hard-caps the result at 30 s so a misconfiguration cannot
    extend the safety-net into a 90 s polling regression.
    """

    raw = str(os.getenv("SOURCING_LOCAL_APPLY_WAITING_PREREQUISITE_DELAY_SECONDS") or "").strip()
    if not raw:
        return _LOCAL_APPLY_CLOSURE_WAITING_PREREQUISITE_DEFAULT_DELAY_SECONDS
    try:
        value = int(raw)
    except (TypeError, ValueError):
        return _LOCAL_APPLY_CLOSURE_WAITING_PREREQUISITE_DEFAULT_DELAY_SECONDS
    if value < 1:
        return 1
    if value > _LOCAL_APPLY_CLOSURE_WAITING_PREREQUISITE_MAX_DELAY_SECONDS:
        return _LOCAL_APPLY_CLOSURE_WAITING_PREREQUISITE_MAX_DELAY_SECONDS
    return value


def _projection_facet_layering_item_lease_seconds(*, phase_budget_ms: int) -> int:
    configured = _env_int("PROJECTION_FACET_LAYERING_ITEM_LEASE_SECONDS", 0)
    if configured > 0:
        return max(1, configured)
    budget_seconds = max(1, math.ceil(max(0, int(phase_budget_ms or 0)) / 1000))
    return min(
        _PROJECTION_FACET_LAYERING_MAX_LEASE_SECONDS,
        max(_PROJECTION_FACET_LAYERING_MIN_LEASE_SECONDS, budget_seconds * 3 + 15),
    )


