    @staticmethod
    def _legacy_materialization_ref_for_command_payload(
        *,
        item_payload: dict[str, Any],
        item_kind: str,
        source: str = "",
    ) -> dict[str, Any]:
        """Return a legacy item ref only for historical/migration-adapter rows.

        New normal-path W6 commands are self-contained in `workflow_commands`.
        A legacy ref means the command owner may claim/read
        `job_materialization_items` as migration input; absence of this ref
        means the owner must execute from command payload alone.
        """

        payload = dict(item_payload or {})
        metadata = dict(payload.get("metadata") or {})
        normalized_source = str(source or payload.get("source") or "").strip()
        legacy_ref_required = (
            normalized_source == "legacy_job_materialization_adapter"
            or bool(metadata.get("migration_adapter"))
            or bool(metadata.get("legacy_materialization_write_contract"))
        )
        item_id = str(payload.get("item_id") or "").strip()
        if not legacy_ref_required or not item_id:
            return {}
        return {
            "table": "job_materialization_items",
            "item_id": item_id,
            "item_kind": str(payload.get("item_kind") or item_kind or "").strip(),
            "migration_adapter": True,
            "retirement_phase": "Phase W6",
        }

    @staticmethod
    def _workflow_command_payload_uses_legacy_materialization_item(payload: dict[str, Any]) -> bool:
        command_payload = dict(payload or {})
        legacy_ref = dict(command_payload.get("legacy_materialization_item") or {})
        return (
            str(legacy_ref.get("table") or "").strip() == "job_materialization_items"
            and bool(str(legacy_ref.get("item_id") or "").strip())
        )

    @staticmethod
    def _workflow_command_payload_with_optional_legacy_ref(
        payload: dict[str, Any],
        *,
        item_payload: dict[str, Any],
        item_kind: str,
        source: str = "",
    ) -> dict[str, Any]:
        command_payload = dict(payload or {})
        legacy_ref = SourcingOrchestrator._legacy_materialization_ref_for_command_payload(
            item_payload=dict(item_payload or {}),
            item_kind=item_kind,
            source=source,
        )
        if legacy_ref:
            command_payload["legacy_materialization_item"] = legacy_ref
        else:
            command_payload.pop("legacy_materialization_item", None)
        return command_payload

    @staticmethod
    def _materialization_item_from_workflow_command(
        command: dict[str, Any],
        *,
        default_item_kind: str,
    ) -> dict[str, Any]:
        """Synthesize the former item envelope from command-owned payload.

        Existing execution primitives still accept an item-shaped payload. W6
        moves storage ownership to `workflow_commands`; this adapter is
        in-memory only and must not write/read `job_materialization_items`.
        """

        command_payload = dict(command or {})
        payload = dict(command_payload.get("payload") or {})
        command_result = dict(command_payload.get("result") or {})
        metadata = {
            **dict(payload.get("materialization_metadata") or {}),
            "command_owned_payload": True,
            "command_payload_storage": "workflow_commands",
            "workflow_command_id": str(command_payload.get("command_id") or "").strip(),
            "workflow_command_type": str(command_payload.get("command_type") or "").strip(),
            "workflow_command_owner": str(command_payload.get("owner") or "").strip(),
        }
        if payload.get("request_payload") not in (None, {}, ""):
            metadata.setdefault("request_payload", dict(payload.get("request_payload") or {}))
        for progress_key in (
            "local_apply_profile_progress",
            "profile_apply_progress",
            "processed_member_count",
            "next_offset",
            "last_page_indexed_count",
            "total_member_count",
            "truncated",
        ):
            if command_result.get(progress_key) not in (None, "", [], {}):
                metadata[progress_key] = command_result.get(progress_key)
        item_kind = str(payload.get("item_kind") or default_item_kind or "").strip()
        candidate_ids = _dedupe_texts(payload.get("candidate_ids") or [])
        source_worker_ids = []
        for worker_id in list(payload.get("source_worker_ids") or []):
            try:
                normalized_worker_id = int(worker_id or 0)
            except (TypeError, ValueError):
                continue
            if normalized_worker_id > 0:
                source_worker_ids.append(normalized_worker_id)
        return {
            "item_id": str(payload.get("item_id") or command_payload.get("idempotency_key") or command_payload.get("command_id") or "").strip(),
            "job_id": str(payload.get("job_id") or "").strip(),
            "target_company": str(payload.get("target_company") or "").strip(),
            "snapshot_id": str(payload.get("snapshot_id") or "").strip(),
            "baseline_snapshot_id": str(payload.get("baseline_snapshot_id") or "").strip(),
            "asset_view": str(payload.get("asset_view") or "canonical_merged").strip() or "canonical_merged",
            "item_kind": item_kind,
            "source": str(payload.get("source") or "workflow_command_payload").strip(),
            "reason": str(payload.get("reason") or "workflow_command_payload").strip(),
            "status": str(command_payload.get("status") or "running").strip(),
            "phase": str(command_payload.get("status") or "running").strip(),
            "priority": _coerce_int(payload.get("priority"), 0),
            "candidate_ids": candidate_ids,
            "candidate_count": _coerce_int(payload.get("candidate_count"), len(candidate_ids)),
            "source_worker_ids": source_worker_ids,
            "idempotency_key": str(command_payload.get("idempotency_key") or payload.get("item_id") or "").strip(),
            "max_attempts": max(1, _coerce_int(command_payload.get("max_attempts"), 5)),
            "metadata": metadata,
            "command_owned_payload": True,
        }

