    def _candidate_review_status_lookup_for_filter(self, job_id: str) -> dict[str, str]:
        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        try:
            records = self.store.list_candidate_review_records(job_id=normalized_job_id, limit=5_000)
        except Exception:
            return {}
        lookup: dict[str, str] = {}
        for record in records:
            candidate_id = str(dict(record).get("candidate_id") or "").strip()
            status = str(dict(record).get("status") or "").strip()
            if candidate_id and status and candidate_id not in lookup:
                lookup[candidate_id] = status
        return lookup

