    @staticmethod
    def _candidate_page_record_display_ready_for_sort(record: dict[str, Any]) -> bool:
        payload = dict(record or {})
        metadata = dict(payload.get("metadata") or {})
        if any(
            bool(payload.get(key) or metadata.get(key))
            for key in ("display_ready", "card_ready", "has_profile_detail", "has_explicit_profile_capture")
        ):
            return True
        if bool(payload.get("needs_profile_completion") or metadata.get("needs_profile_completion")):
            return False
        if payload.get("experience_lines") or metadata.get("experience_lines"):
            return True
        if payload.get("education_lines") or metadata.get("education_lines"):
            return True
        return bool(
            payload.get("headline")
            or payload.get("summary")
            or metadata.get("headline")
            or metadata.get("summary")
            or payload.get("profile_capture_kind")
            or metadata.get("profile_capture_kind")
        )

    @classmethod
    def _prioritize_candidate_page_display_ready_records(
        cls,
        records: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        return sorted(
            [dict(record) for record in list(records or []) if isinstance(record, dict)],
            key=lambda item: (
                0 if cls._candidate_page_record_display_ready_for_sort(item) else 1,
                1 if bool(dict(item).get("needs_profile_completion")) else 0,
            ),
        )

