    @staticmethod
    def _layer_facet_summary_from_outreach_context(context: dict[str, Any]) -> list[dict[str, Any]]:
        context_payload = dict(context or {})
        distribution = dict(context_payload.get("final_layer_distribution") or {})
        if not distribution:
            return []
        cumulative_counts = dict(context_payload.get("cumulative_layer_counts") or {})
        layer_counts = dict(context_payload.get("layer_counts") or {})
        candidate_count = max(
            0,
            _coerce_int(context_payload.get("candidate_count"), 0),
            _coerce_int(cumulative_counts.get("layer_0_roster"), 0),
            _coerce_int(layer_counts.get("layer_0_roster"), 0),
            sum(_coerce_int(distribution.get(f"layer_{layer}"), 0) for layer in range(4)),
        )
        return [
            {
                "id": f"layer_{layer}",
                "label": f"Layer {layer}",
                "count": candidate_count if layer == 0 else int(distribution.get(f"layer_{layer}") or 0),
            }
            for layer in range(4)
        ]

    @staticmethod
    def _normalize_public_layer_zero_facet_summary(facet_summary: dict[str, Any]) -> dict[str, Any]:
        """Render public Layer 0 as the all-candidate layer.

        Internal outreach artifacts keep `final_layer_distribution.layer_0` as
        the exclusive "no stronger signal" bucket. The public board labels
        Layer 0 as "全量候选人", so public facet summaries must not leak the
        exclusive distribution into the UI.
        """

        payload = dict(facet_summary or {})
        layers = [dict(item) for item in list(payload.get("layers") or []) if isinstance(item, dict)]
        if not layers:
            return payload
        candidate_count = _coerce_int(payload.get("candidate_count"), 0)
        if candidate_count <= 0:
            return payload
        by_id = {str(item.get("id") or "").strip(): item for item in layers if str(item.get("id") or "").strip()}
        normalized_layers: list[dict[str, Any]] = []
        for layer in range(4):
            layer_id = f"layer_{layer}"
            source = dict(by_id.get(layer_id) or {})
            source["id"] = layer_id
            source["label"] = str(source.get("label") or f"Layer {layer}")
            if layer == 0:
                source["count"] = candidate_count
            else:
                source["count"] = max(0, _coerce_int(source.get("count"), 0))
            normalized_layers.append(source)
        payload["layers"] = normalized_layers
        return payload

    def _apply_outreach_layer_summary_to_public_facet_summary(
        self,
        *,
        request: JobRequest,
        candidate_source: dict[str, Any],
        facet_summary: dict[str, Any],
    ) -> dict[str, Any]:
        payload = self._normalize_public_layer_zero_facet_summary(dict(facet_summary or {}))
        outreach_context = self._load_outreach_layering_context(
            request=request,
            candidate_source=dict(candidate_source or {}),
            runtime_policy={},
        )
        layer_summary = self._layer_facet_summary_from_outreach_context(outreach_context)
        if not layer_summary:
            return payload
        payload_candidate_count = _coerce_int(payload.get("candidate_count"), 0)
        layering_candidate_count = _coerce_int(dict(layer_summary[0] if layer_summary else {}).get("count"), 0)
        if payload_candidate_count > 0 and layering_candidate_count > 0 and payload_candidate_count != layering_candidate_count:
            # A completed board's public denominator is the canonical serving
            # projection. Older outreach artifacts can contain raw or pre-dedupe
            # row counts; they may annotate matching rows, but must not replace
            # global public facet counts.
            return self._normalize_public_layer_zero_facet_summary(payload)
        public_candidate_count = payload_candidate_count or layering_candidate_count
        normalized_layers: list[dict[str, Any]] = []
        for layer in range(4):
            source = dict(layer_summary[layer]) if layer < len(layer_summary) else {}
            source["id"] = f"layer_{layer}"
            source["label"] = str(source.get("label") or f"Layer {layer}")
            source["count"] = public_candidate_count if layer == 0 else max(0, _coerce_int(source.get("count"), 0))
            normalized_layers.append(source)
        payload["layers"] = normalized_layers
        if public_candidate_count > 0:
            payload["candidate_count"] = max(_coerce_int(payload.get("candidate_count"), 0), public_candidate_count)
        return self._normalize_public_layer_zero_facet_summary(payload)

    def _build_asset_population_facet_summary_from_artifact_summary(
        self,
        artifact_summary: dict[str, Any],
        *,
        intent_keywords: list[str] | None = None,
        expected_candidate_count: int = 0,
    ) -> dict[str, Any]:
        """Build public facets from compact artifact counters without page scans."""

        summary_payload = dict(artifact_summary or {})
        counts_payload = dict(summary_payload.get("public_facet_counts") or {})
        if not counts_payload:
            return {}
        count_candidate_count = _coerce_int(counts_payload.get("candidate_count"), 0)
        artifact_candidate_count = _coerce_int(summary_payload.get("candidate_count"), 0)
        expected_count = max(0, int(expected_candidate_count or 0))
        if expected_count <= 0:
            expected_count = artifact_candidate_count
        if count_candidate_count <= 0:
            return {}
        if expected_count > 0 and count_candidate_count != expected_count:
            return {}
        facet_summary = _public_facet_summary_from_counts(
            counts_payload,
            intent_keywords=list(intent_keywords or []),
        )
        if not facet_summary:
            return {}
        if expected_count > 0 and _coerce_int(facet_summary.get("candidate_count"), 0) != expected_count:
            return {}
        return self._normalize_public_layer_zero_facet_summary(facet_summary)

    def _build_asset_population_facet_summary_payload(
        self,
        *,
        request: JobRequest,
        candidate_source: dict[str, Any],
        effective_execution_semantics: dict[str, Any],
        publishable_email_lookup: dict[str, dict[str, dict[str, Any]]] | None = None,
    ) -> dict[str, Any]:
        candidate_source = dict(candidate_source or {})
        target_company = str(request.target_company or "").strip()
        snapshot_id = str(candidate_source.get("snapshot_id") or "").strip()
        asset_view = (
            str(candidate_source.get("asset_view") or request.asset_view or "canonical_merged").strip()
            or "canonical_merged"
        )
        if not target_company or not snapshot_id:
            return {}
        cache_key = self._asset_population_facet_summary_cache_key(
            request=request,
            target_company=target_company,
            snapshot_id=snapshot_id,
            asset_view=asset_view,
            candidate_source=candidate_source,
        )
        with self._asset_population_summary_cache_lock:
            cached_payload = self._asset_population_summary_cache.get(cache_key)
        if cached_payload is not None:
            return dict(cached_payload)
        stored_facet_summary = self._candidate_source_stored_facet_summary(candidate_source)
        stored_facet_summary_scope = self._candidate_source_stored_facet_summary_scope(candidate_source)
        stored_facet_candidate_count = _coerce_int(stored_facet_summary.get("candidate_count"), 0)
        stored_facet_source_is_overlay = bool(
            str(candidate_source.get("source_kind") or "").strip() == "job_asset_population_overlay"
            or (
                self._candidate_source_asset_population_overlay_path(candidate_source) is not None
                and Path(str(candidate_source.get("source_path") or "")).expanduser()
                == self._candidate_source_asset_population_overlay_path(candidate_source)
            )
        )
        expected_facet_candidate_count = max(
            0,
            _coerce_int(candidate_source.get("candidate_count"), 0),
            _coerce_int(dict(candidate_source.get("result_view_summary") or {}).get("candidate_count"), 0),
        )
        if (
            stored_facet_source_is_overlay
            and stored_facet_summary
            and stored_facet_summary_scope == "global_full_population"
            and stored_facet_candidate_count == expected_facet_candidate_count
        ):
            stored_facet_summary = self._apply_outreach_layer_summary_to_public_facet_summary(
                request=request,
                candidate_source=candidate_source,
                facet_summary=stored_facet_summary,
            )
            with self._asset_population_summary_cache_lock:
                self._asset_population_summary_cache[cache_key] = dict(stored_facet_summary)
            return dict(stored_facet_summary)
        final_serving_outranks_overlay = self._candidate_source_final_serving_artifact_outranks_overlay(
            candidate_source
        )
        serving_overlay_outranks_stored_facets = (
            self._candidate_source_complete_serving_overlay_outranks_stored_facets(candidate_source)
        )
        stored_facet_is_complete = bool(
            stored_facet_summary
            and stored_facet_summary_scope == "global_full_population"
            and (
                expected_facet_candidate_count <= 0
                or stored_facet_candidate_count == expected_facet_candidate_count
            )
        )
        if stored_facet_is_complete and not final_serving_outranks_overlay and not serving_overlay_outranks_stored_facets:
            stored_facet_summary = self._apply_outreach_layer_summary_to_public_facet_summary(
                request=request,
                candidate_source=candidate_source,
                facet_summary=stored_facet_summary,
            )
            with self._asset_population_summary_cache_lock:
                self._asset_population_summary_cache[cache_key] = dict(stored_facet_summary)
            return dict(stored_facet_summary)
        artifact_summary = self._read_job_asset_population_artifact_summary(
            request=request,
            candidate_source=candidate_source,
        )
        if expected_facet_candidate_count > 0:
            artifact_facet_counts = dict(artifact_summary.get("public_facet_counts") or {})
            artifact_count = _coerce_int(artifact_summary.get("candidate_count"), 0)
            artifact_facet_count = _coerce_int(artifact_facet_counts.get("candidate_count"), 0)
            if (
                artifact_facet_counts
                and (artifact_count != expected_facet_candidate_count or artifact_facet_count != expected_facet_candidate_count)
            ):
                # A compact artifact summary from a different population must not
                # trigger an O(all rows) request-path rebuild or leak stale global
                # counts. The canonical projection can still serve rows; facets
                # stay unavailable until the matching projection is published.
                return {}
        artifact_facet_summary = self._build_asset_population_facet_summary_from_artifact_summary(
            artifact_summary,
            intent_keywords=list(request.keywords or []) + list(request.organization_keywords or []),
            expected_candidate_count=expected_facet_candidate_count,
        )
        if artifact_facet_summary:
            artifact_facet_summary = self._apply_outreach_layer_summary_to_public_facet_summary(
                request=request,
                candidate_source=candidate_source,
                facet_summary=artifact_facet_summary,
            )
            with self._asset_population_summary_cache_lock:
                self._asset_population_summary_cache[cache_key] = dict(artifact_facet_summary)
            return dict(artifact_facet_summary)
        if final_serving_outranks_overlay or serving_overlay_outranks_stored_facets:
            max_request_rebuild_rows = max(0, _env_int("JOB_RESULTS_FACET_REQUEST_REBUILD_MAX_ROWS", 500))
            if (
                expected_facet_candidate_count > 0
                and max_request_rebuild_rows > 0
                and expected_facet_candidate_count <= max_request_rebuild_rows
            ):
                pass
            else:
                # A complete serving projection with no exact facet artifact
                # should fail closed. Rebuilding global facets from all rows
                # during a public request turns Google-scale boards into
                # timeout-prone request handlers and can mislabel partial
                # overlay counts as global.
                return {}
        asset_payload = self._build_job_asset_population_payload(
            request=request,
            candidate_source=candidate_source,
            effective_execution_semantics=effective_execution_semantics,
            publishable_email_lookup=publishable_email_lookup,
            include_candidates=True,
            load_profile_timeline=False,
            include_facet_summary=False,
        )
        records = [dict(item) for item in list(asset_payload.get("candidates") or []) if isinstance(item, dict)]
        self._attach_snapshot_outreach_layering_metadata_to_records(
            request=request,
            candidate_source=candidate_source,
            records=records,
        )
        facet_summary = self._build_asset_population_facet_summary_from_records(
            records,
            intent_keywords=list(request.keywords or []) + list(request.organization_keywords or []),
        )
        facet_summary = self._apply_outreach_layer_summary_to_public_facet_summary(
            request=request,
            candidate_source=candidate_source,
            facet_summary=facet_summary,
        )
        with self._asset_population_summary_cache_lock:
            self._asset_population_summary_cache[cache_key] = dict(facet_summary)
        return facet_summary

    def _build_asset_population_profile_fetch_progress_payload(
        self,
        *,
        request: JobRequest,
        candidate_source: dict[str, Any],
        asset_view: str,
    ) -> dict[str, Any]:
        candidate_source = dict(candidate_source or {})
        target_company = str(request.target_company or "").strip()
        snapshot_id = str(candidate_source.get("snapshot_id") or "").strip()
        if not target_company or not snapshot_id:
            return self._build_profile_fetch_progress_payload([])

        stored_progress = self._candidate_source_stored_profile_fetch_progress(candidate_source)
        if stored_progress:
            return stored_progress

        overlay_payload = self._load_candidate_source_asset_population_overlay(candidate_source)
        if overlay_payload:
            overlay_candidates = [
                dict(item) for item in list(overlay_payload.get("candidates") or []) if isinstance(item, dict)
            ]
            overlay_candidates = self._enrich_overlay_candidate_records_from_materialized_sources(
                request=request,
                candidate_source=candidate_source,
                overlay_payload=overlay_payload,
                records=overlay_candidates,
            )
            return self._build_profile_fetch_progress_payload(overlay_candidates)

        summary_progress = self._build_profile_fetch_progress_payload_from_artifact_summary(
            self._read_job_asset_population_artifact_summary(
                request=request,
                candidate_source=candidate_source,
            )
        )
        if summary_progress:
            return summary_progress

        try:
            artifact_store = (
                self._open_public_serving_artifact_store_from_candidate_source(
                    request=request,
                    candidate_source=candidate_source,
                    target_company=target_company,
                    snapshot_id=snapshot_id,
                    asset_view=asset_view,
                )
                or open_snapshot_artifact_store(
                    runtime_dir=self.runtime_dir,
                    target_company=target_company,
                    snapshot_id=snapshot_id,
                    asset_view=asset_view,
                )
            )
            snapshot_window = read_snapshot_candidate_window(store=artifact_store, offset=0, limit=0)
        except CandidateArtifactError:
            snapshot_window = {}
        if snapshot_window:
            page_records = [
                dict(item) for item in list(snapshot_window.get("candidates") or []) if isinstance(item, dict)
            ]
            return self._build_profile_fetch_progress_payload(page_records)

        # Public profile progress is a serving projection metric. Root
        # candidate_documents.json is acquisition/recovery evidence and must not
        # be promoted into public progress when normalized artifacts are absent.
        return self._build_profile_fetch_progress_payload([])

    def _select_job_results_mode(
        self,
        *,
        request: JobRequest,
        effective_execution_semantics: dict[str, Any],
        ranked_result_count: int,
        asset_population_summary: dict[str, Any],
    ) -> str:
        preferred_results_mode = (
            str(dict(effective_execution_semantics or {}).get("default_results_mode") or "").strip().lower()
        )
        asset_population_count = int(dict(asset_population_summary or {}).get("candidate_count") or 0)
        asset_population_available = bool(dict(asset_population_summary or {}).get("available")) and (
            asset_population_count > 0
            or preferred_results_mode == "asset_population"
            or str(request.target_scope or "").strip().lower() == "full_company_asset"
        )
        if asset_population_available and (
            preferred_results_mode != "ranked_results"
            or bool(dict(asset_population_summary or {}).get("default_selected"))
            or ranked_result_count == 0
            or str(request.target_scope or "").strip().lower() == "full_company_asset"
        ):
            return "asset_population"
        return "ranked_results"

    def _build_job_results_payload(
        self,
        job_id: str,
        *,
        include_runtime_details: bool,
        include_manual_review_items: bool,
        include_asset_population_candidates: bool = True,
        asset_population_offset: int = 0,
        asset_population_limit: int | None = None,
        load_asset_population_profile_timeline: bool = True,
        load_ranked_results_profile_timeline: bool = True,
        public_api_contract: bool = False,
    ) -> dict[str, Any] | None:
        context = self._build_job_results_context(job_id)
        if context is None:
            return None
        job = dict(context.get("job") or {})
        workflow_stage_summaries = dict(context.get("workflow_stage_summaries") or {})
        request = context.get("request") or JobRequest.from_payload({})
        candidate_source = dict(context.get("candidate_source") or {})
        effective_execution_semantics = dict(context.get("effective_execution_semantics") or {})
        publishable_email_lookup = context.get("publishable_email_lookup")
        default_results_mode = (
            str(dict(effective_execution_semantics or {}).get("default_results_mode") or "").strip().lower()
        )
        should_hide_ranked_results = bool(
            default_results_mode == "asset_population" and not str(job.get("artifact_path") or "").strip()
        )
        ranked_result_count = self.store.count_job_results(job_id)
        ranked_results = (
            []
            if should_hide_ranked_results
            else [
                self._serialize_candidate_api_record(
                    record,
                    load_profile_timeline=load_ranked_results_profile_timeline,
                    publishable_email_lookup=publishable_email_lookup,
                )
                for record in self.store.get_job_results(job_id)
            ]
        )
        asset_population = self._build_job_asset_population_payload(
            request=request,
            candidate_source=candidate_source,
            effective_execution_semantics=effective_execution_semantics,
            publishable_email_lookup=publishable_email_lookup,
            offset=asset_population_offset,
            limit=asset_population_limit,
            include_candidates=include_asset_population_candidates,
            load_profile_timeline=load_asset_population_profile_timeline,
            fallback_candidate_count=int(
                dict(context.get("job_summary") or {}).get("candidate_count")
                or dict(context.get("stage1_preview_summary") or {}).get("candidate_count")
                or 0
            ),
        )
        public_projection = self._build_public_board_runtime_projection(
            job_id=job_id,
            context=context,
            ranked_result_count=ranked_result_count,
        )
        asset_population = self._merge_public_projection_fields_into_asset_population(
            asset_population,
            public_projection,
        )
        linkedin_stage_1_progress = dict(public_projection.get("linkedin_stage_1_progress") or {})
        job_payload = self._build_job_dashboard_job_payload(job) if public_api_contract else job
        payload: dict[str, Any] = {
            "job": job_payload,
            "results": ranked_results,
            "ranked_results": ranked_results,
            "ranked_result_count": ranked_result_count,
            "asset_population": asset_population,
            "result_view_lifecycle": dict(public_projection.get("result_view_lifecycle") or {}),
            "board_runtime_state": dict(public_projection.get("board_runtime_state") or {}),
            "linkedin_stage_1_progress": linkedin_stage_1_progress,
            "request_preview": _load_job_request_preview(job),
            "provider_execution_manifest": dict(context.get("provider_execution_manifest") or {}),
            "effective_execution_semantics": effective_execution_semantics,
        }
        if include_manual_review_items:
            payload["manual_review_items"] = self.store.list_manual_review_items(job_id=job_id, status="", limit=100)
        else:
            payload["manual_review_count"] = self.store.count_manual_review_items(job_id=job_id, status="")
        if include_runtime_details:
            if public_api_contract:
                payload.update(
                    {
                        "events": [
                            _compact_public_job_event_payload(dict(event))
                            for event in self.store.list_job_events(job_id)
                            if isinstance(event, dict)
                        ],
                        "agent_runtime_session": _compact_public_agent_runtime_session_payload(
                            self.store.get_agent_runtime_session(job_id=job_id) or {}
                        ),
                        "agent_trace_spans": [
                            _compact_public_agent_trace_span_payload(dict(span))
                            for span in self.store.list_agent_trace_spans(job_id=job_id)
                            if isinstance(span, dict)
                        ],
                        "agent_workers": [
                            _compact_public_agent_worker_payload(dict(worker))
                            for worker in self._safe_list_persisted_job_workers(job_id)
                            if isinstance(worker, dict)
                        ],
                        "intent_rewrite": _build_intent_rewrite_payload(
                            request_payload=dict(job.get("request") or {})
                        ),
                        "workflow_stage_summaries": _compact_public_workflow_stage_summaries(
                            workflow_stage_summaries
                        ),
                        "runtime_details_contract": {
                            "schema_version": "public_results_runtime_details_v1",
                            "payload_shape": "bounded_public_diagnostics",
                            "job_payload": "compact_dashboard_job_payload",
                        },
                    }
                )
            else:
                payload.update(
                    {
                        "events": self.store.list_job_events(job_id),
                        "agent_runtime_session": self.store.get_agent_runtime_session(job_id=job_id) or {},
                        "agent_trace_spans": self.store.list_agent_trace_spans(job_id=job_id),
                        "agent_workers": self._safe_list_persisted_job_workers(job_id),
                        "intent_rewrite": _build_intent_rewrite_payload(
                            request_payload=dict(job.get("request") or {})
                        ),
                        "workflow_stage_summaries": workflow_stage_summaries,
                    }
                )
        return payload

    def _build_job_dashboard_job_payload(self, job: dict[str, Any]) -> dict[str, Any]:
        request_payload = dict(job.get("request") or {})
        summary_payload = dict(job.get("summary") or {})
        return {
            "job_id": str(job.get("job_id") or ""),
            "status": str(job.get("status") or ""),
            "stage": str(job.get("stage") or ""),
            "request": {
                "raw_user_request": str(request_payload.get("raw_user_request") or ""),
                "query": str(request_payload.get("query") or ""),
                "target_company": str(request_payload.get("target_company") or ""),
                "target_scope": str(request_payload.get("target_scope") or ""),
            },
            "summary": _compact_public_progress_dict(summary_payload),
        }

    def _build_public_board_runtime_projection(
        self,
        *,
        job_id: str,
        context: dict[str, Any],
        ranked_result_count: int | None = None,
        include_facet_summary: bool = True,
    ) -> dict[str, Any]:
        """Build the canonical public board projection shared by all readers.

        Public endpoints may load different row windows, but they must not
        independently derive lifecycle, facet scope, or board-runtime state from
        those windows. This helper uses the summary-only serving projection as
        the single event-time read model; row endpoints can merge their page rows
        onto it without changing the public contract.
        """

        job = dict(context.get("job") or {})
        request = context.get("request") or JobRequest.from_payload({})
        candidate_source = dict(context.get("candidate_source") or {})
        result_view = dict(context.get("result_view") or {})
        effective_execution_semantics = dict(context.get("effective_execution_semantics") or {})
        linkedin_stage_1_progress = dict(context.get("linkedin_stage_1_progress") or {})
        normalized_ranked_result_count = (
            int(ranked_result_count)
            if ranked_result_count is not None
            else self.store.count_job_results(job_id)
        )
        fallback_candidate_count = int(
            dict(context.get("job_summary") or {}).get("candidate_count")
            or dict(context.get("stage1_preview_summary") or {}).get("candidate_count")
            or 0
        )
        asset_population = self._build_job_asset_population_payload(
            request=request,
            candidate_source=candidate_source,
            effective_execution_semantics=effective_execution_semantics,
            include_candidates=False,
            include_facet_summary=include_facet_summary,
            fallback_candidate_count=fallback_candidate_count,
        )
        if dict(asset_population.get("facet_summary") or {}):
            asset_population["facet_summary"] = self._normalize_public_layer_zero_facet_summary(
                dict(asset_population.get("facet_summary") or {})
            )
        result_mode = self._select_job_results_mode(
            request=request,
            effective_execution_semantics=effective_execution_semantics,
            ranked_result_count=normalized_ranked_result_count,
            asset_population_summary=asset_population,
        )
        asset_population = self._attach_served_candidate_source_to_asset_population(
            request=request,
            candidate_source=candidate_source,
            result_view=result_view,
            asset_population=asset_population,
        )
        result_view_lifecycle = self._load_job_result_lifecycle(
            job_id=job_id,
            job=job,
            request=request,
            candidate_source=candidate_source,
            result_view=result_view,
            asset_population=asset_population,
            linkedin_stage_1_progress=linkedin_stage_1_progress,
            effective_execution_semantics=effective_execution_semantics,
        )
        serving_projection_payload = self._load_job_canonical_serving_projection_payload(
            job_id=job_id,
            result_view_lifecycle=result_view_lifecycle,
            result_view=result_view,
            candidate_source=candidate_source,
        )
        result_view_lifecycle = self._normalize_public_lifecycle_to_serving_projection(
            result_view_lifecycle=result_view_lifecycle,
            serving_projection_payload=serving_projection_payload,
        )
        asset_population = self._apply_canonical_serving_projection_facets(
            asset_population=asset_population,
            serving_projection_payload=serving_projection_payload,
            request=request,
            expected_candidate_count=_coerce_int(result_view_lifecycle.get("expected_candidate_count"), 0),
        )
        asset_population = self._apply_canonical_serving_projection_readiness(
            asset_population=asset_population,
            serving_projection_payload=serving_projection_payload,
        )
        if (
            result_mode != "asset_population"
            and (
                bool(asset_population.get("available"))
                or str(dict(serving_projection_payload or {}).get("status") or "") == "ready"
            )
            and _coerce_int(result_view_lifecycle.get("expected_candidate_count"), 0) > 0
            and str(result_view_lifecycle.get("state") or "").strip()
            in {"current_snapshot_serving", "post_result_layering", "current_serving"}
        ):
            result_mode = "asset_population"
        asset_population = self._canonicalize_public_asset_population_projection(
            asset_population=asset_population,
            result_view_lifecycle=result_view_lifecycle,
            board_runtime_state={},
        )
        board_runtime_state = self._build_board_runtime_state(
            job_id=job_id,
            job=job,
            result_mode=result_mode,
            result_view_lifecycle=result_view_lifecycle,
            asset_population=asset_population,
            facet_summary_scope=str(asset_population.get("facet_summary_scope") or "").strip(),
            facet_summary=dict(asset_population.get("facet_summary") or {}),
            linkedin_stage_1_progress=linkedin_stage_1_progress,
        )
        board_runtime_state = self._apply_serving_projection_facet_readiness_to_board_runtime_state(
            board_runtime_state=board_runtime_state,
            serving_projection_payload=serving_projection_payload,
        )
        asset_population = self._apply_board_runtime_profile_progress_to_asset_population(
            asset_population=asset_population,
            board_runtime_state=board_runtime_state,
        )
        canonical_facet_scope = str(
            board_runtime_state.get("facet_summary_scope") or asset_population.get("facet_summary_scope") or ""
        ).strip()
        if canonical_facet_scope:
            asset_population["facet_summary_scope"] = canonical_facet_scope
        filter_contract = dict(board_runtime_state.get("filter_contract") or {})
        if filter_contract:
            asset_population["filter_contract"] = filter_contract
        asset_population = self._canonicalize_public_asset_population_projection(
            asset_population=asset_population,
            result_view_lifecycle=result_view_lifecycle,
            board_runtime_state=board_runtime_state,
        )
        board_runtime_state = self._apply_serving_projection_facet_readiness_to_board_runtime_state(
            board_runtime_state=board_runtime_state,
            serving_projection_payload=serving_projection_payload,
        )
        filter_contract = dict(board_runtime_state.get("filter_contract") or {})
        if filter_contract:
            asset_population["filter_contract"] = filter_contract
        canonical_facet_scope = str(
            board_runtime_state.get("facet_summary_scope") or asset_population.get("facet_summary_scope") or ""
        ).strip()
        if canonical_facet_scope:
            asset_population["facet_summary_scope"] = canonical_facet_scope
        if str(board_runtime_state.get("facet_summary_status") or "").strip() != "complete":
            asset_population.pop("facet_summary", None)
        canonical_linkedin_stage_1_progress = self._canonicalize_public_linkedin_stage1_progress(
            linkedin_stage_1_progress,
            result_view_lifecycle=result_view_lifecycle,
            board_runtime_state=board_runtime_state,
        )
        return {
            "result_mode": result_mode,
            "asset_population": asset_population,
            "result_view_lifecycle": result_view_lifecycle,
            "board_runtime_state": board_runtime_state,
            "linkedin_stage_1_progress": canonical_linkedin_stage_1_progress,
            "facet_summary": dict(asset_population.get("facet_summary") or {}),
            "facet_summary_scope": canonical_facet_scope,
            "filter_contract": filter_contract,
        }

    def _apply_serving_projection_facet_readiness_to_board_runtime_state(
        self,
        *,
        board_runtime_state: dict[str, Any],
        serving_projection_payload: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Make canonical ServingProjection the owner of board facet/filter state."""

        payload = dict(board_runtime_state or {})
        if str(dict(serving_projection_payload or {}).get("status") or "") != "ready":
            return payload
        projection = dict(dict(serving_projection_payload or {}).get("projection") or {})
        if not projection:
            return payload

        readiness_contract = self.serving_projection_reader.projection_facet_readiness_contract(projection)
        facet_summary = dict(readiness_contract.get("facet_summary") or {})
        filter_count_contract = dict(readiness_contract.get("filter_count_contract") or {})
        canonical_filter_contract = self._candidate_page_filter_contract(
            applied_filter={},
            filter_signature="",
            source="serving_projection_members",
            row_filter_scope="projection_membership",
        )
        canonical_filter_contract.update(filter_count_contract)
        canonical_filter_contract["fallback_used"] = False
        payload["filter_contract"] = canonical_filter_contract

        facet_status = str(facet_summary.get("status") or "").strip()
        if facet_status == "complete":
            facet_candidate_count = max(
                0,
                _coerce_int(facet_summary.get("candidate_count"), 0),
                _coerce_int(projection.get("visible_member_count"), 0),
            )
            public_denominator = max(
                0,
                _coerce_int(payload.get("expected_candidate_count"), 0),
                _coerce_int(payload.get("served_candidate_count"), 0),
                _coerce_int(payload.get("published_candidate_count"), 0),
            )
            if public_denominator > 0 and facet_candidate_count != public_denominator:
                canonical_filter_contract["facet_count_scope"] = "unavailable"
                canonical_filter_contract["facet_unavailable_reason"] = (
                    "projection_facet_count_mismatch_public_denominator"
                )
                canonical_filter_contract["facet_summary_actual_candidate_count"] = facet_candidate_count
                canonical_filter_contract["facet_summary_expected_candidate_count"] = public_denominator
                payload["filter_contract"] = canonical_filter_contract
                payload["facet_summary_status"] = "unavailable"
                payload["facet_summary_scope"] = "unavailable"
                payload["facet_summary_candidate_count"] = 0
                payload["layering_status"] = ""
                watermark = str(payload.get("row_publication_watermark") or "").strip()
                if watermark:
                    parts = watermark.split("|")
                    if len(parts) >= 4:
                        parts[-1] = str(payload.get("layering_status") or "").strip()
                        payload["row_publication_watermark"] = "|".join(parts)
                return payload
            payload["facet_summary_status"] = "complete"
            payload["facet_summary_scope"] = "global_full_population"
            payload["facet_summary_candidate_count"] = facet_candidate_count
            payload["layering_status"] = "completed"
        else:
            payload["facet_summary_status"] = "unavailable"
            payload["facet_summary_scope"] = "unavailable"
            payload["facet_summary_candidate_count"] = 0
            # Missing projection facet products mean no canonical layering view
            # is available yet. Suppress stale lifecycle/overlay "completed"
            # mirrors so all public endpoints fail closed the same way.
            payload["layering_status"] = ""

        watermark = str(payload.get("row_publication_watermark") or "").strip()
        if watermark:
            parts = watermark.split("|")
            if len(parts) >= 4:
                parts[-1] = str(payload.get("layering_status") or "").strip()
                payload["row_publication_watermark"] = "|".join(parts)
        return payload

    @staticmethod
    def _apply_canonical_serving_projection_readiness(
        *,
        asset_population: dict[str, Any],
        serving_projection_payload: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Lift canonical projection readiness into the board card summary.

        The legacy asset-population overlay can lag after event-time local apply
        updates canonical ServingProjection members. Public board readiness must
        prefer the projection membership/readiness owner; otherwise a terminal
        board can expose stale `display_ready_candidate_count` while profile
        text is rendered from newer workflow counters.
        """

        payload = dict(asset_population or {})
        if str(dict(serving_projection_payload or {}).get("status") or "") != "ready":
            return payload
        projection = dict(dict(serving_projection_payload or {}).get("projection") or {})
        if not projection:
            return payload
        counts = dict(projection.get("counts") or {})
        readiness = dict(projection.get("readiness") or {})
        visible_count = max(
            0,
            _coerce_int(projection.get("visible_member_count"), 0),
            _coerce_int(counts.get("visible_member_count"), 0),
            _coerce_int(counts.get("candidate_count"), 0),
            _coerce_int(counts.get("result_count"), 0),
        )
        if visible_count <= 0:
            return payload
        card_ready_count = min(
            visible_count,
            max(
                0,
                _coerce_int(counts.get("card_materialized_count"), 0),
                _coerce_int(readiness.get("card_ready_count"), 0),
            ),
        )
        profile_ready_count = min(
            visible_count,
            max(
                0,
                _coerce_int(counts.get("profile_fetched_count"), 0),
                _coerce_int(readiness.get("profile_ready_count"), 0),
            ),
        )
        if card_ready_count <= 0 and profile_ready_count <= 0:
            return payload
        summary = SourcingOrchestrator._normalize_candidate_card_materialization_summary(
            dict(payload.get("card_materialization_summary") or {}),
            fallback_candidate_count=visible_count,
        )
        candidate_count = max(visible_count, _coerce_int(summary.get("candidate_count"), 0))
        existing_display_ready = _coerce_int(summary.get("display_ready_candidate_count"), 0)
        if card_ready_count <= existing_display_ready:
            return payload

        display_ready_count = min(candidate_count, card_ready_count)
        profile_detail_count = min(
            candidate_count,
            max(_coerce_int(summary.get("profile_detail_candidate_count"), 0), profile_ready_count),
        )
        explicit_profile_capture_count = min(
            candidate_count,
            _coerce_int(summary.get("explicit_profile_capture_candidate_count"), 0),
        )
        preview_count = max(0, candidate_count - display_ready_count)
        needs_profile_completion_count = min(
            preview_count,
            _coerce_int(summary.get("needs_profile_completion_candidate_count"), 0),
        )
        lifted_summary = {
            **summary,
            "quality_fields_available": True,
            "candidate_count": candidate_count,
            "display_ready_candidate_count": display_ready_count,
            "profile_detail_candidate_count": profile_detail_count,
            "explicit_profile_capture_candidate_count": explicit_profile_capture_count,
            "preview_candidate_count": preview_count,
            "needs_profile_completion_candidate_count": needs_profile_completion_count,
            "summary_source": "serving_projection_readiness",
            "serving_projection_id": str(projection.get("projection_id") or "").strip(),
        }
        payload["card_materialization_summary"] = lifted_summary
        artifact_summary = dict(payload.get("artifact_summary") or {})
        if artifact_summary:
            artifact_summary["card_materialization_summary"] = lifted_summary
            payload["artifact_summary"] = artifact_summary
        return payload

    @staticmethod
    def _apply_board_runtime_profile_progress_to_asset_population(
        *,
        asset_population: dict[str, Any],
        board_runtime_state: dict[str, Any],
    ) -> dict[str, Any]:
        """Keep legacy profile progress fields aligned with board runtime.

        Some old artifact summaries count baseline profile-rich rows and this
        run's profile URLs in the same payload. Public UI copy is now driven by
        board_runtime_state; expose the same bounded denominator on the legacy
        `profile_fetch_progress` field so secondary readers cannot show
        impossible totals such as fetched > total.
        """

        payload = dict(asset_population or {})
        board = dict(board_runtime_state or {})
        required_count = max(
            0,
            _coerce_int(board.get("profile_fetch_required_count"), 0),
            _coerce_int(board.get("delta_profile_required_count"), 0),
        )
        if required_count <= 0:
            return payload
        fetched_count = min(
            required_count,
            max(
                0,
                _coerce_int(board.get("profile_fetched_count"), 0),
                _coerce_int(board.get("delta_profile_fetched_count"), 0),
            ),
        )
        pending_count = max(required_count - fetched_count, 0)
        existing = dict(payload.get("profile_fetch_progress") or {})
        status_counts = dict(existing.get("status_counts") or {})
        unrecoverable_count = min(_coerce_int(status_counts.get("unrecoverable"), 0), pending_count)
        retryable_count = min(
            _coerce_int(status_counts.get("failed_retryable"), 0),
            max(pending_count - unrecoverable_count, 0),
        )
        queued_count = max(pending_count - unrecoverable_count - retryable_count, 0)
        payload["profile_fetch_progress"] = {
            **existing,
            "total_url_count": required_count,
            "fetched_url_count": fetched_count,
            "queued_url_count": queued_count,
            "failed_retryable_url_count": retryable_count,
            "unrecoverable_url_count": unrecoverable_count,
            "missing_registry_url_count": 0,
            "deferred_url_count": 0,
            "pending_url_count": pending_count,
            "status_counts": {
                "queued": queued_count,
                "fetched": fetched_count,
                "failed_retryable": retryable_count,
                "unrecoverable": unrecoverable_count,
                "missing": 0,
                "deferred": 0,
            },
            "source_kind": "board_runtime_state",
            "count_scope": "current_run_profile_fetch_required",
        }
        return payload

    def _load_job_canonical_serving_projection_payload(
        self,
        *,
        job_id: str,
        result_view_lifecycle: dict[str, Any] | None = None,
        result_view: dict[str, Any] | None = None,
        candidate_source: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Return the canonical run projection for public serving, if ready.

        Legacy `serving_projection_id` values can still be filesystem overlay
        paths during migration. This helper tries the durable run/projection link
        first and only accepts IDs that resolve through ServingProjectionReader,
        so old overlay artifacts cannot participate in public source precedence.
        """

        normalized_job_id = str(job_id or "").strip()
        projection_ids: list[str] = []

        def _add_projection_id(value: Any) -> None:
            normalized = str(value or "").strip()
            if normalized and normalized not in projection_ids:
                projection_ids.append(normalized)

        if normalized_job_id:
            try:
                run_link = self.store.get_run_projection_link(normalized_job_id)
            except Exception:
                run_link = {}
            _add_projection_id(dict(run_link or {}).get("projection_id"))

        lifecycle = dict(result_view_lifecycle or {})
        result_view_payload = dict(result_view or {})
        result_view_metadata = dict(result_view_payload.get("metadata") or {})
        source_payload = dict(candidate_source or {})
        for value in (
            lifecycle.get("serving_projection_id"),
            dict(lifecycle.get("metadata") or {}).get("serving_projection_id"),
            dict(lifecycle.get("metadata") or {}).get("projection_id"),
            dict(result_view_metadata.get("run_scope_projection") or {}).get("projection_id"),
            result_view_metadata.get("serving_projection_id"),
            source_payload.get("serving_projection_id"),
            dict(source_payload.get("asset_population_patch") or {}).get("serving_projection_id"),
        ):
            _add_projection_id(value)

        for projection_id in projection_ids:
            projection_payload = self.serving_projection_reader.get_projection(projection_id)
            if str(projection_payload.get("status") or "") == "ready":
                return projection_payload
        return {}

    @staticmethod
    def _normalize_public_lifecycle_to_serving_projection(
        *,
        result_view_lifecycle: dict[str, Any],
        serving_projection_payload: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Use canonical projection visible membership as the public denominator.

        Legacy lifecycle rows can retain raw source counts that include hidden
        or manually excluded members. Once the canonical projection has a
        complete row read model, public endpoints must report the visible
        projection membership count so progress, dashboard, candidates, and
        board patches cannot drift.
        """

        payload = dict(result_view_lifecycle or {})
        if str(dict(serving_projection_payload or {}).get("status") or "") != "ready":
            return payload
        projection = dict(dict(serving_projection_payload or {}).get("projection") or {})
        visible_count = _coerce_int(projection.get("visible_member_count"), 0)
        if visible_count <= 0:
            return payload
        baseline_count = _coerce_int(payload.get("baseline_candidate_count"), 0)
        if baseline_count > 0 and visible_count < baseline_count:
            metadata = dict(payload.get("metadata") or {})
            metadata["partial_serving_projection_visible_member_count"] = visible_count
            metadata["partial_serving_projection_visible_member_count_reason"] = (
                "baseline_delta_projection_below_baseline"
            )
            payload["metadata"] = metadata
            return payload
        readiness = dict(projection.get("readiness") or {})
        row_state = str(readiness.get("row") or "").strip().lower()
        row_complete = bool(
            row_state == "complete"
            or (not row_state and _coerce_int(readiness.get("row_count"), 0) >= visible_count)
        )
        if not row_complete:
            return payload
        raw_expected = _coerce_int(payload.get("expected_candidate_count"), 0)
        raw_served = _coerce_int(payload.get("served_candidate_count"), 0)
        if raw_expected == visible_count and raw_served == visible_count:
            return payload
        payload["expected_candidate_count"] = visible_count
        payload["served_candidate_count"] = visible_count
        metadata = dict(payload.get("metadata") or {})
        metadata["canonical_projection_public_count_normalization"] = {
            "source": "serving_projection_members",
            "projection_id": str(projection.get("projection_id") or "").strip(),
            "visible_member_count": visible_count,
            "raw_expected_candidate_count": raw_expected,
            "raw_served_candidate_count": raw_served,
            "reason": "public_projection_counts_visible_members_only",
        }
        payload["metadata"] = metadata
        return payload

    def _apply_canonical_serving_projection_facets(
        self,
        *,
        asset_population: dict[str, Any],
        serving_projection_payload: dict[str, Any] | None,
        request: JobRequest | None = None,
        expected_candidate_count: int = 0,
    ) -> dict[str, Any]:
        """Lift exact canonical projection facet counts into job public state.

        This is deliberately one-way. A ready projection can make facets/layers
        complete for job endpoints; stale job overlays or result-view summaries
        must not downgrade a projection that already has exact public counts.
        """

        payload = dict(asset_population or {})
        if str(dict(serving_projection_payload or {}).get("status") or "") != "ready":
            return payload
        projection = dict(dict(serving_projection_payload or {}).get("projection") or {})
        if not projection:
            return payload
        counts = dict(projection.get("counts") or {})
        public_facet_counts = dict(counts.get("public_facet_counts") or {})
        if not public_facet_counts:
            return payload
        request_payload = request or JobRequest.from_payload({})
        facet_summary = _public_facet_summary_from_counts(
            public_facet_counts,
            intent_keywords=list(request_payload.keywords or []) + list(request_payload.organization_keywords or []),
        )
        if not facet_summary:
            return payload
        facet_summary["status"] = "complete"
        facet_summary["count_scope"] = str(
            public_facet_counts.get("count_scope") or counts.get("count_scope") or "exact_projection"
        )
        projection_count = max(
            0,
            _coerce_int(projection.get("visible_member_count"), 0),
            _coerce_int(counts.get("visible_member_count"), 0),
            _coerce_int(counts.get("candidate_count"), 0),
            _coerce_int(counts.get("result_count"), 0),
        )
        expected_count = max(0, int(expected_candidate_count or 0), projection_count)
        facet_candidate_count = _coerce_int(facet_summary.get("candidate_count"), 0)
        if facet_candidate_count <= 0:
            return payload
        if expected_count > 0 and facet_candidate_count != expected_count:
            return payload

        normalized_facet_summary = self._normalize_public_layer_zero_facet_summary(facet_summary)
        payload["facet_summary"] = normalized_facet_summary
        payload["facet_summary_scope"] = "global_full_population"
        filter_contract = dict(payload.get("filter_contract") or {})
        filter_contract["facet_count_scope"] = "exact_projection"
        filter_contract["facet_summary_source"] = "serving_projection_public_facet_counts"
        filter_contract["facet_summary_projection_id"] = str(projection.get("projection_id") or "").strip()
        payload["filter_contract"] = filter_contract
        artifact_summary = dict(payload.get("artifact_summary") or {})
        if artifact_summary:
            artifact_summary["facet_summary_scope"] = "global_full_population"
            artifact_summary["facet_summary_source"] = "serving_projection_public_facet_counts"
            payload["artifact_summary"] = artifact_summary
        return payload

    @staticmethod
    def _canonicalize_public_linkedin_stage1_progress(
        linkedin_stage_1_progress: dict[str, Any] | None,
        *,
        result_view_lifecycle: dict[str, Any] | None = None,
        board_runtime_state: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Align public Stage 1 counters with the canonical board projection.

        Stage 1 discovery/fetch counters are useful progress detail, but public
        endpoints must not expose stale pre-projection profile counts after the
        canonical board runtime has already proven a later state. This helper is
        one-way: it lifts progress to lifecycle/board watermarks and never
        derives a lower value from a partial lane or legacy summary.
        """

        payload = dict(linkedin_stage_1_progress or {})
        if not payload:
            return {}
        lifecycle = dict(result_view_lifecycle or {})
        board = dict(board_runtime_state or {})

        def _count(value: Any) -> int:
            try:
                return max(int(value or 0), 0)
            except (TypeError, ValueError):
                return 0

        required_count = max(
            _count(payload.get("profile_fetch_required_count")),
            _count(payload.get("profile_url_total_count")),
            _count(board.get("profile_fetch_required_count")),
            _count(board.get("delta_profile_required_count")),
            _count(lifecycle.get("delta_profile_required_count")),
        )
        if required_count <= 0:
            return payload

        fetched_count = min(
            required_count,
            max(
                _count(payload.get("profile_fetched_count")),
                _count(payload.get("fetched_profile_count")),
                _count(board.get("profile_fetched_count")),
                _count(board.get("delta_profile_fetched_count")),
                _count(lifecycle.get("delta_profile_fetched_count")),
            ),
        )
        payload["profile_fetch_required_count"] = required_count
        payload["profile_url_total_count"] = required_count
        payload["profile_fetched_count"] = fetched_count
        payload["fetched_profile_count"] = fetched_count
        payload["deduped_candidate_count"] = max(_count(payload.get("deduped_candidate_count")), required_count)
        payload["deduped_profile_url_count"] = max(_count(payload.get("deduped_profile_url_count")), required_count)

        status_counts_source = dict(payload.get("status_counts") or {})
        remaining_after_fetched = max(required_count - fetched_count, 0)
        unrecoverable_count = min(_count(status_counts_source.get("unrecoverable")), remaining_after_fetched)
        retryable_count = min(
            max(
                _count(payload.get("profile_failed_retryable_count")),
                _count(status_counts_source.get("failed_retryable")),
            ),
            max(remaining_after_fetched - unrecoverable_count, 0),
        )
        pending_count = max(required_count - fetched_count - unrecoverable_count, 0)
        existing_queued_count = max(
            _count(payload.get("profile_queued_count")),
            _count(status_counts_source.get("queued"))
            + _count(status_counts_source.get("missing"))
            + _count(status_counts_source.get("deferred")),
        )
        queued_count = min(existing_queued_count, pending_count) if existing_queued_count > 0 else pending_count
        payload["profile_unrecoverable_count"] = unrecoverable_count
        payload["profile_failed_retryable_count"] = retryable_count
        payload["profile_pending_count"] = pending_count
        payload["profile_queued_count"] = queued_count
        payload["status_counts"] = {
            "queued": queued_count,
            "fetched": fetched_count,
            "failed_retryable": retryable_count,
            "unrecoverable": unrecoverable_count,
            "missing": max(pending_count - queued_count, 0),
            "deferred": 0,
        }
        return payload

    @staticmethod
    def _canonical_public_projection_candidate_count(
        *,
        result_view_lifecycle: dict[str, Any] | None = None,
        board_runtime_state: dict[str, Any] | None = None,
    ) -> int:
        lifecycle = dict(result_view_lifecycle or {})
        board = dict(board_runtime_state or {})
        for source, key in (
            (board, "expected_candidate_count"),
            (lifecycle, "expected_candidate_count"),
            (board, "served_candidate_count"),
            (lifecycle, "served_candidate_count"),
            (board, "published_candidate_count"),
            (board, "row_hydration_target_count"),
        ):
            value = _coerce_int(source.get(key), 0)
            if value > 0:
                return value
        return 0

    @staticmethod
    def _compact_public_asset_population_artifact_summary(
        artifact_summary: dict[str, Any],
        *,
        canonical_candidate_count: int = 0,
    ) -> dict[str, Any]:
        source = dict(artifact_summary or {})
        if not source:
            return {}
        source_candidate_count = _coerce_int(source.get("candidate_count"), 0)
        public_candidate_count = canonical_candidate_count or source_candidate_count
        compacted: dict[str, Any] = {}
        for key in (
            "target_company",
            "company_key",
            "snapshot_id",
            "asset_view",
            "build_profile",
            "projection_version",
            "candidate_page_size",
            "candidate_page_count",
            "profile_detail_count",
            "explicit_profile_capture_count",
            "manual_review_confirmed_count",
            "missing_linkedin_count",
            "manual_review_backlog_count",
            "profile_completion_backlog_count",
            "facet_summary_scope",
            "created_at",
        ):
            value = source.get(key)
            if value not in (None, "", [], {}):
                compacted[key] = _compact_public_workflow_leaf(value)
        if public_candidate_count > 0:
            compacted["candidate_count"] = public_candidate_count
        if source_candidate_count > 0 and public_candidate_count > 0 and source_candidate_count != public_candidate_count:
            compacted["source_candidate_count"] = source_candidate_count
            compacted["count_scope"] = "canonical_public_projection"
        return compacted

    @staticmethod
    def _compact_public_candidate_source_reference(candidate_source: dict[str, Any]) -> dict[str, Any]:
        source = dict(candidate_source or {})
        if not source:
            return {}
        compacted = dict(source)
        for metadata_key in ("result_view_metadata", "asset_population_patch", "result_view_lifecycle"):
            metadata = dict(compacted.get(metadata_key) or {})
            if metadata:
                compacted[metadata_key] = _compact_public_progress_dict(metadata)
        if isinstance(compacted.get("job_scoped_candidate_markers"), list):
            marker_summaries = []
            for marker in list(compacted.get("job_scoped_candidate_markers") or [])[:10]:
                marker_payload = dict(marker or {})
                marker_summaries.append(
                    {
                        "marker_id": str(marker_payload.get("marker_id") or marker_payload.get("id") or "").strip(),
                        "label": str(marker_payload.get("label") or "").strip(),
                        "candidate_count": _coerce_int(
                            marker_payload.get("candidate_count")
                            or len(list(marker_payload.get("candidate_ids") or [])),
                            0,
                        ),
                    }
                )
            compacted["job_scoped_candidate_marker_count"] = len(
                list(compacted.get("job_scoped_candidate_markers") or [])
            )
            compacted["job_scoped_candidate_markers"] = marker_summaries
        for list_key, count_key in (
            ("candidate_ids", "candidate_id_count"),
            ("cumulative_candidate_ids", "cumulative_candidate_id_count"),
            ("delta_candidate_ids", "delta_candidate_id_count"),
        ):
            if isinstance(compacted.get(list_key), list):
                compacted[count_key] = len(list(compacted.get(list_key) or []))
                compacted.pop(list_key, None)
        result_view = dict(compacted.get("result_view") or {})
        if result_view:
            view_payload = {
                key: result_view.get(key)
                for key in (
                    "view_id",
                    "job_id",
                    "target_company",
                    "source_kind",
                    "view_kind",
                    "snapshot_id",
                    "asset_view",
                    "source_path",
                    "authoritative_snapshot_id",
                    "materialization_generation_key",
                    "request_signature",
                )
                if result_view.get(key) not in (None, "", [], {})
            }
            summary_payload = _compact_public_progress_dict(dict(result_view.get("summary") or {}))
            metadata_payload = _compact_public_progress_dict(dict(result_view.get("metadata") or {}))
            if summary_payload:
                view_payload["summary"] = summary_payload
            if metadata_payload:
                view_payload["metadata"] = metadata_payload
            compacted["result_view"] = view_payload
        return compacted

    @classmethod
    def _canonicalize_public_asset_population_projection(
        cls,
        *,
        asset_population: dict[str, Any],
        result_view_lifecycle: dict[str, Any] | None,
        board_runtime_state: dict[str, Any] | None,
    ) -> dict[str, Any]:
        payload = dict(asset_population or {})
        canonical_count = cls._canonical_public_projection_candidate_count(
            result_view_lifecycle=result_view_lifecycle,
            board_runtime_state=board_runtime_state,
        )
        if canonical_count > 0:
            payload["candidate_count"] = canonical_count
            artifact_summary = cls._compact_public_asset_population_artifact_summary(
                dict(payload.get("artifact_summary") or {}),
                canonical_candidate_count=canonical_count,
            )
            if artifact_summary:
                payload["artifact_summary"] = artifact_summary
            else:
                payload.pop("artifact_summary", None)
        elif dict(payload.get("artifact_summary") or {}):
            payload["artifact_summary"] = cls._compact_public_asset_population_artifact_summary(
                dict(payload.get("artifact_summary") or {}),
                canonical_candidate_count=0,
            )

        facet_summary = cls._normalize_public_layer_zero_facet_summary(dict(payload.get("facet_summary") or {}))
        facet_scope = str(payload.get("facet_summary_scope") or "").strip()
        board = dict(board_runtime_state or {})
        if canonical_count > 0 and facet_summary:
            facet_candidate_count = _coerce_int(facet_summary.get("candidate_count"), 0)
            layer_zero_count = 0
            for item in list(facet_summary.get("layers") or []):
                if isinstance(item, dict) and str(item.get("id") or "").strip() == "layer_0":
                    layer_zero_count = _coerce_int(item.get("count"), 0)
                    break
            facet_is_canonical = bool(
                facet_scope == "global_full_population"
                and facet_candidate_count == canonical_count
                and (not list(facet_summary.get("layers") or []) or layer_zero_count == canonical_count)
            )
            board_facet_scope = str(board.get("facet_summary_scope") or "").strip()
            if board and (
                board_facet_scope != "global_full_population"
                or _coerce_int(board.get("facet_summary_candidate_count"), 0) != canonical_count
            ):
                facet_is_canonical = False
            if facet_is_canonical:
                payload["facet_summary"] = facet_summary
                payload["facet_summary_scope"] = "global_full_population"
            else:
                payload.pop("facet_summary", None)
                payload["facet_summary_scope"] = "unavailable"
                filter_contract = dict(payload.get("filter_contract") or {})
                filter_contract["facet_count_scope"] = "unavailable"
                filter_contract["facet_unavailable_reason"] = str(
                    filter_contract.get("facet_unavailable_reason")
                    or "facet_summary_count_mismatch_canonical_projection"
                ).strip()
                payload["filter_contract"] = filter_contract
        elif facet_summary:
            payload["facet_summary"] = facet_summary

        candidate_source = dict(payload.get("candidate_source") or {})
        if candidate_source:
            payload["candidate_source"] = cls._compact_public_candidate_source_reference(candidate_source)
        return payload

    @staticmethod
    def _merge_public_projection_fields_into_asset_population(
        asset_population: dict[str, Any],
        projection: dict[str, Any],
    ) -> dict[str, Any]:
        """Keep row payloads from a page read, but public counters from projection."""

        payload = dict(asset_population or {})
        canonical_asset_population = dict(projection.get("asset_population") or {})
        for key in (
            "candidate_count",
            "profile_fetch_progress",
            "card_materialization_summary",
            "facet_summary_scope",
            "facet_summary",
            "filter_contract",
            "candidate_source",
            "artifact_summary",
        ):
            if key in canonical_asset_population:
                payload[key] = canonical_asset_population.get(key)
        if (
            "facet_summary" not in canonical_asset_population
            and str(canonical_asset_population.get("facet_summary_scope") or "").strip() == "unavailable"
        ):
            payload.pop("facet_summary", None)
        canonical_count = _coerce_int(canonical_asset_population.get("candidate_count"), 0)
        if canonical_count > 0 and any(key in payload for key in ("offset", "limit", "returned_count")):
            offset = _coerce_int(payload.get("offset"), 0)
            returned_count = _coerce_int(payload.get("returned_count"), len(list(payload.get("candidates") or [])))
            next_offset = offset + returned_count
            payload["has_more"] = next_offset < canonical_count
            payload["next_offset"] = next_offset if next_offset < canonical_count else None
        canonical_filter_contract = dict(projection.get("filter_contract") or {})
        if canonical_filter_contract:
            payload["filter_contract"] = canonical_filter_contract
        return payload

    def get_job_dashboard(
        self,
        job_id: str,
        *,
        include_asset_population_preview: bool = True,
    ) -> dict[str, Any] | None:
        context = self._build_job_results_context(job_id)
        if context is None:
            return None
        job = dict(context.get("job") or {})
        workflow_stage_summaries = dict(context.get("workflow_stage_summaries") or {})
        request = context.get("request") or JobRequest.from_payload({})
        candidate_source = dict(context.get("candidate_source") or {})
        effective_execution_semantics = dict(context.get("effective_execution_semantics") or {})
        publishable_email_lookup = context.get("publishable_email_lookup")
        ranked_result_count = self.store.count_job_results(job_id)
        linkedin_stage_1_progress = dict(context.get("linkedin_stage_1_progress") or {})
        public_projection = self._build_public_board_runtime_projection(
            job_id=job_id,
            context=context,
            ranked_result_count=ranked_result_count,
        )
        asset_population = dict(public_projection.get("asset_population") or {})
        result_mode = str(public_projection.get("result_mode") or "").strip() or "ranked_results"
        result_view_lifecycle = dict(public_projection.get("result_view_lifecycle") or {})
        board_runtime_state = dict(public_projection.get("board_runtime_state") or {})
        linkedin_stage_1_progress = dict(public_projection.get("linkedin_stage_1_progress") or {})
        preview_limit = min(max(_env_int("JOB_RESULTS_DASHBOARD_PREVIEW_CANDIDATE_LIMIT", 24), 0), 120)
        ranked_results_preview: list[dict[str, Any]] = []
        if (
            result_mode == "asset_population"
            and include_asset_population_preview
            and preview_limit > 0
            and int(asset_population.get("candidate_count") or 0) > 0
        ):
            projection_preview = self._build_job_asset_population_page_from_canonical_projection(
                job_id=job_id,
                result_view_lifecycle=result_view_lifecycle,
                result_view=dict(context.get("result_view") or {}),
                candidate_source=candidate_source,
                public_projection=public_projection,
                candidate_filter={},
                offset=0,
                limit=preview_limit,
            )
            asset_population = projection_preview or self._build_job_asset_population_payload(
                request=request,
                candidate_source=candidate_source,
                effective_execution_semantics=effective_execution_semantics,
                publishable_email_lookup=publishable_email_lookup,
                offset=0,
                limit=preview_limit,
                include_candidates=True,
                load_profile_timeline=False,
                fallback_candidate_count=int(
                    dict(context.get("job_summary") or {}).get("candidate_count")
                    or dict(context.get("stage1_preview_summary") or {}).get("candidate_count")
                    or 0
                ),
            )
            asset_population = self._merge_public_projection_fields_into_asset_population(
                asset_population,
                public_projection,
            )
        elif preview_limit > 0 and ranked_result_count > 0:
            ranked_results_preview = [
                self._serialize_candidate_api_record(
                    record,
                    load_profile_timeline=False,
                    publishable_email_lookup=publishable_email_lookup,
                )
                for record in self.store.get_job_results_page(
                    job_id,
                    offset=0,
                    limit=preview_limit,
                    include_evidence=False,
                )
            ]
        execution_phase_contract = self._build_execution_phase_contract(
            job=job,
            workflow_stage_summaries=workflow_stage_summaries,
            linkedin_stage_1_progress=linkedin_stage_1_progress,
            result_view_lifecycle=result_view_lifecycle,
        )
        return {
            "job": self._build_job_dashboard_job_payload(job),
            "results": ranked_results_preview,
            "ranked_results": ranked_results_preview,
            "ranked_result_count": ranked_result_count,
            "asset_population": asset_population,
            "result_view_lifecycle": result_view_lifecycle,
            "board_runtime_state": board_runtime_state,
            "linkedin_stage_1_progress": linkedin_stage_1_progress,
            "execution_phase_contract": execution_phase_contract,
            "manual_review_count": self.store.count_manual_review_items(job_id=job_id, status=""),
            "request_preview": _load_job_request_preview(job),
            "provider_execution_manifest": dict(context.get("provider_execution_manifest") or {}),
            "effective_execution_semantics": effective_execution_semantics,
        }

    def get_job_results(self, job_id: str) -> dict[str, Any] | None:
        return self._build_job_results_payload(
            job_id,
            include_runtime_details=True,
            include_manual_review_items=True,
            load_ranked_results_profile_timeline=True,
        )

