    def rebuild_projection_person_search_index_api(self, payload: dict[str, Any]) -> dict[str, Any]:
        normalized = dict(payload or {})
        projection_id = str(normalized.get("projection_id") or "").strip()
        if not projection_id:
            return {"status": "invalid", "reason": "projection_id_required"}
        projection = self.store.get_serving_projection(projection_id)
        if not projection:
            return {"status": "not_found", "reason": "projection_not_found", "projection_id": projection_id}
        return self.person_asset_writer.rebuild_projection_person_search_index(
            projection_id=projection_id,
            count_scope=str(normalized.get("count_scope") or "index_partial").strip() or "index_partial",
            raw_profile_index_watermark=str(normalized.get("raw_profile_index_watermark") or "").strip(),
            evidence_index_watermark=str(normalized.get("evidence_index_watermark") or "").strip(),
            member_page_size=_coerce_int(normalized.get("member_page_size"), 1000),
            max_members=_coerce_int(normalized.get("max_members"), 100_000),
            rebuild_person_indexes=_coerce_bool(normalized.get("rebuild_person_indexes"), True),
        )

