    def get_projection_crm_state_api(
        self,
        projection_id: str,
        *,
        candidate_identity_keys: list[str] | tuple[str, ...] | None = None,
        workspace_id: str = "default",
    ) -> dict[str, Any] | None:
        normalized_projection_id = str(projection_id or "").strip()
        projection = self.store.get_serving_projection(normalized_projection_id)
        if not projection:
            return None
        keys = [str(key or "").strip() for key in list(candidate_identity_keys or []) if str(key or "").strip()]
        members: list[dict[str, Any]] = []
        if keys:
            for key in keys[:250]:
                member = self.store.get_serving_projection_member(normalized_projection_id, key)
                if member:
                    members.append(member)
        else:
            members = self.store.list_serving_projection_members(normalized_projection_id, limit=250, visible_only=True)
        person_keys = [
            str(member.get("person_identity_key") or "").strip()
            for member in members
            if str(member.get("person_identity_key") or "").strip()
        ]
        records_by_person = self.store.list_crm_records_by_person_identity_keys(
            person_keys,
            workspace_id=workspace_id,
        )
        overlays: dict[str, dict[str, Any]] = {}
        for member in members:
            candidate_key = str(member.get("candidate_identity_key") or "").strip()
            person_key = str(member.get("person_identity_key") or "").strip()
            record = dict(records_by_person.get(person_key) or {})
            overlays[candidate_key] = _compact_crm_overlay_summary(record)
        return {
            "status": "ready",
            "projection_id": normalized_projection_id,
            "workspace_id": str(workspace_id or "default").strip() or "default",
            "crm_overlay_by_candidate_identity_key": overlays,
            "read_contract": {
                "source": "crm_records",
                "fallback_used": False,
                "fail_closed": True,
                "auto_create": False,
            },
        }

    def list_crm_records_api(
        self,
        *,
        source_projection_id: str = "",
        source_collection_id: str = "",
        workspace_id: str = "default",
        limit: int = 250,
    ) -> dict[str, Any]:
        records = self.store.list_crm_records(
            source_projection_id=str(source_projection_id or "").strip(),
            source_collection_id=str(source_collection_id or "").strip(),
            workspace_id=str(workspace_id or "default").strip() or "default",
            limit=min(max(int(limit or 250), 1), 1000),
        )
        return {
            "status": "ready",
            "workspace_id": str(workspace_id or "default").strip() or "default",
            "source_projection_id": str(source_projection_id or "").strip(),
            "source_collection_id": str(source_collection_id or "").strip(),
            "crm_records": [self._public_crm_record_payload(record) for record in records],
            "record_count": len(records),
            "read_contract": {
                "source": "crm_records",
                "fallback_used": False,
                "fail_closed": True,
                "legacy_target_candidates_used": False,
            },
        }

    def get_crm_record_api(
        self,
        crm_record_id: str,
        *,
        workspace_id: str = "default",
    ) -> dict[str, Any] | None:
        record = self.store.get_crm_record(str(crm_record_id or "").strip())
