    def backfill_public_web_signals_to_person_asset_layer(self, payload: dict[str, Any]) -> dict[str, Any]:
        normalized = dict(payload or {})
        workspace_id = str(normalized.get("workspace_id") or "default").strip() or "default"
        run_ids = _dedupe_texts(
            [
                str(item or "").strip()
                for item in list(normalized.get("run_ids") or normalized.get("runIds") or [])
                if str(item or "").strip()
            ]
        )
        single_run_id = str(normalized.get("run_id") or normalized.get("runId") or "").strip()
        if single_run_id:
            run_ids = _dedupe_texts([single_run_id, *run_ids])
        signal_filters = {
            "person_identity_key": str(normalized.get("person_identity_key") or "").strip(),
            "record_id": str(normalized.get("record_id") or "").strip(),
            "signal_kind": str(normalized.get("signal_kind") or "").strip(),
        }
        limit = min(max(_coerce_int(normalized.get("limit"), 1000), 1), 10_000)
        dry_run = _coerce_bool(normalized.get("dry_run"), True)
        reviewed = _coerce_bool(normalized.get("reviewed"), False)
        signals: list[dict[str, Any]] = []
        if run_ids:
            remaining = limit
            for run_id in run_ids:
                if remaining <= 0:
                    break
                page = self.store.list_person_public_web_signals(
                    run_id=run_id,
                    person_identity_key=signal_filters["person_identity_key"],
                    record_id=signal_filters["record_id"],
                    signal_kind=signal_filters["signal_kind"],
                    limit=remaining,
                )
                signals.extend([dict(item or {}) for item in page])
                remaining = limit - len(signals)
        else:
            signals = [
                dict(item or {})
                for item in self.store.list_person_public_web_signals(
                    person_identity_key=signal_filters["person_identity_key"],
                    record_id=signal_filters["record_id"],
                    signal_kind=signal_filters["signal_kind"],
                    limit=limit,
                )
            ]
        seen_signal_ids: set[str] = set()
        deduped_signals: list[dict[str, Any]] = []
        for signal in signals:
            signal_id = str(signal.get("signal_id") or "").strip()
            if not signal_id or signal_id in seen_signal_ids:
                continue
            seen_signal_ids.add(signal_id)
            deduped_signals.append(signal)
        eligible_signals = [
            signal
            for signal in deduped_signals
            if str(signal.get("person_identity_key") or "").strip()
            and (
                str(signal.get("normalized_value") or signal.get("value") or "").strip()
                or str(signal.get("source_url") or signal.get("url") or "").strip()
            )
        ]
        selected_run_ids = _dedupe_texts(str(signal.get("run_id") or "").strip() for signal in deduped_signals)
        if dry_run:
            return {
                "status": "dry_run",
                "reason": "public_web_signal_person_asset_backfill_preview",
                "workspace_id": workspace_id,
                "signal_count": len(deduped_signals),
                "eligible_signal_count": len(eligible_signals),
                "skipped_count": len(deduped_signals) - len(eligible_signals),
                "run_ids": selected_run_ids,
                "limit": limit,
                "migration_path": True,
                "module_state_mutated": False,
                "read_contract": {
                    "source": "person_public_web_signals",
                    "target": "PersonAsset.public_web_signal+PersonEvidence",
                    "fallback_used": False,
                    "fail_closed": True,
                    "normal_reader_repair": False,
                },
            }
        if not reviewed:
            return {
                "status": "invalid",
                "reason": "operator_review_required",
                "workspace_id": workspace_id,
                "migration_path": True,
                "module_state_mutated": False,
                "read_contract": {
                    "source": "person_public_web_signals",
                    "target": "PersonAsset.public_web_signal+PersonEvidence",
                    "fallback_used": False,
                    "fail_closed": True,
                    "normal_reader_repair": False,
                    "apply_requires_reviewed": True,
                },
            }
        if not eligible_signals:
            return {
                "status": "backfilled",
                "reason": "no_eligible_public_web_signals",
                "workspace_id": workspace_id,
                "signal_count": len(deduped_signals),
                "eligible_signal_count": 0,
                "asset_count": 0,
                "evidence_count": 0,
                "entity_delta_count": 0,
                "skipped_count": len(deduped_signals),
                "run_ids": selected_run_ids,
                "migration_path": True,
                "module_state_mutated": False,
                "read_contract": {
                    "source": "person_public_web_signals",
                    "target": "PersonAsset.public_web_signal+PersonEvidence",
                    "fallback_used": False,
                    "fail_closed": True,
                    "normal_reader_repair": False,
                },
            }
        grouped_by_run: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for signal in eligible_signals:
            signal_run_id = str(signal.get("run_id") or "").strip() or "historical-public-web-signals"
            grouped_by_run[signal_run_id].append(signal)
        aggregate = {
            "asset_count": 0,
            "evidence_count": 0,
            "entity_delta_count": 0,
            "skipped_count": len(deduped_signals) - len(eligible_signals),
            "asset_ids": [],
            "evidence_ids": [],
            "entity_delta_ids": [],
        }
        results: list[dict[str, Any]] = []
        for run_id, run_signals in grouped_by_run.items():
            result = self._sync_crm_public_web_signals_to_person_asset_layer(
                command={},
                activity={},
                attempt={},
                run_id=run_id,
                batch_id=str(normalized.get("batch_id") or "historical_public_web_signal_backfill").strip(),
                workspace_id=workspace_id,
                signals=run_signals,
            )
            results.append(result)
            aggregate["asset_count"] += int(result.get("asset_count") or 0)
            aggregate["evidence_count"] += int(result.get("evidence_count") or 0)
            aggregate["entity_delta_count"] += int(result.get("entity_delta_count") or 0)
            aggregate["skipped_count"] += int(result.get("skipped_count") or 0)
            aggregate["asset_ids"].extend(list(result.get("asset_ids") or []))
            aggregate["evidence_ids"].extend(list(result.get("evidence_ids") or []))
            aggregate["entity_delta_ids"].extend(list(result.get("entity_delta_ids") or []))
        return {
            "status": "backfilled",
            "reason": "public_web_signal_person_asset_backfill",
            "workspace_id": workspace_id,
            "signal_count": len(deduped_signals),
            "eligible_signal_count": len(eligible_signals),
            "run_ids": list(grouped_by_run.keys()),
            "run_count": len(grouped_by_run),
            "asset_count": aggregate["asset_count"],
            "evidence_count": aggregate["evidence_count"],
            "entity_delta_count": aggregate["entity_delta_count"],
            "skipped_count": aggregate["skipped_count"],
            "asset_ids": aggregate["asset_ids"][:500],
            "evidence_ids": aggregate["evidence_ids"][:500],
            "entity_delta_ids": aggregate["entity_delta_ids"][:500],
            "results": results[:50],
            "migration_path": True,
            "module_state_mutated": True,
            "read_contract": {
                "source": "person_public_web_signals",
                "target": "PersonAsset.public_web_signal+PersonEvidence",
                "fallback_used": False,
                "fail_closed": True,
                "normal_reader_repair": False,
            },
        }

    def backfill_person_avatar_media_assets_api(self, payload: dict[str, Any]) -> dict[str, Any]:
        normalized = dict(payload or {})
        projection_id = str(normalized.get("projection_id") or normalized.get("projectionId") or "").strip()
        collection_id = str(normalized.get("collection_id") or normalized.get("collectionId") or "").strip()
        if not projection_id and collection_id:
            pointer = self.store.get_collection_authoritative_pointer(collection_id)
            projection_id = str(dict(pointer or {}).get("active_projection_id") or "").strip()
        if not projection_id:
            return {
                "status": "invalid",
                "reason": "projection_id_required",
                "migration_path": True,
                "module_state_mutated": False,
            }
        projection = self.store.get_serving_projection(projection_id)
        if not projection:
            return {
                "status": "not_found",
                "reason": "serving_projection_not_found",
                "projection_id": projection_id,
                "migration_path": True,
                "module_state_mutated": False,
            }
        limit = min(max(_coerce_int(normalized.get("limit"), 500), 1), 5000)
        dry_run = _coerce_bool(normalized.get("dry_run"), True)
        reviewed = _coerce_bool(normalized.get("reviewed"), False)
        force = _coerce_bool(normalized.get("force"), False)
        run_now = _coerce_bool(normalized.get("run_now"), False)
        workflow_run_id = str(normalized.get("workflow_run_id") or normalized.get("workflowRunId") or "").strip()
        if not workflow_run_id:
            workflow_run_id = "wf_media_asset_backfill_" + hashlib.sha1(
                f"{projection_id}:{collection_id}:person_avatar_media".encode("utf-8")
            ).hexdigest()[:24]
        batch_id = str(normalized.get("batch_id") or normalized.get("batchId") or "").strip()
        if not batch_id:
            batch_id = "person_avatar_media_backfill_" + hashlib.sha1(
                f"{projection_id}:{limit}:{force}".encode("utf-8")
            ).hexdigest()[:16]
        members = self.store.list_serving_projection_members(
            projection_id,
            visible_only=True,
            limit=limit,
            offset=0,
        )
        candidates: list[dict[str, Any]] = []
        skipped_existing_count = 0
        skipped_missing_url_count = 0
        skipped_missing_identity_count = 0
        for member in members:
            public_summary = dict(member.get("public_summary") or {})
            member_metadata = dict(member.get("metadata") or {})
            person_identity_key = str(
                member.get("person_identity_key") or public_summary.get("person_identity_key") or ""
            ).strip()
            if not person_identity_key:
                skipped_missing_identity_count += 1
                continue
            source_url = _candidate_avatar_media_source_url(public_summary, member_metadata)
            if not source_url:
                skipped_missing_url_count += 1
                continue
            if not force:
                existing_assets = self.store.list_person_assets(
                    person_identity_key=person_identity_key,
                    asset_type="avatar_media",
                    limit=5,
                )
                if any(str(asset.get("status") or "").strip() == "available" for asset in existing_assets):
                    skipped_existing_count += 1
                    continue
            command_payload = {
                "entity_type": "person",
                "asset_type": "avatar_media",
                "person_identity_key": person_identity_key,
                "source_url": source_url,
                "source_projection_id": projection_id,
                "candidate_id": str(member.get("candidate_id") or public_summary.get("candidate_id") or "").strip(),
                "linkedin_url": str(
                    public_summary.get("linkedin_url")
                    or public_summary.get("profile_url")
                    or public_summary.get("canonical_profile_url")
                    or ""
                ).strip(),
                "visibility_scope": "public_summary",
                "batch_id": batch_id,
                "causality": {
                    "migration_phase": "Phase7c_person_avatar_media_backfill",
                    "projection_id": projection_id,
                    "collection_id": collection_id,
                    "candidate_identity_key": str(member.get("candidate_identity_key") or "").strip(),
                },
            }
            payload_hash = hashlib.sha1(
                json.dumps(command_payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
            ).hexdigest()[:24]
            candidates.append(
                {
                    "person_identity_key": person_identity_key,
                    "candidate_identity_key": str(member.get("candidate_identity_key") or "").strip(),
                    "candidate_id": command_payload["candidate_id"],
                    "source_url": source_url,
                    "idempotency_key": (
                        f"media.asset.cache:person-avatar-backfill:{projection_id}:{person_identity_key}:{payload_hash}"
                    ),
                    "payload": command_payload,
                }
            )
        if dry_run:
            return {
                "status": "dry_run",
                "reason": "person_avatar_media_backfill_preview",
                "projection_id": projection_id,
                "collection_id": collection_id,
                "workflow_run_id": workflow_run_id,
                "batch_id": batch_id,
                "member_count": len(members),
                "eligible_command_count": len(candidates),
                "skipped_existing_count": skipped_existing_count,
                "skipped_missing_url_count": skipped_missing_url_count,
                "skipped_missing_identity_count": skipped_missing_identity_count,
                "commands": [
                    {
                        "person_identity_key": item["person_identity_key"],
                        "candidate_identity_key": item["candidate_identity_key"],
                        "source_url": item["source_url"],
                        "idempotency_key": item["idempotency_key"],
                    }
                    for item in candidates[:100]
                ],
                "migration_path": True,
                "module_state_mutated": False,
                "read_contract": {
                    "source": "serving_projection_members.provider_avatar_metadata",
                    "target": "workflow_commands(media.asset.cache)",
                    "fallback_used": False,
                    "fail_closed": True,
                    "normal_reader_repair": False,
                    "request_path_fetch": False,
                },
            }
        if not reviewed:
            return {
                "status": "invalid",
                "reason": "operator_review_required",
                "projection_id": projection_id,
                "collection_id": collection_id,
                "workflow_run_id": workflow_run_id,
                "batch_id": batch_id,
                "migration_path": True,
                "module_state_mutated": False,
                "read_contract": {
                    "source": "serving_projection_members.provider_avatar_metadata",
                    "target": "workflow_commands(media.asset.cache)",
                    "fallback_used": False,
                    "fail_closed": True,
                    "normal_reader_repair": False,
                    "request_path_fetch": False,
                    "apply_requires_reviewed": True,
                },
            }
        commands: list[dict[str, Any]] = []
        if candidates:
            self.durable_runtime_writer.append_event_and_reduce(
                workflow_run_id=workflow_run_id,
                operation_id="",
                event_family="workflow_event",
                event_type="WorkflowStarted",
                idempotency_key=f"{workflow_run_id}:person_avatar_media_backfill_started",
                actor="person_avatar_media_backfill_operator",
                source="person_avatar_media_backfill",
                payload={
                    "workflow_type": "media_asset_backfill",
                    "stage_key": default_stage_id_for_command_type(MEDIA_ASSET_CACHE_COMMAND_TYPE),
                    "projection_id": projection_id,
                    "collection_id": collection_id,
                    "batch_id": batch_id,
                    "migration_phase": "Phase7c_person_avatar_media_backfill",
                },
            )
        for item in candidates:
            apply_result = self.durable_runtime_writer.append_event_and_reduce(
                workflow_run_id=workflow_run_id,
                operation_id="",
                event_family="workflow_event",
                event_type="CommandPlanRequested",
                idempotency_key=f"{item['idempotency_key']}:plan",
                actor="person_avatar_media_backfill_operator",
                source="person_avatar_media_backfill",
                payload={
                    "workflow_type": "media_asset_backfill",
                    "stage_key": default_stage_id_for_command_type(MEDIA_ASSET_CACHE_COMMAND_TYPE),
                    "command_type": MEDIA_ASSET_CACHE_COMMAND_TYPE,
                    "idempotency_key": item["idempotency_key"],
                    "payload": item["payload"],
                    "max_attempts": max(1, _coerce_int(normalized.get("max_attempts"), 3)),
                    "retry_policy": {"kind": "media_asset_cache_backfill", "retry_delay_seconds": 30},
                },
            )
            command = self._workflow_command_from_apply_result_or_store(
                apply_result=apply_result,
                workflow_run_id=workflow_run_id,
                idempotency_key=str(item["idempotency_key"]),
            )
            if command:
                commands.append(command)
        drain_result = {}
        if run_now and commands:
            drain_result = self._drain_media_asset_cache_commands(
                {"workflow_run_id": workflow_run_id, "command_limit": len(commands)}
            )
        return {
            "status": "planned",
            "reason": "person_avatar_media_backfill_commands_planned",
            "projection_id": projection_id,
            "collection_id": collection_id,
            "workflow_run_id": workflow_run_id,
            "batch_id": batch_id,
            "member_count": len(members),
            "eligible_command_count": len(candidates),
            "planned_command_count": len(commands),
            "skipped_existing_count": skipped_existing_count,
            "skipped_missing_url_count": skipped_missing_url_count,
            "skipped_missing_identity_count": skipped_missing_identity_count,
            "run_now": run_now,
            "drain_result": drain_result,
            "commands": [
                self._workflow_command_observation(command, migration_phase="Phase7c_person_avatar_media_backfill")
                for command in commands[:100]
            ],
            "migration_path": True,
            "module_state_mutated": bool(commands),
            "read_contract": {
                "source": "serving_projection_members.provider_avatar_metadata",
                "target": "workflow_commands(media.asset.cache)",
                "fallback_used": False,
                "fail_closed": True,
                "normal_reader_repair": False,
                "request_path_fetch": False,
            },
        }

    def backfill_company_logo_media_assets_api(self, payload: dict[str, Any]) -> dict[str, Any]:
        normalized = dict(payload or {})
        workspace_id = str(normalized.get("workspace_id") or "default").strip() or "default"
        collection_id = str(normalized.get("collection_id") or normalized.get("collectionId") or "").strip()
        target_company = str(normalized.get("target_company") or normalized.get("company") or "").strip()
        company_key = str(normalized.get("company_key") or normalized.get("companyKey") or "").strip()
        if collection_id and (not target_company or not company_key):
            registry = self._collection_registry_summary(collection_id)
            target_company = target_company or str(registry.get("target_company") or "").strip()
            company_key = company_key or str(registry.get("company_key") or "").strip()
        company_key = company_key or normalize_company_key(target_company)
        if not company_key and not target_company:
            return {
                "status": "invalid",
                "reason": "company_key_or_target_company_required",
                "migration_path": True,
                "module_state_mutated": False,
            }
        limit = min(max(_coerce_int(normalized.get("limit"), 100), 1), 1000)
        dry_run = _coerce_bool(normalized.get("dry_run"), True)
        reviewed = _coerce_bool(normalized.get("reviewed"), False)
        force = _coerce_bool(normalized.get("force"), False)
        run_now = _coerce_bool(normalized.get("run_now"), False)
        include_homepage_favicon = _coerce_bool(normalized.get("include_homepage_favicon"), False)
        workflow_run_id = str(normalized.get("workflow_run_id") or normalized.get("workflowRunId") or "").strip()
        if not workflow_run_id:
            workflow_run_id = "wf_media_asset_backfill_" + hashlib.sha1(
                f"{workspace_id}:{company_key}:{target_company}:company_logo_media".encode("utf-8")
            ).hexdigest()[:24]
        batch_id = str(normalized.get("batch_id") or normalized.get("batchId") or "").strip()
        if not batch_id:
            batch_id = "company_logo_media_backfill_" + hashlib.sha1(
                f"{workspace_id}:{company_key}:{target_company}:{limit}:{force}".encode("utf-8")
            ).hexdigest()[:16]
        stable_logo_assets = [
            asset
            for asset in self.store.list_company_assets(
                workspace_id=workspace_id,
                company_key=company_key,
                target_company=target_company,
                asset_type="logo_media",
                status="available",
                limit=10,
            )
            if _company_logo_media_asset_is_stable(asset)
        ]
        explicit_source_urls = _dedupe_texts(
            [
                str(normalized.get("source_url") or "").strip(),
                str(normalized.get("logo_url") or "").strip(),
                *_coerce_string_list(normalized.get("source_urls")),
                *_coerce_string_list(normalized.get("logo_urls")),
            ]
        )
        source_candidates = self._company_logo_media_source_candidates(
            workspace_id=workspace_id,
            company_key=company_key,
            target_company=target_company,
            explicit_source_urls=explicit_source_urls,
            include_homepage_favicon=include_homepage_favicon,
            limit=limit,
        )
        skipped_existing_count = len(stable_logo_assets) if stable_logo_assets and not force else 0
        candidates: list[dict[str, Any]] = []
        if not skipped_existing_count:
            for source in source_candidates[:limit]:
                source_url = str(source.get("source_url") or "").strip()
                if not _media_source_url_allowed(source_url):
                    continue
                command_payload = {
                    "workspace_id": workspace_id,
                    "entity_type": "company",
                    "asset_type": "logo_media",
                    "company_key": company_key,
                    "target_company": target_company or company_key,
                    "source_url": source_url,
                    "visibility_scope": "public_summary",
                    "batch_id": batch_id,
                    "causality": {
                        "migration_phase": "Phase5c_company_logo_media_backfill",
                        "collection_id": collection_id,
                        "source_kind": str(source.get("source_kind") or "").strip(),
                        "source_asset_id": str(source.get("source_asset_id") or "").strip(),
                        "source_evidence_id": str(source.get("source_evidence_id") or "").strip(),
                    },
                }
                payload_hash = hashlib.sha1(
                    json.dumps(command_payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
                ).hexdigest()[:24]
                candidates.append(
                    {
                        "source_url": source_url,
                        "source_kind": str(source.get("source_kind") or "").strip(),
                        "idempotency_key": f"media.asset.cache:company-logo-backfill:{company_key}:{payload_hash}",
                        "payload": command_payload,
                    }
                )
        if dry_run:
            return {
                "status": "dry_run",
                "reason": "company_logo_media_backfill_preview",
                "workspace_id": workspace_id,
                "company_key": company_key,
                "target_company": target_company,
                "collection_id": collection_id,
                "workflow_run_id": workflow_run_id,
                "batch_id": batch_id,
                "source_candidate_count": len(source_candidates),
                "eligible_command_count": len(candidates),
                "skipped_existing_count": skipped_existing_count,
                "include_homepage_favicon": include_homepage_favicon,
                "commands": [
                    {
                        "source_url": item["source_url"],
                        "source_kind": item["source_kind"],
                        "idempotency_key": item["idempotency_key"],
                    }
                    for item in candidates[:100]
                ],
                "migration_path": True,
                "module_state_mutated": False,
                "read_contract": {
                    "source": "explicit_logo_url+CompanyAsset.logo_media+CompanyEvidence.logo_url",
                    "target": "workflow_commands(media.asset.cache)",
                    "fallback_used": False,
                    "fail_closed": True,
                    "normal_reader_repair": False,
                    "request_path_fetch": False,
                    "homepage_favicon_derivation_default": False,
                },
            }
        if not reviewed:
            return {
                "status": "invalid",
                "reason": "operator_review_required",
                "workspace_id": workspace_id,
                "company_key": company_key,
                "target_company": target_company,
                "collection_id": collection_id,
                "workflow_run_id": workflow_run_id,
                "batch_id": batch_id,
                "migration_path": True,
                "module_state_mutated": False,
                "read_contract": {
                    "source": "explicit_logo_url+CompanyAsset.logo_media+CompanyEvidence.logo_url",
                    "target": "workflow_commands(media.asset.cache)",
                    "fallback_used": False,
                    "fail_closed": True,
                    "normal_reader_repair": False,
                    "request_path_fetch": False,
                    "homepage_favicon_derivation_default": False,
                    "apply_requires_reviewed": True,
                },
            }
        commands: list[dict[str, Any]] = []
        if candidates:
            self.durable_runtime_writer.append_event_and_reduce(
                workflow_run_id=workflow_run_id,
                operation_id="",
                event_family="workflow_event",
                event_type="WorkflowStarted",
                idempotency_key=f"{workflow_run_id}:company_logo_media_backfill_started",
                actor="company_logo_media_backfill_operator",
                source="company_logo_media_backfill",
                payload={
                    "workflow_type": "media_asset_backfill",
                    "stage_key": default_stage_id_for_command_type(MEDIA_ASSET_CACHE_COMMAND_TYPE),
                    "workspace_id": workspace_id,
                    "company_key": company_key,
                    "target_company": target_company,
                    "collection_id": collection_id,
                    "batch_id": batch_id,
                    "migration_phase": "Phase5c_company_logo_media_backfill",
                },
            )
        for item in candidates:
            apply_result = self.durable_runtime_writer.append_event_and_reduce(
                workflow_run_id=workflow_run_id,
                operation_id="",
                event_family="workflow_event",
                event_type="CommandPlanRequested",
                idempotency_key=f"{item['idempotency_key']}:plan",
                actor="company_logo_media_backfill_operator",
                source="company_logo_media_backfill",
                payload={
                    "workflow_type": "media_asset_backfill",
                    "stage_key": default_stage_id_for_command_type(MEDIA_ASSET_CACHE_COMMAND_TYPE),
                    "command_type": MEDIA_ASSET_CACHE_COMMAND_TYPE,
                    "idempotency_key": item["idempotency_key"],
                    "payload": item["payload"],
                    "max_attempts": max(1, _coerce_int(normalized.get("max_attempts"), 3)),
                    "retry_policy": {"kind": "media_asset_cache_backfill", "retry_delay_seconds": 30},
                },
            )
            command = self._workflow_command_from_apply_result_or_store(
                apply_result=apply_result,
                workflow_run_id=workflow_run_id,
                idempotency_key=str(item["idempotency_key"]),
            )
            if command:
                commands.append(command)
        drain_result = {}
        if run_now and commands:
            drain_result = self._drain_media_asset_cache_commands(
                {"workflow_run_id": workflow_run_id, "command_limit": len(commands)}
            )
        return {
            "status": "planned",
            "reason": "company_logo_media_backfill_commands_planned",
            "workspace_id": workspace_id,
            "company_key": company_key,
            "target_company": target_company,
            "collection_id": collection_id,
            "workflow_run_id": workflow_run_id,
            "batch_id": batch_id,
            "source_candidate_count": len(source_candidates),
            "eligible_command_count": len(candidates),
            "planned_command_count": len(commands),
            "skipped_existing_count": skipped_existing_count,
            "run_now": run_now,
            "drain_result": drain_result,
            "commands": [
                self._workflow_command_observation(command, migration_phase="Phase5c_company_logo_media_backfill")
                for command in commands[:100]
            ],
            "migration_path": True,
            "module_state_mutated": bool(commands),
            "read_contract": {
                "source": "explicit_logo_url+CompanyAsset.logo_media+CompanyEvidence.logo_url",
                "target": "workflow_commands(media.asset.cache)",
                "fallback_used": False,
                "fail_closed": True,
                "normal_reader_repair": False,
                "request_path_fetch": False,
                "homepage_favicon_derivation_default": False,
            },
        }

    def ingest_company_logo_from_profile_experience_api(self, payload: dict[str, Any]) -> dict[str, Any]:
        normalized = dict(payload or {})
        workspace_id = str(normalized.get("workspace_id") or "default").strip() or "default"
        target_company = str(normalized.get("target_company") or normalized.get("company") or "").strip()
        company_key = str(normalized.get("company_key") or normalized.get("companyKey") or "").strip()
        company_key = company_key or normalize_company_key(target_company)
        if not company_key and not target_company:
            return {
                "status": "invalid",
                "reason": "company_key_or_target_company_required",
                "module_state_mutated": False,
                "normal_path": True,
            }
        force = _coerce_bool(normalized.get("force"), False)
        dry_run = _coerce_bool(normalized.get("dry_run"), False)
        run_now = _coerce_bool(normalized.get("run_now"), False)
        skip_workflow_started = _coerce_bool(normalized.get("skip_workflow_started"), False)
        limit = min(max(_coerce_int(normalized.get("limit"), 10), 1), 100)
        min_ttl_seconds = max(0, _coerce_int(normalized.get("min_ttl_seconds"), 300))
        now_epoch = _coerce_int(normalized.get("now_epoch"), int(datetime.now(timezone.utc).timestamp()))
        collection_id = str(normalized.get("collection_id") or normalized.get("collectionId") or "").strip()
        source_run_id = str(normalized.get("source_run_id") or normalized.get("run_id") or "").strip()
        source_command_id = str(normalized.get("source_command_id") or normalized.get("command_id") or "").strip()
        source_profile_path = str(normalized.get("source_profile_path") or normalized.get("profile_path") or "").strip()
        profile_payload = (
            normalized.get("profile_payload")
            or normalized.get("profile")
            or normalized.get("raw_profile")
            or normalized.get("rawProfile")
            or {}
        )
        stable_logo_assets = [
            asset
            for asset in self.store.list_company_assets(
                workspace_id=workspace_id,
                company_key=company_key,
                target_company=target_company,
                asset_type="logo_media",
                status="available",
                limit=10,
            )
            if _company_logo_media_asset_is_stable(asset)
        ]
        if stable_logo_assets and not force:
            return {
                "status": "skipped",
                "reason": "stable_company_logo_already_available",
                "workspace_id": workspace_id,
                "company_key": company_key,
                "target_company": target_company,
                "stable_logo_asset_id": str(stable_logo_assets[0].get("asset_id") or ""),
                "candidate_count": 0,
                "eligible_command_count": 0,
                "module_state_mutated": False,
                "normal_path": True,
                "read_contract": {
                    "source": "CompanyAsset.logo_media",
                    "target": "no_op_existing_stable_logo",
                    "fallback_used": False,
                    "fail_closed": True,
                    "request_path_fetch": False,
                    "logo_source_discovery_required": False,
                },
            }
        candidates = _company_logo_experience_candidates_from_profile_payload(
            profile_payload,
            company_key=company_key,
            target_company=target_company,
            now_epoch=now_epoch,
            min_ttl_seconds=min_ttl_seconds,
            limit=limit,
        )
        eligible = [
            candidate
            for candidate in candidates
            if bool(candidate.get("eligible")) and _media_source_url_allowed(str(candidate.get("source_url") or ""))
        ]
        expired_count = sum(1 for candidate in candidates if str(candidate.get("rejection_reason") or "") == "expired_or_insufficient_ttl")
        if dry_run:
            return {
                "status": "dry_run",
                "reason": "profile_experience_logo_preview",
                "workspace_id": workspace_id,
                "company_key": company_key,
                "target_company": target_company,
                "collection_id": collection_id,
                "candidate_count": len(candidates),
                "eligible_command_count": len(eligible),
                "expired_or_insufficient_ttl_count": expired_count,
                "fallback_strategy": "logo_source_discovery" if not eligible else "",
                "commands": [
                    {
                        "source_url": str(candidate.get("source_url") or ""),
                        "company_name": str(candidate.get("company_name") or ""),
                        "expires_at_epoch": candidate.get("expires_at_epoch"),
                    }
                    for candidate in eligible[:100]
                ],
                "module_state_mutated": False,
                "normal_path": True,
                "read_contract": {
                    "source": "fresh_harvest_profile_experience.companyLogo",
                    "target": "CompanyEvidence.logo_url+workflow_commands(media.asset.cache)",
                    "fallback_used": not bool(eligible),
                    "fallback_source": "logo_source_discovery" if not eligible else "",
                    "fail_closed": True,
                    "request_path_fetch": False,
                    "existing_stable_logo_no_op": True,
                },
            }
        if not eligible:
            return {
                "status": "source_discovery_required",
                "reason": "profile_experience_logo_missing_or_expired",
                "workspace_id": workspace_id,
                "company_key": company_key,
                "target_company": target_company,
                "collection_id": collection_id,
                "candidate_count": len(candidates),
                "expired_or_insufficient_ttl_count": expired_count,
                "module_state_mutated": False,
                "normal_path": True,
                "fallback_strategy": "logo_source_discovery",
                "read_contract": {
                    "source": "fresh_harvest_profile_experience.companyLogo",
                    "target": "logo_source_discovery",
                    "fallback_used": True,
                    "fallback_source": "logo_source_discovery",
                    "fail_closed": True,
                    "request_path_fetch": False,
                    "historical_hotlink_rejected": True,
                },
            }

        workflow_run_id = str(normalized.get("workflow_run_id") or normalized.get("workflowRunId") or "").strip()
        if not workflow_run_id:
            workflow_run_id = "wf_profile_company_logo_" + hashlib.sha1(
                f"{workspace_id}:{company_key}:{target_company}:{source_run_id}:{source_profile_path}".encode("utf-8")
            ).hexdigest()[:24]
        batch_id = str(normalized.get("batch_id") or normalized.get("batchId") or "").strip()
        if not batch_id:
            batch_id = "profile_company_logo_" + hashlib.sha1(
                f"{workspace_id}:{company_key}:{target_company}:{workflow_run_id}".encode("utf-8")
            ).hexdigest()[:16]
        writer = CompanyAssetWriter(self.store, writer_id="profile_experience_logo_evidence_writer")
        evidence_rows: list[dict[str, Any]] = []
        commands: list[dict[str, Any]] = []
        if not skip_workflow_started:
            self.durable_runtime_writer.append_event_and_reduce(
                workflow_run_id=workflow_run_id,
                operation_id="",
                event_family="workflow_event",
                event_type="WorkflowStarted",
                idempotency_key=f"{workflow_run_id}:profile_company_logo_ingest_started",
                actor="profile_experience_logo_ingest",
                source="profile_experience_logo_ingest",
                payload={
                    "workflow_type": "media_asset_ingest",
                    "stage_key": default_stage_id_for_command_type(MEDIA_ASSET_CACHE_COMMAND_TYPE),
                    "workspace_id": workspace_id,
                    "company_key": company_key,
                    "target_company": target_company,
                    "collection_id": collection_id,
                    "source_run_id": source_run_id,
                    "source_command_id": source_command_id,
                    "batch_id": batch_id,
                    "normal_path": True,
                },
            )
        for candidate in eligible[:limit]:
            source_url = str(candidate.get("source_url") or "").strip()
            evidence_hash = hashlib.sha1(
                f"{workspace_id}:{company_key}:{source_url}:profile_experience_logo".encode("utf-8")
            ).hexdigest()[:24]
            evidence_id = f"ce_profile_logo_{evidence_hash}"
            evidence = writer.record_evidence(
                {
                    "evidence_id": evidence_id,
                    "workspace_id": workspace_id,
                    "company_key": company_key,
                    "target_company": target_company or str(candidate.get("company_name") or company_key),
                    "evidence_type": "logo_url",
                    "value": source_url,
                    "normalized_value": source_url,
                    "source_url": source_url,
                    "source_domain": _source_domain_from_url(source_url),
                    "confidence_score": 0.85,
                    "evidence_excerpt": str(candidate.get("evidence_excerpt") or "")[:1000],
                    "artifact_refs": {
                        "source_profile_path": source_profile_path,
                        "source_run_id": source_run_id,
                        "source_command_id": source_command_id,
                    },
                    "status": "observed",
                    "metadata": {
                        "source_kind": "profile_experience_company_logo",
                        "company_name": str(candidate.get("company_name") or ""),
                        "logo_kind": str(candidate.get("logo_kind") or ""),
                        "expires_at_epoch": candidate.get("expires_at_epoch"),
                        "expires_at": str(candidate.get("expires_at") or ""),
                        "min_ttl_seconds": min_ttl_seconds,
                        "collection_id": collection_id,
                        "normal_path": True,
                    },
                }
            )
            evidence_rows.append(evidence)
            command_payload = {
                "workspace_id": workspace_id,
                "entity_type": "company",
                "asset_type": "logo_media",
                "company_key": company_key,
                "target_company": target_company or str(candidate.get("company_name") or company_key),
                "source_url": source_url,
                "visibility_scope": "public_summary",
                "batch_id": batch_id,
                "source_kind": "profile_experience_company_logo",
                "source_evidence_id": evidence_id,
                "source_profile_run_id": source_run_id,
                "source_profile_command_id": source_command_id,
                "source_profile_path": source_profile_path,
                "causality": {
                    "source_kind": "profile_experience_company_logo",
                    "collection_id": collection_id,
                    "source_run_id": source_run_id,
                    "source_command_id": source_command_id,
                    "source_profile_path": source_profile_path,
                    "source_evidence_id": evidence_id,
                },
            }
            payload_hash = hashlib.sha1(
                json.dumps(command_payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
            ).hexdigest()[:24]
            idempotency_key = f"media.asset.cache:profile-company-logo:{company_key}:{payload_hash}"
            apply_result = self.durable_runtime_writer.append_event_and_reduce(
                workflow_run_id=workflow_run_id,
                operation_id="",
                event_family="workflow_event",
                event_type="CommandPlanRequested",
                idempotency_key=f"{idempotency_key}:plan",
                actor="profile_experience_logo_ingest",
                source="profile_experience_logo_ingest",
                payload={
                    "workflow_type": "media_asset_ingest",
                    "stage_key": default_stage_id_for_command_type(MEDIA_ASSET_CACHE_COMMAND_TYPE),
                    "command_type": MEDIA_ASSET_CACHE_COMMAND_TYPE,
                    "idempotency_key": idempotency_key,
                    "payload": command_payload,
                    "max_attempts": max(1, _coerce_int(normalized.get("max_attempts"), 3)),
                    "retry_policy": {"kind": "media_asset_cache_fresh_profile_logo", "retry_delay_seconds": 30},
                },
            )
            command = self._workflow_command_from_apply_result_or_store(
                apply_result=apply_result,
                workflow_run_id=workflow_run_id,
                idempotency_key=idempotency_key,
            )
            if command:
                commands.append(command)
        drain_result = {}
        if run_now and commands:
            drain_result = self._drain_media_asset_cache_commands(
                {"workflow_run_id": workflow_run_id, "command_limit": len(commands)}
            )
        return {
            "status": "planned",
            "reason": "profile_experience_logo_commands_planned",
            "workspace_id": workspace_id,
            "company_key": company_key,
            "target_company": target_company,
            "collection_id": collection_id,
            "workflow_run_id": workflow_run_id,
            "batch_id": batch_id,
            "candidate_count": len(candidates),
            "eligible_command_count": len(eligible),
            "evidence_count": len(evidence_rows),
            "planned_command_count": len(commands),
            "expired_or_insufficient_ttl_count": expired_count,
            "run_now": run_now,
            "drain_result": drain_result,
            "evidence": [
                {
                    "evidence_id": str(item.get("evidence_id") or ""),
                    "source_url": str(item.get("source_url") or ""),
                    "evidence_type": str(item.get("evidence_type") or ""),
                }
                for item in evidence_rows[:100]
            ],
            "commands": [
                self._workflow_command_observation(command, migration_phase="W11_profile_experience_company_logo")
                for command in commands[:100]
            ],
            "module_state_mutated": bool(evidence_rows or commands),
            "normal_path": True,
            "read_contract": {
                "source": "fresh_harvest_profile_experience.companyLogo",
                "target": "CompanyEvidence.logo_url+workflow_commands(media.asset.cache)",
                "fallback_used": False,
                "fail_closed": True,
                "request_path_fetch": False,
                "existing_stable_logo_no_op": True,
                "historical_hotlink_rejected": True,
            },
        }

    def _plan_company_logo_profile_experience_discover_command(
        self,
        *,
        job: dict[str, Any],
        request: JobRequest,
        snapshot_dir: Path,
        apply_result: dict[str, Any],
        worker_ids: list[int] | tuple[int, ...],
    ) -> dict[str, Any]:
        if not _env_bool("COMPANY_PROFILE_EXPERIENCE_LOGO_INGEST_ENABLED", True):
            return {"status": "skipped", "reason": "profile_experience_logo_ingest_disabled"}
        if not isinstance(snapshot_dir, Path):
            return {"status": "skipped", "reason": "snapshot_dir_missing"}
        harvest_profile_dir = snapshot_dir / "harvest_profiles"
        if not harvest_profile_dir.exists():
            return {"status": "skipped", "reason": "harvest_profiles_missing"}
        target_company = str(request.target_company or "").strip()
        company_key = normalize_company_key(target_company)
        if not company_key and not target_company:
            return {"status": "skipped", "reason": "target_company_missing"}
        stable_logo_assets = [
            asset
            for asset in self.store.list_company_assets(
                workspace_id="default",
                company_key=company_key,
                target_company=target_company,
                asset_type="logo_media",
                status="available",
                limit=10,
            )
            if _company_logo_media_asset_is_stable(asset)
        ]
        if stable_logo_assets:
            return {
                "status": "skipped",
                "reason": "stable_company_logo_already_available",
                "company_key": company_key,
                "target_company": target_company,
                "stable_logo_asset_id": str(stable_logo_assets[0].get("asset_id") or ""),
                "request_path_fetch": False,
                "non_blocking": True,
            }
        job_id = str(job.get("job_id") or "").strip()
        workflow_run_id = legacy_job_workflow_run_id(job_id)
        snapshot_id = str(snapshot_dir.name or "").strip()
        if not job_id or not workflow_run_id or not snapshot_id:
            return {"status": "skipped", "reason": "workflow_scope_missing", "request_path_fetch": False}
        applied_profile_url_keys = _dedupe_texts(
            normalize_linkedin_profile_url_key(str(value or ""))
            for value in list(apply_result.get("applied_profile_url_keys") or [])
            if normalize_linkedin_profile_url_key(str(value or ""))
        )
        source_worker_ids = [int(value) for value in list(worker_ids or []) if int(value or 0) > 0]
        idempotency_key = f"company.logo.profile_experience.discover:{workflow_run_id}:{company_key}:{snapshot_id}"
        self.durable_runtime_writer.append_event_and_reduce(
            workflow_run_id=workflow_run_id,
            operation_id="",
            event_family="workflow_event",
            event_type="WorkflowStarted",
            idempotency_key=f"{workflow_run_id}:company_logo_profile_discover_started",
            actor="profile_local_apply_owner",
            source="profile_company_logo_discover_planner",
            payload={
                "workflow_type": "company_asset_media_discovery",
                "stage_key": default_stage_id_for_command_type(
                    COMPANY_LOGO_PROFILE_EXPERIENCE_DISCOVER_COMMAND_TYPE
                ),
                "workspace_id": "default",
                "company_key": company_key,
                "target_company": target_company,
                "snapshot_id": snapshot_id,
                "snapshot_dir": str(snapshot_dir),
                "non_blocking": True,
            },
        )
        apply_plan = self.durable_runtime_writer.append_event_and_reduce(
            workflow_run_id=workflow_run_id,
            operation_id="",
            event_family="workflow_event",
            event_type="CommandPlanRequested",
            idempotency_key=f"{idempotency_key}:plan",
            actor="profile_local_apply_owner",
            source="profile_company_logo_discover_planner",
            payload={
                "workflow_type": "company_asset_media_discovery",
                "stage_key": default_stage_id_for_command_type(
                    COMPANY_LOGO_PROFILE_EXPERIENCE_DISCOVER_COMMAND_TYPE
                ),
                "command_type": COMPANY_LOGO_PROFILE_EXPERIENCE_DISCOVER_COMMAND_TYPE,
                "idempotency_key": idempotency_key,
                "payload": {
                    "workspace_id": "default",
                    "company_key": company_key,
                    "target_company": target_company,
                    "collection_id": f"company:{company_key}" if company_key else "",
                    "source_run_id": job_id,
                    "snapshot_id": snapshot_id,
                    "snapshot_dir": str(snapshot_dir),
                    "harvest_profile_dir": str(harvest_profile_dir),
                    "preferred_profile_url_keys": applied_profile_url_keys[:5],
                    "source_worker_ids": source_worker_ids,
                    "max_profile_payload_reads": 1,
                    "source_kind": "profile_experience_company_logo",
                    "request_path_fetch": False,
                    "non_blocking": True,
                    "causality": {
                        "source_kind": "profile_experience_company_logo",
                        "source_run_id": job_id,
                        "snapshot_id": snapshot_id,
                        "source_worker_ids": source_worker_ids,
                    },
                },
                "max_attempts": 2,
                "retry_policy": {
                    "kind": "company_logo_profile_experience_discover",
                    "retry_delay_seconds": 30,
                },
            },
        )
        command = self._workflow_command_from_apply_result_or_store(
            apply_result=apply_plan,
            workflow_run_id=workflow_run_id,
            idempotency_key=idempotency_key,
        )
        return {
            "status": "planned" if command else "skipped",
            "reason": (
                "company_logo_profile_experience_discover_command_planned"
                if command
                else "company_logo_profile_experience_discover_command_not_created"
            ),
            "company_key": company_key,
            "target_company": target_company,
            "workflow_run_id": workflow_run_id,
            "snapshot_id": snapshot_id,
            "worker_ids": source_worker_ids,
            "preferred_profile_url_key_count": len(applied_profile_url_keys),
            "request_path_fetch": False,
            "non_blocking": True,
            "workflow_command": self._workflow_command_observation(
                command,
                migration_phase="W11_company_logo_profile_experience_discover",
            ),
        }

    def _run_company_logo_profile_experience_discover_command(
        self,
        command: dict[str, Any],
        *,
        lease_seconds: int = 300,
    ) -> dict[str, Any]:
        command_payload = dict(command or {})
        command_id = str(command_payload.get("command_id") or "").strip()
        if not command_id:
            return {"status": "skipped", "reason": "company_logo_profile_discover_command_id_missing"}
        lease_owner = f"{COMPANY_ASSET_OWNER}-{uuid.uuid4().hex[:8]}"
        claimed = self.store.claim_workflow_command(
            command_id,
            lease_owner=lease_owner,
            lease_seconds=max(30, int(lease_seconds or 300)),
        )
        if not claimed:
            latest = self.store.get_workflow_command(command_id) or command_payload
            self._sync_operation_run_from_workflow_command(
                latest,
                actor=COMPANY_ASSET_OWNER,
                source="company_asset.command_owner",
            )
            return {
                "status": "skipped",
                "reason": "company_logo_profile_discover_command_not_claimed",
                "command_status": str(latest.get("status") or "").strip(),
                "workflow_command": self._workflow_command_observation(
                    latest,
                    migration_phase="W11_company_logo_profile_experience_discover",
                ),
            }
        self.store.mark_workflow_command_running(command_id, lease_owner=lease_owner)
        latest_command = self.store.get_workflow_command(command_id) or claimed
        payload = dict(latest_command.get("payload") or {})
        activity, attempt = self._start_workflow_command_activity_attempt(
            latest_command,
            activity_type=COMPANY_LOGO_PROFILE_EXPERIENCE_DISCOVER_COMMAND_TYPE,
            owner=COMPANY_ASSET_OWNER,
            phase="company_logo_profile_experience_discover_started",
            lease_owner=lease_owner,
            provider="local_profile_asset_reader",
            provider_request_ref=command_id,
            input_payload={
                "company_key": str(payload.get("company_key") or "").strip(),
                "target_company": str(payload.get("target_company") or "").strip(),
                "snapshot_id": str(payload.get("snapshot_id") or "").strip(),
                "max_profile_payload_reads": max(1, _coerce_int(payload.get("max_profile_payload_reads"), 1)),
            },
            entity_counts={"company_logo_discovery_count": 1},
            metadata={
                "activity_owner": COMPANY_ASSET_OWNER,
                "company_logo_contract": "profile_experience_logo_discover_owner_v1",
                "non_blocking": True,
            },
            attempt_suffix="company_logo_profile_experience_discover",
        )
        try:
            result = self._execute_company_logo_profile_experience_discover_command_payload(
                latest_command,
                activity=activity,
                attempt=attempt,
            )
        except Exception as exc:
            self._finish_workflow_command_activity_attempt(
                activity=activity,
                attempt=attempt,
                status="failed",
                phase="company_logo_profile_experience_discover_failed",
                output={"status": "failed", "reason": "company_logo_profile_discover_failed", "error": str(exc)},
                error={"reason": "company_logo_profile_discover_failed", "error": str(exc)},
                metadata={"company_asset_owner": COMPANY_ASSET_OWNER},
                attempt_status="failed",
            )
            failed = self.store.mark_workflow_command_failed(
                command_id,
                error_text=f"company_logo_profile_discover_failed:{exc}",
                retryable=True,
                retry_delay_seconds=30,
            )
            self._sync_operation_run_from_workflow_command(
                failed or latest_command,
                actor=COMPANY_ASSET_OWNER,
                source="company_asset.command_owner",
            )
            return {
                "status": "failed",
                "reason": "company_logo_profile_discover_failed",
                "error": str(exc),
                "workflow_command": self._workflow_command_observation(
                    failed or latest_command,
                    migration_phase="W11_company_logo_profile_experience_discover",
                ),
            }
        result_status = str(result.get("status") or "").strip()
        if result_status in {"invalid", "failed"}:
            self._finish_workflow_command_activity_attempt(
                activity=activity,
                attempt=attempt,
                status="failed",
                phase=str(result.get("reason") or "company_logo_profile_experience_discover_failed"),
                output=dict(result or {}),
                error={"reason": str(result.get("reason") or "company_logo_profile_discover_not_completed")},
                metadata={"company_asset_owner": COMPANY_ASSET_OWNER},
                attempt_status="failed",
            )
            failed = self.store.mark_workflow_command_failed(
                command_id,
                error_text=str(result.get("reason") or "company_logo_profile_discover_not_completed"),
                retryable=False,
                retry_delay_seconds=0,
            )
            self._sync_operation_run_from_workflow_command(
                failed or latest_command,
                actor=COMPANY_ASSET_OWNER,
                source="company_asset.command_owner",
            )
            return {
                **result,
                "status": "failed",
                "workflow_command": self._workflow_command_observation(
                    failed or latest_command,
                    migration_phase="W11_company_logo_profile_experience_discover",
                ),
            }
        entity_delta_id = self._record_company_logo_profile_experience_entity_delta(
            command=latest_command,
            activity=activity,
            attempt=attempt,
            result=result,
        )
        final_activity, final_attempt = self._finish_workflow_command_activity_attempt(
            activity=activity,
            attempt=attempt,
            status="succeeded",
            phase=str(result.get("reason") or result.get("status") or "company_logo_profile_experience_discovered"),
            output={**dict(result or {}), "entity_delta_id": entity_delta_id},
            entity_counts={
                "company_evidence_count": _coerce_int(result.get("evidence_count"), 0),
                "planned_media_command_count": _coerce_int(result.get("planned_command_count"), 0),
                "profile_payload_read_count": _coerce_int(result.get("profile_payload_read_count"), 0),
            },
            artifact_refs=[str(result.get("source_profile_path") or "")],
            metadata={"company_asset_owner": COMPANY_ASSET_OWNER, "non_blocking": True},
        )
        result = {
            **result,
            "status": "completed",
            "activity_run_id": str(final_activity.get("activity_run_id") or activity.get("activity_run_id") or ""),
            "attempt_id": str(final_attempt.get("attempt_id") or attempt.get("attempt_id") or ""),
            "entity_delta_id": entity_delta_id,
            "activity_spine_contract": "command_activity_attempt_entity_delta_v1",
        }
        succeeded = self.store.mark_workflow_command_succeeded(
            command_id,
            result={**result, "migration_phase": "W11_company_logo_profile_experience_discover"},
        )
        self._sync_operation_run_from_workflow_command(
            succeeded or latest_command,
            actor=COMPANY_ASSET_OWNER,
            source="company_asset.command_owner",
        )
        return {
            **result,
            "workflow_command": self._workflow_command_observation(
                succeeded or latest_command,
                migration_phase="W11_company_logo_profile_experience_discover",
            ),
        }

    def _execute_company_logo_profile_experience_discover_command_payload(
        self,
        command: dict[str, Any],
        *,
        activity: dict[str, Any],
        attempt: dict[str, Any],
    ) -> dict[str, Any]:
        command_payload = dict(command or {})
        payload = dict(command_payload.get("payload") or {})
        selection = self._select_company_logo_profile_payload_for_command(payload)
        profile_payload = dict(selection.get("profile_payload") or {})
        if not profile_payload:
            return {
                "status": "source_discovery_required",
                "reason": str(selection.get("reason") or "profile_payload_unavailable_for_logo_discovery"),
                "company_key": str(payload.get("company_key") or "").strip(),
                "target_company": str(payload.get("target_company") or "").strip(),
                "profile_payload_read_count": _coerce_int(selection.get("profile_payload_read_count"), 0),
                "profile_file_inspected_count": _coerce_int(selection.get("profile_file_inspected_count"), 0),
                "module_state_mutated": False,
                "fallback_strategy": "logo_source_discovery",
                "request_path_fetch": False,
                "non_blocking": True,
            }
        ingest = self.ingest_company_logo_from_profile_experience_api(
            {
                "workspace_id": str(payload.get("workspace_id") or "default").strip() or "default",
                "target_company": str(payload.get("target_company") or "").strip(),
                "company_key": str(payload.get("company_key") or "").strip(),
                "profile_payload": profile_payload,
                "source_profile_path": str(selection.get("source_profile_path") or ""),
                "source_run_id": str(payload.get("source_run_id") or ""),
                "source_command_id": str(command_payload.get("command_id") or ""),
                "collection_id": str(payload.get("collection_id") or ""),
                "workflow_run_id": str(command_payload.get("workflow_run_id") or ""),
                "dry_run": False,
                "run_now": False,
                "limit": 1,
                "skip_workflow_started": True,
            }
        )
        return {
            **ingest,
            "source": "company_logo_profile_experience_discover_owner",
            "source_profile_path": str(selection.get("source_profile_path") or ""),
            "profile_payload_read_count": _coerce_int(selection.get("profile_payload_read_count"), 0),
            "profile_file_inspected_count": _coerce_int(selection.get("profile_file_inspected_count"), 0),
            "request_path_fetch": False,
            "non_blocking": True,
            "activity_run_id": str(activity.get("activity_run_id") or ""),
            "attempt_id": str(attempt.get("attempt_id") or ""),
        }

    def _select_company_logo_profile_payload_for_command(self, payload: dict[str, Any]) -> dict[str, Any]:
        command_payload = dict(payload or {})
        harvest_profile_dir_value = str(command_payload.get("harvest_profile_dir") or "").strip()
        snapshot_dir_value = str(command_payload.get("snapshot_dir") or "").strip()
        if not harvest_profile_dir_value and not snapshot_dir_value:
            return {
                "status": "missing",
                "reason": "harvest_profile_dir_missing",
                "profile_payload_read_count": 0,
                "profile_file_inspected_count": 0,
            }
        harvest_profile_dir = Path(harvest_profile_dir_value) if harvest_profile_dir_value else Path()
        if not harvest_profile_dir_value and snapshot_dir_value:
            harvest_profile_dir = Path(snapshot_dir_value) / "harvest_profiles"
        if not harvest_profile_dir or not harvest_profile_dir.exists():
            return {
                "status": "missing",
                "reason": "harvest_profiles_missing",
                "profile_payload_read_count": 0,
                "profile_file_inspected_count": 0,
            }
        preferred_profile_url_keys = {
            normalize_linkedin_profile_url_key(str(value or ""))
            for value in list(command_payload.get("preferred_profile_url_keys") or [])
            if normalize_linkedin_profile_url_key(str(value or ""))
        }
        max_payload_reads = min(max(1, _coerce_int(command_payload.get("max_profile_payload_reads"), 1)), 1)
        max_file_inspects = max_payload_reads
        profile_paths = sorted(
            [path for path in harvest_profile_dir.glob("*.json") if path.is_file()],
            key=lambda path: path.stat().st_mtime if path.exists() else 0,
            reverse=True,
        )
        inspected_count = 0
        payload_read_count = 0
        first_payload: dict[str, Any] = {}
        first_path = ""
        for profile_path in profile_paths[:max_file_inspects]:
            inspected_count += 1
            profile_payload = _read_json_dict(profile_path)
            if not profile_payload:
                continue
            profile_url_key = _profile_payload_profile_url_key(profile_payload)
            if preferred_profile_url_keys and profile_url_key and profile_url_key not in preferred_profile_url_keys:
                continue
            payload_read_count += 1
            first_payload = profile_payload
            first_path = str(profile_path)
            break
        if not first_payload:
            return {
                "status": "missing",
                "reason": "matching_profile_payload_missing",
                "preferred_profile_url_key_count": len(preferred_profile_url_keys),
                "profile_payload_read_count": payload_read_count,
                "profile_file_inspected_count": inspected_count,
            }
        return {
            "status": "selected",
            "reason": "single_profile_payload_selected",
            "profile_payload": first_payload,
            "source_profile_path": first_path,
            "profile_payload_read_count": payload_read_count,
            "profile_file_inspected_count": inspected_count,
        }

    def _record_company_logo_profile_experience_entity_delta(
        self,
        *,
        command: dict[str, Any],
        activity: dict[str, Any],
        attempt: dict[str, Any],
        result: dict[str, Any],
    ) -> str:
        payload = dict(dict(command or {}).get("payload") or {})
        company_key = str(result.get("company_key") or payload.get("company_key") or "").strip()
        evidence_items = [dict(item) for item in list(result.get("evidence") or []) if isinstance(item, dict)]
        evidence_id = str(evidence_items[0].get("evidence_id") or "").strip() if evidence_items else ""
        entity_type = "company_evidence" if evidence_id else "company_logo_discovery"
        entity_key = evidence_id or company_key
        if not entity_key:
            return ""
        delta = self._record_command_activity_entity_delta(
            command=command,
            activity=activity,
            attempt=attempt,
            entity_type=entity_type,
            entity_key=entity_key,
            delta_kind="company_logo_profile_experience_discovered",
            status="recorded" if evidence_id else "no_op",
            reason=str(result.get("reason") or result.get("status") or "company_logo_profile_experience_discovered"),
            source_ref={
                "company_key": company_key,
                "target_company": str(result.get("target_company") or payload.get("target_company") or "").strip(),
                "source_profile_path": str(result.get("source_profile_path") or ""),
                "command_type": COMPANY_LOGO_PROFILE_EXPERIENCE_DISCOVER_COMMAND_TYPE,
            },
            entity_payload={
                "evidence_id": evidence_id,
                "evidence_count": _coerce_int(result.get("evidence_count"), 0),
                "planned_media_command_count": _coerce_int(result.get("planned_command_count"), 0),
                "fallback_strategy": str(result.get("fallback_strategy") or ""),
            },
            projection_effect={"entered_projection": False, "company_media_cache_planned": bool(evidence_id)},
            artifact_refs=[str(result.get("source_profile_path") or "")],
            metadata={"company_asset_owner": COMPANY_ASSET_OWNER, "non_blocking": True},
            idempotency_scope="company_logo_profile_experience_discover",
        )
        return str(delta.get("delta_id") or "").strip()

    def _drain_company_logo_profile_experience_discover_commands(
        self,
        payload: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        payload = dict(payload or {})
        if not _env_bool("COMPANY_LOGO_PROFILE_EXPERIENCE_DISCOVER_COMMAND_OWNER_ENABLED", True):
            return {
                "status": "skipped",
                "reason": "company_logo_profile_experience_discover_command_owner_disabled",
                "owner": COMPANY_ASSET_OWNER,
                "command_type": COMPANY_LOGO_PROFILE_EXPERIENCE_DISCOVER_COMMAND_TYPE,
                "command_count": 0,
                "executed_command_count": 0,
                "completed_count": 0,
                "failed_count": 0,
                "legacy_bridge_used": False,
                "migration_phase": "W11_company_logo_profile_experience_discover",
            }
        workflow_run_id = str(payload.get("workflow_run_id") or "").strip()
        limit = max(
            1,
            _coerce_int(
                payload.get("command_limit")
                or payload.get("company_logo_profile_experience_discover_command_limit"),
                10,
            ),
        )
        ready_commands = self.store.list_ready_workflow_commands(
            workflow_run_id=workflow_run_id,
            owner=COMPANY_ASSET_OWNER,
            command_type=COMPANY_LOGO_PROFILE_EXPERIENCE_DISCOVER_COMMAND_TYPE,
            limit=limit,
        )
        results: list[dict[str, Any]] = []
        completed_count = 0
        failed_count = 0
        for command in ready_commands:
            result = self._run_company_logo_profile_experience_discover_command(
                dict(command),
                lease_seconds=max(30, _env_int("COMPANY_LOGO_PROFILE_EXPERIENCE_DISCOVER_COMMAND_LEASE_SECONDS", 300)),
            )
            results.append(result)
            if str(result.get("status") or "") == "completed":
                completed_count += 1
            elif str(result.get("status") or "") == "failed":
                failed_count += 1
        return {
            "status": "active" if ready_commands else "idle",
            "reason": (
                "company_logo_profile_experience_discover_command_owner"
                if ready_commands
                else "no_ready_company_logo_profile_experience_discover_commands"
            ),
            "workflow_run_id": workflow_run_id,
            "command_count": len(ready_commands),
            "executed_command_count": len(results),
            "completed_count": completed_count,
            "failed_count": failed_count,
            "owner": COMPANY_ASSET_OWNER,
            "command_type": COMPANY_LOGO_PROFILE_EXPERIENCE_DISCOVER_COMMAND_TYPE,
            "legacy_bridge_used": False,
            "migration_phase": "W11_company_logo_profile_experience_discover",
            "items": results,
        }

    def get_legacy_result_endpoint_retirement_status(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        query = dict(payload or {})
        source_run_id = str(query.get("job_id") or query.get("run_id") or "").strip()
        projection_id = str(query.get("projection_id") or "").strip()
        missing_links: list[str] = []
        legacy_endpoints = [
            "/api/jobs/{job_id}/results",
            "/api/jobs/{job_id}/dashboard",
            "/api/jobs/{job_id}/candidates",
            "/api/jobs/{job_id}/candidates/{candidate_id}",
        ]
        if source_run_id:
            link = self.store.get_run_projection_link(source_run_id)
            if not link:
                missing_links.append(source_run_id)
            elif not projection_id:
                projection_id = str(link.get("projection_id") or "").strip()
        projection_ready = False
        if projection_id:
            projection_payload = self.serving_projection_reader.get_projection(projection_id)
            projection_ready = str(projection_payload.get("status") or "") == "ready"
        explicit_cutover_value = os.getenv("SOURCING_RETIRE_LEGACY_JOB_RESULT_ENDPOINTS")
        legacy_override_allowed = _env_bool("SOURCING_ALLOW_LEGACY_JOB_RESULT_ENDPOINTS", False)
        ready_for_cutover = projection_ready and not missing_links
        if legacy_override_allowed:
            cutover_mode = False
        elif explicit_cutover_value is not None:
            cutover_mode = _env_bool("SOURCING_RETIRE_LEGACY_JOB_RESULT_ENDPOINTS", False)
        else:
            cutover_mode = True
        status = "ready_for_cutover" if (projection_ready and not missing_links) else "migration_required"
        if cutover_mode and status == "ready_for_cutover":
            status = "cutover_enforced"
        elif cutover_mode and status == "migration_required":
            status = "retired_migration_required"
        return {
            "status": status,
            "cutover_enforced": cutover_mode,
            "cutover_defaulted_from_projection": bool(
                cutover_mode and explicit_cutover_value is None and not legacy_override_allowed and ready_for_cutover
            ),
            "cutover_defaulted_to_migration_required": bool(
                cutover_mode and explicit_cutover_value is None and not legacy_override_allowed and not ready_for_cutover
            ),
            "legacy_override_allowed": legacy_override_allowed,
            "source_run_id": source_run_id,
            "projection_id": projection_id,
            "projection_ready": projection_ready,
            "missing_run_projection_links": missing_links,
            "legacy_endpoints": legacy_endpoints,
            "normal_serving_allowed": not cutover_mode,
            "retirement_contract": {
                "steady_state": "projection_routes_only",
                "legacy_behavior_after_cutover": "projection_pointer_or_migration_required_410",
                "public_reader_fallback_allowed": False,
            },
            "read_contract": {
                "source": "run_projection_links+serving_projections",
                "fallback_used": False,
                "fail_closed": True,
            },
        }

    def get_legacy_public_web_retirement_status(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        query = dict(payload or {})
        return audit_legacy_public_web_retirement(
            store=self.store,
            workspace_id=str(query.get("workspace_id") or "default").strip() or "default",
            row_limit=max(1, _coerce_int(query.get("row_limit") or query.get("limit"), 10000)),
            sample_limit=max(1, _coerce_int(query.get("sample_limit"), 25)),
        )

    def get_job_candidate_page(
        self,
        job_id: str,
        *,
        offset: int = 0,
        limit: int = 120,
        lightweight: bool = False,
        candidate_filter: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        context = self._build_job_results_context(job_id)
        if context is None:
            return None
        normalized_offset = max(int(offset or 0), 0)
        normalized_limit = min(max(int(limit or 0), 1), 250)
        normalized_candidate_filter = self._normalize_candidate_page_filter(candidate_filter)
        filter_active = self._candidate_page_filter_active(normalized_candidate_filter)
        filter_signature = self._candidate_page_filter_signature(normalized_candidate_filter)
        review_status_lookup = self._candidate_review_status_lookup_for_filter(job_id)
        candidate_page_delay_ms = max(0, _env_int("SOURCING_TEST_CANDIDATE_PAGE_DELAY_MS", 0))
        if candidate_page_delay_ms > 0:
            time.sleep(min(candidate_page_delay_ms, 5_000) / 1000.0)
        request = context.get("request") or JobRequest.from_payload({})
        candidate_source = dict(context.get("candidate_source") or {})
        effective_execution_semantics = dict(context.get("effective_execution_semantics") or {})
        publishable_email_lookup = context.get("publishable_email_lookup")
        linkedin_stage_1_progress = dict(context.get("linkedin_stage_1_progress") or {})
        ranked_result_count = self.store.count_job_results(job_id)
        public_projection = self._build_public_board_runtime_projection(
            job_id=job_id,
            context=context,
            ranked_result_count=ranked_result_count,
        )
        result_mode = str(public_projection.get("result_mode") or "").strip() or "ranked_results"
        board_runtime_state_for_order = dict(public_projection.get("board_runtime_state") or {})
        prioritize_display_ready_filtered_rows = bool(
            str(board_runtime_state_for_order.get("phase") or "").strip() != "current_snapshot_serving"
            or (
                int(board_runtime_state_for_order.get("display_ready_candidate_count") or 0)
                < int(board_runtime_state_for_order.get("published_candidate_count") or 0)
            )
        )
        if result_mode == "asset_population":
            asset_population_page = self._build_job_asset_population_page_from_canonical_projection(
                job_id=job_id,
                result_view_lifecycle=dict(public_projection.get("result_view_lifecycle") or {}),
                result_view=dict(context.get("result_view") or {}),
                candidate_source=candidate_source,
                public_projection=public_projection,
                candidate_filter=normalized_candidate_filter,
                offset=normalized_offset,
                limit=normalized_limit,
            )
            if asset_population_page:
                pass
            elif filter_active:
                overlay_payload = self._load_candidate_source_asset_population_overlay(candidate_source)
                if overlay_payload and list(overlay_payload.get("candidates") or []):
                    overlay_path = self._candidate_source_asset_population_overlay_path(candidate_source)
                    asset_population_page = {
                        "available": True,
                        "target_company": str(
                            overlay_payload.get("target_company") or request.target_company or ""
                        ).strip(),
                        "snapshot_id": str(
                            overlay_payload.get("snapshot_id") or candidate_source.get("snapshot_id") or ""
                        ).strip(),
                        "asset_view": str(
                            overlay_payload.get("asset_view")
                            or candidate_source.get("asset_view")
                            or request.asset_view
                            or "canonical_merged"
                        ).strip()
                        or "canonical_merged",
                        "source_kind": "job_asset_population_overlay",
                        "source_path": str(overlay_path or ""),
                        "candidate_count": int(
                            overlay_payload.get("candidate_count")
                            or len(list(overlay_payload.get("candidates") or []))
                            or 0
                        ),
                        "profile_fetch_progress": dict(overlay_payload.get("profile_fetch_progress") or {}),
                        "card_materialization_summary": dict(
                            overlay_payload.get("card_materialization_summary") or {}
                        ),
                        "facet_summary": self._normalize_public_layer_zero_facet_summary(
                            dict(overlay_payload.get("facet_summary") or {})
                        ),
                        "facet_summary_scope": str(
                            overlay_payload.get("facet_summary_scope") or "current_served_partial"
                        ).strip(),
                        "filter_contract": self._candidate_page_filter_contract(
                            applied_filter=normalized_candidate_filter,
                            filter_signature=filter_signature,
                        ),
                        "candidates": [
                            dict(item)
                            for item in list(overlay_payload.get("candidates") or [])
                            if isinstance(item, dict)
                        ],
                    }
                else:
                    asset_population_page = self._build_job_asset_population_payload(
                        request=request,
                        candidate_source=candidate_source,
                        effective_execution_semantics=effective_execution_semantics,
                        publishable_email_lookup=publishable_email_lookup,
                        offset=0,
                        limit=0,
                        include_candidates=True,
                        load_profile_timeline=False,
                    )
                all_candidates = [
                    dict(item) for item in list(asset_population_page.get("candidates") or []) if isinstance(item, dict)
                ]
                profile_enrich_max_rows = max(0, _env_int("JOB_RESULTS_FILTER_PROFILE_ENRICH_MAX_ROWS", 500))
                profile_progress_expected = max(
                    0,
                    _coerce_int(board_runtime_state_for_order.get("profile_fetch_required_count"), 0),
                    _coerce_int(board_runtime_state_for_order.get("delta_profile_required_count"), 0),
                    _coerce_int(
                        dict(public_projection.get("result_view_lifecycle") or {}).get("delta_profile_required_count"),
                        0,
                    ),
                )
                compact_profile_rows_need_hydration = bool(
                    profile_progress_expected > 0
                    and len(all_candidates) <= profile_enrich_max_rows
                    and (
                        int(board_runtime_state_for_order.get("display_ready_candidate_count") or 0)
                        < int(board_runtime_state_for_order.get("published_candidate_count") or 0)
                        or str(board_runtime_state_for_order.get("row_publication_tier") or "").strip()
                        in {"lifecycle", "partial_patch"}
                    )
                )
                profile_enrichment_required = bool(
                    str(normalized_candidate_filter.get("search_keyword") or "").strip()
                    or compact_profile_rows_need_hydration
                )
                if profile_enrichment_required:
                    # Result search needs profile text. Facet-only filtering
                    # must not hydrate every profile row: large canonical
                    # boards can answer recall/layer/audit filters from the
                    # served projection and source-match metadata.
                    all_candidates = self._enrich_candidate_records_from_profile_registry(all_candidates)
                filtered_candidates = self._apply_candidate_page_filter(
                    candidates=all_candidates,
                    candidate_filter=normalized_candidate_filter,
                    intent_keywords=list(request.keywords or []) + list(request.organization_keywords or []),
                    review_status_lookup=review_status_lookup,
                )
                if prioritize_display_ready_filtered_rows:
                    filtered_candidates = self._prioritize_candidate_page_display_ready_records(filtered_candidates)
                paged_candidates = filtered_candidates[normalized_offset : normalized_offset + normalized_limit]
                if not lightweight:
                    rich_candidates: list[dict[str, Any]] = []
                    job_payload = dict(context.get("job") or {})
                    for candidate in paged_candidates:
                        candidate_id = str(candidate.get("candidate_id") or "").strip()
                        rich_candidate = (
                            self._load_job_asset_population_candidate_record(
                                job=job_payload,
                                candidate_id=candidate_id,
                                load_profile_timeline=True,
                                publishable_email_lookup=publishable_email_lookup,
                            )
                            if candidate_id
                            else None
                        )
                        rich_candidates.append(dict(rich_candidate or candidate))
                    paged_candidates = rich_candidates
                next_offset = normalized_offset + len(paged_candidates)
                has_more = next_offset < len(filtered_candidates)
                asset_population_page = {
                    **asset_population_page,
                    "offset": normalized_offset,
                    "limit": len(paged_candidates),
                    "returned_count": len(paged_candidates),
                    "has_more": has_more,
                    "next_offset": next_offset if has_more else None,
                    "filtered_candidate_count": len(filtered_candidates),
                    "filter_signature": filter_signature,
                    "applied_filter": dict(normalized_candidate_filter),
                    "filter_contract": self._candidate_page_filter_contract(
                        applied_filter=normalized_candidate_filter,
                        filter_signature=filter_signature,
                    ),
                    "candidates": paged_candidates,
                }
            else:
                asset_population_page = self._build_job_asset_population_payload(
                    request=request,
                    candidate_source=candidate_source,
                    effective_execution_semantics=effective_execution_semantics,
                    publishable_email_lookup=publishable_email_lookup,
                    offset=normalized_offset,
                    limit=normalized_limit,
                    include_candidates=True,
                    load_profile_timeline=not lightweight,
                )
            asset_population_page = self._merge_public_projection_fields_into_asset_population(
                asset_population_page,
                public_projection,
            )
            total_candidates = int(asset_population_page.get("candidate_count") or 0)
            candidates = list(asset_population_page.get("candidates") or [])
            filtered_candidate_count = int(asset_population_page.get("filtered_candidate_count") or total_candidates)
            canonical_total_candidates = self._canonical_public_projection_candidate_count(
                result_view_lifecycle=public_projection.get("result_view_lifecycle"),
                board_runtime_state=public_projection.get("board_runtime_state"),
            )
            if canonical_total_candidates > 0:
                total_candidates = canonical_total_candidates
                if not filter_active:
                    filtered_candidate_count = canonical_total_candidates
                else:
                    filtered_candidate_count = min(filtered_candidate_count, canonical_total_candidates)
            result_view_lifecycle = dict(public_projection.get("result_view_lifecycle") or {})
            board_runtime_state = dict(public_projection.get("board_runtime_state") or {})
            linkedin_stage_1_progress = dict(public_projection.get("linkedin_stage_1_progress") or {})
            next_offset = normalized_offset + len(candidates)
            has_more = next_offset < filtered_candidate_count
            canonical_filter_contract = {
                **dict(asset_population_page.get("filter_contract") or {}),
                "filter_signature": str(asset_population_page.get("filter_signature") or filter_signature),
                "filter_active": filter_active,
            }
            return {
                "job_id": job_id,
                "result_mode": "asset_population",
                "offset": normalized_offset,
                "limit": normalized_limit,
                "returned_count": len(candidates),
                "total_candidates": total_candidates,
                "filtered_candidate_count": filtered_candidate_count,
                "has_more": has_more,
                "next_offset": next_offset if has_more else None,
                "profile_fetch_progress": dict(asset_population_page.get("profile_fetch_progress") or {}),
                "card_materialization_summary": dict(
                    asset_population_page.get("card_materialization_summary") or {}
                ),
                "result_view_lifecycle": result_view_lifecycle,
                "board_runtime_state": board_runtime_state,
                "linkedin_stage_1_progress": linkedin_stage_1_progress,
                "provider_execution_manifest": dict(context.get("provider_execution_manifest") or {}),
                "facet_summary": dict(asset_population_page.get("facet_summary") or {}),
                "facet_summary_scope": str(asset_population_page.get("facet_summary_scope") or "").strip(),
                "filter_signature": str(asset_population_page.get("filter_signature") or filter_signature),
                "applied_filter": dict(asset_population_page.get("applied_filter") or normalized_candidate_filter),
                "filter_contract": canonical_filter_contract,
                "candidates": candidates,
            }

        if filter_active:
            ranked_source_records = [
                self._serialize_candidate_api_record(
                    record,
                    load_profile_timeline=not lightweight,
                    publishable_email_lookup=publishable_email_lookup,
                )
                for record in self.store.get_job_results_page(
                    job_id,
                    offset=0,
                    limit=max(ranked_result_count, 1),
                    include_evidence=False,
                )
            ]
            filtered_ranked_results = self._apply_candidate_page_filter(
                candidates=ranked_source_records,
                candidate_filter=normalized_candidate_filter,
                intent_keywords=list(request.keywords or []) + list(request.organization_keywords or []),
                review_status_lookup=review_status_lookup,
            )
            ranked_results = filtered_ranked_results[normalized_offset : normalized_offset + normalized_limit]
            filtered_ranked_count = len(filtered_ranked_results)
        else:
            ranked_results = [
                self._serialize_candidate_api_record(
                    record,
                    load_profile_timeline=not lightweight,
                    publishable_email_lookup=publishable_email_lookup,
                )
                for record in self.store.get_job_results_page(
                    job_id,
                    offset=normalized_offset,
                    limit=normalized_limit,
                    include_evidence=False,
                )
            ]
            filtered_ranked_count = ranked_result_count
        next_offset = normalized_offset + len(ranked_results)
        ranked_result_view_lifecycle = dict(public_projection.get("result_view_lifecycle") or {})
        ranked_board_runtime_state = dict(public_projection.get("board_runtime_state") or {})
        ranked_linkedin_stage_1_progress = dict(public_projection.get("linkedin_stage_1_progress") or {})
        return {
            "job_id": job_id,
            "result_mode": "ranked_results",
            "offset": normalized_offset,
            "limit": normalized_limit,
            "returned_count": len(ranked_results),
            "total_candidates": ranked_result_count,
            "filtered_candidate_count": filtered_ranked_count,
            "has_more": next_offset < filtered_ranked_count,
            "next_offset": next_offset if next_offset < filtered_ranked_count else None,
            "profile_fetch_progress": self._build_profile_fetch_progress_payload(ranked_results),
            "result_view_lifecycle": ranked_result_view_lifecycle,
            "board_runtime_state": ranked_board_runtime_state,
            "linkedin_stage_1_progress": ranked_linkedin_stage_1_progress,
            "provider_execution_manifest": dict(context.get("provider_execution_manifest") or {}),
            "filter_signature": filter_signature,
            "applied_filter": dict(normalized_candidate_filter),
            "filter_contract": self._candidate_page_filter_contract(
                applied_filter=normalized_candidate_filter,
                filter_signature=filter_signature,
            ),
                "candidates": ranked_results,
        }

    def _build_job_asset_population_page_from_canonical_projection(
        self,
        *,
        job_id: str,
        result_view_lifecycle: dict[str, Any],
        result_view: dict[str, Any],
        candidate_source: dict[str, Any],
        public_projection: dict[str, Any],
        candidate_filter: dict[str, Any],
        offset: int,
        limit: int,
    ) -> dict[str, Any]:
        serving_projection_payload = self._load_job_canonical_serving_projection_payload(
            job_id=job_id,
            result_view_lifecycle=result_view_lifecycle,
            result_view=result_view,
            candidate_source=candidate_source,
        )
        projection = dict(dict(serving_projection_payload or {}).get("projection") or {})
        projection_id = str(projection.get("projection_id") or "").strip()
        if not projection_id:
            return {}
        projection_page = self.serving_projection_reader.get_projection_candidates(
            projection_id,
            offset=offset,
            limit=limit,
            candidate_filter=candidate_filter,
        )
        status = str(projection_page.get("status") or "").strip()
        if status == "not_ready":
            return {
                "available": True,
                "source_kind": "serving_projection_members",
                "source_path": projection_id,
                "candidate_count": _coerce_int(projection.get("visible_member_count"), 0),
                "offset": offset,
                "limit": 0,
                "returned_count": 0,
                "filtered_candidate_count": 0,
                "has_more": False,
                "next_offset": None,
                "facet_summary": dict(dict(public_projection.get("asset_population") or {}).get("facet_summary") or {}),
                "facet_summary_scope": str(
                    dict(public_projection.get("asset_population") or {}).get("facet_summary_scope") or ""
                ).strip(),
                "filter_signature": str(projection_page.get("filter_signature") or ""),
                "applied_filter": dict(projection_page.get("applied_filter") or candidate_filter),
                "filter_contract": dict(projection_page.get("filter_contract") or {}),
                "read_contract": dict(projection_page.get("read_contract") or {}),
                "status": "not_ready",
                "reason": str(projection_page.get("reason") or "projection_person_search_index_unavailable"),
                "candidates": [],
            }
        if status != "ready":
            return {}
        canonical_asset_population = dict(public_projection.get("asset_population") or {})
        rows = [
            self._projection_candidate_page_row_to_legacy_candidate(row)
            for row in list(projection_page.get("candidates") or [])
            if isinstance(row, dict)
        ]
        facet_summary = dict(canonical_asset_population.get("facet_summary") or projection_page.get("facet_summary") or {})
        facet_summary_scope = str(
            canonical_asset_population.get("facet_summary_scope")
            or (
                "global_full_population"
                if str(facet_summary.get("status") or "") == "complete"
                else "unavailable"
            )
        ).strip()
        return {
            "available": True,
            "default_selected": True,
            "source_kind": "serving_projection_members",
            "snapshot_id": str(result_view_lifecycle.get("current_snapshot_id") or candidate_source.get("snapshot_id") or ""),
            "asset_view": str(candidate_source.get("asset_view") or "canonical_merged").strip() or "canonical_merged",
            "source_path": projection_id,
            "candidate_count": int(projection_page.get("total_candidates") or projection_page.get("candidate_count") or 0),
            "offset": int(projection_page.get("offset") or offset),
            "limit": len(rows),
            "returned_count": len(rows),
            "filtered_candidate_count": int(
                projection_page.get("filtered_candidate_count")
                or projection_page.get("total_candidates")
                or projection_page.get("candidate_count")
                or 0
            ),
            "has_more": bool(projection_page.get("has_more")),
            "next_offset": projection_page.get("next_offset"),
            "profile_fetch_progress": dict(canonical_asset_population.get("profile_fetch_progress") or {}),
            "card_materialization_summary": dict(canonical_asset_population.get("card_materialization_summary") or {}),
            "facet_summary_scope": facet_summary_scope,
            "facet_summary": facet_summary,
            "filter_signature": str(projection_page.get("filter_signature") or ""),
            "applied_filter": dict(projection_page.get("applied_filter") or candidate_filter),
            "filter_contract": dict(projection_page.get("filter_contract") or {}),
            "index_filter_readiness": dict(projection_page.get("index_filter_readiness") or {}),
            "read_contract": {
                **dict(projection_page.get("read_contract") or {}),
                "source": str(dict(projection_page.get("read_contract") or {}).get("source") or "serving_projection_members"),
                "fallback_used": bool(dict(projection_page.get("read_contract") or {}).get("fallback_used")),
                "fail_closed": True,
            },
            "candidates": rows,
        }

    @staticmethod
    def _projection_candidate_page_row_to_legacy_candidate(row: dict[str, Any]) -> dict[str, Any]:
        payload = dict(row or {})
        public_summary = dict(payload.get("public_summary") or {})
        projection_metrics = dict(payload.get("projection_metrics") or {})
        crm_overlay_summary = dict(payload.get("crm_overlay_summary") or {})
        candidate_id = (
            str(payload.get("candidate_id") or "").strip()
            or str(public_summary.get("candidate_id") or public_summary.get("id") or "").strip()
            or str(payload.get("candidate_identity_key") or "").strip()
        )
        display_name = str(
            public_summary.get("display_name")
            or public_summary.get("name")
            or public_summary.get("name_en")
            or candidate_id
        ).strip()
        linkedin_url = str(
            public_summary.get("linkedin_url")
            or public_summary.get("profile_url")
            or public_summary.get("url")
            or ""
        ).strip()
        employment_status = str(
            payload.get("employment_scope")
            or public_summary.get("employment_status")
            or public_summary.get("status")
            or ""
        ).strip()
        record = {
            **public_summary,
            "candidate_id": candidate_id,
            "id": candidate_id,
            "display_name": display_name,
            "name": str(public_summary.get("name") or display_name).strip(),
            "linkedin_url": linkedin_url,
            "employment_status": employment_status,
            "source_dataset": str(payload.get("source_shard_key") or payload.get("lane") or "").strip(),
            "projection_id": str(payload.get("projection_id") or "").strip(),
            "candidate_identity_key": str(payload.get("candidate_identity_key") or "").strip(),
            "person_identity_key": str(payload.get("person_identity_key") or "").strip(),
            "profile_url_key": str(payload.get("profile_url_key") or "").strip(),
            "rank_index": int(payload.get("rank_index") or 0),
            "rank_key": str(payload.get("rank_key") or "").strip(),
            "row_readiness": str(payload.get("row_readiness") or "").strip(),
            "profile_readiness": str(payload.get("profile_readiness") or "").strip(),
            "card_readiness": str(payload.get("card_readiness") or "").strip(),
            "visibility_state": str(payload.get("visibility_state") or "").strip(),
            "crm_overlay_summary": crm_overlay_summary,
            "public_summary": public_summary,
            "projection_metrics": projection_metrics,
        }
        for key in (
            "has_profile_detail",
            "needs_profile_completion",
            "low_profile_richness",
            "has_explicit_profile_capture",
            "display_ready",
        ):
            if key not in record and key in projection_metrics:
                record[key] = projection_metrics.get(key)
        return record

    def get_job_board_visible_patch_log(
        self,
        job_id: str,
        *,
        after_published_at: str = "",
        after_sequence: int = 0,
        limit: int = 50,
    ) -> dict[str, Any] | None:
        context = self._build_job_results_context(job_id)
        if context is None:
            return None
        public_projection = self._build_public_board_runtime_projection(
            job_id=job_id,
            context=context,
            ranked_result_count=self.store.count_job_results(job_id),
        )
        result_view_lifecycle = dict(public_projection.get("result_view_lifecycle") or {})
        board_runtime_state = dict(public_projection.get("board_runtime_state") or {})
        patches = self.store.list_job_board_visible_patches(job_id=job_id, limit=0)
        patches = sorted(
            patches,
            key=lambda patch: (
                int(patch.get("sequence_index") or 0),
                _parse_timestamp(str(patch.get("published_at") or "")) or datetime.min.replace(tzinfo=timezone.utc),
                str(patch.get("patch_id") or ""),
            ),
        )
        after_dt = _parse_timestamp(str(after_published_at or ""))
        normalized_after_sequence = max(0, int(after_sequence or 0))
        filtered_patches: list[dict[str, Any]] = []
        for patch in patches:
            published_dt = _parse_timestamp(str(patch.get("published_at") or ""))
            patch_sequence = int(patch.get("sequence_index") or 0)
            if normalized_after_sequence > 0:
                if patch_sequence <= normalized_after_sequence:
                    continue
            elif after_dt is not None:
                if published_dt is not None and published_dt < after_dt:
                    continue
                if published_dt is not None and published_dt == after_dt:
                    continue
            filtered_patches.append(patch)
        max_limit = min(max(int(limit or 50), 1), 200)
        public_patches = [self._build_public_board_visible_patch_payload(patch) for patch in filtered_patches[:max_limit]]
        latest_patch = public_patches[-1] if public_patches else {}
        latest_known_patch = self._build_public_board_visible_patch_payload(patches[-1]) if patches else {}
        return {
            "job_id": job_id,
            "patches": public_patches,
            "returned_count": len(public_patches),
            "has_more": len(filtered_patches) > len(public_patches),
            "latest_published_at": str(
                latest_patch.get("published_at") or latest_known_patch.get("published_at") or ""
            ),
            "latest_sequence_index": int(
                latest_patch.get("sequence_index") or latest_known_patch.get("sequence_index") or 0
            ),
            "board_runtime_state": board_runtime_state,
            "result_view_lifecycle": result_view_lifecycle,
        }

    def _build_public_board_visible_patch_payload(self, patch: dict[str, Any]) -> dict[str, Any]:
        payload = dict(patch or {})
        card_summary = (
            self._candidate_card_materialization_summary_from_patch_metadata(payload)
            or self._build_candidate_card_materialization_summary_from_board_visible_patch(payload)
        )
        return {
            "patch_id": str(payload.get("patch_id") or ""),
            "job_id": str(payload.get("job_id") or ""),
            "snapshot_id": str(payload.get("snapshot_id") or ""),
            "baseline_snapshot_id": str(payload.get("baseline_snapshot_id") or ""),
            "patch_kind": str(payload.get("patch_kind") or ""),
            "patch_phase": str(payload.get("patch_phase") or ""),
            "reason": str(payload.get("reason") or ""),
            "sequence_index": int(payload.get("sequence_index") or 0),
            "candidate_count": int(payload.get("candidate_count") or 0),
            "cumulative_candidate_count": int(payload.get("cumulative_candidate_count") or 0),
            "served_candidate_count": int(payload.get("served_candidate_count") or 0),
            "display_ready_candidate_count": int(card_summary.get("display_ready_candidate_count") or 0),
            "profile_detail_candidate_count": int(card_summary.get("profile_detail_candidate_count") or 0),
            "explicit_profile_capture_candidate_count": int(
                card_summary.get("explicit_profile_capture_candidate_count") or 0
            ),
            "preview_candidate_count": int(card_summary.get("preview_candidate_count") or 0),
            "needs_profile_completion_candidate_count": int(
                card_summary.get("needs_profile_completion_candidate_count") or 0
            ),
            "low_profile_richness_candidate_count": int(card_summary.get("low_profile_richness_candidate_count") or 0),
            "quality_fields_available": bool(card_summary.get("quality_fields_available")),
            "serving_projection_phase": str(payload.get("serving_projection_phase") or ""),
            "published_at": str(payload.get("published_at") or ""),
        }

    def _build_candidate_card_materialization_summary_from_board_visible_patch(
        self,
        patch: dict[str, Any],
    ) -> dict[str, Any]:
        frozen_summary = self._candidate_card_materialization_summary_from_patch_metadata(patch)
        if frozen_summary:
            return frozen_summary
        overlay_path_value = str(dict(patch or {}).get("overlay_path") or "").strip()
        if overlay_path_value:
            overlay_path = Path(overlay_path_value).expanduser()
            if overlay_path.exists() and not overlay_path.is_dir():
                overlay_payload = self._load_asset_population_overlay_payload_from_path(overlay_path)
                overlay_records = [
                    dict(item) for item in list(dict(overlay_payload or {}).get("candidates") or []) if isinstance(item, dict)
                ]
                overlay_records = self._normalize_board_visible_profile_records(overlay_records)
                if overlay_records:
                    cumulative_ids = [
                        str(item or "").strip()
                        for item in list(dict(patch or {}).get("cumulative_candidate_ids") or [])
                        if str(item or "").strip()
                    ]
                    if cumulative_ids:
                        by_id = {
                            str(record.get("candidate_id") or record.get("id") or "").strip(): record
                            for record in overlay_records
                        }
                        selected_records = [by_id[item] for item in cumulative_ids if item in by_id]
                    else:
                        selected_records = overlay_records
                    if selected_records:
                        return self._build_candidate_card_materialization_summary_from_records(selected_records)
        return self._build_candidate_card_materialization_summary_from_serving_projection(
            job_id=str(dict(patch or {}).get("job_id") or ""),
            latest_patch=patch,
            fallback_candidate_count=int(
                dict(patch or {}).get("served_candidate_count")
                or dict(patch or {}).get("cumulative_candidate_count")
                or dict(patch or {}).get("candidate_count")
                or 0
            ),
        )

    def _frontend_history_phase_from_job(self, job: dict[str, Any] | None) -> str:
        if not isinstance(job, dict) or not job:
            return "plan"
        status = str(job.get("status") or "").strip().lower()
        if status == "completed":
            job_id = str(job.get("job_id") or "").strip()
            if job_id and self._job_active_background_worker_count(job_id) > 0:
                return "running"
            return "results"
        return "running"

    def _job_active_background_worker_count(self, job_id: str) -> int:
        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return 0
        try:
            workers = self.store.list_agent_workers(job_id=normalized_job_id)
        except Exception:
            return 0
        return _active_background_worker_count_from_summary(_job_worker_summary(workers))

    def _resolve_frontend_history_phase(self, *, job: dict[str, Any] | None, preferred_phase: str = "") -> str:
        resolved_job_phase = self._frontend_history_phase_from_job(job)
        normalized_preferred_phase = str(preferred_phase or "").strip()
        if not normalized_preferred_phase:
            return resolved_job_phase
        if normalized_preferred_phase == "results" and resolved_job_phase == "running":
            return "running"
        return normalized_preferred_phase

    def _persist_frontend_history_link(
        self,
        *,
        history_id: str,
        query_text: str = "",
        target_company: str = "",
        review_id: int = 0,
        job_id: str = "",
        phase: str = "",
        request_payload: dict[str, Any] | None = None,
        plan_payload: dict[str, Any] | None = None,
        metadata: dict[str, Any] | None = None,
        merge_metadata: bool = False,
    ) -> dict[str, Any] | None:
        normalized_history_id = str(history_id or "").strip()
        if not normalized_history_id:
            return None
        resolved_metadata = dict(metadata or {})
        if merge_metadata:
            existing = self.store.get_frontend_history_link(normalized_history_id)
            resolved_metadata = _merge_nested_payloads(dict((existing or {}).get("metadata") or {}), resolved_metadata)
        return self.store.upsert_frontend_history_link(
            {
                "history_id": normalized_history_id,
                "query_text": str(query_text or "").strip(),
                "target_company": str(target_company or "").strip(),
                "review_id": int(review_id or 0),
                "job_id": str(job_id or "").strip(),
                "phase": str(phase or "").strip(),
                "request": dict(request_payload or {}),
                "plan": dict(plan_payload or {}),
                "metadata": resolved_metadata,
            }
        )

    def _sync_frontend_history_phase_for_job(
        self,
        *,
        job: dict[str, Any] | None = None,
        phase: str = "",
    ) -> None:
        job_payload = dict(job or {})
        job_id = str(job_payload.get("job_id") or "").strip()
        if not job_id:
            return
        request_payload = dict(job_payload.get("request") or {})
        plan_payload = dict(job_payload.get("plan") or {})
        resolved_phase = self._resolve_frontend_history_phase(job=job_payload, preferred_phase=phase)
        if not resolved_phase:
            return
        query_text = str(request_payload.get("raw_user_request") or request_payload.get("query") or "").strip()
        target_company = str(request_payload.get("target_company") or "").strip()
        for link in self.store.list_frontend_history_links_for_job(job_id, limit=50):
            history_id = str(link.get("history_id") or "").strip()
            if not history_id:
                continue
            self._persist_frontend_history_link(
                history_id=history_id,
                query_text=query_text or str(link.get("query_text") or "").strip(),
                target_company=target_company or str(link.get("target_company") or "").strip(),
                review_id=int(link.get("review_id") or 0),
                job_id=job_id,
                phase=resolved_phase,
                request_payload=request_payload or dict(link.get("request") or {}),
                plan_payload=plan_payload or dict(link.get("plan") or {}),
                metadata=dict(link.get("metadata") or {}),
            )

    def get_frontend_history_recovery(self, history_id: str) -> dict[str, Any]:
        normalized_history_id = str(history_id or "").strip()
        if not normalized_history_id:
            return {"status": "invalid", "reason": "history_id is required"}
        resolved = self.store.resolve_frontend_history_link(normalized_history_id)
        if resolved is None:
            return {"status": "not_found", "history_id": normalized_history_id}
        review_id = int(resolved.get("review_id") or 0)
        job_id = str(resolved.get("job_id") or "").strip()
        review_session = self.store.get_plan_review_session(review_id) if review_id > 0 else None
        job = self.store.get_job(job_id) if job_id else None
        request_payload = dict(resolved.get("request") or {})
        plan_payload = dict(resolved.get("plan") or {})
        if not request_payload and review_session is not None:
            request_payload = dict(review_session.get("request") or {})
        if not plan_payload and review_session is not None:
            plan_payload = dict(review_session.get("plan") or {})
        if not request_payload and job is not None:
            request_payload = dict(job.get("request") or {})
        if not plan_payload and job is not None:
            plan_payload = dict(job.get("plan") or {})
        query_text = (
            str(resolved.get("query_text") or "").strip() or str(request_payload.get("raw_user_request") or "").strip()
        )
        target_company = (
            str(resolved.get("target_company") or "").strip()
            or str(request_payload.get("target_company") or "").strip()
            or str((review_session or {}).get("target_company") or "").strip()
        )
        if job is not None:
            phase = self._frontend_history_phase_from_job(job)
        elif review_session is not None or request_payload or plan_payload:
            phase = "plan"
        else:
            phase = str(resolved.get("phase") or "").strip() or "idle"
        metadata = dict(resolved.get("metadata") or {})
        plan_generation = dict(metadata.get("plan_generation") or {})
        error_message = str(plan_generation.get("error_message") or "").strip()
        if job is not None:
            request_preview = _load_job_request_preview(job)
        elif request_payload and plan_payload:
            try:
                request = JobRequest.from_payload(request_payload)
                plan = hydrate_sourcing_plan(plan_payload)
                request_preview = _build_request_preview_payload(
                    request=request,
                    effective_request=_build_effective_retrieval_request(request, plan),
                )
            except Exception:
                request_preview = _build_request_preview_payload(request=request_payload)
        elif request_payload:
            request_preview = _build_request_preview_payload(request=request_payload)
        else:
            request_preview = {}
        return {
            "status": "found",
            "recovery": {
                "history_id": normalized_history_id,
                "source": str(resolved.get("source") or ""),
                "query_text": query_text,
                "target_company": target_company,
                "review_id": review_id,
                "job_id": job_id,
                "phase": phase,
                "request": request_payload,
                "plan": plan_payload,
                "plan_review_gate": dict((review_session or {}).get("gate") or {}),
                "plan_review_session": _plan_review_session_api_summary(review_session),
                "request_preview": request_preview,
                "metadata": metadata,
                "error_message": error_message,
                "job": _job_api_summary(job),
                "created_at": _serialize_api_timestamp(str(resolved.get("created_at") or "")),
                "updated_at": _serialize_api_timestamp(str(resolved.get("updated_at") or "")),
            },
        }

    def list_frontend_history(self, *, limit: int = 24) -> dict[str, Any]:
        try:
            resolved_limit = max(1, min(int(limit or 24), 100))
        except (TypeError, ValueError):
            resolved_limit = 24
        history: list[dict[str, Any]] = []
        for row in self.store.list_frontend_history_links(limit=resolved_limit):
            history_id = str(row.get("history_id") or "").strip()
            if not history_id:
                continue
            recovered = self.get_frontend_history_recovery(history_id)
            if recovered.get("status") != "found":
                continue
            history.append(dict(recovered.get("recovery") or {}))
        return {
            "history": history[:resolved_limit],
            "count": len(history[:resolved_limit]),
        }

    def delete_frontend_history(self, history_id: str) -> dict[str, Any]:
        normalized_history_id = str(history_id or "").strip()
        if not normalized_history_id:
            return {"status": "invalid", "reason": "history_id is required"}
        deleted = self.store.delete_frontend_history_link(normalized_history_id)
        return {
            "status": "deleted" if deleted else "not_found",
            "history_id": normalized_history_id,
        }

    def _maybe_promote_workflow_job_to_completed_from_final_results(
        self,
        job: dict[str, Any],
    ) -> dict[str, Any]:
        if str(job.get("job_type") or "") != "workflow":
            return job
        status = str(job.get("status") or "").strip().lower()
        if status in {"failed", "superseded", "cancelled", "canceled"}:
            return job
        if status in {"completed", "results"} and self._job_is_terminal(job):
            return job
        job_id = str(job.get("job_id") or "").strip()
        if not job_id:
            return job

        workflow_stage_summaries = self._load_workflow_stage_summaries(job=job)
        stage2_final_summary = dict(dict(workflow_stage_summaries.get("summaries") or {}).get("stage_2_final") or {})
        job_summary = dict(job.get("summary") or {})
        if str(job_summary.get("awaiting_user_action") or "").strip():
            return job
        if str(stage2_final_summary.get("analysis_stage") or "").strip().lower() not in {"", "stage_2_final"}:
            return job
        if str(stage2_final_summary.get("status") or "").strip().lower() != "completed":
            return job
        result_count = self.store.count_job_results(job_id)
        manual_review_count = self.store.count_manual_review_items(job_id=job_id, status="")
        if result_count <= 0 and manual_review_count <= 0:
            return job
        promotion_blockers = self._workflow_completion_promotion_blockers(job)
        if promotion_blockers:
            return job

        request = JobRequest.from_payload(dict(job.get("request") or {}))
        plan_payload = dict(job.get("plan") or {})
        final_summary = self._persist_completed_workflow_summary(
            job_id=job_id,
            request=request,
            plan=plan_payload,
            artifact={
                "summary": stage2_final_summary,
                "artifact_path": str(job.get("artifact_path") or stage2_final_summary.get("artifact_path") or ""),
            },
            preserved_summary=job_summary,
        )
        if bool(final_summary.get("workflow_completion_deferred")):
            self.store.update_agent_runtime_session_status(job_id, "running")
            self._sync_frontend_history_phase_for_job(
                job={
                    **job,
                    "status": "running",
                    "stage": "retrieving",
                },
                phase="results",
            )
        else:
            self.store.update_agent_runtime_session_status(job_id, "completed")
            self._sync_frontend_history_phase_for_job(
                job={
                    **job,
                    "status": "completed",
                    "stage": "completed",
                },
                phase="results",
            )
            completed_events = self.store.list_job_events(job_id, stage="completed", limit=1, descending=True)
            if not completed_events:
                self.store.append_job_event(
                    job_id,
                    "completed",
                    "completed",
                    "Workflow completed after results reconciliation.",
                    final_summary,
                )
        return self.store.get_job(job_id) or job

    def _workflow_completion_policy_evaluation(
        self,
        job: dict[str, Any],
        *,
        ignore_workflow_lease: bool = False,
    ) -> dict[str, Any]:
        job_id = str(dict(job or {}).get("job_id") or "").strip()
        if not job_id:
            return {
                "status": "blocked",
                "job_id": job_id,
                "policy_version": _LINKEDIN_COMPLETION_POLICY_VERSION,
                "first_blocker": {"reason": "job_id_missing"},
                "policies": {},
            }

        workflow_owner_blocker: dict[str, Any] = {}
        if not ignore_workflow_lease:
            try:
                workflow_job_lease = self.store.get_workflow_job_lease(job_id)
            except Exception:
                return {
                    "status": "blocked",
                    "job_id": job_id,
                    "policy_version": _LINKEDIN_COMPLETION_POLICY_VERSION,
                    "first_blocker": {"reason": "workflow_job_lease_lookup_unavailable"},
                    "policies": {},
                }
            if workflow_job_lease:
                lease_payload = dict(workflow_job_lease)
                lease_owner = str(lease_payload.get("lease_owner") or "").strip()
                owner_dead_local_process = workflow_job_lease_owner_is_dead_local_process(lease_owner)
                lease_alive = _workflow_job_lease_is_alive(lease_payload) and not owner_dead_local_process
                if lease_alive:
                    workflow_owner_blocker = {
                        "reason": "active_workflow_owner_present",
                        "lease_owner": lease_owner,
                        "lease_heartbeat_age_seconds": _workflow_job_lease_heartbeat_age_seconds(lease_payload),
                    }

        try:
            workers = self.store.list_agent_workers(job_id=job_id)
        except Exception:
            return {
                "status": "blocked",
                "job_id": job_id,
                "policy_version": _LINKEDIN_COMPLETION_POLICY_VERSION,
                "first_blocker": {"reason": "worker_lookup_unavailable"},
                "policies": {},
            }
        worker_summary = _job_worker_summary(workers)
        active_worker_count = _active_background_worker_count_from_summary(worker_summary)
        blocked_task = str(dict(job.get("summary") or {}).get("blocked_task") or "").strip()
        blocking_workers = _progress_blocking_workers(workers, blocked_task=blocked_task)

        lifecycle_row = self.store.get_job_result_lifecycle(job_id)
        patch_projection: dict[str, Any] = {}
        if lifecycle_row:
            current_snapshot_id = str(dict(lifecycle_row).get("current_snapshot_id") or "").strip()
            patch_projection = self._job_board_visible_patch_progress_projection(
                job_id=job_id,
                snapshot_id=current_snapshot_id,
            )

        materialization_items = self.store.list_job_materialization_items(job_id=job_id, limit=500)
        linkedin_stage_1_progress = self._build_linkedin_stage1_progress_payload(job=job, workers=workers)
        workflow_state_unavailable = False
        try:
            workflow_state = self.store.get_workflow_current_state(legacy_job_workflow_run_id(job_id)) or {}
        except Exception:
            workflow_state_unavailable = True
            workflow_state = {}
        evaluation = _evaluate_linkedin_completion_policies(
            job_id=job_id,
            workflow_owner_blocker=workflow_owner_blocker,
            active_worker_count=active_worker_count,
            blocking_worker_count=len(blocking_workers),
            blocked_task=blocked_task,
            lifecycle=dict(lifecycle_row or {}),
            patch_projection=patch_projection,
            materialization_items=materialization_items,
            blocking_materialization_item_kinds=_WORKFLOW_COMPLETION_BLOCKING_MATERIALIZATION_ITEM_KINDS,
            linkedin_stage_1_progress=linkedin_stage_1_progress,
            workflow_current_state=workflow_state,
        )
        if workflow_state_unavailable:
            first_blocker = dict(evaluation.get("first_blocker") or {})
            if str(first_blocker.get("reason") or "") == "serving_finalized_proof_missing":
                first_blocker["reason"] = "serving_finalized_proof_unavailable"
                evaluation["first_blocker"] = first_blocker
                serving_policy = dict(dict(evaluation.get("policies") or {}).get("serving_finalized") or {})
                serving_policy["reason"] = "serving_finalized_proof_unavailable"
                policies = dict(evaluation.get("policies") or {})
                policies["serving_finalized"] = serving_policy
                evaluation["policies"] = policies
        return evaluation

    def _workflow_completion_promotion_blockers(
        self,
        job: dict[str, Any],
        *,
        ignore_workflow_lease: bool = False,
    ) -> dict[str, Any]:
        job_id = str(job.get("job_id") or "").strip()
        if not job_id:
            return {"reason": "job_id_missing"}
        completion_policy = self._workflow_completion_policy_evaluation(
            job,
            ignore_workflow_lease=ignore_workflow_lease,
        )
        blocker = _completion_policy_first_blocker(completion_policy)
        if blocker:
            blocker["completion_policy"] = completion_policy
            return blocker
        return {}

    def _build_effective_execution_semantics(
        self,
        *,
        request: JobRequest,
        organization_execution_profile: dict[str, Any],
        asset_reuse_plan: dict[str, Any],
        candidate_source: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        return compile_execution_semantics(
            request=request,
            organization_execution_profile=organization_execution_profile,
            asset_reuse_plan=asset_reuse_plan,
            candidate_source=candidate_source,
        )

    def _build_job_asset_population_payload(
        self,
        *,
        request: JobRequest,
        candidate_source: dict[str, Any],
        effective_execution_semantics: dict[str, Any],
        publishable_email_lookup: dict[str, dict[str, dict[str, Any]]] | None = None,
        offset: int = 0,
        limit: int | None = None,
        include_candidates: bool = True,
        load_profile_timeline: bool = True,
        fallback_candidate_count: int = 0,
        include_facet_summary: bool = True,
    ) -> dict[str, Any]:
        candidate_source = dict(candidate_source or {})
        asset_population_supported = bool(dict(effective_execution_semantics or {}).get("asset_population_supported"))
        can_fallback_to_snapshot_population = bool(
            str(request.target_company or "").strip() and candidate_source_is_snapshot_authoritative(candidate_source)
        )
        if not asset_population_supported and not can_fallback_to_snapshot_population:
            return {"available": False, "candidate_count": 0, "candidates": []}
        target_company = str(request.target_company or "").strip()
        snapshot_id = str(candidate_source.get("snapshot_id") or "").strip()
        asset_view = (
            str(candidate_source.get("asset_view") or request.asset_view or "canonical_merged").strip()
            or "canonical_merged"
        )
        if not target_company or not snapshot_id:
            return {"available": False, "candidate_count": 0, "candidates": []}
        normalized_offset = max(int(offset or 0), 0)
        if not include_candidates:
            return self._build_job_asset_population_summary_payload(
                request=request,
                candidate_source=candidate_source,
                effective_execution_semantics=effective_execution_semantics,
                fallback_candidate_count=fallback_candidate_count,
                include_facet_summary=include_facet_summary,
            )
        normalized_limit = max(int(limit or 0), 0) if limit is not None else 0
        cache_key = self._asset_population_cache_key(
            target_company=target_company,
            snapshot_id=snapshot_id,
            asset_view=asset_view,
            candidate_source=candidate_source,
        )
        if normalized_offset == 0 and normalized_limit == 0:
            with self._asset_population_payload_cache_lock:
                cached_payload = self._asset_population_payload_cache.get(cache_key)
            if cached_payload is not None:
                payload = dict(cached_payload)
                if include_facet_summary:
                    payload["facet_summary"] = self._build_asset_population_facet_summary_payload(
                        request=request,
                        candidate_source=candidate_source,
                        effective_execution_semantics=effective_execution_semantics,
                        publishable_email_lookup=publishable_email_lookup,
                    )
                return payload
        overlay_payload = self._load_candidate_source_asset_population_overlay(candidate_source)
        if overlay_payload:
            overlay_candidate_source = dict(candidate_source)
            if overlay_payload.get(
                "job_scoped_candidate_markers"
            ) and not self._normalized_job_scoped_candidate_markers(overlay_candidate_source):
                overlay_candidate_source["job_scoped_candidate_markers"] = list(
                    overlay_payload.get("job_scoped_candidate_markers") or []
                )
            summary_payload = self._build_job_asset_population_summary_payload(
                request=request,
                candidate_source=overlay_candidate_source,
                effective_execution_semantics=effective_execution_semantics,
                fallback_candidate_count=fallback_candidate_count,
                include_facet_summary=include_facet_summary,
            )
            overlay_candidates = [
                dict(item) for item in list(overlay_payload.get("candidates") or []) if isinstance(item, dict)
            ]
            total_candidates = int(overlay_payload.get("candidate_count") or len(overlay_candidates) or 0)
            if normalized_limit > 0:
                page_records = overlay_candidates[normalized_offset : normalized_offset + normalized_limit]
            else:
                page_records = overlay_candidates[normalized_offset:]
            page_records = self._enrich_overlay_candidate_records_from_materialized_sources(
                request=request,
                candidate_source=overlay_candidate_source,
                overlay_payload=overlay_payload,
                records=page_records,
            )
            page_records = self._enrich_candidate_records_from_profile_registry(page_records)
            self._attach_snapshot_outreach_layering_metadata_to_records(
                request=request,
                candidate_source=overlay_candidate_source,
                records=page_records,
            )
            self._annotate_job_scoped_candidate_markers_on_records(
                records=page_records,
                candidate_source=overlay_candidate_source,
            )
            timeline_preview_limit = (
                max(0, _env_int("JOB_RESULTS_ASSET_TIMELINE_PREVIEW_LIMIT", 96)) if load_profile_timeline else 0
            )
            serialized_candidates = [
                self._serialize_asset_population_candidate_api_record(
                    dict(record),
                    load_profile_timeline=bool(
                        load_profile_timeline and index < timeline_preview_limit
                    ),
                    publishable_email_lookup=publishable_email_lookup,
                )
                for index, record in enumerate(page_records)
            ]
            next_offset = normalized_offset + len(serialized_candidates)
            has_more = next_offset < total_candidates
            summary_facet_summary = dict(summary_payload.get("facet_summary") or {})
            summary_facet_scope = str(summary_payload.get("facet_summary_scope") or "").strip()
            if include_facet_summary and summary_facet_summary:
                facet_summary = summary_facet_summary
                facet_summary_scope = summary_facet_scope or "current_served_partial"
            elif include_facet_summary and summary_facet_scope and summary_facet_scope != "global_full_population":
                facet_summary = {}
                facet_summary_scope = summary_facet_scope
            elif include_facet_summary:
                facet_summary = self._build_asset_population_facet_summary_payload(
                    request=request,
                    candidate_source=overlay_candidate_source,
                    effective_execution_semantics=effective_execution_semantics,
                    publishable_email_lookup=publishable_email_lookup,
                )
                facet_summary_scope = "global_full_population" if facet_summary else "unavailable"
            else:
                facet_summary = {}
                facet_summary_scope = ""
            payload = {
                "available": True,
                "default_selected": str(dict(effective_execution_semantics or {}).get("default_results_mode") or "")
                .strip()
                .lower()
                == "asset_population",
                "source_kind": "job_asset_population_overlay",
                "snapshot_id": str(overlay_payload.get("snapshot_id") or snapshot_id),
                "asset_view": str(overlay_payload.get("asset_view") or asset_view),
                "source_path": str(self._candidate_source_asset_population_overlay_path(candidate_source) or ""),
                "candidate_count": total_candidates,
                "offset": normalized_offset,
                "limit": len(serialized_candidates),
                "has_more": has_more,
                "next_offset": next_offset if has_more else None,
                "profile_fetch_progress": dict(summary_payload.get("profile_fetch_progress") or {}),
                "card_materialization_summary": dict(
                    summary_payload.get("card_materialization_summary") or {}
                ),
                "facet_summary_scope": facet_summary_scope,
                "facet_summary": facet_summary,
                "candidates": serialized_candidates,
            }
            if normalized_offset == 0 and normalized_limit == 0:
                with self._asset_population_payload_cache_lock:
                    self._asset_population_payload_cache[cache_key] = payload
            return payload
        artifact_store = None
        try:
            artifact_store = (
                self._open_public_serving_artifact_store_from_candidate_source(
                    request=request,
                    candidate_source=candidate_source,
                    target_company=target_company,
                    snapshot_id=snapshot_id,
                    asset_view=asset_view,
                )
                or open_snapshot_artifact_store(
                    runtime_dir=self.runtime_dir,
                    target_company=target_company,
                    snapshot_id=snapshot_id,
                    asset_view=asset_view,
                )
            )
            try:
                snapshot_window = read_snapshot_candidate_window(
                    artifact_store,
                    offset=normalized_offset,
                    limit=normalized_limit,
                )
            except CandidateArtifactError:
                snapshot_window = read_snapshot_materialized_candidate_window(
                    artifact_store,
                    offset=normalized_offset,
                    limit=normalized_limit,
                )
        except CandidateArtifactError:
            snapshot_window = {}
        if snapshot_window:
            summary_payload = self._build_job_asset_population_summary_payload(
                request=request,
                candidate_source=candidate_source,
                effective_execution_semantics=effective_execution_semantics,
                fallback_candidate_count=fallback_candidate_count,
                include_facet_summary=include_facet_summary,
            )
            page_records = [
                dict(item) for item in list(snapshot_window.get("candidates") or []) if isinstance(item, dict)
            ]
            self._attach_snapshot_outreach_layering_metadata_to_records(
                request=request,
                candidate_source=candidate_source,
                records=page_records,
            )
            self._annotate_job_scoped_candidate_markers_on_records(
                records=page_records,
                candidate_source=candidate_source,
            )
            total_candidates = int(snapshot_window.get("total_candidate_count") or 0)
            timeline_preview_limit = (
                max(0, _env_int("JOB_RESULTS_ASSET_TIMELINE_PREVIEW_LIMIT", 96)) if load_profile_timeline else 0
            )
            serialized_candidates = [
                self._serialize_asset_population_candidate_api_record(
                    record,
                    load_profile_timeline=bool(
                        load_profile_timeline and index < timeline_preview_limit
                    ),
                    publishable_email_lookup=publishable_email_lookup,
                )
                for index, record in enumerate(page_records)
            ]
            next_offset = normalized_offset + len(serialized_candidates)
            has_more = next_offset < total_candidates
            artifact_source_path = str(snapshot_window.get("source_path") or "").strip() or (
                str(artifact_store.artifact_dir / "manifest.json")
                if artifact_store is not None
                else str(candidate_source.get("source_path") or "").strip()
            )
            artifact_source_kind = str(
                snapshot_window.get("source_kind") or "materialized_candidate_documents_manifest"
            ).strip()
            payload = {
                "available": True,
                "default_selected": str(dict(effective_execution_semantics or {}).get("default_results_mode") or "")
                .strip()
                .lower()
                == "asset_population",
                "source_kind": artifact_source_kind,
                "snapshot_id": snapshot_id,
                "asset_view": asset_view,
                "source_path": artifact_source_path,
                "candidate_count": total_candidates,
                "offset": normalized_offset,
                "limit": len(serialized_candidates),
                "has_more": has_more,
                "next_offset": next_offset if has_more else None,
                "profile_fetch_progress": dict(summary_payload.get("profile_fetch_progress") or {}),
                "card_materialization_summary": dict(
                    summary_payload.get("card_materialization_summary") or {}
                ),
                "facet_summary_scope": "global_full_population",
                "facet_summary": self._build_asset_population_facet_summary_payload(
                    request=request,
                    candidate_source=candidate_source,
                    effective_execution_semantics=effective_execution_semantics,
                    publishable_email_lookup=publishable_email_lookup,
                )
                if include_facet_summary
                else {},
                "candidates": serialized_candidates,
            }
            if normalized_offset == 0 and normalized_limit == 0:
                with self._asset_population_payload_cache_lock:
                    self._asset_population_payload_cache[cache_key] = payload
            return payload
        serving_proof = self._candidate_source_public_serving_artifact_proof(
            {
                **candidate_source,
                "target_company": target_company,
                "snapshot_id": snapshot_id,
                "asset_view": asset_view,
            }
        )
        return {
            "available": False,
            "default_selected": False,
            "source_kind": str(candidate_source.get("source_kind") or "").strip(),
            "snapshot_id": snapshot_id,
            "asset_view": asset_view,
            "source_path": str(candidate_source.get("source_path") or "").strip(),
            "candidate_count": 0,
            "offset": normalized_offset,
            "limit": 0,
            "has_more": False,
            "next_offset": None,
            "status": "public_serving_artifact_missing",
            "reason": "candidate_documents_not_public_serving_artifact",
            "public_serving_artifact_proof": serving_proof,
            "profile_fetch_progress": self._build_profile_fetch_progress_payload([]),
            "card_materialization_summary": {},
            "facet_summary_scope": "unavailable",
            "facet_summary": {},
            "candidates": [],
        }

    def _load_asset_population_candidate_shard_payload(
        self,
        *,
        request: JobRequest,
        candidate_source: dict[str, Any],
        effective_execution_semantics: dict[str, Any],
        candidate_id: str,
    ) -> dict[str, Any] | None:
        asset_population_supported = bool(dict(effective_execution_semantics or {}).get("asset_population_supported"))
        can_fallback_to_snapshot_population = bool(
            str(request.target_company or "").strip() and candidate_source_is_snapshot_authoritative(candidate_source)
        )
        if not asset_population_supported and not can_fallback_to_snapshot_population:
            return None
        overlay_payload = self._load_candidate_source_asset_population_overlay(candidate_source)
        if overlay_payload:
            overlay_candidates = {
                str(dict(item).get("candidate_id") or "").strip(): dict(item)
                for item in list(overlay_payload.get("candidates") or [])
                if isinstance(item, dict) and str(dict(item).get("candidate_id") or "").strip()
            }
            candidate_record = dict(overlay_candidates.get(str(candidate_id or "").strip()) or {})
            if candidate_record:
                candidate_record = self._enrich_overlay_candidate_records_from_materialized_sources(
                    request=request,
                    candidate_source=candidate_source,
                    overlay_payload=overlay_payload,
                    records=[candidate_record],
                )[0]
                candidate_record = self._enrich_candidate_records_from_profile_registry([candidate_record])[0]
                evidence_lookup = dict(overlay_payload.get("evidence_lookup") or {})
                return {
                    "candidate_id": str(candidate_record.get("candidate_id") or "").strip(),
                    "snapshot_id": str(overlay_payload.get("snapshot_id") or candidate_source.get("snapshot_id") or ""),
                    "asset_view": str(overlay_payload.get("asset_view") or candidate_source.get("asset_view") or ""),
                    "normalized_candidate": dict(candidate_record),
                    "materialized_candidate": dict(candidate_record),
                    "evidence": [
                        dict(item)
                        for item in list(
                            evidence_lookup.get(str(candidate_record.get("candidate_id") or "").strip()) or []
                        )
                        if isinstance(item, dict)
                    ],
                }
        target_company = str(request.target_company or "").strip()
        snapshot_id = str(candidate_source.get("snapshot_id") or "").strip()
        asset_view = (
            str(candidate_source.get("asset_view") or request.asset_view or "canonical_merged").strip()
            or "canonical_merged"
        )
        if not target_company or not snapshot_id:
            return None
        try:
            artifact_store = (
                self._open_public_serving_artifact_store_from_candidate_source(
                    request=request,
                    candidate_source=candidate_source,
                    target_company=target_company,
                    snapshot_id=snapshot_id,
                    asset_view=asset_view,
                )
                or open_snapshot_artifact_store(
                    runtime_dir=self.runtime_dir,
                    target_company=target_company,
                    snapshot_id=snapshot_id,
                    asset_view=asset_view,
                )
            )
            return read_snapshot_candidate_shard(artifact_store, candidate_id=candidate_id)
        except CandidateArtifactError:
            return None

    def _merge_asset_population_candidate_shard_record(self, shard_payload: dict[str, Any]) -> dict[str, Any]:
        normalized_record = dict(dict(shard_payload or {}).get("normalized_candidate") or {})
        materialized_record = dict(dict(shard_payload or {}).get("materialized_candidate") or {})
        if not normalized_record and not materialized_record:
            return {}
        merged = dict(normalized_record)
        for key, value in materialized_record.items():
            if key == "metadata":
                continue
            if value not in (None, "", [], {}):
                merged[key] = value
        merged_metadata = dict(normalized_record.get("metadata") or {})
        merged_metadata.update(dict(materialized_record.get("metadata") or {}))
        if merged_metadata:
            merged["metadata"] = merged_metadata
        return merged

    def _load_job_asset_population_candidate_record(
        self,
        *,
        job: dict[str, Any],
        candidate_id: str,
        load_profile_timeline: bool = True,
        publishable_email_lookup: dict[str, dict[str, dict[str, Any]]] | None = None,
    ) -> dict[str, Any] | None:
        normalized_candidate_id = str(candidate_id or "").strip()
        if not normalized_candidate_id:
            return None
        workflow_stage_summaries = self._load_workflow_stage_summaries(job=job)
        plan_payload = dict(job.get("plan") or {})
        job_summary = dict(job.get("summary") or {})
        stage1_preview_summary = dict(
            dict(workflow_stage_summaries.get("summaries") or {}).get("stage_1_preview") or {}
        )
        request = JobRequest.from_payload(dict(job.get("request") or {}))
        asset_reuse_plan = dict(plan_payload.get("asset_reuse_plan") or {})
        candidate_source, _ = self._resolve_job_candidate_source(
            job=job,
            request=request,
            job_summary=job_summary,
            stage1_preview_summary=stage1_preview_summary,
        )
        organization_execution_profile = self._organization_execution_profile_from_plan_payload(
            plan_payload=plan_payload,
            request=request,
            candidate_source=candidate_source,
        )
        if publishable_email_lookup is None:
            publishable_email_lookup = self._snapshot_publishable_email_lookup_for_request(
                request=request,
                candidate_source=candidate_source,
            )
        effective_execution_semantics = self._build_effective_execution_semantics(
            request=request,
            organization_execution_profile=organization_execution_profile,
            asset_reuse_plan=asset_reuse_plan,
            candidate_source=candidate_source,
        )
        asset_population_supported = bool(dict(effective_execution_semantics or {}).get("asset_population_supported"))
        can_fallback_to_snapshot_population = bool(
            str(request.target_company or "").strip() and candidate_source_is_snapshot_authoritative(candidate_source)
        )
        if not asset_population_supported and not can_fallback_to_snapshot_population:
            return None
        overlay_payload = self._load_candidate_source_asset_population_overlay(candidate_source)
        if overlay_payload:
            overlay_candidate_source = dict(candidate_source)
            if overlay_payload.get(
                "job_scoped_candidate_markers"
            ) and not self._normalized_job_scoped_candidate_markers(overlay_candidate_source):
                overlay_candidate_source["job_scoped_candidate_markers"] = list(
                    overlay_payload.get("job_scoped_candidate_markers") or []
                )
            overlay_record = next(
                (
                    dict(item)
                    for item in list(overlay_payload.get("candidates") or [])
                    if isinstance(item, dict)
                    and str(dict(item).get("candidate_id") or "").strip() == normalized_candidate_id
                ),
                {},
            )
            if overlay_record:
                overlay_record = self._enrich_overlay_candidate_records_from_materialized_sources(
                    request=request,
                    candidate_source=overlay_candidate_source,
                    overlay_payload=overlay_payload,
                    records=[overlay_record],
                )[0]
                overlay_record = self._enrich_candidate_records_from_profile_registry([overlay_record])[0]
                self._attach_snapshot_outreach_layering_metadata_to_records(
                    request=request,
                    candidate_source=overlay_candidate_source,
                    records=[overlay_record],
                )
                self._annotate_job_scoped_candidate_markers_on_records(
                    records=[overlay_record],
                    candidate_source=overlay_candidate_source,
                )
                return self._serialize_candidate_api_record(
                    overlay_record,
                    load_profile_timeline=load_profile_timeline,
                    publishable_email_lookup=publishable_email_lookup,
                )
        shard_payload = self._load_asset_population_candidate_shard_payload(
            request=request,
            candidate_source=candidate_source,
            effective_execution_semantics=effective_execution_semantics,
            candidate_id=normalized_candidate_id,
        )
        if shard_payload:
            merged_record = self._merge_asset_population_candidate_shard_record(shard_payload)
            self._attach_snapshot_outreach_layering_metadata_to_records(
                request=request,
                candidate_source=candidate_source,
                records=[merged_record],
            )
            self._annotate_job_scoped_candidate_markers_on_records(
                records=[merged_record],
                candidate_source=candidate_source,
            )
            return self._serialize_candidate_api_record(
                merged_record,
                load_profile_timeline=load_profile_timeline,
                publishable_email_lookup=publishable_email_lookup,
            )

        # Candidate detail is a public read. If no overlay/shard/materialized
        # serving artifact has the row, fail closed instead of loading root
        # candidate_documents.json as a hidden compatibility source.
        return None

    def _load_asset_population_raw_candidate_lookup(
        self,
        *,
        target_company: str,
        snapshot_id: str,
        asset_view: str,
        candidate_source: dict[str, Any],
    ) -> dict[str, dict[str, Any]]:
        try:
            loaded = load_company_snapshot_candidate_documents_with_materialization_fallback(
                runtime_dir=self.runtime_dir,
                store=self.store,
                target_company=target_company,
                snapshot_id=snapshot_id,
                view=asset_view,
                allow_materialization_fallback=True,
                allow_candidate_documents_fallback=False,
            )
        except CandidateArtifactError:
            return {}
        return {
            str(candidate.candidate_id or "").strip(): candidate.to_record()
            for candidate in list(loaded.get("candidates") or [])
            if isinstance(candidate, Candidate) and str(candidate.candidate_id or "").strip()
        }

    def _merge_asset_population_candidate_record(
        self,
        *,
        candidate: Candidate,
        raw_candidate_lookup: dict[str, dict[str, Any]],
    ) -> dict[str, Any]:
        base_record = candidate.to_record()
        raw_record = dict(raw_candidate_lookup.get(str(candidate.candidate_id or "").strip()) or {})
        if not raw_record:
            return base_record
        merged = dict(base_record)
        for key, value in raw_record.items():
            if key == "metadata":
                continue
            if value not in (None, "", [], {}):
                merged[key] = value
        merged_metadata = dict(base_record.get("metadata") or {})
        merged_metadata.update(dict(raw_record.get("metadata") or {}))
        if merged_metadata:
            merged["metadata"] = merged_metadata
        return merged

    def _serialize_candidate_api_record(
        self,
        record: dict[str, Any],
        *,
        load_profile_timeline: bool,
        publishable_email_lookup: dict[str, dict[str, dict[str, Any]]] | None = None,
    ) -> dict[str, Any]:
        payload = dict(record or {})
        metadata = dict(payload.get("metadata") or {})
        source_path = str(payload.get("source_path") or metadata.get("source_path") or "").strip()
        timeline = self._resolve_candidate_profile_timeline(
            payload=payload,
            metadata=metadata,
            source_path=source_path,
            load_profile_timeline=load_profile_timeline,
        )
        education_lines = list(timeline.get("education_lines") or [])
        experience_lines = list(timeline.get("experience_lines") or [])
        suppress_embedded_primary_email = _timeline_requires_primary_email_scrub(
            timeline,
            context={
                **payload,
                "metadata": metadata,
            },
        )
        serialized = dict(payload)
        serialized["source_path"] = source_path
        serialized["metadata"] = metadata
        function_ids = _normalize_candidate_level_function_ids(
            payload.get("function_ids"),
            metadata.get("function_ids"),
            source_shard_filters=metadata.get("source_shard_filters"),
        )
        if function_ids:
            serialized["function_ids"] = function_ids
        for field_name in (
            "headline",
            "summary",
            "about",
            "profile_location",
            "public_identifier",
            "avatar_url",
            "photo_url",
            "primary_email",
        ):
            if field_name == "primary_email" and suppress_embedded_primary_email:
                continue
            metadata_value = str(metadata.get(field_name) or "").strip()
            if metadata_value and not serialized.get(field_name):
                serialized[field_name] = metadata_value
        for field_name in (
            "headline",
            "summary",
            "about",
            "profile_location",
            "public_identifier",
            "avatar_url",
            "photo_url",
            "primary_email",
        ):
            field_value = timeline.get(field_name)
            if field_name == "primary_email":
                if suppress_embedded_primary_email:
                    serialized.pop("primary_email", None)
                    serialized.pop("email", None)
                    continue
                if field_value:
                    serialized[field_name] = field_value
                else:
                    serialized.pop("primary_email", None)
                    serialized.pop("email", None)
                continue
            if field_value and not serialized.get(field_name):
                serialized[field_name] = field_value
        if not str(serialized.get("linkedin_url") or "").strip():
            linkedin_lookup_url = _candidate_profile_lookup_url(payload, metadata)
            if linkedin_lookup_url:
                serialized["linkedin_url"] = linkedin_lookup_url
        email_metadata = _normalized_primary_email_metadata(timeline.get("primary_email_metadata"))
        if email_metadata and str(serialized.get("primary_email") or "").strip():
            serialized["primary_email_metadata"] = email_metadata
        else:
            serialized.pop("primary_email_metadata", None)
        if not str(serialized.get("primary_email") or "").strip():
            serialized.pop("primary_email", None)
            serialized.pop("email", None)
        if not serialized.get("media_url"):
            media_url = str(
                serialized.get("avatar_url")
                or serialized.get("photo_url")
                or metadata.get("avatar_url")
                or metadata.get("photo_url")
                or payload.get("media_url")
                or ""
            ).strip()
            if media_url:
                serialized["media_url"] = media_url
        for field_name in ("outreach_layer", "outreach_layer_key", "outreach_layer_source"):
            if serialized.get(field_name) not in (None, ""):
                continue
            metadata_lookup_value = str(metadata.get(field_name) or "").strip()
            if metadata_lookup_value:
                serialized[field_name] = metadata_lookup_value
        if education_lines:
            serialized["education_lines"] = education_lines
        if experience_lines:
            serialized["experience_lines"] = experience_lines
        source_match_keywords = _candidate_source_match_keywords(payload=serialized, metadata=metadata)
        if source_match_keywords:
            serialized["matched_keywords"] = _dedupe_texts(
                list(serialized.get("matched_keywords") or []) + source_match_keywords
            )
            matched_fields = list(serialized.get("matched_fields") or [])
            existing_match_values = {
                str(item.get("matched_on") or item.get("keyword") or "").strip().lower()
                for item in matched_fields
                if isinstance(item, dict)
            }
            source_type = str(metadata.get("seed_source_type") or metadata.get("source_type") or "").strip()
            for keyword in source_match_keywords:
                if keyword.lower() in existing_match_values:
                    continue
                matched_fields.append(
                    {
                        "field": "source_seed_query",
                        "matched_on": keyword,
                        "source_type": source_type,
                    }
                )
                existing_match_values.add(keyword.lower())
            serialized["matched_fields"] = matched_fields
        source_match_records = _candidate_source_match_records_for_api(payload=serialized, metadata=metadata)
        if source_match_records:
            serialized["source_matches"] = source_match_records
        return self._apply_publishable_email_overlay_from_lookup(
            source_record=payload,
            serialized_record=serialized,
            publishable_email_lookup=publishable_email_lookup,
        )

    def _serialize_asset_population_candidate_api_record(
        self,
        record: dict[str, Any],
        *,
        load_profile_timeline: bool,
        publishable_email_lookup: dict[str, dict[str, dict[str, Any]]] | None = None,
    ) -> dict[str, Any]:
        serialized = self._serialize_candidate_api_record(
            record,
            load_profile_timeline=load_profile_timeline,
            publishable_email_lookup=publishable_email_lookup,
        )
        compact: dict[str, Any] = {}
        for field_name in (
            "candidate_id",
            "display_name",
            "name_en",
            "name_zh",
            "category",
            "employment_status",
            "organization",
            "role",
            "headline",
            "summary",
            "linkedin_url",
            "source_dataset",
            "team",
            "role_bucket",
            "function_ids",
            "focus_areas",
            "outreach_layer",
            "outreach_layer_key",
            "outreach_layer_source",
            "profile_location",
            "public_identifier",
            "media_url",
            "avatar_url",
            "photo_url",
            "primary_email",
            "primary_email_metadata",
            "profile_capture_kind",
            "current_destination",
            "joined_at",
            "left_at",
            "matched_keywords",
            "source_matches",
        ):
            value = serialized.get(field_name)
            if value in (None, "", [], {}):
                continue
            compact[field_name] = value

        education_lines = _normalized_text_lines(serialized.get("education_lines"))
        experience_lines = _normalized_text_lines(serialized.get("experience_lines"))
        if education_lines:
            compact["education_lines"] = education_lines
        if experience_lines:
            compact["experience_lines"] = experience_lines

        if serialized.get("matched_fields"):
            compact["matched_fields"] = list(serialized.get("matched_fields") or [])

        has_profile_detail = _timeline_has_complete_profile_detail(
            {
                "experience_lines": experience_lines,
                "education_lines": education_lines,
                "headline": serialized.get("headline"),
                "summary": serialized.get("summary"),
                "about": serialized.get("about"),
                "primary_email": serialized.get("primary_email"),
                "languages": serialized.get("languages"),
                "skills": serialized.get("skills"),
                "profile_capture_kind": serialized.get("profile_capture_kind"),
                "profile_capture_source_path": serialized.get("profile_capture_source_path"),
                "source_path": serialized.get("source_path"),
            }
        )
        has_explicit_profile_capture = bool(
            serialized.get("has_explicit_profile_capture")
            or dict(serialized.get("metadata") or {}).get("has_explicit_profile_capture")
            or (
                _profile_capture_kind_has_profile_detail(serialized.get("profile_capture_kind"))
                and has_profile_detail
            )
        )
        compact["has_profile_detail"] = has_profile_detail
        compact["has_explicit_profile_capture"] = has_explicit_profile_capture
        linkedin_url = str(serialized.get("linkedin_url") or "").strip()
        needs_profile_completion = bool(linkedin_url and not (has_profile_detail or has_explicit_profile_capture))
        compact["needs_profile_completion"] = needs_profile_completion
        low_profile_richness = bool(
            linkedin_url
            and (has_profile_detail or has_explicit_profile_capture)
            and not needs_profile_completion
            and (not experience_lines or not education_lines)
        )
        compact["low_profile_richness"] = low_profile_richness
        return compact

    def _build_profile_fetch_progress_payload(self, records: list[dict[str, Any]]) -> dict[str, Any]:
        profile_urls: list[str] = []
        for record in list(records or []):
            payload = dict(record or {})
            metadata = dict(payload.get("metadata") or {})
            profile_url = _candidate_profile_lookup_url(payload, metadata)
            if profile_url and profile_url not in profile_urls:
                profile_urls.append(profile_url)
        status_counts: dict[str, int] = {
            "queued": 0,
            "fetched": 0,
            "failed_retryable": 0,
            "unrecoverable": 0,
            "missing": 0,
            "deferred": 0,
        }
        if not profile_urls:
            return {
                "total_url_count": 0,
                "status_counts": status_counts,
                "queued_url_count": 0,
                "fetched_url_count": 0,
                "failed_retryable_url_count": 0,
                "unrecoverable_url_count": 0,
                "missing_registry_url_count": 0,
                "deferred_url_count": 0,
                "pending_url_count": 0,
            }
        registry_entries: dict[str, dict[str, Any]] = {}
        try:
            registry_entries = self.store.get_linkedin_profile_registry_bulk(profile_urls)
        except Exception:
            registry_entries = {}
        for profile_url in profile_urls:
            key = normalize_linkedin_profile_url_key(profile_url)
            status = str(dict(registry_entries.get(key) or {}).get("status") or "").strip().lower()
            if not status:
                status = "missing"
            if status not in status_counts:
                status_counts[status] = 0
            status_counts[status] += 1
        pending_count = int(status_counts.get("queued") or 0) + int(status_counts.get("failed_retryable") or 0)
        return {
            "total_url_count": len(profile_urls),
            "status_counts": status_counts,
            "queued_url_count": int(status_counts.get("queued") or 0),
            "fetched_url_count": int(status_counts.get("fetched") or 0),
            "failed_retryable_url_count": int(status_counts.get("failed_retryable") or 0),
            "unrecoverable_url_count": int(status_counts.get("unrecoverable") or 0),
            "missing_registry_url_count": int(status_counts.get("missing") or 0),
            "deferred_url_count": int(status_counts.get("deferred") or 0),
            "pending_url_count": pending_count,
        }

    def _build_profile_fetch_progress_payload_from_artifact_summary(
        self,
        artifact_summary: dict[str, Any] | None,
    ) -> dict[str, Any]:
        summary_payload = dict(artifact_summary or {})
        candidate_count = max(int(summary_payload.get("candidate_count") or 0), 0)
        if candidate_count <= 0:
            return {}
        has_profile_progress_fields = any(
            key in summary_payload
            for key in (
                "profile_detail_count",
                "profile_completion_backlog_count",
                "missing_linkedin_count",
            )
        )
        if not has_profile_progress_fields:
            return {}
        fetched_count = max(int(summary_payload.get("profile_detail_count") or 0), 0)
        missing_linkedin_count = max(int(summary_payload.get("missing_linkedin_count") or 0), 0)
        backlog_count = max(int(summary_payload.get("profile_completion_backlog_count") or 0), 0)
        total_url_count = max(candidate_count - missing_linkedin_count, fetched_count + backlog_count, 0)
        fetched_count = min(fetched_count, total_url_count)
        missing_registry_count = max(total_url_count - fetched_count, 0)
        status_counts = {
            "queued": 0,
            "fetched": fetched_count,
            "failed_retryable": 0,
            "unrecoverable": 0,
            "missing": missing_registry_count,
            "deferred": 0,
        }
        return {
            "total_url_count": total_url_count,
            "status_counts": status_counts,
            "queued_url_count": 0,
            "fetched_url_count": fetched_count,
            "failed_retryable_url_count": 0,
            "unrecoverable_url_count": 0,
            "missing_registry_url_count": missing_registry_count,
            "deferred_url_count": 0,
            "pending_url_count": 0,
            "source_kind": "artifact_summary",
        }

    def _search_seed_entries_for_progress(
        self,
        *,
        job: dict[str, Any],
        workers: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        entries: list[dict[str, Any]] = []

        def add_snapshot_entries(snapshot: SearchSeedSnapshot | None) -> None:
            if not isinstance(snapshot, SearchSeedSnapshot):
                return
            for item in list(snapshot.entries or []):
                if isinstance(item, dict):
                    entries.append(dict(item))
            for lane, lane_entries in dict(snapshot.lane_entries or {}).items():
                lane_key = normalize_search_seed_employment_scope(lane)
                for item in list(lane_entries or []):
                    if not isinstance(item, dict):
                        continue
                    record = dict(item)
                    if lane_key != "all":
                        record.setdefault("employment_status", lane_key)
                    entries.append(record)

        job_summary = dict(job.get("summary") or {})
        progress = _normalize_acquisition_progress_payload(job_summary.get("acquisition_progress"))
        latest_state = dict(progress.get("latest_state") or {})
        restored_snapshot = _restore_search_seed_snapshot(dict(latest_state.get("search_seed_snapshot") or {}))
        snapshot_dir_value = str(latest_state.get("snapshot_dir") or "").strip()
        disk_snapshot = None
        if snapshot_dir_value:
            disk_snapshot = _restore_search_seed_snapshot_from_snapshot_dir(
                snapshot_dir=Path(snapshot_dir_value).expanduser(),
                identity=_company_identity_from_record(dict(latest_state.get("company_identity") or {})),
            )
        add_snapshot_entries(restored_snapshot)
        add_snapshot_entries(disk_snapshot)
        for worker in list(workers or []):
            output_payload = dict(worker.get("output") or {})
            for item in list(output_payload.get("entries") or []):
                if isinstance(item, dict):
                    entries.append(dict(item))
            summary_payload = dict(output_payload.get("summary") or {})
            for item in list(summary_payload.get("entries") or []):
                if isinstance(item, dict):
                    entries.append(dict(item))

        return entries

    def _company_roster_entries_for_progress(
        self,
        *,
        job: dict[str, Any],
        workers: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        entries: list[dict[str, Any]] = []

        def add_snapshot(roster_snapshot: CompanyRosterSnapshot | None) -> None:
            if not isinstance(roster_snapshot, CompanyRosterSnapshot):
                return
            roster_entries = list(roster_snapshot.visible_entries or roster_snapshot.raw_entries or [])
            for item in roster_entries:
                if not isinstance(item, dict):
                    continue
                record = dict(item)
                record.setdefault("employment_status", "current")
                entries.append(record)

        def add_payload_items(payload: dict[str, Any]) -> None:
            for key in ("entries", "items", "visible_entries", "raw_entries"):
                for item in list(payload.get(key) or []):
                    if not isinstance(item, dict):
                        continue
                    record = dict(item)
                    record.setdefault("employment_status", "current")
                    entries.append(record)

        job_summary = dict(job.get("summary") or {})
        progress = _normalize_acquisition_progress_payload(job_summary.get("acquisition_progress"))
        latest_state = dict(progress.get("latest_state") or {})
        restored_snapshot = _restore_company_roster_snapshot(dict(latest_state.get("roster_snapshot") or {}))
        if restored_snapshot is None:
            snapshot_dir_value = str(latest_state.get("snapshot_dir") or "").strip()
            if snapshot_dir_value:
                restored_snapshot = self._restore_roster_snapshot_from_snapshot_dir(
                    snapshot_dir=Path(snapshot_dir_value).expanduser(),
                    identity=_company_identity_from_record(dict(latest_state.get("company_identity") or {})),
                )
        add_snapshot(restored_snapshot)

        for worker in list(workers or []):
            metadata = dict(worker.get("metadata") or {})
            checkpoint = dict(worker.get("checkpoint") or {})
            recovery_kind = str(metadata.get("recovery_kind") or checkpoint.get("recovery_kind") or "").strip().lower()
            if recovery_kind != "harvest_company_employees":
                continue
            if effective_worker_status(worker) != "completed":
                continue
            output_payload = dict(worker.get("output") or {})
            summary_payload = dict(output_payload.get("summary") or {})
            add_payload_items(output_payload)
            add_payload_items(summary_payload)

            snapshot_dir_value = str(
                summary_payload.get("snapshot_dir")
                or metadata.get("snapshot_dir")
                or metadata.get("root_snapshot_dir")
                or ""
            ).strip()
            if not snapshot_dir_value:
                continue
            restored_worker_snapshot = self._restore_roster_snapshot_from_snapshot_dir(
                snapshot_dir=Path(snapshot_dir_value).expanduser(),
                identity=_company_identity_from_record(
                    dict(summary_payload.get("company_identity") or metadata.get("identity") or {})
                ),
            )
            add_snapshot(restored_worker_snapshot)

        return entries

    def _profile_urls_from_worker_payload(self, worker: dict[str, Any]) -> list[str]:
        urls: list[str] = []

        def add_values(values: Any) -> None:
            for value in list(values or []):
                url = str(value or "").strip()
                if url:
                    urls.append(url)

        metadata = dict(worker.get("metadata") or {})
        input_payload = dict(worker.get("input") or worker.get("input_payload") or {})
        output_payload = dict(worker.get("output") or {})
        summary_payload = dict(output_payload.get("summary") or {})
        add_values(metadata.get("profile_urls"))
        add_values(input_payload.get("profile_urls"))
        add_values(summary_payload.get("requested_urls"))
        add_values(summary_payload.get("profile_urls"))
        add_values(output_payload.get("requested_urls"))
        add_values(output_payload.get("profile_urls"))
        deduped: list[str] = []
        seen: set[str] = set()
        for url in urls:
            key = normalize_linkedin_profile_url_key(url)
            if not key or key in seen:
                continue
            seen.add(key)
            deduped.append(url)
        return deduped

    def _local_apply_profile_url_chunk_for_worker(
        self,
        *,
        item: dict[str, Any],
        worker: dict[str, Any],
        snapshot_id: str,
        profile_url_limit: int,
    ) -> tuple[list[str], dict[str, Any]]:
        """Select the next bounded profile-url apply chunk for one harvest worker.

        The durable item is kept as the owner; progress is mirrored both in item
        metadata and the worker's provisional inline apply marker so a crash
        after candidate-doc writes can resume without reprocessing the full
        provider batch.
        """

        limit = max(0, int(profile_url_limit or 0))
        if limit <= 0:
            return [], {}
        all_profile_urls = self._profile_urls_from_worker_payload(worker)
        if len(all_profile_urls) <= limit:
            return [], {}
        all_profile_url_keys: list[str] = []
        all_profile_url_by_key: dict[str, str] = {}
        for profile_url in all_profile_urls:
            key = normalize_linkedin_profile_url_key(profile_url)
            if not key or key in all_profile_url_by_key:
                continue
            all_profile_url_by_key[key] = profile_url
            all_profile_url_keys.append(key)
        if len(all_profile_url_keys) <= limit:
            return [], {}
        item_metadata = dict(dict(item or {}).get("metadata") or {})
        item_progress = dict(item_metadata.get("local_apply_profile_progress") or {})
        output = dict(dict(worker or {}).get("output") or {})
        marker = dict(output.get("inline_incremental_apply") or {})
        marker_snapshot_id = str(marker.get("snapshot_id") or "").strip()
        marker_progress_committed = bool(marker.get("profile_apply_progress_committed"))
        processed_keys = _dedupe_texts(
            [
                *list(item_progress.get("cumulative_applied_profile_url_keys") or []),
                *list(item_progress.get("processed_profile_url_keys") or []),
                *(
                    list(marker.get("cumulative_applied_profile_url_keys") or [])
                    if marker_snapshot_id == str(snapshot_id or "").strip() and marker_progress_committed
                    else []
                ),
                *(
                    list(marker.get("applied_profile_url_keys") or [])
                    if marker_snapshot_id == str(snapshot_id or "").strip() and marker_progress_committed
                    else []
                ),
            ]
        )
        processed_key_set = {key for key in processed_keys if key}
        remaining_keys = [key for key in all_profile_url_keys if key not in processed_key_set]
        if not remaining_keys:
            return [], {
                "profile_url_apply_complete": True,
                "total_profile_url_count": len(all_profile_url_keys),
                "processed_profile_url_count": len(all_profile_url_keys),
                "cumulative_applied_profile_url_keys": all_profile_url_keys,
                "remaining_profile_url_count": 0,
            }
        chunk_keys = remaining_keys[:limit]
        chunk_urls = [all_profile_url_by_key[key] for key in chunk_keys if key in all_profile_url_by_key]
        cumulative_keys = _dedupe_texts([*processed_keys, *chunk_keys])
        complete = len(set(cumulative_keys)) >= len(set(all_profile_url_keys))
        return chunk_urls, {
            "profile_url_apply_complete": complete,
            "total_profile_url_count": len(all_profile_url_keys),
            "processed_profile_url_count": len(cumulative_keys),
            "previously_processed_profile_url_count": len(processed_key_set),
            "applied_profile_url_count": len(chunk_keys),
            "remaining_profile_url_count": max(0, len(all_profile_url_keys) - len(set(cumulative_keys))),
            "applied_profile_url_keys": chunk_keys,
            "cumulative_applied_profile_url_keys": cumulative_keys,
            "profile_url_chunk_size": len(chunk_keys),
            "profile_url_chunk_limit": limit,
        }

    def _commit_worker_inline_apply_profile_progress(
        self,
        *,
        worker_id: int,
        snapshot_id: str,
        progress: dict[str, Any],
    ) -> None:
        if worker_id <= 0:
            return
        worker = self.store.get_agent_worker(worker_id=worker_id)
        if worker is None:
            return
        checkpoint = dict(worker.get("checkpoint") or {})
        output = dict(worker.get("output") or {})
        marker = dict(output.get("inline_incremental_apply") or {})
        if str(marker.get("snapshot_id") or "").strip() != str(snapshot_id or "").strip():
            return
        marker["profile_apply_progress_committed"] = True
        for key in (
            "profile_url_apply_complete",
            "total_profile_url_count",
            "processed_profile_url_count",
            "previously_processed_profile_url_count",
            "applied_profile_url_count",
            "remaining_profile_url_count",
            "applied_profile_url_keys",
            "cumulative_applied_profile_url_keys",
            "profile_url_chunk_size",
            "profile_url_chunk_limit",
        ):
            if key in progress:
                marker[key] = progress.get(key)
        output["inline_incremental_apply"] = marker
        self.store.checkpoint_agent_worker(
            worker_id,
            checkpoint_payload=checkpoint,
            output_payload=output,
            status=str(worker.get("status") or "completed"),
        )

    @staticmethod
    def _local_apply_profile_progress_from_ingest_marker(marker: dict[str, Any]) -> dict[str, Any]:
        marker_payload = dict(marker or {})
        progress_keys = (
            "profile_url_apply_complete",
            "total_profile_url_count",
            "processed_profile_url_count",
            "previously_processed_profile_url_count",
            "applied_profile_url_count",
            "remaining_profile_url_count",
            "applied_profile_url_keys",
            "cumulative_applied_profile_url_keys",
            "profile_url_chunk_size",
            "profile_url_chunk_limit",
            "profile_apply_progress_committed",
        )
        progress = {key: marker_payload.get(key) for key in progress_keys if key in marker_payload}
        if not progress:
            return {}
        total = _coerce_int(progress.get("total_profile_url_count"), 0)
        processed = _coerce_int(progress.get("processed_profile_url_count"), 0)
        if total > 0 and processed >= total:
            progress["profile_url_apply_complete"] = True
            progress["processed_profile_url_count"] = total
            progress["remaining_profile_url_count"] = 0
        return progress

    def _profile_url_key_hash(self, profile_url_or_key: str) -> str:
        key = normalize_linkedin_profile_url_key(profile_url_or_key)
        if not key:
            return ""
        return hashlib.sha1(key.encode("utf-8")).hexdigest()[:16]

    def _build_linkedin_stage1_progress_payload(
        self,
        *,
        job: dict[str, Any],
        workers: list[dict[str, Any]],
    ) -> dict[str, Any]:
        entries = self._search_seed_entries_for_progress(job=job, workers=workers)
        roster_entries = self._company_roster_entries_for_progress(job=job, workers=workers)
        lane_seen: dict[str, set[str]] = {"current": set(), "former": set(), "all": set()}
        deduped_entry_keys: set[str] = set()
        seed_profile_urls: list[str] = []
        seed_profile_url_keys: set[str] = set()

        def add_returned_record(record: dict[str, Any], *, default_scope: str = "") -> None:
            if not isinstance(record, dict):
                return
            entry = dict(record)
            profile_url = str(entry.get("profile_url") or entry.get("linkedin_url") or "").strip()
            key = normalize_linkedin_profile_url_key(profile_url) if profile_url else ""
            if profile_url and key and key not in seed_profile_url_keys:
                seed_profile_url_keys.add(key)
                seed_profile_urls.append(profile_url)
            entry_key = key or str(entry.get("seed_key") or entry.get("full_name") or "").strip().lower()
            if not entry_key:
                return
            deduped_entry_keys.add(entry_key)
            scope = normalize_search_seed_employment_scope(
                entry.get("employment_status")
                or entry.get("employment_scope")
                or entry.get("lane")
                or default_scope
                or ""
            )
            lane_seen.setdefault(scope, set()).add(entry_key)

        for entry in entries:
            add_returned_record(entry)
        for entry in roster_entries:
            add_returned_record(entry, default_scope="current")

        worker_profile_urls: list[str] = []
        completed_profile_url_keys: set[str] = set()
        for worker in list(workers or []):
            urls = self._profile_urls_from_worker_payload(worker)
            worker_profile_urls.extend(urls)
            if effective_worker_status(worker) == "completed":
                for url in urls:
                    key = normalize_linkedin_profile_url_key(url)
                    if key:
                        completed_profile_url_keys.add(key)

        required_urls: list[str] = []
        required_seen: set[str] = set()
        # The user-facing denominator is the full post-dedupe profile set that
        # Stage 1 determined needs detail, not only the subset already scheduled
        # into scraper workers. Otherwise the UI can drift 225/273 -> 297/297 as
        # the tail is queued instead of staying stable at 225/297.
        profile_fetch_scope_urls = [*seed_profile_urls, *worker_profile_urls]
        for url in profile_fetch_scope_urls:
            key = normalize_linkedin_profile_url_key(url)
            if not key or key in required_seen:
                continue
            required_seen.add(key)
            required_urls.append(url)
        if not entries and not required_urls:
            return {}

        deduped_candidate_count = max(len(deduped_entry_keys), len(seed_profile_url_keys))
        deduped_profile_url_count = len(seed_profile_url_keys)
        returned_population_count = (
            len(lane_seen.get("current") or set())
            + len(lane_seen.get("former") or set())
            + len(lane_seen.get("all") or set())
        )
        if returned_population_count > 0:
            # Dynamic progress is a live diagnostic, not the durable Stage 1
            # lifecycle source of truth. Keep its lane, deduped, and profile
            # denominator counters on the same semantic version so public
            # preflight never sees current-lane-only counts mixed with a later
            # all-lane deduped population.
            deduped_candidate_count = min(deduped_candidate_count, returned_population_count)
            deduped_profile_url_count = min(deduped_profile_url_count, returned_population_count)
        business_required_count = min(
            len(required_urls),
            max(deduped_candidate_count, deduped_profile_url_count),
        )
        business_required_urls = required_urls[:business_required_count]
        status_counts: dict[str, int] = {
            "queued": 0,
            "fetched": 0,
            "failed_retryable": 0,
            "unrecoverable": 0,
            "missing": 0,
            "deferred": 0,
        }
        registry_entries: dict[str, dict[str, Any]] = {}
        if business_required_urls:
            try:
                registry_entries = self.store.get_linkedin_profile_registry_bulk(business_required_urls)
            except Exception:
                registry_entries = {}
        for url in business_required_urls:
            key = normalize_linkedin_profile_url_key(url)
            status = str(dict(registry_entries.get(key) or {}).get("status") or "").strip().lower()
            if not status and key in completed_profile_url_keys:
                status = "fetched"
            if not status:
                status = "missing"
            if status not in status_counts:
                status_counts[status] = 0
            status_counts[status] += 1

        fetched_count = int(status_counts.get("fetched") or 0)
        unrecoverable_count = int(status_counts.get("unrecoverable") or 0)
        pending_count = max(len(business_required_urls) - fetched_count - unrecoverable_count, 0)
        queued_count = (
            int(status_counts.get("queued") or 0)
            + int(status_counts.get("missing") or 0)
            + int(status_counts.get("deferred") or 0)
        )
        payload = {
            "current_search_returned_count": len(lane_seen.get("current") or set()),
            "former_search_returned_count": len(lane_seen.get("former") or set()),
            "all_search_returned_count": len(lane_seen.get("all") or set()),
            "deduped_candidate_count": deduped_candidate_count,
            "deduped_profile_url_count": deduped_profile_url_count,
            "profile_fetch_required_count": len(business_required_urls),
            "profile_fetched_count": fetched_count,
            "profile_queued_count": queued_count,
            "profile_failed_retryable_count": int(status_counts.get("failed_retryable") or 0),
            "profile_unrecoverable_count": unrecoverable_count,
            "profile_pending_count": pending_count,
            "status_counts": status_counts,
            "profile_fetch_required_url_key_hashes": [
                self._profile_url_key_hash(url) for url in business_required_urls if self._profile_url_key_hash(url)
            ],
            "worker_known_profile_url_count": len(set(worker_profile_urls)),
        }
        payload["profile_url_total_count"] = payload["profile_fetch_required_count"]
        payload["fetched_profile_count"] = payload["profile_fetched_count"]
        return payload

    def _stage1_progress_payload_from_lifecycle_row(
        self,
        row: dict[str, Any] | None,
        *,
        dynamic_progress: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Project canonical lifecycle Stage 1 counters into the public progress shape.

        The lifecycle row is the event-time source of truth for lane counts and
        the profile denominator. The live builder may still provide registry
        status counts as profile batches finish, but it must not erase or inflate
        the persisted Stage 1 business projection.
        """

        source = dict(row or {})
        if not source or str(source.get("source_validation_status") or "").strip() != "validated":
            return {}
        has_stage1_projection = bool(
            str(source.get("projection_source_snapshot_id") or "").strip()
            or int(source.get("stage1_current_search_returned_count") or 0)
            or int(source.get("stage1_former_search_returned_count") or 0)
            or int(source.get("stage1_all_search_returned_count") or 0)
            or int(source.get("stage1_deduped_candidate_count") or 0)
            or int(source.get("stage1_deduped_profile_url_count") or 0)
            or int(source.get("stage1_profile_fetch_required_count") or 0)
            or int(source.get("stage1_profile_fetched_count") or 0)
        )
        if not has_stage1_projection:
            return {}

        dynamic = dict(dynamic_progress or {})
        current_count = _coerce_int(source.get("stage1_current_search_returned_count"), 0)
        former_count = _coerce_int(source.get("stage1_former_search_returned_count"), 0)
        all_count = _coerce_int(source.get("stage1_all_search_returned_count"), 0)
        returned_population_count = current_count + former_count + all_count
        deduped_candidate_count = _coerce_int(source.get("stage1_deduped_candidate_count"), 0)
        deduped_profile_url_count = _coerce_int(source.get("stage1_deduped_profile_url_count"), 0)
        if returned_population_count > 0:
            deduped_candidate_count = min(deduped_candidate_count, returned_population_count)
            deduped_profile_url_count = min(deduped_profile_url_count, returned_population_count)
        deduped_population_count = max(deduped_candidate_count, deduped_profile_url_count)
        required_count = max(0, _coerce_int(source.get("stage1_profile_fetch_required_count"), 0))
        if deduped_population_count > 0:
            required_count = min(required_count, deduped_population_count)
        elif returned_population_count == 0:
            required_count = 0
        lifecycle_fetched_count = max(
            _coerce_int(source.get("stage1_profile_fetched_count"), 0),
            _coerce_int(source.get("delta_profile_fetched_count"), 0),
        )
        dynamic_fetched_count = _coerce_int(
            dynamic.get("profile_fetched_count") or dynamic.get("fetched_profile_count"),
            0,
        )
        fetched_count = max(lifecycle_fetched_count, dynamic_fetched_count)
        if required_count > 0:
            fetched_count = min(fetched_count, required_count)
        else:
            fetched_count = 0

        dynamic_retryable_count = max(0, _coerce_int(dynamic.get("profile_failed_retryable_count"), 0))
        dynamic_unrecoverable_count = max(0, _coerce_int(dynamic.get("profile_unrecoverable_count"), 0))
        if required_count > 0:
            remaining_after_fetched = max(required_count - fetched_count, 0)
            unrecoverable_count = min(dynamic_unrecoverable_count, remaining_after_fetched)
            retryable_count = min(dynamic_retryable_count, max(remaining_after_fetched - unrecoverable_count, 0))
            pending_count = max(required_count - fetched_count - unrecoverable_count, 0)
            queued_count = min(
                pending_count,
                max(
                    _coerce_int(dynamic.get("profile_queued_count"), 0),
                    pending_count if not dynamic else 0,
                ),
            )
        else:
            unrecoverable_count = 0
            retryable_count = 0
            pending_count = 0
            queued_count = 0

        status_counts_source = dict(dynamic.get("status_counts") or {})
        status_counts = {
            "queued": queued_count,
            "fetched": fetched_count,
            "failed_retryable": retryable_count,
            "unrecoverable": unrecoverable_count,
            "missing": max(pending_count - queued_count, 0),
            "deferred": _coerce_int(status_counts_source.get("deferred"), 0),
        }
        return {
            "current_search_returned_count": current_count,
            "former_search_returned_count": former_count,
            "all_search_returned_count": all_count,
            "deduped_candidate_count": deduped_candidate_count,
            "deduped_profile_url_count": deduped_profile_url_count,
            "profile_fetch_required_count": required_count,
            "profile_fetched_count": fetched_count,
            "profile_queued_count": queued_count,
            "profile_failed_retryable_count": retryable_count,
            "profile_unrecoverable_count": unrecoverable_count,
            "profile_pending_count": pending_count,
            "status_counts": status_counts,
            "profile_url_total_count": required_count,
            "fetched_profile_count": fetched_count,
        }

    def _build_public_linkedin_stage1_progress_payload(
        self,
        *,
        job: dict[str, Any],
        workers: list[dict[str, Any]],
    ) -> dict[str, Any]:
        dynamic_progress = self._build_linkedin_stage1_progress_payload(job=job, workers=workers)
        job_id = str(dict(job or {}).get("job_id") or "").strip()
        if not job_id:
            return dynamic_progress
        lifecycle_progress = self._stage1_progress_payload_from_lifecycle_row(
            self.store.get_job_result_lifecycle(job_id),
            dynamic_progress=dynamic_progress,
        )
        return lifecycle_progress or dynamic_progress

    def _build_excel_intake_progress_payload(self, *, job: dict[str, Any]) -> dict[str, Any]:
        job_payload = dict(job or {})
        job_summary = dict(job_payload.get("summary") or {})
        workflow_kind = str(job_summary.get("workflow_kind") or job_payload.get("job_type") or "").strip().lower()
        if workflow_kind not in {"excel_intake", "excel_intake_batch"}:
            return {}
        intake_summary = dict(job_summary.get("intake_summary") or {})
        row_manifest = dict(job_summary.get("excel_row_manifest") or {})
        linkedin_stage = dict(job_summary.get("linkedin_stage_1") or {})
        status_counts = {
            str(key or "").strip(): int(value or 0)
            for key, value in dict(row_manifest.get("status_counts") or {}).items()
            if str(key or "").strip()
        }
        manual_review_row_count = sum(
            int(intake_summary.get(field_name) or 0)
            for field_name in ("manual_review_local_count", "manual_review_search_count")
        )
        if manual_review_row_count == 0 and status_counts:
            manual_review_row_count = int(status_counts.get("manual_review_local") or 0) + int(
                status_counts.get("manual_review_search") or 0
            )
        unresolved_row_count = int(intake_summary.get("unresolved_count") or status_counts.get("unresolved") or 0)
        invalid_row_count = int(intake_summary.get("invalid_count") or status_counts.get("invalid") or 0)
        total_row_count = int(
            row_manifest.get("total_row_count")
            or intake_summary.get("total_rows")
            or linkedin_stage.get("total_rows")
            or job_summary.get("row_count")
            or 0
        )
        matched_row_count = int(
            row_manifest.get("matched_row_count")
            or intake_summary.get("persisted_candidate_count")
            or linkedin_stage.get("persisted_candidate_count")
            or 0
        )
        review_row_count = int(
            row_manifest.get("review_row_count")
            or (manual_review_row_count + unresolved_row_count + invalid_row_count)
        )
        target_candidate_count = int(
            linkedin_stage.get("excel_import_candidate_count")
            or intake_summary.get("persisted_candidate_count")
            or matched_row_count
            or 0
        )
        return {
            "workflow_kind": workflow_kind,
            "target_company": str(job_summary.get("target_company") or job_payload.get("target_company") or "").strip(),
            "input_filename": str(job_summary.get("input_filename") or "").strip(),
            "total_row_count": total_row_count,
            "matched_row_count": matched_row_count,
            "target_candidate_count": target_candidate_count,
            "manual_review_row_count": manual_review_row_count,
            "unresolved_row_count": unresolved_row_count,
            "invalid_row_count": invalid_row_count,
            "review_row_count": review_row_count,
            "status_counts": status_counts,
            "row_manifest_available": bool(row_manifest),
            "row_manifest_truncated": bool(row_manifest.get("truncated")),
        }

    @staticmethod
    def _format_excel_intake_progress_message(excel_intake_progress: dict[str, Any]) -> str:
        progress = dict(excel_intake_progress or {})
        total_row_count = int(progress.get("total_row_count") or 0)
        matched_row_count = int(progress.get("matched_row_count") or 0)
        manual_review_row_count = int(progress.get("manual_review_row_count") or 0)
        unresolved_row_count = int(progress.get("unresolved_row_count") or 0)
        invalid_row_count = int(progress.get("invalid_row_count") or 0)
        unresolved_label = "未解析/无效" if invalid_row_count > 0 else "未解析"
        unresolved_display_count = unresolved_row_count + invalid_row_count
        if total_row_count > 0:
            return (
                f"Excel 导入完成：共 {total_row_count} 行，已匹配 {matched_row_count} 行，"
                f"需人工审核 {manual_review_row_count} 行，{unresolved_label} {unresolved_display_count} 行。"
            )
        return "Excel 导入完成。"

    def _build_execution_phase_contract(
        self,
        *,
        job: dict[str, Any],
        workflow_stage_summaries: dict[str, Any],
        linkedin_stage_1_progress: dict[str, Any],
        result_view_lifecycle: dict[str, Any],
    ) -> dict[str, Any]:
        summaries = dict(dict(workflow_stage_summaries or {}).get("summaries") or {})
        job_summary = dict(job.get("summary") or {})
        public_web_summary = dict(summaries.get("public_web_stage_2") or {})
        public_web_status = str(public_web_summary.get("status") or "").strip().lower()
        public_stage_slot_present = bool(
            public_web_status
            or str(public_web_summary.get("started_at") or "").strip()
            or str(public_web_summary.get("completed_at") or "").strip()
            or str(public_web_summary.get("summary_path") or "").strip()
        )
        workflow_kind = (
            str(
                public_web_summary.get("workflow_kind")
                or job_summary.get("workflow_kind")
                or job.get("job_type")
                or ""
            )
            .strip()
            .lower()
        )
        public_web_stage_explicit = public_web_summary.get("public_web_stage_applicable")
        if isinstance(public_web_stage_explicit, bool):
            public_web_stage_applicable = public_web_stage_explicit
        else:
            local_stage_workflow = workflow_kind in {"excel_intake", "excel_intake_batch"}
            public_web_stage_applicable = public_stage_slot_present and not local_stage_workflow
        profile_required_count = int(linkedin_stage_1_progress.get("profile_fetch_required_count") or 0)
        profile_fetched_count = int(linkedin_stage_1_progress.get("profile_fetched_count") or 0)
        worker_known_profile_url_count = int(linkedin_stage_1_progress.get("worker_known_profile_url_count") or 0)
        delta_profile_progress_applicable = result_view_lifecycle.get("delta_profile_progress_applicable") is not False
        baseline_candidate_count = int(result_view_lifecycle.get("baseline_candidate_count") or 0)
        served_candidate_count = int(result_view_lifecycle.get("served_candidate_count") or 0)
        expected_candidate_count = int(result_view_lifecycle.get("expected_candidate_count") or 0)
        full_local_reuse_serving_complete = bool(
            not delta_profile_progress_applicable
            and expected_candidate_count > 0
            and served_candidate_count >= expected_candidate_count
        )
        profile_work_pending = bool(
            delta_profile_progress_applicable
            and (
                (profile_required_count > 0 and profile_fetched_count < profile_required_count)
                or (profile_required_count <= 0 and worker_known_profile_url_count > 0)
            )
        )
        lifecycle_state = str(result_view_lifecycle.get("state") or "").strip().lower()
        background_materialization_status = (
            str(result_view_lifecycle.get("background_snapshot_materialization_status") or "").strip().lower()
        )
        outreach_layering_status = str(result_view_lifecycle.get("outreach_layering_status") or "").strip().lower()
        job_status = str(job.get("status") or "").strip().lower()
        job_stage = str(job.get("stage") or "").strip().lower()
        explicit_background_materialization = background_materialization_status in {
            "scheduled",
            "running",
            "materializing",
            "deferred",
        }
        profile_terminal_for_materialization = bool(
            profile_required_count <= 0 or profile_fetched_count >= profile_required_count
        )
        baseline_delta_materialization_evidence = bool(
            baseline_candidate_count > 0
            and expected_candidate_count > baseline_candidate_count
            and (
                explicit_background_materialization
                or (
                    lifecycle_state in {"delta_applying", "current_snapshot_materializing"}
                    and profile_terminal_for_materialization
                )
            )
        )
        no_baseline_materialization_evidence = bool(
            baseline_candidate_count <= 0
            and (
                explicit_background_materialization
                or (
                    served_candidate_count > 0
                    and lifecycle_state in {"current_snapshot_materializing", "current_snapshot_serving"}
                    and profile_terminal_for_materialization
                )
            )
        )
        local_materialization_evidence = bool(
            baseline_delta_materialization_evidence or no_baseline_materialization_evidence
        )
        local_materialization_active = bool(
            local_materialization_evidence
            and not full_local_reuse_serving_complete
        )
        explicit_local_stage_slot = bool(
            public_stage_slot_present
            and not public_web_stage_applicable
            and (local_materialization_active or workflow_kind in {"excel_intake", "excel_intake_batch"})
        )
        post_result_layering_active = outreach_layering_status in {"scheduled", "running", "deferred"}
        excel_intake_progress = self._build_excel_intake_progress_payload(job=job)
        excel_intake_completed = bool(
            excel_intake_progress
            and workflow_kind in {"excel_intake", "excel_intake_batch"}
            and job_status == "completed"
        )

        local_stage_title = (
            str(public_web_summary.get("title") or "").strip()
            if public_stage_slot_present and not public_web_stage_applicable
            else ""
        ) or "本地资产物化"
        local_stage_detail = (
            str(public_web_summary.get("text") or "").strip()
            if public_stage_slot_present and not public_web_stage_applicable
            else ""
        ) or "正在将已取回的 LinkedIn Profile 合并到候选人看板与检索索引。"
        if (
            not public_stage_slot_present
            and baseline_candidate_count > 0
            and expected_candidate_count > baseline_candidate_count
            and local_materialization_active
        ):
            fetched_text = (
                f"新增 LinkedIn Profile 已取回 {profile_fetched_count}/{profile_required_count}；"
                if profile_required_count > 0
                else ""
            )
            local_stage_detail = (
                f"当前已服务 baseline {baseline_candidate_count} 位；{fetched_text}"
                f"正在将新增候选人合并到看板，预计服务 {expected_candidate_count} 位。"
            )
        if profile_work_pending:
            active_phase_id = "linkedin_acquisition"
            active_stage_id = "linkedin_stage_1"
            active_phase_label = "LinkedIn Stage 1"
            active_phase_detail = (
                f"正在取回 LinkedIn Profile {profile_fetched_count}/{profile_required_count}。"
                if profile_required_count > 0
                else "正在等待 LinkedIn Profile 队列回写。"
            )
        elif excel_intake_completed:
            active_phase_id = "final_results"
            active_stage_id = "stage_2_final"
            active_phase_label = "Excel Intake"
            active_phase_detail = self._format_excel_intake_progress_message(excel_intake_progress)
        elif self._job_is_terminal(job) and not local_materialization_active and not post_result_layering_active:
            active_phase_id = "final_results"
            active_stage_id = "stage_2_final"
            active_phase_label = "Final Results"
            active_phase_detail = "Workflow completed."
        elif post_result_layering_active:
            active_phase_id = "post_result_layering"
            active_stage_id = "stage_2_final"
            active_phase_label = "结果分层刷新"
            active_phase_detail = "候选人看板已可用，后台正在刷新线索分层与审核信息。"
        elif public_web_stage_applicable and public_web_status not in {"completed", "skipped"}:
            active_phase_id = "public_web_stage_2"
            active_stage_id = "public_web_stage_2"
            active_phase_label = "Public Web Stage 2"
            active_phase_detail = "正在补充公开网页、论文与外部证据。"
        elif local_materialization_active:
            active_phase_id = "local_asset_materialization"
            active_stage_id = "public_web_stage_2"
            active_phase_label = local_stage_title
            active_phase_detail = local_stage_detail
        elif job_stage in {"acquiring", "retrieving"}:
            active_phase_id = "linkedin_acquisition"
            active_stage_id = "linkedin_stage_1"
            active_phase_label = "LinkedIn Stage 1"
            active_phase_detail = "正在获取 LinkedIn roster 与 profile 数据。"
        else:
            active_phase_id = "linkedin_acquisition"
            active_stage_id = "linkedin_stage_1"
            active_phase_label = "LinkedIn Stage 1"
            active_phase_detail = "正在获取 LinkedIn roster 与 profile 数据。"

        local_stage_applicable = bool(local_materialization_active or explicit_local_stage_slot)
        if public_web_stage_applicable:
            public_stage_title = str(public_web_summary.get("title") or "").strip() or "Public Web Stage 2"
            public_stage_detail = str(public_web_summary.get("text") or "").strip()
        elif local_stage_applicable:
            public_stage_title = local_stage_title
            public_stage_detail = local_stage_detail
        else:
            public_stage_title = active_phase_label
            public_stage_detail = active_phase_detail
        return {
            "active_phase_id": active_phase_id,
            "active_stage_id": active_stage_id,
            "active_phase_label": active_phase_label,
            "active_phase_detail": active_phase_detail,
            "public_web_stage_applicable": public_web_stage_applicable,
            "local_asset_materialization_applicable": local_stage_applicable,
            "profile_work_pending": profile_work_pending,
            "stage_title_overrides": {
                "public_web_stage_2": public_stage_title,
            },
            "stage_detail_overrides": {
                "public_web_stage_2": public_stage_detail,
            },
        }

    # ------------------------------------------------------------------
    # Event-driven canonical lifecycle writers (rebuild slice 2)
    # ------------------------------------------------------------------
    #
    # These helpers persist `job_result_lifecycle` rows from clean inputs at
    # workflow state transitions, instead of rebuilding from `job.summary` /
    # `result_view.metadata` / stage files on every public read. Each writer is
    # patch-style (the underlying `upsert_job_result_lifecycle` merges) so
    # callers may pass only the fields known at the transition site.
    #
    # See `docs/JOB_RESULT_LIFECYCLE_DESIGN.md` §Writer ownership.

    def _delta_profile_progress_contract_from_plan(
        self,
        *,
        request: JobRequest | None,
        plan: Any,
        asset_reuse_plan: dict[str, Any] | None = None,
        effective_execution_semantics: dict[str, Any] | None = None,
    ) -> tuple[bool, str]:
        """Return whether delta-profile progress is a user-visible lifecycle lane.

        LinkedIn Stage 1 can exist for many workflow shapes, but the lifecycle
        `delta_profile_*` counters are only applicable when the planner actually
        requested baseline+delta acquisition. Snapshot-only reuse must not show
        stale source-snapshot profile work as active progress.
        """

        plan_payload = _plan_payload(plan)
        reuse_plan = dict(asset_reuse_plan or plan_payload.get("asset_reuse_plan") or {})
        baseline_explanation = dict(
            reuse_plan.get("baseline_selection_explanation")
            or reuse_plan.get("request_family_match_explanation")
            or {}
        )
        semantics = dict(effective_execution_semantics or {})
        execution_preferences = dict(getattr(request, "execution_preferences", {}) or {})
        requires_delta = bool(
            reuse_plan.get("requires_delta_acquisition")
            or baseline_explanation.get("requires_delta_acquisition")
            or semantics.get("requires_delta_acquisition")
            or str(execution_preferences.get("delta_baseline_snapshot_id") or "").strip()
        )
        planner_mode = (
            str(
                reuse_plan.get("planner_mode")
                or baseline_explanation.get("planner_mode")
                or semantics.get("planner_mode")
                or ""
            )
            .strip()
            .lower()
        )
        effective_mode = str(semantics.get("effective_acquisition_mode") or "").strip().lower()
        acquisition_strategy = getattr(plan, "acquisition_strategy", None)
        if acquisition_strategy is None:
            acquisition_strategy = dict(plan_payload.get("acquisition_strategy") or {})
        strategy_type = (
            str(
                reuse_plan.get("strategy_type")
                or (
                    dict(acquisition_strategy).get("strategy_type")
                    if isinstance(acquisition_strategy, dict)
                    else getattr(acquisition_strategy, "strategy_type", "")
                )
                or semantics.get("strategy_type")
                or ""
            )
            .strip()
            .lower()
        )
        default_mode = (
            str(
                reuse_plan.get("default_acquisition_mode")
                or (
                    dict(acquisition_strategy).get("default_acquisition_mode")
                    if isinstance(acquisition_strategy, dict)
                    else getattr(acquisition_strategy, "default_acquisition_mode", "")
                )
                or semantics.get("profile_default_acquisition_mode")
                or ""
            )
            .strip()
            .lower()
        )
        if not requires_delta and (
            strategy_type == "full_company_roster"
            or default_mode == "full_company_roster"
            or effective_mode == "full_live_roster"
        ):
            return False, "not_applicable_live_roster_stage1"
        suppress_for_reuse = bool(
            not requires_delta
            and (
                planner_mode in {"reuse_snapshot_only", "reuse_snapshot", "reuse_completed"}
                or effective_mode == "full_local_asset_reuse"
                or bool(semantics.get("full_local_asset_reuse"))
            )
        )
        if suppress_for_reuse:
            return False, "not_applicable_snapshot_reuse_no_delta"
        return True, "linkedin_stage_1_progress"

    def _suppress_delta_profile_progress_for_reuse_row(
        self,
        *,
        row: dict[str, Any],
        job: dict[str, Any],
        request: JobRequest | None = None,
        effective_execution_semantics: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        applicable, reason = self._delta_profile_progress_contract_from_plan(
            request=request or JobRequest.from_payload(dict(job.get("request") or {})),
            plan=dict(job.get("plan") or {}),
            effective_execution_semantics=effective_execution_semantics,
        )
        if applicable:
            return row
        rendered = dict(row)
        rendered["delta_profile_progress_applicable"] = False
        rendered["delta_profile_progress_reason"] = reason
        rendered["delta_profile_required_count"] = 0
        rendered["delta_profile_fetched_count"] = 0
        rendered["delta_profile_materialized_count"] = 0
        rendered["delta_profile_board_visible_count"] = 0
        return rendered

    def initialize_job_result_lifecycle(
        self,
        *,
        job_id: str,
        request: JobRequest,
        plan: Any,
        baseline_snapshot_id: str = "",
        baseline_candidate_count: int = 0,
        workflow_kind: str = "",
    ) -> dict[str, Any]:
        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        target_company = str(request.target_company or "").strip()
        from .company_registry import normalize_company_key

        company_key = normalize_company_key(target_company) if target_company else ""
        # If this is a delta workflow, the planner has already computed the
        # baseline snapshot id; pass it in. Otherwise the row simply records
        # the planning phase.
        asset_reuse_plan = dict(getattr(plan, "asset_reuse_plan", None) or {})
        delta_progress_applicable, delta_progress_reason = self._delta_profile_progress_contract_from_plan(
            request=request,
            plan=plan,
            asset_reuse_plan=asset_reuse_plan,
        )
        fields = {
            "view_id": "",
            "company_key": company_key,
            "target_company": target_company,
            "workflow_kind": str(workflow_kind or "").strip(),
            "phase": "planning",
            "phase_status": "active",
            "state": "planning",
            "baseline_snapshot_id": str(baseline_snapshot_id or "").strip(),
            "baseline_candidate_count": int(baseline_candidate_count or 0),
            "expected_candidate_count": int(baseline_candidate_count or 0),
            "served_candidate_count": 0,
            "delta_profile_progress_applicable": delta_progress_applicable,
            "delta_profile_progress_reason": delta_progress_reason,
            "source_validation_status": "validated",
        }
        return self.store.upsert_job_result_lifecycle(job_id=normalized_job_id, fields=fields)

    def publish_baseline_job_result_lifecycle(
        self,
        *,
        job_id: str,
        view_id: str,
        target_company: str,
        company_key: str,
        baseline_snapshot_id: str,
        baseline_candidate_count: int,
        requires_delta_acquisition: bool = True,
    ) -> dict[str, Any]:
        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        baseline_snapshot_id = str(baseline_snapshot_id or "").strip()
        baseline_count = int(baseline_candidate_count or 0)
        fields = {
            "view_id": str(view_id or "").strip(),
            "target_company": str(target_company or "").strip(),
            "company_key": str(company_key or "").strip(),
            "phase": "baseline_serving",
            "phase_status": "active",
            "state": "baseline_serving",
            "baseline_snapshot_id": baseline_snapshot_id,
            "served_snapshot_id": baseline_snapshot_id,
            "baseline_candidate_count": baseline_count,
            "served_candidate_count": baseline_count,
            "expected_candidate_count": baseline_count,
            "delta_profile_progress_applicable": bool(requires_delta_acquisition),
            "source_validation_status": "validated",
        }
        return self.store.upsert_job_result_lifecycle(job_id=normalized_job_id, fields=fields)

    def update_job_result_lifecycle_from_materialization(
        self,
        *,
        job_id: str,
        served_snapshot_id: str,
        served_candidate_count: int,
        current_snapshot_id: str = "",
        delta_profile_required_count: int | None = None,
        delta_profile_fetched_count: int | None = None,
        delta_profile_applied_count: int | None = None,
        delta_profile_materialized_count: int | None = None,
        delta_profile_board_visible_count: int | None = None,
        background_status: str = "",
        outreach_status: str = "",
        view_id: str = "",
    ) -> dict[str, Any]:
        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        existing = self.store.get_job_result_lifecycle(normalized_job_id) or {}
        metadata_payload = dict(existing.get("metadata") or {})
        served = str(served_snapshot_id or "").strip()
        baseline = str(existing.get("baseline_snapshot_id") or "").strip()
        current = str(current_snapshot_id or existing.get("current_snapshot_id") or "").strip()
        serving_view_id = str(view_id or existing.get("view_id") or "").strip()
        # Decide phase from concrete inputs, not by re-projecting summaries.
        if served and baseline and served == baseline:
            new_phase = "baseline_serving"
            new_state = "baseline_serving"
        elif served:
            new_phase = "current_snapshot_serving"
            new_state = "current_snapshot_serving"
        else:
            new_phase = str(existing.get("phase") or "")
            new_state = str(existing.get("state") or "")
        fields: dict[str, Any] = {
            "served_snapshot_id": served,
            "served_candidate_count": int(served_candidate_count or 0),
            "phase": new_phase,
            "state": new_state,
            "phase_status": "active",
            "source_validation_status": "validated",
        }
        if str(background_status or "").strip():
            fields["background_snapshot_materialization_status"] = str(background_status or "").strip()
        if str(outreach_status or "").strip():
            fields["outreach_layering_status"] = str(outreach_status or "").strip()
        if current_snapshot_id:
            fields["current_snapshot_id"] = current
        if view_id:
            fields["view_id"] = serving_view_id
        if delta_profile_required_count is not None:
            fields["delta_profile_required_count"] = max(
                int(existing.get("delta_profile_required_count") or 0),
                int(delta_profile_required_count or 0),
            )
        if delta_profile_fetched_count is not None:
            fields["delta_profile_fetched_count"] = max(
                int(existing.get("delta_profile_fetched_count") or 0),
                int(delta_profile_fetched_count or 0),
            )
        if delta_profile_applied_count is not None:
            fields["delta_profile_applied_count"] = max(
                int(existing.get("delta_profile_applied_count") or 0),
                int(delta_profile_applied_count or 0),
            )
        if delta_profile_materialized_count is not None:
            fields["delta_profile_materialized_count"] = max(
                int(existing.get("delta_profile_materialized_count") or 0),
                int(delta_profile_materialized_count or 0),
            )
        if delta_profile_board_visible_count is not None:
            fields["delta_profile_board_visible_count"] = max(
                int(existing.get("delta_profile_board_visible_count") or 0),
                int(delta_profile_board_visible_count or 0),
            )
        current_for_patch_projection = str(current or served or "").strip()
        patch_projection = self._job_board_visible_patch_progress_projection(
            job_id=normalized_job_id,
            snapshot_id=current_for_patch_projection,
        )
        patch_board_visible_count = _coerce_int(
            patch_projection.get("delta_profile_board_visible_count"),
            0,
        )
        if patch_board_visible_count > 0:
            required_for_patch_projection = int(
                fields.get("delta_profile_required_count")
                or existing.get("delta_profile_required_count")
                or 0
            )
            if required_for_patch_projection > 0:
                patch_board_visible_count = min(patch_board_visible_count, required_for_patch_projection)
            fields["delta_profile_board_visible_count"] = max(
                int(fields.get("delta_profile_board_visible_count") or 0),
                int(existing.get("delta_profile_board_visible_count") or 0),
                patch_board_visible_count,
            )
            fields["delta_profile_materialized_count"] = max(
                int(fields.get("delta_profile_materialized_count") or 0),
                int(existing.get("delta_profile_materialized_count") or 0),
                patch_board_visible_count,
            )
            fields["delta_profile_applied_count"] = max(
                int(fields.get("delta_profile_applied_count") or 0),
                int(existing.get("delta_profile_applied_count") or 0),
                patch_board_visible_count,
            )
            fields["delta_profile_fetched_count"] = max(
                int(fields.get("delta_profile_fetched_count") or 0),
                int(existing.get("delta_profile_fetched_count") or 0),
                patch_board_visible_count,
            )
        served_current_snapshot = bool(served and current and served == current and served != baseline)
        full_current_serving_with_complete_delta = False
        if served_current_snapshot:
            required_count = int(fields.get("delta_profile_required_count") or existing.get("delta_profile_required_count") or 0)
            baseline_count = int(existing.get("baseline_candidate_count") or 0)
            served_count = int(served_candidate_count or 0)
            fetched_count = max(
                int(fields.get("delta_profile_fetched_count") or 0),
                int(existing.get("delta_profile_fetched_count") or 0),
            )
            # A full current-snapshot result view is the serving truth. Partial
            # board-visible patch ledgers are streaming progress only; once the
            # complete current snapshot is published, do not let an older patch
            # count (for example 272/297) keep public APIs in a false pending
            # state or drive frontend totals.
            #
            # The delta profile denominator is URL-level work. The final board
            # candidate count can be smaller because provider URL rows may
            # canonicalize into an existing candidate or merge with each other.
            # Therefore full serving is proven by current-snapshot serving plus
            # fetched URL completion, not by `served >= baseline + required`.
            full_current_serving_with_complete_delta = bool(
                required_count > 0
                and served_count > 0
                and (
                    fetched_count >= required_count
                    or served_count >= baseline_count + required_count
                )
            )
            if full_current_serving_with_complete_delta:
                fields["delta_profile_fetched_count"] = max(
                    int(fields.get("delta_profile_fetched_count") or 0),
                    int(existing.get("delta_profile_fetched_count") or 0),
                    required_count,
                )
                fields["delta_profile_applied_count"] = max(
                    int(fields.get("delta_profile_applied_count") or 0),
                    int(existing.get("delta_profile_applied_count") or 0),
                    required_count,
                )
                fields["delta_profile_materialized_count"] = max(
                    int(fields.get("delta_profile_materialized_count") or 0),
                    int(existing.get("delta_profile_materialized_count") or 0),
                    required_count,
                )
                fields["delta_profile_board_visible_count"] = max(
                    int(fields.get("delta_profile_board_visible_count") or 0),
                    int(existing.get("delta_profile_board_visible_count") or 0),
                    required_count,
                )
                if not str(background_status or "").strip():
                    fields["background_snapshot_materialization_status"] = "current_snapshot_serving"
        if served_current_snapshot and serving_view_id:
            fields["serving_projection_id"] = serving_view_id
            fields["serving_projection_phase"] = "current_snapshot_serving"
            if delta_profile_board_visible_count is None:
                materialized_count = int(fields.get("delta_profile_materialized_count") or existing.get("delta_profile_materialized_count") or 0)
                existing_board_visible = int(existing.get("delta_profile_board_visible_count") or 0)
                if materialized_count > 0 or existing_board_visible > 0:
                    fields["delta_profile_board_visible_count"] = max(
                        existing_board_visible,
                        materialized_count,
                    )
        served_count_for_expected = int(served_candidate_count or 0)
        if served_count_for_expected:
            delta_progress_applicable = bool(existing.get("delta_profile_progress_applicable") is not False)
            already_promoted = bool(metadata_payload.get("delta_profile_denominator_promoted"))
            required_count = int(fields.get("delta_profile_required_count") or existing.get("delta_profile_required_count") or 0)
            baseline_count = int(existing.get("baseline_candidate_count") or 0)
            final_current_snapshot_serving = bool(served_current_snapshot and full_current_serving_with_complete_delta)
            can_promote_from_full_serving = bool(
                delta_progress_applicable
                and not already_promoted
                and final_current_snapshot_serving
                and required_count > 0
            )
            existing_expected_count = int(existing.get("expected_candidate_count") or 0)
            if (
                served_count_for_expected > existing_expected_count
                or can_promote_from_full_serving
                or final_current_snapshot_serving
            ) and (not delta_progress_applicable or already_promoted or can_promote_from_full_serving):
                fields["expected_candidate_count"] = served_count_for_expected
            if can_promote_from_full_serving:
                metadata_payload["delta_profile_denominator_promoted"] = True
                metadata_payload["stage1_terminal_promoted_at"] = _utc_now_iso()
                fields["metadata"] = metadata_payload
        return self.store.upsert_job_result_lifecycle(job_id=normalized_job_id, fields=fields)

    def _job_board_visible_patch_progress_projection(
        self,
        *,
        job_id: str,
        snapshot_id: str = "",
    ) -> dict[str, Any]:
        """Return the event-time board-visible watermark for a job snapshot.

        The patch ledger is append-only publication evidence. Lifecycle rows are
        the public projection, but concurrent lifecycle writers can race; readers
        and completion gates must be able to recover the monotonic watermark from
        the ledger instead of trusting a stale in-memory lifecycle merge.
        """

        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        normalized_snapshot_id = str(snapshot_id or "").strip()
        try:
            patches = self.store.list_job_board_visible_patches(
                job_id=normalized_job_id,
                snapshot_id=normalized_snapshot_id,
                limit=0,
            )
        except Exception:
            return {}
        if not patches:
            return {}
        max_cumulative_count = 0
        max_served_count = 0
        latest_patch: dict[str, Any] = {}
        for patch in patches:
            patch_payload = dict(patch or {})
            cumulative_ids = [
                str(candidate_id or "").strip()
                for candidate_id in list(patch_payload.get("cumulative_candidate_ids") or [])
                if str(candidate_id or "").strip()
            ]
            cumulative_count = max(
                _coerce_int(patch_payload.get("cumulative_candidate_count"), 0),
                len(_dedupe_texts(cumulative_ids)),
            )
            max_cumulative_count = max(max_cumulative_count, cumulative_count)
            max_served_count = max(max_served_count, _coerce_int(patch_payload.get("served_candidate_count"), 0))
            if not latest_patch or (
                _coerce_int(patch_payload.get("sequence_index"), 0),
                str(patch_payload.get("published_at") or patch_payload.get("updated_at") or ""),
            ) >= (
                _coerce_int(latest_patch.get("sequence_index"), 0),
                str(latest_patch.get("published_at") or latest_patch.get("updated_at") or ""),
            ):
                latest_patch = patch_payload
        return {
            "delta_profile_board_visible_count": max_cumulative_count,
            "delta_profile_materialized_count": max_cumulative_count,
            "delta_profile_applied_count": max_cumulative_count,
            "delta_profile_fetched_count": max_cumulative_count,
            "served_candidate_count": max_served_count,
            "latest_patch": latest_patch,
            "patch_count": len(patches),
        }

    def _normalize_lifecycle_from_board_visible_patch_projection(
        self,
        *,
        job_id: str,
        row: dict[str, Any],
    ) -> dict[str, Any]:
        normalized = dict(row or {})
        normalized_job_id = str(job_id or "").strip()
        current_snapshot_id = str(normalized.get("current_snapshot_id") or "").strip()
        if not normalized_job_id or not current_snapshot_id:
            return normalized
        expected_count = max(0, _coerce_int(normalized.get("expected_candidate_count"), 0))
        delta_required_count = max(0, _coerce_int(normalized.get("delta_profile_required_count"), 0))
        if expected_count <= 0:
            return normalized
        patch_projection = self._job_board_visible_patch_progress_projection(
            job_id=normalized_job_id,
            snapshot_id=current_snapshot_id,
        )
        patch_served_count = max(0, _coerce_int(patch_projection.get("served_candidate_count"), 0))
        patch_delta_visible_count = max(0, _coerce_int(patch_projection.get("delta_profile_board_visible_count"), 0))
        if patch_served_count < expected_count:
            return normalized
        if delta_required_count > 0 and patch_delta_visible_count < delta_required_count:
            return normalized
        normalized["served_snapshot_id"] = current_snapshot_id
        normalized["served_candidate_count"] = max(
            _coerce_int(normalized.get("served_candidate_count"), 0),
            patch_served_count,
        )
        normalized["expected_candidate_count"] = max(expected_count, patch_served_count)
        normalized["phase"] = "current_snapshot_serving"
        normalized["state"] = "current_snapshot_serving"
        normalized["serving_projection_phase"] = "current_snapshot_serving"
        if delta_required_count > 0:
            normalized["delta_profile_fetched_count"] = max(
                _coerce_int(normalized.get("delta_profile_fetched_count"), 0),
                min(delta_required_count, patch_delta_visible_count),
            )
            normalized["delta_profile_materialized_count"] = max(
                _coerce_int(normalized.get("delta_profile_materialized_count"), 0),
                min(delta_required_count, patch_delta_visible_count),
            )
            normalized["delta_profile_board_visible_count"] = max(
                _coerce_int(normalized.get("delta_profile_board_visible_count"), 0),
                min(delta_required_count, patch_delta_visible_count),
            )
        metadata_payload = dict(normalized.get("metadata") or {})
        metadata_payload["public_board_visible_patch_normalization"] = {
            "source": "job_board_visible_patches",
            "served_candidate_count": patch_served_count,
            "delta_profile_board_visible_count": patch_delta_visible_count,
            "reason": "complete_patch_ledger_outranks_stale_lifecycle_count",
        }
        normalized["metadata"] = metadata_payload
        return normalized

    def update_job_result_lifecycle_from_board_visible_patch(
        self,
        *,
        job_id: str,
        current_snapshot_id: str,
        delta_profile_board_visible_count: int,
        delta_profile_applied_count: int | None = None,
        delta_profile_materialized_count: int | None = None,
        served_candidate_count: int | None = None,
        served_snapshot_id: str = "",
        serving_projection_id: str = "",
        serving_projection_phase: str = "",
        view_id: str = "",
        patch: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Record a partial board-visible delta patch without inventing a new source.

        This writer is intentionally narrower than the full materialization writer:
        it may advance board-visible/materialized delta counters and attach patch
        metadata. It only changes `served_snapshot_id` when the caller provides an
        explicit serving projection, so counts and board rows cannot diverge.
        """

        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        existing = self.store.get_job_result_lifecycle(normalized_job_id) or {}
        metadata = dict(existing.get("metadata") or {})
        required_count = int(existing.get("delta_profile_required_count") or 0)
        visible_count = max(0, int(delta_profile_board_visible_count or 0))
        if required_count > 0:
            visible_count = min(visible_count, required_count)
        fetched_count = max(int(existing.get("delta_profile_fetched_count") or 0), visible_count)
        applied_count = (
            max(visible_count, int(existing.get("delta_profile_applied_count") or 0))
            if delta_profile_applied_count is None
            else max(visible_count, int(delta_profile_applied_count or 0))
        )
        materialized_count = (
            max(visible_count, int(existing.get("delta_profile_materialized_count") or 0))
            if delta_profile_materialized_count is None
            else max(visible_count, int(delta_profile_materialized_count or 0))
        )
        if fetched_count > 0:
            applied_count = min(applied_count, fetched_count)
            materialized_count = min(materialized_count, fetched_count)
        if required_count > 0:
            applied_count = min(applied_count, required_count)
            materialized_count = min(materialized_count, required_count)
        resolved_serving_projection_phase = (
            str(serving_projection_phase or "partial_delta_overlay").strip() or "partial_delta_overlay"
        )
        existing_served_snapshot_id = str(existing.get("served_snapshot_id") or "").strip()
        existing_serving_projection_phase = str(existing.get("serving_projection_phase") or "").strip()
        existing_served_count = max(0, int(existing.get("served_candidate_count") or 0))
        row_shell_publication = dict(metadata.get("row_shell_publication") or {})
        row_shell_served_count = 0
        row_shell_projection_id = ""
        row_shell_active = False
        if str(row_shell_publication.get("snapshot_id") or "").strip() == str(current_snapshot_id or "").strip():
            row_shell_served_count = _coerce_int(row_shell_publication.get("served_candidate_count"), 0)
            row_shell_projection_id = str(row_shell_publication.get("serving_projection_id") or "").strip()
            row_shell_active = row_shell_served_count > 0
        full_current_snapshot_serving = resolved_serving_projection_phase in {
            "current_snapshot_serving",
            "current_serving",
        }
        row_shell_current_snapshot_serving = (
            resolved_serving_projection_phase == "current_snapshot_row_shell_overlay"
        )
        incoming_partial_projection = resolved_serving_projection_phase in {
            "partial_delta_overlay",
            "partial_delta_board_visible_overlay",
            "partial_current_snapshot_overlay",
        }
        existing_current_rows_served = bool(
            existing_served_snapshot_id
            and str(current_snapshot_id or "").strip()
            and existing_served_snapshot_id == str(current_snapshot_id or "").strip()
            and existing_serving_projection_phase
            in {"current_snapshot_row_shell_overlay", "current_snapshot_serving", "current_serving"}
            and existing_served_count > 0
        )
        preserve_existing_current_rows = bool(
            incoming_partial_projection and (existing_current_rows_served or row_shell_active)
        )
        if preserve_existing_current_rows:
            if existing_serving_projection_phase in {"current_snapshot_serving", "current_serving"}:
                resolved_serving_projection_phase = existing_serving_projection_phase
                full_current_snapshot_serving = True
                row_shell_current_snapshot_serving = False
            elif row_shell_active or existing_serving_projection_phase == "current_snapshot_row_shell_overlay":
                resolved_serving_projection_phase = "current_snapshot_row_shell_overlay"
                row_shell_current_snapshot_serving = True
                full_current_snapshot_serving = False
        fields: dict[str, Any] = {
            "phase": "current_snapshot_serving" if full_current_snapshot_serving else "current_snapshot_materializing",
            "state": "current_snapshot_serving" if full_current_snapshot_serving else "current_snapshot_materializing",
            "phase_status": "active",
            "current_snapshot_id": str(current_snapshot_id or existing.get("current_snapshot_id") or "").strip(),
            "delta_profile_fetched_count": fetched_count,
            "delta_profile_applied_count": applied_count,
            "delta_profile_materialized_count": materialized_count,
            "delta_profile_board_visible_count": visible_count,
            "background_snapshot_materialization_status": (
                "current_snapshot_serving"
                if full_current_snapshot_serving
                else (
                    "row_shell_serving"
                    if row_shell_current_snapshot_serving or preserve_existing_current_rows
                    else "partial_board_visible"
                )
            ),
            "source_validation_status": "validated",
        }
        if served_candidate_count is not None:
            served_count = max(
                0,
                int(served_candidate_count or 0),
                existing_served_count if preserve_existing_current_rows else 0,
                row_shell_served_count if row_shell_current_snapshot_serving or preserve_existing_current_rows else 0,
            )
            fields["served_candidate_count"] = served_count
            if served_count > int(existing.get("expected_candidate_count") or 0):
                delta_progress_applicable = bool(existing.get("delta_profile_progress_applicable") is not False)
                already_promoted = bool(metadata.get("delta_profile_denominator_promoted"))
                baseline_count = int(existing.get("baseline_candidate_count") or 0)
                can_promote_from_full_patch = bool(
                    delta_progress_applicable
                    and not already_promoted
                    and full_current_snapshot_serving
                    and required_count > 0
                    and served_count >= baseline_count + required_count
                )
                if not delta_progress_applicable or already_promoted or can_promote_from_full_patch:
                    fields["expected_candidate_count"] = served_count
                if can_promote_from_full_patch:
                    metadata["delta_profile_denominator_promoted"] = True
                    metadata["stage1_terminal_promoted_at"] = _utc_now_iso()
                    fields["metadata"] = metadata
                elif (
                    not delta_progress_applicable
                    and served_count > 0
                    and required_count <= 0
                    and str(current_snapshot_id or "").strip()
                    and (
                        full_current_snapshot_serving
                        or row_shell_current_snapshot_serving
                        or preserve_existing_current_rows
                    )
                ):
                    stage1_required_count = max(
                        _coerce_int(existing.get("stage1_profile_fetch_required_count"), 0),
                        _coerce_int(existing.get("stage1_deduped_candidate_count"), 0),
                        _coerce_int(existing.get("stage1_deduped_profile_url_count"), 0),
                    )
                    if stage1_required_count > 0 and served_count >= stage1_required_count:
                        fields["expected_candidate_count"] = served_count
                        metadata["delta_profile_denominator_promoted"] = True
                        metadata["stage1_terminal_promoted_at"] = (
                            str(metadata.get("stage1_terminal_promoted_at") or "").strip()
                            or _utc_now_iso()
                        )
                        fields["metadata"] = metadata
        current_rows_projection_complete = bool(
            (full_current_snapshot_serving or row_shell_current_snapshot_serving or preserve_existing_current_rows)
            and required_count > 0
            and visible_count >= required_count
            and fetched_count >= required_count
        )
        if current_rows_projection_complete:
            served_count_for_completion = int(
                fields.get("served_candidate_count")
                or existing_served_count
                or row_shell_served_count
                or 0
            )
            expected_count_for_completion = int(
                fields.get("expected_candidate_count")
                or existing.get("expected_candidate_count")
                or served_count_for_completion
                or 0
            )
            if served_count_for_completion > 0 and (
                expected_count_for_completion <= 0
                or served_count_for_completion >= expected_count_for_completion
            ):
                fields["phase"] = "current_snapshot_serving"
                fields["state"] = "current_snapshot_serving"
        if preserve_existing_current_rows:
            fields["served_snapshot_id"] = str(current_snapshot_id or existing_served_snapshot_id).strip()
            fields["serving_projection_id"] = str(
                row_shell_projection_id
                or existing.get("serving_projection_id")
                or serving_projection_id
                or ""
            ).strip()
            fields["serving_projection_phase"] = resolved_serving_projection_phase
        elif served_snapshot_id and serving_projection_id:
            fields["served_snapshot_id"] = str(served_snapshot_id).strip()
            fields["serving_projection_id"] = str(serving_projection_id).strip()
            fields["serving_projection_phase"] = resolved_serving_projection_phase
        if view_id:
            fields["view_id"] = str(view_id).strip()
        if patch:
            patches = [
                dict(item)
                for item in list(metadata.get("board_visible_patches") or [])
                if isinstance(item, dict)
            ]
            normalized_patch = dict(patch)
            patch_id = str(normalized_patch.get("patch_id") or "").strip()
            if patch_id:
                patches = [item for item in patches if str(item.get("patch_id") or "").strip() != patch_id]
            patches.append(normalized_patch)
            metadata["latest_board_visible_patch"] = normalized_patch
            metadata["board_visible_patches"] = patches[-20:]
        fields["metadata"] = metadata
        return self.store.upsert_job_result_lifecycle(job_id=normalized_job_id, fields=fields)

    def mark_job_result_lifecycle_terminal(
        self,
        *,
        job_id: str,
        outcome: str = "completed",
    ) -> dict[str, Any]:
        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        existing = self.store.get_job_result_lifecycle(normalized_job_id) or {}
        outcome = str(outcome or "completed").strip().lower() or "completed"
        # Architectural invariant: a terminal job must not expose stable
        # `results` while serving stale baseline-only with materialization
        # incomplete. Encode this at the writer so the persisted row is honest.
        baseline = str(existing.get("baseline_snapshot_id") or "")
        served = str(existing.get("served_snapshot_id") or "")
        current = str(existing.get("current_snapshot_id") or "")
        delta_required = int(existing.get("delta_profile_required_count") or 0)
        delta_fetched = int(existing.get("delta_profile_fetched_count") or 0)
        delta_materialized = int(existing.get("delta_profile_materialized_count") or 0)
        delta_board_visible = int(existing.get("delta_profile_board_visible_count") or 0)
        if outcome == "failed":
            phase = "failed"
            state = "failed"
        elif baseline and served == baseline and delta_required > 0 and delta_materialized < delta_required:
            background = str(existing.get("background_snapshot_materialization_status") or "").strip().lower()
            phase = (
                "current_snapshot_materializing"
                if background in {"", "deferred", "scheduled", "running"}
                else "delta_applying"
            )
            state = phase
        else:
            phase = "current_serving" if served and served != baseline else str(existing.get("phase") or "")
            state = phase
        fields: dict[str, Any] = {
            "phase": phase,
            "state": state,
            "phase_status": "terminal",
            "source_validation_status": "validated",
        }
        # Safety-net promotion: if delta_profile_denominator_promoted is False
        # but the row has Stage 1 lane counts, do the one-shot promotion now.
        # This handles jobs that completed without an explicit lane-terminal signal.
        metadata_payload = dict(existing.get("metadata") or {})
        already_promoted = bool(metadata_payload.get("delta_profile_denominator_promoted"))
        delta_progress_applicable = bool(existing.get("delta_profile_progress_applicable") is not False)
        delta_required_count = int(existing.get("delta_profile_required_count") or 0)
        stage1_profile_required = int(existing.get("stage1_profile_fetch_required_count") or 0)
        if not already_promoted and (delta_required_count > 0 or stage1_profile_required > 0):
            baseline_count = int(existing.get("baseline_candidate_count") or 0)
            served_count = int(existing.get("served_candidate_count") or 0)
            existing_expected = int(existing.get("expected_candidate_count") or 0)
            full_current_snapshot_serving_with_complete_delta = bool(
                served
                and current
                and served == current
                and served != baseline
                and served_count > 0
                and delta_required_count > 0
                and max(delta_fetched, delta_materialized, delta_board_visible) >= delta_required_count
            )
            if full_current_snapshot_serving_with_complete_delta:
                # The current snapshot projection is the authoritative
                # post-dedupe serving total. Do not re-inflate it to
                # baseline + URL denominator: one fetched profile URL may
                # merge into an existing canonical candidate row.
                promoted_expected = served_count
            elif delta_progress_applicable and delta_required_count > 0:
                promoted_expected = max(
                    baseline_count + delta_required_count,
                    served_count,
                    existing_expected,
                )
            else:
                # Non-delta/live-roster workflows publish the canonical board
                # population, not raw lane rows. Preserve Stage 1/profile
                # denominators, but do not let a stale raw existing_expected
                # (for example 120 current + 25 former = 145 raw rows) inflate a
                # deduped served board (140 canonical rows) at terminal time.
                promoted_expected = max(
                    stage1_profile_required,
                    int(existing.get("stage1_deduped_candidate_count") or 0),
                    served_count,
                )
            if promoted_expected > 0:
                fields["expected_candidate_count"] = promoted_expected
            metadata_payload["delta_profile_denominator_promoted"] = True
            metadata_payload["stage1_terminal_promoted_at"] = _utc_now_iso()
            fields["metadata"] = metadata_payload
        if outcome != "failed" and not delta_progress_applicable:
            served_count = int(existing.get("served_candidate_count") or 0)
            current_snapshot_served = bool(
                served
                and current
                and served == current
                and served_count > 0
            )
            if current_snapshot_served:
                # Non-delta/live-roster workflows expose the canonical board
                # row set. Raw lane rows can be larger before identity dedupe
                # (for example Lovable 120 current + 25 former => 140 people);
                # terminal accounting must not preserve the raw 145 denominator
                # once the deduped current snapshot is serving.
                fields["expected_candidate_count"] = served_count
                metadata_payload = dict(fields.get("metadata") or metadata_payload)
                metadata_payload["non_delta_terminal_expected_source"] = "canonical_served_candidate_count"
                fields["metadata"] = metadata_payload
        return self.store.upsert_job_result_lifecycle(job_id=normalized_job_id, fields=fields)

    def _stage1_lanes_terminal_for_job(
        self,
        *,
        job_id: str,
        request: JobRequest,
        snapshot_id: str,
    ) -> bool:
        """Determine whether Stage 1 lanes have reached a terminal state.

        The workflow-specific source is resolved through the shared discovery
        lane registry. Scoped-search and live-roster differ by durable lane
        source only; the public lifecycle promotion contract is identical.
        """

        normalized_job_id = str(job_id or "").strip()
        normalized_snapshot_id = str(snapshot_id or "").strip()
        if not normalized_job_id or not normalized_snapshot_id:
            return False
        try:
            contract = linkedin_stage1_discovery_lane_contract(
                dict(getattr(request, "execution_preferences", {}) or {})
            )
            workers = self._safe_list_persisted_job_workers(normalized_job_id)
            if discovery_lane_has_non_terminal_worker(workers, contract):
                return False
            if contract.durable_item_kind:
                discovery_items = self.store.list_job_materialization_items(
                    job_id=normalized_job_id,
                    item_kind=contract.durable_item_kind,
                    limit=500,
                )
                discovery_items = [
                    dict(item)
                    for item in list(discovery_items or [])
                    if str(dict(item).get("snapshot_id") or "").strip() == normalized_snapshot_id
                ]
                workflow_run_id = legacy_job_workflow_run_id(normalized_job_id)
                stage1_proof_prefix = f"stage1_lane:{contract.lane_kind}:{normalized_snapshot_id}"
                proof_events = [
                    dict(event)
                    for event in self.store.list_workflow_events(workflow_run_id, limit=0)
                    if str(dict(event).get("event_type") or "").strip() == "CompletionProofRecorded"
                    and str(dict(dict(event).get("payload") or {}).get("proof_key") or "").strip().startswith(
                        stage1_proof_prefix
                    )
                ]
                discovery_commands = [
                    dict(command)
                    for command in self.store.list_workflow_commands(
                        workflow_run_id=workflow_run_id,
                        owner=LINKEDIN_DISCOVERY_QUERY_RUN_OWNER,
                        limit=0,
                    )
                    if str(dict(command).get("command_type") or "").strip()
                    == LINKEDIN_DISCOVERY_QUERY_RUN_COMMAND_TYPE
                    and str(dict(dict(command).get("payload") or {}).get("snapshot_id") or "").strip()
                    == normalized_snapshot_id
                ]
                non_terminal_discovery_commands = [
                    command
                    for command in discovery_commands
                    if str(command.get("status") or "").strip().lower()
                    not in {"succeeded", "failed_terminal", "cancelled", "superseded"}
                ]
                if non_terminal_discovery_commands:
                    return False
                terminal_discovery_commands = [
                    command
                    for command in discovery_commands
                    if str(command.get("status") or "").strip().lower()
                    in {"succeeded", "failed_terminal", "cancelled", "superseded"}
                ]
                if contract.require_any_durable_item and not (
                    discovery_items or proof_events or terminal_discovery_commands
                ):
                    return False
                all_terminal = all(
                    str(dict(item).get("status") or "").strip().lower() in contract.terminal_item_statuses
                    for item in discovery_items
                )
                if not all_terminal:
                    return False
            lane_workers = [
                dict(worker)
                for worker in workers
                if discovery_lane_worker_matches(dict(worker), contract)
            ]
            if contract.require_any_worker and not lane_workers:
                return False
            if contract.require_snapshot_apply_marker:
                return any(
                    str(self._worker_inline_incremental_apply_marker(worker).get("snapshot_id") or "").strip()
                    == normalized_snapshot_id
                    for worker in lane_workers
                )
            return True
        except Exception:
            return False

    def update_job_result_lifecycle_from_stage1(
        self,
        *,
        job_id: str,
        linkedin_stage_1_progress: dict[str, Any],
        projection_source_snapshot_id: str = "",
        queued_profile_url_count_from_workers: int | None = None,
        is_delta_workflow: bool | None = None,
        stage1_lanes_terminal: bool = False,
    ) -> dict[str, Any]:
        """Atomic Stage 1 projection writer.

        The caller must pass a single coherent `linkedin_stage_1_progress`
        payload (the dict returned by `_build_linkedin_stage1_progress_payload`)
        and the snapshot id its lane evidence came from. Lane counts and the
        profile denominator are persisted as one snapshot, never mixed across
        sources. Worker-derived queued URL totals can be supplied for
        observability only via `queued_profile_url_count_from_workers`; that
        value is stored in metadata so the public-facing
        `stage1_profile_fetch_required_count` cannot be inflated by URLs the
        lane snapshot has not yet seen — the OpenAI Infra `current=0/former=10/
        profile_required=77` failure mode by construction.

        Stale-write rejection: when the stored row already has a
        `projection_source_snapshot_id`, this writer ignores writes whose
        snapshot id sorts strictly less than the stored one (snapshot ids are
        timestamp-prefixed and therefore monotonic).
        """

        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        progress = dict(linkedin_stage_1_progress or {})
        new_snapshot_id = str(projection_source_snapshot_id or "").strip()
        existing = self.store.get_job_result_lifecycle(normalized_job_id) or {}
        stored_snapshot_id = str(existing.get("projection_source_snapshot_id") or "").strip()
        if new_snapshot_id and stored_snapshot_id and new_snapshot_id < stored_snapshot_id:
            # Stale write — older lane snapshot must not overwrite newer.
            return existing

        def _ci(name: str) -> int:
            try:
                return max(int(progress.get(name) or 0), 0)
            except (TypeError, ValueError):
                return 0

        current_count = _ci("current_search_returned_count")
        former_count = _ci("former_search_returned_count")
        all_count = _ci("all_search_returned_count")
        deduped_candidate_count = _ci("deduped_candidate_count")
        deduped_profile_url_count = _ci("deduped_profile_url_count")
        profile_fetch_required_count = _ci("profile_fetch_required_count")
        profile_fetched_count = _ci("profile_fetched_count")

        # Contract enforcement: deduped counts must not exceed lane sums.
        # This prevents the OpenAI `current=0, former=74, deduped=241` bug
        # where worker URLs inflated deduped beyond what lanes actually returned.
        lane_total = current_count + former_count + all_count
        if lane_total > 0:
            deduped_candidate_count = min(deduped_candidate_count, lane_total)
            deduped_profile_url_count = min(deduped_profile_url_count, lane_total)

        # Coherence guard: profile_fetch_required_count is the lane-projection
        # denominator. It must not exceed the deduped population this writer
        # actually saw. The old clause included `profile_fetch_required_count`
        # in the max(...), making the constraint vacuous. Fixed: the max is
        # strictly over deduped counts, so `profile_fetch_required <= deduped`.
        coherent_required = min(
            profile_fetch_required_count,
            max(deduped_candidate_count, deduped_profile_url_count),
        )
        # If lane returned zero rows but the worker queue holds URLs, profile
        # fetch denominator must stay 0 in the business projection (and the
        # worker count is exposed separately as a technical metric).
        if (
            current_count == 0
            and former_count == 0
            and all_count == 0
            and deduped_candidate_count == 0
            and deduped_profile_url_count == 0
        ):
            coherent_required = 0
            profile_fetched_count = 0

        # delta_profile_required/fetched mirror the Stage 1 totals only when
        # this is a delta workflow. For full local reuse / live roster the
        # delta progress is not applicable.
        existing_progress_applicable = bool(existing.get("delta_profile_progress_applicable") is not False)
        delta_progress_applicable = (
            bool(is_delta_workflow) if is_delta_workflow is not None else existing_progress_applicable
        )

        # Phase progression. Move from `baseline_serving`/`planning` into
        # `delta_applying` once any actual Stage 1 work has been observed in
        # this snapshot. Do not regress out of more advanced phases.
        existing_phase = str(existing.get("phase") or "").strip()
        next_phase = existing_phase
        any_stage1_progress = bool(
            current_count
            or former_count
            or all_count
            or deduped_candidate_count
            or coherent_required
            or profile_fetched_count
        )
        if existing_phase in {"", "planning", "baseline_serving"} and any_stage1_progress:
            next_phase = "delta_applying" if delta_progress_applicable else "current_snapshot_serving"

        metadata_payload = dict(existing.get("metadata") or {})
        worker_meta = dict(metadata_payload.get("workers") or {})
        if queued_profile_url_count_from_workers is not None:
            try:
                worker_meta["queued_profile_url_count"] = max(int(queued_profile_url_count_from_workers), 0)
            except (TypeError, ValueError):
                worker_meta["queued_profile_url_count"] = 0
            metadata_payload["workers"] = worker_meta

        fields: dict[str, Any] = {
            "stage1_current_search_returned_count": current_count,
            "stage1_former_search_returned_count": former_count,
            "stage1_all_search_returned_count": all_count,
            "stage1_deduped_candidate_count": deduped_candidate_count,
            "stage1_deduped_profile_url_count": deduped_profile_url_count,
            "stage1_profile_fetch_required_count": coherent_required,
            "stage1_profile_fetched_count": profile_fetched_count,
            "delta_profile_progress_applicable": delta_progress_applicable,
            "delta_profile_progress_reason": (
                "linkedin_stage_1_progress"
                if delta_progress_applicable
                else (
                    "not_applicable_live_roster_stage1"
                    if any_stage1_progress
                    else "not_applicable_full_local_asset_reuse"
                )
            ),
            "metadata": metadata_payload,
            "source_validation_status": "validated",
        }
        if delta_progress_applicable:
            existing_required = int(existing.get("delta_profile_required_count") or 0)
            existing_fetched = int(existing.get("delta_profile_fetched_count") or 0)
            existing_applied = int(existing.get("delta_profile_applied_count") or 0)
            existing_materialized = int(existing.get("delta_profile_materialized_count") or 0)
            existing_board_visible = int(existing.get("delta_profile_board_visible_count") or 0)
            fields["delta_profile_required_count"] = max(coherent_required, existing_required)
            fields["delta_profile_fetched_count"] = max(profile_fetched_count, existing_fetched)
            if existing_applied:
                fields["delta_profile_applied_count"] = existing_applied
            if existing_materialized:
                fields["delta_profile_materialized_count"] = existing_materialized
            if existing_board_visible:
                fields["delta_profile_board_visible_count"] = existing_board_visible
            # expected_candidate_count for an in-progress delta workflow:
            # HOLD at baseline until Stage 1 lanes are terminal, then promote
            # ONCE to baseline + delta_required. This prevents the 300/351 →
            # 300/425 → 300/525 drift observed in the OpenAI manual test.
            existing_baseline = int(existing.get("baseline_candidate_count") or 0)
            existing_served = int(existing.get("served_candidate_count") or 0)
            existing_expected = int(existing.get("expected_candidate_count") or 0)
            existing_metadata = dict(existing.get("metadata") or {})
            already_promoted = bool(existing_metadata.get("delta_profile_denominator_promoted"))
            existing_served_snapshot = str(existing.get("served_snapshot_id") or "").strip()
            existing_current_snapshot = str(existing.get("current_snapshot_id") or "").strip()
            full_current_snapshot_served = bool(
                existing_served_snapshot
                and existing_current_snapshot
                and existing_served_snapshot == existing_current_snapshot
                and existing_served_snapshot != str(existing.get("baseline_snapshot_id") or "").strip()
            )
            can_promote_from_full_serving = bool(
                full_current_snapshot_served
                and int(fields["delta_profile_required_count"] or 0) > 0
                and existing_served >= existing_baseline + int(fields["delta_profile_required_count"] or 0)
            )
            if already_promoted:
                # Promotion is one-way. A later stale/non-terminal observation
                # must not erase the durable denominator contract.
                metadata_payload["delta_profile_denominator_promoted"] = True
            elif stage1_lanes_terminal or can_promote_from_full_serving:
                # Promote ONCE: baseline + delta_required.
                projected_expected = max(
                    existing_baseline + int(fields["delta_profile_required_count"] or 0),
                    existing_served,
                    existing_expected,
                )
                if projected_expected:
                    fields["expected_candidate_count"] = projected_expected
                metadata_payload["delta_profile_denominator_promoted"] = True
                metadata_payload["stage1_terminal_promoted_at"] = _utc_now_iso()
            else:
                # Hold at the currently served baseline. Do not preserve a
                # drifted existing_expected from partial board-visible writers;
                # that was the source of 300/400/597 pre-promotion samples.
                projected_expected = max(existing_baseline, existing_served)
                if projected_expected:
                    fields["expected_candidate_count"] = projected_expected
                metadata_payload["delta_profile_denominator_promoted"] = False
        else:
            fields["delta_profile_required_count"] = 0
            fields["delta_profile_fetched_count"] = 0
            fields["delta_profile_applied_count"] = 0
            fields["delta_profile_materialized_count"] = 0
            fields["delta_profile_board_visible_count"] = 0
            # Live-roster: same gate. Until terminal, hold at served; after
            # terminal, promote to max(coherent_required, deduped, served).
            existing_served = int(existing.get("served_candidate_count") or 0)
            existing_expected = int(existing.get("expected_candidate_count") or 0)
            existing_metadata = dict(existing.get("metadata") or {})
            already_promoted = bool(existing_metadata.get("delta_profile_denominator_promoted"))
            if already_promoted:
                metadata_payload["delta_profile_denominator_promoted"] = True
                if (
                    existing_served > 0
                    and coherent_required > 0
                    and existing_served >= coherent_required
                    and existing_expected > existing_served
                ):
                    fields["expected_candidate_count"] = max(
                        coherent_required,
                        deduped_candidate_count,
                        deduped_profile_url_count,
                        existing_served,
                    )
            elif stage1_lanes_terminal:
                live_roster_expected = max(
                    coherent_required,
                    deduped_candidate_count,
                    deduped_profile_url_count,
                    existing_served,
                )
                if live_roster_expected:
                    fields["expected_candidate_count"] = live_roster_expected
                metadata_payload["delta_profile_denominator_promoted"] = True
                metadata_payload["stage1_terminal_promoted_at"] = _utc_now_iso()
            else:
                live_roster_expected = existing_served or existing_expected
                if live_roster_expected:
                    fields["expected_candidate_count"] = live_roster_expected
                metadata_payload["delta_profile_denominator_promoted"] = False
        fields["metadata"] = metadata_payload
        if new_snapshot_id:
            fields["projection_source_snapshot_id"] = new_snapshot_id
        if next_phase and next_phase != existing_phase:
            fields["phase"] = next_phase
            fields["state"] = next_phase
        return self.store.upsert_job_result_lifecycle(job_id=normalized_job_id, fields=fields)

    def _persist_canonical_lifecycle(
        self,
        *,
        job_id: str,
        projection: dict[str, Any],
        target_company: str = "",
        company_key: str = "",
        view_id: str = "",
        workflow_kind: str = "",
        phase: str = "",
        phase_status: str = "",
        background_status: str = "",
        outreach_status: str = "",
        last_event_id: int = 0,
        projection_source_snapshot_id: str = "",
        source_validation_status: str = "validated",
    ) -> dict[str, Any]:
        """Map an event-time lifecycle projection to the canonical
        `job_result_lifecycle` row schema and persist it.

        This is the shared event-time/backfill writer for canonical lifecycle
        rows; public-API readers render rows and do not route through it.
        """

        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        projection = dict(projection or {})
        # Map projection fields onto canonical row fields; leave per-lane Stage 1
        # counters at 0 here (they will be filled by the Stage 1 projection
        # writer in a follow-up patch).
        fields: dict[str, Any] = {
            "view_id": view_id,
            "company_key": company_key,
            "target_company": target_company,
            "workflow_kind": workflow_kind,
            "phase": phase or projection.get("state") or "",
            "phase_status": phase_status,
            "state": projection.get("state") or "",
            "baseline_snapshot_id": projection.get("baseline_snapshot_id") or "",
            "current_snapshot_id": projection.get("current_snapshot_id") or "",
            "served_snapshot_id": projection.get("served_snapshot_id") or "",
            "baseline_candidate_count": int(projection.get("baseline_candidate_count") or 0),
            "expected_candidate_count": int(projection.get("expected_candidate_count") or 0),
            "served_candidate_count": int(projection.get("served_candidate_count") or 0),
            "delta_profile_required_count": int(projection.get("delta_profile_required_count") or 0),
            "delta_profile_fetched_count": int(projection.get("delta_profile_fetched_count") or 0),
            "delta_profile_materialized_count": int(projection.get("delta_profile_materialized_count") or 0),
            "delta_profile_progress_applicable": bool(projection.get("delta_profile_progress_applicable") is not False),
            "delta_profile_progress_reason": str(projection.get("delta_profile_progress_reason") or ""),
            "background_snapshot_materialization_status": str(
                background_status or projection.get("background_snapshot_materialization_status") or ""
            ),
            "outreach_layering_status": str(outreach_status or projection.get("outreach_layering_status") or ""),
            "source_validation_status": source_validation_status or "validated",
            "last_event_id": int(last_event_id or 0),
            "projection_source_snapshot_id": str(projection_source_snapshot_id or ""),
        }
        return self.store.upsert_job_result_lifecycle(job_id=normalized_job_id, fields=fields)

    def _project_canonical_lifecycle_payload(
        self,
        *,
        row: dict[str, Any],
    ) -> dict[str, Any]:
        """Render the canonical row in the public-API lifecycle payload shape.

        The keys returned here are the public lifecycle contract. Public
        readers do not reconstruct them from job summaries, result-view
        metadata, stage files, or candidate materialization state.
        """

        delta_profile_progress_applicable = bool(row.get("delta_profile_progress_applicable") is not False)
        delta_profile_required_count = int(row.get("delta_profile_required_count") or 0)
        delta_profile_fetched_count = int(row.get("delta_profile_fetched_count") or 0)
        delta_profile_materialized_count = int(row.get("delta_profile_materialized_count") or 0)
        delta_profile_board_visible_count = int(row.get("delta_profile_board_visible_count") or 0)
        served_candidate_count = int(row.get("served_candidate_count") or 0)
        expected_candidate_count = int(row.get("expected_candidate_count") or 0)
        if not delta_profile_progress_applicable:
            delta_profile_required_count = 0
            delta_profile_fetched_count = 0
            delta_profile_materialized_count = 0
            delta_profile_board_visible_count = 0
            stage1_profile_required_count = max(
                0,
                _coerce_int(row.get("stage1_profile_fetch_required_count"), 0),
            )
            stage1_deduped_count = max(
                0,
                _coerce_int(row.get("stage1_deduped_candidate_count"), 0),
                _coerce_int(row.get("stage1_deduped_profile_url_count"), 0),
            )
            stage1_raw_lane_count = (
                _coerce_int(row.get("stage1_current_search_returned_count"), 0)
                + _coerce_int(row.get("stage1_former_search_returned_count"), 0)
                + _coerce_int(row.get("stage1_all_search_returned_count"), 0)
            )
            stage1_public_candidate_count = max(stage1_profile_required_count, stage1_deduped_count)
            baseline_candidate_count = _coerce_int(row.get("baseline_candidate_count"), 0)
            if (
                baseline_candidate_count <= 0
                and stage1_public_candidate_count > 0
                and stage1_raw_lane_count >= expected_candidate_count > stage1_public_candidate_count
            ):
                # Full-company/live-roster acquisition may preserve raw provider
                # rows for audit, but public progress/result pages expose the
                # deduped board population. Do this before served rows are
                # complete so `/progress` never regresses from raw 145 to public
                # 140 when the final projection becomes available.
                expected_candidate_count = stage1_public_candidate_count
                if served_candidate_count > expected_candidate_count:
                    served_candidate_count = expected_candidate_count
            current_snapshot_id = str(row.get("current_snapshot_id") or "").strip()
            served_snapshot_id = str(row.get("served_snapshot_id") or "").strip()
            if (
                current_snapshot_id
                and served_snapshot_id == current_snapshot_id
                and served_candidate_count > 0
                and expected_candidate_count > served_candidate_count
                and stage1_profile_required_count > 0
                and served_candidate_count >= max(stage1_profile_required_count, stage1_deduped_count)
            ):
                # Live-roster raw source rows can be preserved in audit files,
                # but public lifecycle denominators are canonical board rows.
                expected_candidate_count = served_candidate_count
        else:
            state = str(row.get("state") or row.get("phase") or "").strip()
            serving_projection_phase = str(row.get("serving_projection_phase") or "").strip()
            terminal_current_serving = state in {
                "current_snapshot_serving",
                "post_result_layering",
                "current_serving",
            } or serving_projection_phase == "current_snapshot_serving"
            current_snapshot_id = str(row.get("current_snapshot_id") or "").strip()
            served_snapshot_id = str(row.get("served_snapshot_id") or "").strip()
            if (
                terminal_current_serving
                and current_snapshot_id
                and served_snapshot_id == current_snapshot_id
                and served_candidate_count > 0
                and expected_candidate_count > served_candidate_count
                and delta_profile_required_count > 0
                and max(
                    delta_profile_fetched_count,
                    delta_profile_materialized_count,
                    delta_profile_board_visible_count,
                )
                >= delta_profile_required_count
            ):
                # Legacy terminal rows may have promoted expected_count with
                # baseline + URL denominator. The current snapshot is already
                # serving, so public reads expose the post-dedupe serving total.
                expected_candidate_count = served_candidate_count
            # Legacy rows from the board-visible transition can have a stale
            # board-visible counter even after the full current snapshot is
            # already serving. Public payloads must expose the serving snapshot
            # as truth and not let a patch-ledger mirror keep the UI pending.
            if (
                terminal_current_serving
                and current_snapshot_id
                and served_snapshot_id == current_snapshot_id
                and expected_candidate_count > 0
                and served_candidate_count >= expected_candidate_count
                and delta_profile_required_count > 0
                and delta_profile_materialized_count >= delta_profile_required_count
            ):
                delta_profile_board_visible_count = max(
                    delta_profile_board_visible_count,
                    delta_profile_materialized_count,
                )

        return {
            "state": str(row.get("state") or row.get("phase") or "unavailable"),
            "baseline_snapshot_id": str(row.get("baseline_snapshot_id") or ""),
            "current_snapshot_id": str(row.get("current_snapshot_id") or ""),
            "served_snapshot_id": str(row.get("served_snapshot_id") or ""),
            "baseline_candidate_count": int(row.get("baseline_candidate_count") or 0),
            "served_candidate_count": served_candidate_count,
            "expected_candidate_count": expected_candidate_count,
            "delta_profile_progress_applicable": delta_profile_progress_applicable,
            "delta_profile_progress_reason": str(row.get("delta_profile_progress_reason") or ""),
            "delta_profile_required_count": delta_profile_required_count,
            "delta_profile_fetched_count": delta_profile_fetched_count,
            "delta_profile_materialized_count": delta_profile_materialized_count,
            "delta_profile_board_visible_count": delta_profile_board_visible_count,
            "delta_profile_pending_count": 0,
            "delta_profile_queued_count": 0,
            "delta_profile_retryable_count": 0,
            "serving_projection_id": str(row.get("serving_projection_id") or ""),
            "serving_projection_phase": str(row.get("serving_projection_phase") or ""),
            "background_snapshot_materialization_status": str(
                row.get("background_snapshot_materialization_status") or ""
            ),
            "outreach_layering_status": str(row.get("outreach_layering_status") or ""),
            "source_validation_status": str(row.get("source_validation_status") or ""),
            "metadata": _compact_public_progress_dict(dict(row.get("metadata") or {})),
        }

    def _job_result_lifecycle_repair_required_payload(
        self,
        *,
        job_id: str,
        reason: str,
        persisted: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        row = dict(persisted or {})
        metadata = dict(row.get("metadata") or {})
        metadata["repair_required"] = True
        metadata["repair_reason"] = str(reason or "job_result_lifecycle_repair_required")
        metadata["job_id"] = str(job_id or "").strip()
        return self._project_canonical_lifecycle_payload(
            row={
                **row,
                "state": "lifecycle_repair_required",
                "phase": "lifecycle_repair_required",
                "source_validation_status": str(row.get("source_validation_status") or "repair_required"),
                "metadata": metadata,
            }
        )

    def _normalize_lifecycle_for_terminal_phase(
        self,
        *,
        job: dict[str, Any],
        projection: dict[str, Any],
    ) -> dict[str, Any]:
        """Apply lifecycle state normalization to projection.

        For all jobs (running or terminal): when serving baseline-only with
        incomplete delta materialization, override the state to
        `current_snapshot_materializing` or `delta_applying` based on background
        materialization status.

        For terminal jobs: enforce the architectural invariant that a completed
        job must not expose stable `results` while serving stale baseline-only
        with materialization incomplete.

        For failed jobs: always report state="failed" regardless of
        materialization state.

        This is a render-time normalization only; we do not write back to the
        canonical row. The materialization writer will eventually update the row
        to reflect the true serving state once materialization completes.
        """

        normalized = dict(projection or {})
        status = str(job.get("status") or "").strip().lower()
        # Failed jobs always report state="failed" regardless of materialization
        # state. The terminal invariant only applies to completed jobs that
        # finished while delta was incomplete.
        if status == "failed":
            return normalized
        baseline_snapshot_id = str(normalized.get("baseline_snapshot_id") or "")
        served_snapshot_id = str(normalized.get("served_snapshot_id") or "")
        delta_required = int(normalized.get("delta_profile_required_count") or 0)
        delta_materialized = int(normalized.get("delta_profile_materialized_count") or 0)
        if (
            baseline_snapshot_id
            and served_snapshot_id == baseline_snapshot_id
            and delta_required > 0
            and delta_materialized < delta_required
        ):
            # When delta acquisition is actively in progress (stage=acquiring),
            # report state as delta_applying regardless of background materialization status
            stage = str(job.get("stage") or "").strip().lower()
            if stage == "acquiring":
                normalized["state"] = "delta_applying"
            else:
                # For jobs past acquisition, check background materialization status
                background_status = str(normalized.get("background_snapshot_materialization_status") or "").strip().lower()
                normalized["state"] = (
                    "current_snapshot_materializing"
                    if background_status in {"", "deferred", "scheduled", "running"}
                    else "delta_applying"
                )
        return normalized

    def _normalize_lifecycle_for_final_result_view(
        self,
        *,
        row: dict[str, Any],
        job: dict[str, Any] | None,
        candidate_source: dict[str, Any] | None,
        result_view: dict[str, Any] | None,
        asset_population: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Render completed serving facts from the durable result view.

        The lifecycle row is the event-time writer's projection, but older
        partial-delta writers can leave an inflated expected count after final
        candidate dedupe. When a result view has a public serving proof, its
        summary count is the canonical board population for public reads.
        """

        normalized = dict(row or {})
        source_payload = dict(candidate_source or {})
        view_payload = dict(result_view or source_payload.get("result_view") or {})
        if not view_payload:
            return normalized
        if str(view_payload.get("source_kind") or "").strip() != "company_snapshot":
            return normalized
        if str(view_payload.get("view_kind") or "").strip() != "asset_population":
            return normalized
        view_summary = dict(view_payload.get("summary") or {})
        view_metadata = dict(view_payload.get("metadata") or {})
        source_path_value = str(view_payload.get("source_path") or source_payload.get("source_path") or "").strip()
        source_path_is_normalized_artifact = bool(
            source_path_value
            and self._path_is_normalized_candidate_artifact(Path(source_path_value).expanduser())
        )
        asset_population_patch = {
            **dict(source_payload.get("asset_population_patch") or {}),
            **dict(view_metadata.get("asset_population_patch") or {}),
        }
        partial_board_visible_patch = dict(view_metadata.get("partial_board_visible_patch") or {})
        row_projection_phase = str(normalized.get("serving_projection_phase") or "").strip()
        partial_projection_phases = {
            "partial_current_snapshot_overlay",
            "partial_delta_overlay",
            "partial_delta_board_visible_overlay",
            "current_snapshot_row_shell_overlay",
        }
        patch_mode = str(asset_population_patch.get("mode") or asset_population_patch.get("overlay_write_mode") or "").strip()
        recovery_reason = str(view_summary.get("recovery_reason") or "").strip()
        if (
            (
                not source_path_is_normalized_artifact
                and (
                    row_projection_phase in partial_projection_phases
                    or bool(partial_board_visible_patch)
                    or patch_mode.startswith("partial_")
                    or recovery_reason.startswith("partial_")
                    or str(view_summary.get("summary_provider") or "").strip()
                    == "stage1_row_shell_publication"
                )
            )
        ):
            # A partial overlay/result view is a row-publication proof, not a
            # terminal serving proof. It must not collapse expected_count down to
            # the currently visible rows or flip the lifecycle to final serving.
            return normalized
        served_count = _coerce_int(view_summary.get("candidate_count"), 0)
        if served_count <= 0:
            return normalized
        snapshot_id = str(view_payload.get("snapshot_id") or "").strip()
        if not snapshot_id:
            return normalized
        row_state = str(normalized.get("state") or normalized.get("phase") or "").strip()
        row_projection_phase = str(normalized.get("serving_projection_phase") or "").strip()
        row_already_current_serving = bool(
            row_state in {"current_snapshot_serving", "post_result_layering", "current_serving"}
            or row_projection_phase == "current_snapshot_serving"
        )
        if (
            row_already_current_serving
            and _coerce_int(normalized.get("served_candidate_count"), 0) == served_count
            and _coerce_int(normalized.get("expected_candidate_count"), 0) == served_count
        ):
            return normalized
        current_snapshot_id = str(normalized.get("current_snapshot_id") or "").strip()
        if current_snapshot_id and snapshot_id != current_snapshot_id:
            return normalized
        baseline_snapshot_id = str(normalized.get("baseline_snapshot_id") or "").strip()
        baseline_candidate_count = max(0, _coerce_int(normalized.get("baseline_candidate_count"), 0))
        if (
            baseline_snapshot_id
            and snapshot_id != baseline_snapshot_id
            and baseline_candidate_count > 0
            and served_count < baseline_candidate_count
        ):
            # A baseline+delta current snapshot must never become public
            # current-serving with fewer rows than the baseline it extends.
            # During large materialization the normalized artifact can be
            # readable before all baseline rows have been compacted; that is a
            # partial artifact, not final serving proof.
            metadata_payload = dict(normalized.get("metadata") or {})
            metadata_payload["partial_result_view_candidate_count"] = served_count
            metadata_payload["partial_result_view_candidate_count_reason"] = (
                "baseline_delta_current_snapshot_below_baseline"
            )
            normalized["metadata"] = metadata_payload
            return normalized
        delta_required_count = max(0, _coerce_int(normalized.get("delta_profile_required_count"), 0))
        delta_terminal_count = max(
            0,
            _coerce_int(normalized.get("delta_profile_fetched_count"), 0),
            _coerce_int(normalized.get("delta_profile_materialized_count"), 0),
            _coerce_int(normalized.get("delta_profile_board_visible_count"), 0),
        )
        delta_profile_progress_applicable = bool(normalized.get("delta_profile_progress_applicable") is not False)
        if baseline_snapshot_id and snapshot_id == baseline_snapshot_id and delta_profile_progress_applicable:
            return normalized
        if baseline_snapshot_id and snapshot_id == baseline_snapshot_id and delta_required_count > delta_terminal_count:
            return normalized

        public_source = {
            **source_payload,
            "result_view": view_payload,
            "target_company": str(view_payload.get("target_company") or source_payload.get("target_company") or "").strip(),
            "snapshot_id": snapshot_id,
            "asset_view": str(view_payload.get("asset_view") or source_payload.get("asset_view") or "canonical_merged").strip()
            or "canonical_merged",
            "source_path": str(view_payload.get("source_path") or source_payload.get("source_path") or "").strip(),
        }
        proof_ready = bool(self._candidate_source_public_serving_artifact_proof(public_source).get("ready"))
        asset_population_payload = dict(asset_population or {})
        asset_population_ready = bool(
            asset_population_payload.get("available")
            and _coerce_int(asset_population_payload.get("candidate_count"), 0) == served_count
        )
        if not proof_ready and not asset_population_ready:
            return normalized

        job_payload = dict(job or {})
        job_status = str(job_payload.get("status") or "").strip().lower()
        workflow_terminal_proved = bool(
            self._job_is_terminal(job_payload)
            if str(job_payload.get("job_type") or "").strip() == "workflow"
            else job_status in {"completed", "results"}
        )
        delta_terminal = bool(delta_required_count <= 0 or delta_terminal_count >= delta_required_count)
        if not workflow_terminal_proved and not delta_terminal:
            return normalized

        normalized["current_snapshot_id"] = snapshot_id
        normalized["served_snapshot_id"] = snapshot_id
        normalized["served_candidate_count"] = served_count
        normalized["expected_candidate_count"] = served_count
        normalized["phase"] = "current_snapshot_serving"
        normalized["state"] = "current_snapshot_serving"
        normalized["phase_status"] = "active"
        normalized["source_validation_status"] = "validated"
        normalized["serving_projection_id"] = str(
            source_payload.get("asset_population_overlay_path")
            or dict(view_payload.get("metadata") or {}).get("asset_population_overlay_path")
            or normalized.get("serving_projection_id")
            or view_payload.get("view_id")
            or ""
        ).strip()
        normalized["serving_projection_phase"] = "current_snapshot_serving"
        if delta_required_count > 0 and delta_terminal:
            normalized["delta_profile_fetched_count"] = max(
                _coerce_int(normalized.get("delta_profile_fetched_count"), 0),
                delta_required_count,
            )
            normalized["delta_profile_materialized_count"] = max(
                _coerce_int(normalized.get("delta_profile_materialized_count"), 0),
                delta_required_count,
            )
            normalized["delta_profile_board_visible_count"] = max(
                _coerce_int(normalized.get("delta_profile_board_visible_count"), 0),
                delta_required_count,
            )
        metadata_payload = dict(normalized.get("metadata") or {})
        metadata_payload["public_result_view_normalization"] = {
            "source": "job_result_view",
            "candidate_count": served_count,
            "reason": "final_result_view_outranks_partial_lifecycle_count",
        }
        normalized["metadata"] = metadata_payload
        if not str(normalized.get("background_snapshot_materialization_status") or "").strip():
            normalized["background_snapshot_materialization_status"] = "current_snapshot_serving"
        return normalized

    def _load_job_result_lifecycle(
        self,
        *,
        job_id: str,
        job: dict[str, Any] | None = None,
        request: JobRequest | None = None,
        candidate_source: dict[str, Any] | None = None,
        result_view: dict[str, Any] | None = None,
        asset_population: dict[str, Any] | None = None,
        linkedin_stage_1_progress: dict[str, Any] | None = None,
        effective_execution_semantics: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Canonical lifecycle reader for `/dashboard`, `/progress`, `/candidates`.

        Strategy:
        1. If a persisted lifecycle row exists with `source_validation_status`
           = `validated`, render and return it. Public reads do not mutate the
           row in this path; writers are responsible for transitions.
        2. Otherwise (legacy job, missing row, or `pending_validation`), return
           an explicit repair-required diagnostic. Public reads no longer
           rebuild lifecycle from job/result-view summaries or write back a
           projected row.

        Slice 5 change: The fast path no longer requires a stored result_view
        to exist. A validated canonical row is trusted even when no result_view
        has been persisted yet. This allows materialization writers to record
        lifecycle state before the full result_view upsert completes, and
        prevents public reads from falling back to multi-source reconstruction
        that can diverge from the event-time writer's projection.

        See `docs/JOB_RESULT_LIFECYCLE_DESIGN.md` §Reader ownership.
        """

        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        # Fast path: persisted validated rows are authoritative. Public reads
        # do not mutate, repair, or enrich the row in this path; event-time
        # writers and explicit repair tools own all lifecycle transitions.
        persisted = self.store.get_job_result_lifecycle(normalized_job_id)
        if not persisted:
            return self._job_result_lifecycle_repair_required_payload(
                job_id=normalized_job_id,
                reason="job_result_lifecycle_missing",
            )
        source_validation_status = str(persisted.get("source_validation_status") or "").strip()
        if source_validation_status != "validated":
            return self._job_result_lifecycle_repair_required_payload(
                job_id=normalized_job_id,
                reason=f"job_result_lifecycle_not_validated:{source_validation_status or '<empty>'}",
                persisted=persisted,
            )
        if persisted:
            # Even on the fast path we apply the terminal-phase invariant so a
            # job that finished while the row still said `baseline_serving`
            # cannot leak `results` to the user. This is a render-time
            # normalization only; we do not write back.
            job_for_norm = dict(job or self.store.get_job(normalized_job_id) or {})
            normalized = self._normalize_lifecycle_for_terminal_phase(
                job=job_for_norm,
                projection={
                    "state": persisted.get("state") or persisted.get("phase") or "",
                    "baseline_snapshot_id": persisted.get("baseline_snapshot_id") or "",
                    "served_snapshot_id": persisted.get("served_snapshot_id") or "",
                    "delta_profile_required_count": persisted.get("delta_profile_required_count") or 0,
                    "delta_profile_materialized_count": persisted.get("delta_profile_materialized_count") or 0,
                    "background_snapshot_materialization_status": persisted.get(
                        "background_snapshot_materialization_status"
                    )
                    or "",
                },
            )
            persisted_view = dict(persisted)
            persisted_view["state"] = normalized.get("state") or persisted_view.get("state") or ""
            if self._validated_current_serving_requires_public_artifact(
                row=persisted_view,
                candidate_source=candidate_source,
                result_view=result_view,
            ):
                partial_public_artifact_count = (
                    _coerce_int(dict(asset_population or {}).get("candidate_count"), 0)
                    if bool(dict(asset_population or {}).get("available"))
                    else 0
                )
                existing_metadata_payload = dict(persisted_view.get("metadata") or {})
                row_shell_publication = dict(existing_metadata_payload.get("row_shell_publication") or {})
                latest_board_visible_patch = dict(existing_metadata_payload.get("latest_board_visible_patch") or {})
                public_served_count = max(
                    _coerce_int(row_shell_publication.get("served_candidate_count"), 0),
                    _coerce_int(latest_board_visible_patch.get("served_candidate_count"), 0),
                    partial_public_artifact_count,
                )
                persisted_served_count = _coerce_int(persisted_view.get("served_candidate_count"), 0)
                persisted_view["state"] = "current_snapshot_materializing"
                persisted_view["phase"] = "current_snapshot_materializing"
                persisted_view["serving_projection_phase"] = "partial_current_snapshot_overlay"
                persisted_view["served_candidate_count"] = public_served_count
                if _coerce_int(persisted_view.get("expected_candidate_count"), 0) <= 0:
                    persisted_view["expected_candidate_count"] = persisted_served_count
                persisted_view["source_validation_status"] = "validated"
                metadata_payload = dict(existing_metadata_payload)
                metadata_payload["public_serving_artifact_missing"] = True
                metadata_payload["public_serving_artifact_missing_reason"] = (
                    "candidate_documents_not_public_serving_artifact"
                )
                if persisted_served_count > public_served_count:
                    metadata_payload["unpublished_lifecycle_served_candidate_count"] = persisted_served_count
                if partial_public_artifact_count and partial_public_artifact_count < public_served_count:
                    metadata_payload["partial_public_serving_artifact_candidate_count"] = (
                        partial_public_artifact_count
                    )
                    metadata_payload["public_served_candidate_count_preserved_from"] = (
                        "canonical_lifecycle_or_row_shell_publication"
                    )
                persisted_view["metadata"] = metadata_payload
            persisted_view = self._normalize_lifecycle_for_final_result_view(
                row=persisted_view,
                job=job_for_norm,
                candidate_source=candidate_source,
                result_view=result_view,
                asset_population=asset_population,
            )
            persisted_view = self._normalize_lifecycle_from_board_visible_patch_projection(
                job_id=normalized_job_id,
                row=persisted_view,
            )
            persisted_view = self._suppress_delta_profile_progress_for_reuse_row(
                row=persisted_view,
                job=job_for_norm,
                request=request,
                effective_execution_semantics=effective_execution_semantics,
            )
            return self._project_canonical_lifecycle_payload(row=persisted_view)
        return self._job_result_lifecycle_repair_required_payload(
            job_id=normalized_job_id,
            reason="job_result_lifecycle_unreachable_reader_state",
            persisted=persisted,
        )

    def _asset_population_served_candidate_source_payload(
        self,
        *,
        request: JobRequest,
        candidate_source: dict[str, Any],
        result_view: dict[str, Any],
        asset_population: dict[str, Any],
    ) -> dict[str, Any]:
        payload = dict(asset_population or {})
        if not bool(payload.get("available")):
            return {}
        served_snapshot_id = str(payload.get("snapshot_id") or "").strip()
        if not served_snapshot_id:
            return {}
        source_payload = dict(candidate_source or {})
        view_payload = dict(result_view or {})
        asset_view = (
            str(payload.get("asset_view") or source_payload.get("asset_view") or request.asset_view or "").strip()
            or "canonical_merged"
        )
        source_snapshot_id = str(source_payload.get("snapshot_id") or "").strip()
        view_snapshot_id = str(view_payload.get("snapshot_id") or "").strip()
        served_source = {
            "source_kind": str(source_payload.get("source_kind") or "company_snapshot").strip() or "company_snapshot",
            "target_company": str(request.target_company or source_payload.get("target_company") or "").strip(),
            "snapshot_id": served_snapshot_id,
            "asset_view": asset_view,
            "source_path": str(payload.get("source_path") or "").strip(),
            "candidate_count": int(payload.get("candidate_count") or source_payload.get("candidate_count") or 0),
            "served_by": "asset_population",
        }
        if source_snapshot_id == served_snapshot_id:
            for key in (
                "authoritative_snapshot_id",
                "materialization_generation_key",
                "materialization_generation_sequence",
                "materialization_watermark",
            ):
                if source_payload.get(key) not in (None, ""):
                    served_source[key] = source_payload.get(key)
        if view_snapshot_id == served_snapshot_id:
            served_source = self._apply_job_result_view_to_candidate_source(served_source, view_payload)
        return served_source

    def _attach_served_candidate_source_to_asset_population(
        self,
        *,
        request: JobRequest,
        candidate_source: dict[str, Any],
        result_view: dict[str, Any],
        asset_population: dict[str, Any],
    ) -> dict[str, Any]:
        payload = dict(asset_population or {})
        served_source = self._asset_population_served_candidate_source_payload(
            request=request,
            candidate_source=candidate_source,
            result_view=result_view,
            asset_population=payload,
        )
        if served_source:
            payload["candidate_source"] = served_source
        return payload

    def _build_board_runtime_state(
        self,
        *,
        job_id: str,
        job: dict[str, Any],
        result_mode: str,
        result_view_lifecycle: dict[str, Any],
        asset_population: dict[str, Any] | None = None,
        facet_summary_scope: str = "",
        facet_summary: dict[str, Any] | None = None,
        linkedin_stage_1_progress: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Render the single backend-driven runtime contract for the candidate board."""

        normalized_job_id = str(job_id or "").strip()
        lifecycle = dict(result_view_lifecycle or {})
        asset_population = dict(asset_population or {})
        facet_summary = dict(facet_summary or asset_population.get("facet_summary") or {})
        linkedin_stage_1_progress = dict(linkedin_stage_1_progress or {})
        card_materialization_summary = dict(asset_population.get("card_materialization_summary") or {})
        normalized_result_mode = str(result_mode or "").strip() or "ranked_results"
        lifecycle_expected_count = int(lifecycle.get("expected_candidate_count") or 0)
        expected_count = lifecycle_expected_count if lifecycle_expected_count > 0 else int(
            asset_population.get("candidate_count") or 0
        )
        served_count = max(0, int(lifecycle.get("served_candidate_count") or 0))
        baseline_count = max(0, int(lifecycle.get("baseline_candidate_count") or 0))
        delta_required_count = max(0, int(lifecycle.get("delta_profile_required_count") or 0))
        delta_fetched_count = max(0, int(lifecycle.get("delta_profile_fetched_count") or 0))
        delta_materialized_count = max(0, int(lifecycle.get("delta_profile_materialized_count") or 0))
        delta_board_visible_count = max(0, int(lifecycle.get("delta_profile_board_visible_count") or 0))
        lifecycle_state = str(lifecycle.get("state") or "unavailable").strip() or "unavailable"
        serving_projection_phase = str(lifecycle.get("serving_projection_phase") or "").strip()
        current_snapshot_id = str(lifecycle.get("current_snapshot_id") or asset_population.get("snapshot_id") or "").strip()
        patches = (
            self.store.list_job_board_visible_patches(
                job_id=normalized_job_id,
                snapshot_id=current_snapshot_id,
                limit=0,
            )
            if normalized_job_id and current_snapshot_id
            else self.store.list_job_board_visible_patches(job_id=normalized_job_id, limit=0)
            if normalized_job_id
            else []
        )
        latest_patch = dict(patches[-1]) if patches else {}
        latest_sequence = int(latest_patch.get("sequence_index") or 0)
        latest_patch_served_count = max(0, int(latest_patch.get("served_candidate_count") or 0))
        latest_patch_cumulative_count = max(0, int(latest_patch.get("cumulative_candidate_count") or 0))
        lifecycle_stage_required_count = max(
            0,
            _coerce_int(lifecycle.get("stage1_profile_fetch_required_count"), 0),
        )
        lifecycle_stage_fetched_count = max(
            0,
            _coerce_int(lifecycle.get("stage1_profile_fetched_count"), 0),
        )
        lifecycle_stage_deduped_count = max(
            0,
            _coerce_int(lifecycle.get("stage1_deduped_candidate_count"), 0),
            _coerce_int(lifecycle.get("stage1_deduped_profile_url_count"), 0),
        )
        lifecycle_stage_raw_lane_count = (
            _coerce_int(lifecycle.get("stage1_current_search_returned_count"), 0)
            + _coerce_int(lifecycle.get("stage1_former_search_returned_count"), 0)
            + _coerce_int(lifecycle.get("stage1_all_search_returned_count"), 0)
        )
        lifecycle_stage_discovered_count = lifecycle_stage_deduped_count or max(0, lifecycle_stage_raw_lane_count)
        progress_stage_required_count = max(
            0,
            _coerce_int(
                linkedin_stage_1_progress.get("profile_fetch_required_count")
                or linkedin_stage_1_progress.get("profileFetchRequiredCount"),
                0,
            ),
        )
        progress_stage_fetched_count = max(
            0,
            _coerce_int(
                linkedin_stage_1_progress.get("profile_fetched_count")
                or linkedin_stage_1_progress.get("profileFetchedCount"),
                0,
            ),
        )
        progress_stage_deduped_count = max(
            0,
            _coerce_int(
                linkedin_stage_1_progress.get("deduped_candidate_count")
                or linkedin_stage_1_progress.get("dedupedCandidateCount"),
                0,
            ),
            _coerce_int(
                linkedin_stage_1_progress.get("deduped_profile_url_count")
                or linkedin_stage_1_progress.get("dedupedProfileUrlCount"),
                0,
            ),
        )
        progress_stage_raw_lane_count = (
            _coerce_int(
                linkedin_stage_1_progress.get("current_search_returned_count")
                or linkedin_stage_1_progress.get("currentSearchReturnedCount"),
                0,
            )
            + _coerce_int(
                linkedin_stage_1_progress.get("former_search_returned_count")
                or linkedin_stage_1_progress.get("formerSearchReturnedCount"),
                0,
            )
            + _coerce_int(
                linkedin_stage_1_progress.get("all_search_returned_count")
                or linkedin_stage_1_progress.get("allSearchReturnedCount"),
                0,
            )
        )
        progress_stage_discovered_count = progress_stage_deduped_count or max(0, progress_stage_raw_lane_count)
        lifecycle_stage_projection_available = bool(
            lifecycle_stage_required_count
            or lifecycle_stage_fetched_count
            or lifecycle_stage_discovered_count
            or str(lifecycle.get("projection_source_snapshot_id") or "").strip()
        )
        if lifecycle_stage_projection_available:
            stage_profile_required_count = max(lifecycle_stage_required_count, delta_required_count)
            stage_profile_fetched_count = lifecycle_stage_fetched_count
            stage_discovered_count = lifecycle_stage_discovered_count
        else:
            stage_profile_required_count = max(progress_stage_required_count, delta_required_count)
            stage_profile_fetched_count = progress_stage_fetched_count
            stage_discovered_count = progress_stage_discovered_count
        # The lifecycle row is now the canonical denominator. Do NOT lift
        # expected_count from dynamic Stage 1 progress (stage_profile_required_count
        # or stage_discovered_count) — that would reintroduce the 300/351 → 300/525
        # drift. The lifecycle writer gates promotion on stage1_lanes_terminal.
        terminal_serving = bool(
            lifecycle_state in {"current_snapshot_serving", "post_result_layering", "current_serving"}
            or serving_projection_phase == "current_snapshot_serving"
        )
        if terminal_serving and expected_count > 0 and served_count >= expected_count:
            published_count = served_count
        elif latest_patch_served_count > 0:
            published_count = latest_patch_served_count
        elif latest_patch_cumulative_count > 0:
            published_count = baseline_count + latest_patch_cumulative_count if baseline_count > 0 else latest_patch_cumulative_count
        elif served_count > 0:
            published_count = served_count
        else:
            published_count = 0
        if expected_count > 0:
            published_count = min(max(published_count, 0), expected_count)
        patch_card_materialization_summary = (
            self._build_candidate_card_materialization_summary_from_board_visible_patch(latest_patch)
            if latest_patch
            else {}
        )
        final_display_ready_count = int(card_materialization_summary.get("display_ready_candidate_count") or 0)
        patch_display_ready_count = int(
            patch_card_materialization_summary.get("display_ready_candidate_count") or 0
        )
        final_card_summary_regresses_patch = bool(
            patch_card_materialization_summary
            and patch_display_ready_count > final_display_ready_count
        )
        final_card_summary_complete = bool(
            terminal_serving
            and expected_count > 0
            and served_count >= expected_count
            and int(card_materialization_summary.get("candidate_count") or 0) >= expected_count
            and (
                int(card_materialization_summary.get("display_ready_candidate_count") or 0) >= expected_count
                or (
                    int(card_materialization_summary.get("display_ready_candidate_count") or 0)
                    + int(card_materialization_summary.get("needs_profile_completion_candidate_count") or 0)
                )
                >= expected_count
            )
        )
        if patch_card_materialization_summary and (
            final_card_summary_regresses_patch or not final_card_summary_complete
        ):
            # Board-visible patches are the event-time publication contract.
            # Prefer their frozen card-quality counters over mutable serving
            # overlays so public progress cannot jump from 0 to final after a
            # later materialization rewrites the same projection path. Once the
            # current snapshot is fully serving and the final asset summary
            # proves non-regressing card readiness, the final serving projection
            # outranks stale partial patch history; patches remain only the row
            # publication sequence/watermark. A complete partition that includes
            # needs_profile_completion is not allowed to reduce display-ready
            # counts already published by event-time board patches.
            card_materialization_summary = patch_card_materialization_summary
        elif not card_materialization_summary:
            card_materialization_summary = self._build_candidate_card_materialization_summary_from_serving_projection(
                job_id=normalized_job_id,
                latest_patch=latest_patch,
                fallback_candidate_count=published_count or served_count or expected_count,
            )
        card_summary_candidate_count = max(0, int(card_materialization_summary.get("candidate_count") or 0))
        display_ready_candidate_count = max(
            0,
            int(card_materialization_summary.get("display_ready_candidate_count") or 0),
        )
        quality_fields_available = bool(card_materialization_summary.get("quality_fields_available"))
        if not quality_fields_available and card_summary_candidate_count <= 0:
            if stage_profile_required_count > 0:
                display_ready_candidate_count = 0
            else:
                display_ready_candidate_count = published_count
        if expected_count > 0:
            display_ready_candidate_count = min(display_ready_candidate_count, expected_count)
        if published_count > 0:
            display_ready_candidate_count = min(display_ready_candidate_count, published_count)
        if baseline_count > 0 and published_count >= baseline_count:
            # A baseline result view was already serviceable before this run's delta.
            # Missing card-quality fields on a legacy overlay must not make the UI
            # report the baseline board as newly un-materialized.
            display_ready_candidate_count = max(display_ready_candidate_count, baseline_count)
        preview_candidate_count = max(
            0,
            int(card_materialization_summary.get("preview_candidate_count") or 0),
        )
        if preview_candidate_count <= 0 and published_count > display_ready_candidate_count:
            preview_candidate_count = published_count - display_ready_candidate_count
        profile_detail_candidate_count = max(
            0,
            int(card_materialization_summary.get("profile_detail_candidate_count") or 0),
        )
        needs_profile_completion_candidate_count = max(
            0,
            int(card_materialization_summary.get("needs_profile_completion_candidate_count") or 0),
        )
        low_profile_richness_candidate_count = max(
            0,
            int(card_materialization_summary.get("low_profile_richness_candidate_count") or 0),
        )
        explicit_profile_capture_candidate_count = max(
            0,
            int(card_materialization_summary.get("explicit_profile_capture_candidate_count") or 0),
        )
        delta_profile_progress_applicable = bool(lifecycle.get("delta_profile_progress_applicable") is not False)
        if delta_profile_progress_applicable and delta_required_count > 0:
            delta_display_ready_projection_count = max(0, display_ready_candidate_count - baseline_count)
            delta_explicit_profile_capture_count = (
                max(0, explicit_profile_capture_candidate_count - baseline_count)
                if baseline_count > 0
                else explicit_profile_capture_candidate_count
            )
            delta_card_ready_projection_count = min(
                delta_required_count,
                max(
                    0,
                    delta_display_ready_projection_count,
                    delta_explicit_profile_capture_count,
                    delta_materialized_count,
                    delta_board_visible_count,
                ),
            )
            # Card-visible evidence implies the profile was fetched and locally
            # applied; normalize the event-time projection before public copy is
            # rendered so readers never show card materialization ahead of
            # profile fetch.
            delta_board_visible_count = min(
                delta_required_count,
                max(delta_board_visible_count, delta_card_ready_projection_count),
            )
            delta_materialized_count = min(
                delta_required_count,
                max(delta_materialized_count, delta_board_visible_count, delta_card_ready_projection_count),
            )
            delta_fetched_count = min(
                delta_required_count,
                max(delta_fetched_count, delta_materialized_count, delta_board_visible_count),
            )
            stage_profile_required_count = max(stage_profile_required_count, delta_required_count)
            if stage_profile_required_count > 0:
                stage_profile_fetched_count = min(
                    stage_profile_required_count,
                    max(stage_profile_fetched_count, delta_fetched_count),
                )
        elif stage_profile_required_count > 0:
            # Live/no-baseline row-shell publication can expose roster rows before
            # the profile worker has fetched full details. Public projection must
            # not infer profile fetch progress from card-like roster fields.
            display_ready_candidate_count = min(display_ready_candidate_count, stage_profile_fetched_count)
            profile_detail_candidate_count = min(profile_detail_candidate_count, stage_profile_fetched_count)
            explicit_profile_capture_candidate_count = min(
                explicit_profile_capture_candidate_count,
                stage_profile_fetched_count,
            )
            needs_profile_completion_candidate_count = max(
                needs_profile_completion_candidate_count,
                max(0, published_count - display_ready_candidate_count),
            )
        if stage_profile_required_count > 0:
            stage_profile_fetched_count = min(stage_profile_fetched_count, stage_profile_required_count)
        if published_count > display_ready_candidate_count:
            preview_candidate_count = max(preview_candidate_count, published_count - display_ready_candidate_count)
        publication_status = "unavailable"
        if expected_count > 0 and published_count >= expected_count:
            publication_status = "complete"
        elif published_count > 0:
            publication_status = "partial"
        elif expected_count > 0:
            publication_status = "pending"
        served_snapshot_matches_current = bool(
            str(lifecycle.get("served_snapshot_id") or "").strip()
            == str(lifecycle.get("current_snapshot_id") or asset_population.get("snapshot_id") or "").strip()
        )
        current_snapshot_publication_complete = bool(
            publication_status == "complete"
            and expected_count > 0
            and published_count >= expected_count
            and served_snapshot_matches_current
        )
        if current_snapshot_publication_complete:
            served_count = max(served_count, published_count)
        if (
            terminal_serving
            and current_snapshot_publication_complete
            and final_card_summary_complete
            and not delta_profile_progress_applicable
            and stage_profile_required_count > 0
            and max(profile_detail_candidate_count, explicit_profile_capture_candidate_count)
            >= stage_profile_required_count
        ):
            # A terminal current-snapshot projection with a complete final card
            # partition is only stronger profile-fetch evidence when it carries
            # actual profile-detail/explicit-capture proof. Row-shell and
            # needs-profile-completion partitions can prove row publication, but
            # must not make public progress jump to 297/297 before profile
            # workers have really fetched the tail and then regress to 223/297.
            stage_profile_fetched_count = stage_profile_required_count
        current_snapshot_fully_serving = bool(
            terminal_serving
            and publication_status == "complete"
            and expected_count > 0
            and served_count >= expected_count
            and served_snapshot_matches_current
        )
        facet_candidate_count = int(facet_summary.get("candidate_count") or 0)
        resolved_facet_scope = str(facet_summary_scope or asset_population.get("facet_summary_scope") or "").strip()
        asset_population_candidate_count = max(0, int(asset_population.get("candidate_count") or 0))
        facet_candidate_denominator = expected_count if expected_count > 0 else asset_population_candidate_count
        facet_summary_ready = bool(
            resolved_facet_scope == "global_full_population"
            and facet_candidate_count > 0
            and (
                facet_candidate_count == facet_candidate_denominator
                if facet_candidate_denominator > 0
                else True
            )
        )
        effective_facet_scope = (
            "global_full_population"
            if facet_summary_ready
            else "current_served_partial"
            if facet_candidate_count > 0
            else "unavailable"
        )
        outreach_layering_status = str(lifecycle.get("outreach_layering_status") or "").strip().lower()
        layer_options = list(facet_summary.get("layers") or [])
        layer_candidate_count = sum(max(0, int(dict(item).get("count") or 0)) for item in layer_options if isinstance(item, dict))
        if facet_summary_ready and layer_candidate_count > 0:
            # The complete full-population facet summary is the serving contract;
            # it must outrank stale post-result progress copied from older rows.
            outreach_layering_status = "completed"
        elif not outreach_layering_status and layer_candidate_count > 0:
            outreach_layering_status = "completed"
        facet_summary_status = "complete" if facet_summary_ready else ("pending" if published_count > 0 else "unavailable")
        layering_status = outreach_layering_status or ("completed" if layer_candidate_count > 0 else "unavailable")
        # Row serving and global statistics are separate readiness dimensions.
        # A complete candidate-row projection must not be downgraded to
        # `partial_serving` only because the bounded facet/layering builder is
        # still scheduled. Facet/layering readiness is exposed below through
        # facet_summary_status/layering_status/filter_contract.
        public_current_snapshot_rows_serving = bool(
            current_snapshot_publication_complete
            and expected_count > 0
            and served_count >= expected_count
            and (
                serving_projection_phase != "current_snapshot_row_shell_overlay"
                or (
                    stage_profile_required_count > 0
                    and stage_profile_fetched_count >= stage_profile_required_count
                    and display_ready_candidate_count >= stage_profile_required_count
                )
            )
            and (
                stage_profile_required_count <= 0
                or stage_profile_fetched_count >= stage_profile_required_count
            )
        )
        effective_terminal_serving = bool(terminal_serving or public_current_snapshot_rows_serving)
        if str(job.get("status") or "").strip().lower() == "failed" or lifecycle_state == "failed":
            board_phase = "failed"
        elif publication_status == "complete" and effective_terminal_serving:
            board_phase = "current_snapshot_serving"
        elif publication_status in {"partial", "complete"}:
            board_phase = "partial_serving"
        elif expected_count > 0:
            board_phase = "awaiting_publication"
        else:
            board_phase = "unavailable"
        lifecycle_metadata = dict(lifecycle.get("metadata") or {})
        row_shell_publication = dict(lifecycle_metadata.get("row_shell_publication") or {})
        row_shell_published_at = str(row_shell_publication.get("published_at") or "").strip()
        row_publication_patch = latest_patch
        if current_snapshot_publication_complete and expected_count > 0 and patches:
            complete_row_publication_patches = [
                dict(patch)
                for patch in patches
                if _coerce_int(dict(patch).get("served_candidate_count"), 0) >= expected_count
                and str(dict(patch).get("serving_projection_phase") or "").strip()
                in {
                    "current_snapshot_row_shell_overlay",
                    "current_snapshot_serving",
                    "current_serving",
                    "partial_current_snapshot_overlay",
                }
            ]
            if complete_row_publication_patches:
                row_publication_patch = sorted(
                    complete_row_publication_patches,
                    key=lambda patch: (
                        _coerce_int(patch.get("sequence_index"), 0),
                        str(patch.get("published_at") or patch.get("updated_at") or ""),
                        str(patch.get("patch_id") or ""),
                    ),
                )[0]
        row_publication_sequence = int(row_publication_patch.get("sequence_index") or 0)
        row_publication_published_at = str(
            row_publication_patch.get("published_at") or row_publication_patch.get("updated_at") or ""
        ).strip()
        row_publication_started_at = str(row_shell_published_at or row_publication_published_at).strip()
        row_publication_watermark = "|".join(
            [
                str(lifecycle.get("current_snapshot_id") or asset_population.get("snapshot_id") or ""),
                str(row_publication_sequence),
                str(published_count),
                str(layering_status),
            ]
        )
        row_publication_tier = (
            "current_snapshot_serving"
            if effective_terminal_serving and current_snapshot_publication_complete
            else "partial_patch"
            if latest_sequence > 0
            else "lifecycle"
        )

        profile_fetch_status_text = ""
        candidate_discovery_status_text = ""
        card_materialization_status_text = ""
        profile_fetch_status_detail = ""
        card_materialization_status_detail = ""
        delta_profile_denominator_promoted = bool(lifecycle_metadata.get("delta_profile_denominator_promoted"))
        public_stage1_profile_complete = bool(
            current_snapshot_publication_complete
            and stage_profile_required_count > 0
            and stage_profile_fetched_count >= stage_profile_required_count
        )
        public_denominator_promoted = bool(
            delta_profile_denominator_promoted
            or public_stage1_profile_complete
        )
        if delta_profile_progress_applicable and delta_required_count > 0:
            delta_display_ready_count = max(0, display_ready_candidate_count - baseline_count)
            delta_explicit_profile_capture_count = (
                max(0, explicit_profile_capture_candidate_count - baseline_count)
                if baseline_count > 0
                else explicit_profile_capture_candidate_count
            )
            delta_card_ready_count = min(
                delta_required_count,
                max(
                    0,
                    delta_display_ready_count,
                    delta_explicit_profile_capture_count,
                    delta_materialized_count,
                    delta_board_visible_count,
                ),
            )
            if public_denominator_promoted:
                # Stage 1 lanes are terminal; show the stable denominator.
                profile_fetch_status_text = (
                    f"新增 LinkedIn Profile 已取回 {min(delta_fetched_count, delta_required_count)}/{delta_required_count}"
                )
                card_materialization_status_text = (
                    f"卡片详情已合入看板 {delta_card_ready_count}/{delta_required_count}"
                )
            else:
                # Before Stage 1 has promoted the canonical denominator, do not
                # publish a user-facing profile/card fraction from a partial lane
                # such as former-only 74. Candidate discovery remains visible;
                # profile/card copy appears only once the stable denominator is known.
                profile_fetch_status_detail = "Stage 1 仍在发现候选人"
                card_materialization_status_detail = "Stage 1 仍在发现候选人"
        elif stage_profile_required_count > 0:
            stage_card_materialized_count = min(display_ready_candidate_count, stage_profile_required_count)
            if current_snapshot_fully_serving:
                stage_card_materialized_count = min(
                    stage_profile_required_count,
                    max(
                        stage_card_materialized_count,
                        profile_detail_candidate_count,
                        explicit_profile_capture_candidate_count,
                    ),
                )
            if public_denominator_promoted:
                profile_fetch_status_text = (
                    f"本次 LinkedIn Profile 已取回 {min(stage_profile_fetched_count, stage_profile_required_count)}/{stage_profile_required_count}"
                )
                card_materialization_status_text = (
                    f"卡片详情已合入看板 {stage_card_materialized_count}/{stage_profile_required_count}"
                )
            else:
                # Same rule for no-baseline scoped search/live roster: avoid
                # exposing partial-lane denominators as if they were stable totals.
                profile_fetch_status_detail = "Stage 1 仍在发现候选人"
                card_materialization_status_detail = "Stage 1 仍在发现候选人"
        elif expected_count > 0 and published_count > 0 and published_count < expected_count:
            profile_fetch_status_text = f"已发布可浏览候选人 {published_count}/{expected_count}"
        # Candidate sync is row-publication/hydration progress. Card richness
        # and profile detail readiness are reported by the dedicated note lines
        # below; using display_ready here makes a complete board look stuck
        # when baseline rows are intentionally low-richness or preview-only.
        if publication_status == "complete" and expected_count > 0:
            sync_display_count = expected_count
        elif published_count > 0:
            sync_display_count = published_count
        else:
            sync_display_count = display_ready_candidate_count if (
                quality_fields_available or card_summary_candidate_count > 0 or stage_profile_required_count > 0
            ) else published_count
        sync_status_text = f"{sync_display_count}/{expected_count}" if expected_count > 0 else "0/0"
        if expected_count > 0:
            discovery_display_count = (
                expected_count
                if publication_status == "complete"
                else min(max(stage_discovered_count, sync_display_count), expected_count)
            )
            candidate_discovery_status_text = f"候选人发现 {discovery_display_count}/{expected_count}"
        sync_note_lines = [
            {"id": line_id, "text": text}
            for line_id, text in [
                ("candidate_discovery", candidate_discovery_status_text),
                ("profile_fetch", profile_fetch_status_text),
                ("card_materialization", card_materialization_status_text),
            ]
            if text
        ]
        note_text = "；".join(str(item.get("text") or "") for item in sync_note_lines if item.get("text"))
        return {
            "schema_version": 1,
            "job_id": normalized_job_id,
            "result_mode": normalized_result_mode,
            "phase": board_phase,
            "publication_status": publication_status,
            "expected_candidate_count": expected_count,
            "served_candidate_count": served_count,
            "published_candidate_count": published_count,
            "display_ready_candidate_count": display_ready_candidate_count,
            "preview_candidate_count": preview_candidate_count,
            "profile_detail_candidate_count": profile_detail_candidate_count,
            "explicit_profile_capture_candidate_count": explicit_profile_capture_candidate_count,
            "needs_profile_completion_candidate_count": needs_profile_completion_candidate_count,
            "low_profile_richness_candidate_count": low_profile_richness_candidate_count,
            "card_materialization_quality_fields_available": quality_fields_available,
            "row_hydration_target_count": published_count,
            "candidate_discovery_count": min(stage_discovered_count, expected_count) if expected_count > 0 else stage_discovered_count,
            "profile_fetch_required_count": stage_profile_required_count,
            "profile_fetched_count": stage_profile_fetched_count,
            "baseline_candidate_count": baseline_count,
            "delta_profile_required_count": delta_required_count,
            "delta_profile_fetched_count": delta_fetched_count,
            "delta_profile_materialized_count": delta_materialized_count,
            "delta_profile_board_visible_count": delta_board_visible_count,
            "row_publication_sequence": row_publication_sequence,
            "row_publication_tier": row_publication_tier,
            "row_publication_watermark": row_publication_watermark,
            "row_publication_started_at": row_publication_started_at,
            "row_publication_updated_at": row_publication_published_at or row_shell_published_at,
            "facet_summary_status": facet_summary_status,
            "facet_summary_scope": effective_facet_scope,
            "facet_summary_candidate_count": facet_candidate_count,
            "layering_status": layering_status,
            "filter_contract": {
                "source": "backend_board_runtime_state",
                "facet_count_scope": effective_facet_scope,
                "row_filter_scope": "backend_filtered_served_population",
                "backend_filtered_paging_supported": True,
            },
            "sync_status_text": sync_status_text,
            "sync_note_lines": sync_note_lines,
            "candidate_discovery_status_text": candidate_discovery_status_text,
            "profile_fetch_status_text": profile_fetch_status_text,
            "card_materialization_status_text": card_materialization_status_text,
            "profile_fetch_status_detail": profile_fetch_status_detail,
            "card_materialization_status_detail": card_materialization_status_detail,
            "delta_profile_denominator_promoted": public_denominator_promoted,
            "note_text": note_text,
        }

    def _resolve_candidate_profile_timeline(
        self,
        *,
        payload: dict[str, Any],
        metadata: dict[str, Any],
        source_path: str,
        load_profile_timeline: bool,
    ) -> dict[str, Any]:
        experience_lines = _normalized_text_lines(payload.get("experience_lines") or metadata.get("experience_lines"))
        education_lines = _normalized_text_lines(payload.get("education_lines") or metadata.get("education_lines"))
        if not load_profile_timeline:
            capture_kind = str(
                payload.get("profile_capture_kind") or metadata.get("profile_capture_kind") or ""
            ).strip()
            profile_capture_source_path = str(
                payload.get("profile_capture_source_path")
                or metadata.get("profile_capture_source_path")
                or source_path
                or ""
            ).strip()
            return {
                "experience_lines": experience_lines,
                "education_lines": education_lines,
                "headline": str(payload.get("headline") or metadata.get("headline") or "").strip(),
                "summary": str(payload.get("summary") or metadata.get("summary") or "").strip(),
                "about": str(payload.get("about") or metadata.get("about") or "").strip(),
                "profile_location": str(
                    payload.get("profile_location")
                    or metadata.get("profile_location")
                    or payload.get("location")
                    or metadata.get("location")
                    or ""
                ).strip(),
                "public_identifier": str(
                    payload.get("public_identifier")
                    or metadata.get("public_identifier")
                    or payload.get("username")
                    or metadata.get("username")
                    or ""
                ).strip(),
                "avatar_url": str(
                    payload.get("avatar_url")
                    or payload.get("photo_url")
                    or payload.get("media_url")
                    or metadata.get("avatar_url")
                    or metadata.get("photo_url")
                    or metadata.get("media_url")
                    or ""
                ).strip(),
                "photo_url": str(
                    payload.get("photo_url")
                    or payload.get("avatar_url")
                    or metadata.get("photo_url")
                    or metadata.get("avatar_url")
                    or ""
                ).strip(),
                "primary_email": str(
                    payload.get("primary_email")
                    or payload.get("email")
                    or metadata.get("primary_email")
                    or metadata.get("email")
                    or ""
                ).strip(),
                "primary_email_metadata": _normalized_primary_email_metadata(
                    payload.get("primary_email_metadata") or metadata.get("primary_email_metadata")
                ),
                "profile_capture_kind": capture_kind,
                "profile_capture_source_path": profile_capture_source_path,
                "source_kind": "",
                "source_path": source_path,
            }
        profile_url = _candidate_profile_lookup_url(payload, metadata)
        if not profile_url:
            resolved = _resolve_candidate_profile_timeline(
                payload=payload,
                metadata=metadata,
                source_path=source_path,
            )
        else:
            resolved = _resolve_candidate_profile_timeline(
                payload=payload,
                metadata=metadata,
                source_path=source_path,
                registry_row=self.store.get_linkedin_profile_registry(profile_url),
            )
        if experience_lines and not resolved.get("experience_lines"):
            resolved["experience_lines"] = experience_lines
        if education_lines and not resolved.get("education_lines"):
            resolved["education_lines"] = education_lines
        return {
            "experience_lines": _normalized_text_lines(resolved.get("experience_lines")),
            "education_lines": _normalized_text_lines(resolved.get("education_lines")),
            "headline": str(resolved.get("headline") or "").strip(),
            "summary": str(resolved.get("summary") or "").strip(),
            "about": str(resolved.get("about") or "").strip(),
            "profile_location": str(resolved.get("profile_location") or "").strip(),
            "public_identifier": str(resolved.get("public_identifier") or "").strip(),
            "avatar_url": str(resolved.get("avatar_url") or "").strip(),
            "photo_url": str(resolved.get("photo_url") or "").strip(),
            "primary_email": str(resolved.get("primary_email") or "").strip(),
            "primary_email_metadata": _normalized_primary_email_metadata(resolved.get("primary_email_metadata")),
            "profile_capture_kind": str(resolved.get("profile_capture_kind") or "").strip(),
            "profile_capture_source_path": str(resolved.get("profile_capture_source_path") or "").strip(),
            "source_kind": str(resolved.get("source_kind") or "").strip(),
            "source_path": str(resolved.get("source_path") or source_path or "").strip(),
        }

    def _candidate_record_has_materialized_profile_detail(self, record: dict[str, Any] | None) -> bool:
        payload = dict(record or {})
        metadata = dict(payload.get("metadata") or {})
        return _timeline_has_complete_profile_detail(
            {
                **metadata,
                **payload,
                "experience_lines": payload.get("experience_lines") or metadata.get("experience_lines"),
                "education_lines": payload.get("education_lines") or metadata.get("education_lines"),
                "source_path": (
                    payload.get("profile_capture_source_path")
                    or metadata.get("profile_capture_source_path")
                    or payload.get("source_path")
                    or metadata.get("source_path")
                ),
            }
        )

    def _merge_authoritative_detail_and_result_record(
        self,
        *,
        authoritative_record: dict[str, Any] | None,
        raw_result_record: dict[str, Any] | None,
    ) -> dict[str, Any]:
        authoritative_record = dict(authoritative_record or {})
        merged = dict(authoritative_record)
        materialized_profile_owned_fields = {
            "experience_lines",
            "education_lines",
            "headline",
            "summary",
            "about",
            "profile_location",
            "public_identifier",
            "avatar_url",
            "photo_url",
            "media_url",
            "primary_email",
            "primary_email_metadata",
            "profile_capture_kind",
            "profile_capture_source_path",
        }
        if raw_result_record is not None:
            for key, value in dict(raw_result_record).items():
                if key == "metadata":
                    continue
                if (
                    authoritative_record
                    and key in materialized_profile_owned_fields
                    and authoritative_record.get(key) not in (None, "", [], {})
                ):
                    continue
                if value not in (None, "", [], {}):
                    merged[key] = value
            metadata = dict(authoritative_record.get("metadata") or {})
            for key, value in dict(dict(raw_result_record).get("metadata") or {}).items():
                if (
                    authoritative_record
                    and key in materialized_profile_owned_fields
                    and (
                        authoritative_record.get(key) not in (None, "", [], {})
                        or metadata.get(key) not in (None, "", [], {})
                    )
                ):
                    continue
                if value not in (None, "", [], {}):
                    metadata[key] = value
            if metadata:
                merged["metadata"] = metadata
        return merged

    def _build_job_candidate_api_context(self, job: dict[str, Any]) -> dict[str, Any]:
        workflow_stage_summaries = self._load_workflow_stage_summaries(job=job)
        plan_payload = dict(job.get("plan") or {})
        job_summary = dict(job.get("summary") or {})
        stage1_preview_summary = dict(
            dict(workflow_stage_summaries.get("summaries") or {}).get("stage_1_preview") or {}
        )
        request = JobRequest.from_payload(dict(job.get("request") or {}))
        asset_reuse_plan = dict(plan_payload.get("asset_reuse_plan") or {})
        job_id = str(job.get("job_id") or "").strip()
        workers = self._safe_list_persisted_job_workers(job_id) if job_id else []
        linkedin_stage_1_progress = self._build_public_linkedin_stage1_progress_payload(
            job=job,
            workers=workers,
        )
        candidate_source, result_view = self._resolve_job_candidate_source(
            job=job,
            request=request,
            job_summary=job_summary,
            stage1_preview_summary=stage1_preview_summary,
            linkedin_stage_1_progress=linkedin_stage_1_progress,
        )
        organization_execution_profile = self._organization_execution_profile_from_plan_payload(
            plan_payload=plan_payload,
            request=request,
            candidate_source=candidate_source,
        )
        effective_execution_semantics = self._build_effective_execution_semantics(
            request=request,
            organization_execution_profile=organization_execution_profile,
            asset_reuse_plan=asset_reuse_plan,
            candidate_source=candidate_source,
        )
        publishable_email_lookup = self._snapshot_publishable_email_lookup_for_request(
            request=request,
            candidate_source=candidate_source,
        )
        return {
            "workflow_stage_summaries": workflow_stage_summaries,
            "plan_payload": plan_payload,
            "job_summary": job_summary,
            "stage1_preview_summary": stage1_preview_summary,
            "request": request,
            "candidate_source": candidate_source,
            "result_view": result_view,
            "effective_execution_semantics": effective_execution_semantics,
            "publishable_email_lookup": publishable_email_lookup,
            "linkedin_stage_1_progress": linkedin_stage_1_progress,
        }

    def _build_job_candidate_api_payload(
        self,
        *,
        normalized_candidate_id: str,
        result_record: dict[str, Any] | None,
        candidate: Candidate | None,
        load_profile_timeline: bool = True,
        publishable_email_lookup: dict[str, dict[str, dict[str, Any]]] | None = None,
    ) -> dict[str, Any]:
        candidate_payload = candidate.to_record() if candidate is not None else {}
        if result_record is not None:
            candidate_payload.update(
                {
                    "candidate_id": normalized_candidate_id,
                    "display_name": str(
                        result_record.get("display_name") or candidate_payload.get("display_name") or ""
                    ),
                    "name_en": str(result_record.get("name_en") or candidate_payload.get("name_en") or ""),
                    "name_zh": str(result_record.get("name_zh") or candidate_payload.get("name_zh") or ""),
                    "category": str(result_record.get("category") or candidate_payload.get("category") or ""),
                    "organization": str(
                        result_record.get("organization") or candidate_payload.get("organization") or ""
                    ),
                    "role": str(result_record.get("role") or candidate_payload.get("role") or ""),
                    "team": str(result_record.get("team") or candidate_payload.get("team") or ""),
                    "employment_status": str(
                        result_record.get("employment_status") or candidate_payload.get("employment_status") or ""
                    ),
                    "focus_areas": str(result_record.get("focus_areas") or candidate_payload.get("focus_areas") or ""),
                    "linkedin_url": str(
                        result_record.get("linkedin_url") or candidate_payload.get("linkedin_url") or ""
                    ),
                    "media_url": str(result_record.get("media_url") or candidate_payload.get("media_url") or ""),
                    "avatar_url": str(result_record.get("avatar_url") or candidate_payload.get("avatar_url") or ""),
                    "photo_url": str(result_record.get("photo_url") or candidate_payload.get("photo_url") or ""),
                    "primary_email": str(
                        result_record.get("primary_email") or candidate_payload.get("primary_email") or ""
                    ),
                    "primary_email_metadata": _normalized_primary_email_metadata(
                        result_record.get("primary_email_metadata") or candidate_payload.get("primary_email_metadata")
                    ),
                    "function_ids": _normalize_candidate_level_function_ids(
                        result_record.get("function_ids"),
                        candidate_payload.get("function_ids"),
                        source_shard_filters=dict(candidate_payload.get("metadata") or {}).get("source_shard_filters"),
                    ),
                    "confidence_label": str(result_record.get("confidence_label") or ""),
                    "confidence_score": result_record.get("confidence_score"),
                    "confidence_reason": str(result_record.get("confidence_reason") or ""),
                    "explanation": str(result_record.get("explanation") or ""),
                    "matched_fields": list(result_record.get("matched_fields") or []),
                }
            )
            experience_lines = _normalized_text_lines(result_record.get("experience_lines"))
            education_lines = _normalized_text_lines(result_record.get("education_lines"))
            if experience_lines:
                candidate_payload["experience_lines"] = experience_lines
            if education_lines:
                candidate_payload["education_lines"] = education_lines
        candidate_metadata = dict(candidate_payload.get("metadata") or {})
        if result_record is not None:
            candidate_metadata.update(dict(result_record.get("metadata") or {}))
        candidate_source_path = str(
            candidate_payload.get("source_path")
            or (result_record or {}).get("source_path")
            or candidate_metadata.get("source_path")
            or ""
        ).strip()
        candidate_payload["metadata"] = candidate_metadata
        candidate_payload["source_path"] = candidate_source_path
        candidate_timeline = self._resolve_candidate_profile_timeline(
            payload=candidate_payload,
            metadata=candidate_metadata,
            source_path=candidate_source_path,
            load_profile_timeline=load_profile_timeline,
        )
        if candidate_timeline.get("experience_lines"):
            candidate_payload["experience_lines"] = list(candidate_timeline.get("experience_lines") or [])
        if candidate_timeline.get("education_lines"):
            candidate_payload["education_lines"] = list(candidate_timeline.get("education_lines") or [])
        for field_name in (
            "avatar_url",
            "photo_url",
            "primary_email",
            "headline",
            "summary",
            "about",
            "profile_location",
        ):
            field_value = candidate_timeline.get(field_name)
            if field_name == "primary_email":
                if _timeline_requires_primary_email_scrub(
                    candidate_timeline,
                    context={
                        **candidate_payload,
                        "metadata": candidate_metadata,
                    },
                ):
                    candidate_payload.pop("primary_email", None)
                    candidate_payload.pop("email", None)
                    continue
                if field_value:
                    candidate_payload[field_name] = field_value
                continue
            if field_value and not candidate_payload.get(field_name):
                candidate_payload[field_name] = field_value
        candidate_email_metadata = _normalized_primary_email_metadata(candidate_timeline.get("primary_email_metadata"))
        if candidate_email_metadata and str(candidate_payload.get("primary_email") or "").strip():
            candidate_payload["primary_email_metadata"] = candidate_email_metadata
        else:
            candidate_payload.pop("primary_email_metadata", None)
        candidate_payload = self._apply_publishable_email_overlay_from_lookup(
            source_record=result_record or candidate_payload,
            serialized_record=candidate_payload,
            publishable_email_lookup=publishable_email_lookup,
        )
        if not str(candidate_payload.get("primary_email") or "").strip():
            candidate_payload.pop("primary_email", None)
            candidate_payload.pop("email", None)
        if not candidate_payload.get("media_url"):
            media_url = str(candidate_payload.get("avatar_url") or candidate_payload.get("photo_url") or "").strip()
            if media_url:
                candidate_payload["media_url"] = media_url
        return candidate_payload

    def _load_authoritative_candidate_detail_for_source(
        self,
        *,
        request: JobRequest | None,
        candidate_source: dict[str, Any],
        candidate_id: str,
    ) -> dict[str, Any]:
        if not candidate_source_is_snapshot_authoritative(candidate_source):
            return {}
        overlay_payload = self._load_candidate_source_asset_population_overlay(candidate_source)
        if overlay_payload:
            overlay_record = next(
                (
                    dict(item)
                    for item in list(overlay_payload.get("candidates") or [])
                    if isinstance(item, dict)
                    and str(dict(item).get("candidate_id") or "").strip() == str(candidate_id or "").strip()
                ),
                {},
            )
            if overlay_record:
                overlay_record = self._enrich_overlay_candidate_records_from_materialized_sources(
                    request=request if isinstance(request, JobRequest) else JobRequest.from_payload({}),
                    candidate_source=candidate_source,
                    overlay_payload=overlay_payload,
                    records=[overlay_record],
                )[0]
                overlay_record = self._enrich_candidate_records_from_profile_registry([overlay_record])[0]
                return {
                    "status": "loaded",
                    "target_company": str(
                        overlay_payload.get("target_company")
                        or candidate_source.get("target_company")
                        or (request.target_company if isinstance(request, JobRequest) else "")
                        or ""
                    ).strip(),
                    "company_key": normalize_company_key(
                        str(
                            overlay_payload.get("target_company")
                            or candidate_source.get("target_company")
                            or (request.target_company if isinstance(request, JobRequest) else "")
                            or ""
                        ).strip()
                    ),
                    "snapshot_id": str(overlay_payload.get("snapshot_id") or candidate_source.get("snapshot_id") or ""),
                    "asset_view": str(
                        overlay_payload.get("asset_view") or candidate_source.get("asset_view") or "canonical_merged"
                    ),
                    "source_kind": "job_asset_population_overlay",
                    "candidate": self._candidate_from_overlay_record(overlay_record),
                    "materialized_record": dict(overlay_record),
                    "evidence_records": build_evidence_records_from_payloads(
                        list(
                            dict(overlay_payload.get("evidence_lookup") or {}).get(str(candidate_id or "").strip())
                            or []
                        )
                    ),
                    "evidence": [
                        dict(item)
                        for item in list(
                            dict(overlay_payload.get("evidence_lookup") or {}).get(str(candidate_id or "").strip())
                            or []
                        )
                        if isinstance(item, dict)
                    ],
                }
        target_company = str(
            (request.target_company if isinstance(request, JobRequest) else "")
            or candidate_source.get("target_company")
            or ""
        ).strip()
        snapshot_id = str(candidate_source.get("snapshot_id") or "").strip()
        asset_view = (
            str(
                candidate_source.get("asset_view")
                or (request.asset_view if isinstance(request, JobRequest) else "")
                or "canonical_merged"
            ).strip()
            or "canonical_merged"
        )
        if not target_company or not snapshot_id:
            return {}
        try:
            return load_authoritative_candidate_detail(
                runtime_dir=str(self.runtime_dir),
                target_company=target_company,
                candidate_id=candidate_id,
                snapshot_id=snapshot_id,
                asset_view=asset_view,
                store=self.store,
                allow_candidate_documents_fallback=False,
            )
        except CandidateArtifactError:
            return {}

    def _load_authoritative_candidate_details_for_source(
        self,
        *,
        request: JobRequest | None,
        candidate_source: dict[str, Any],
        candidate_ids: list[str],
    ) -> dict[str, dict[str, Any]]:
        if not candidate_source_is_snapshot_authoritative(candidate_source):
            return {}
        overlay_payload = self._load_candidate_source_asset_population_overlay(candidate_source)
        if overlay_payload:
            overlay_candidates = {
                str(dict(item).get("candidate_id") or "").strip(): dict(item)
                for item in list(overlay_payload.get("candidates") or [])
                if isinstance(item, dict) and str(dict(item).get("candidate_id") or "").strip()
            }
            evidence_lookup = dict(overlay_payload.get("evidence_lookup") or {})
            overlay_details: dict[str, dict[str, Any]] = {}
            for candidate_id in list(candidate_ids or []):
                normalized_candidate_id = str(candidate_id or "").strip()
                if not normalized_candidate_id:
                    continue
                overlay_record = dict(overlay_candidates.get(normalized_candidate_id) or {})
                if not overlay_record:
                    continue
                overlay_record = self._enrich_overlay_candidate_records_from_materialized_sources(
                    request=request if isinstance(request, JobRequest) else JobRequest.from_payload({}),
                    candidate_source=candidate_source,
                    overlay_payload=overlay_payload,
                    records=[overlay_record],
                )[0]
                overlay_record = self._enrich_candidate_records_from_profile_registry([overlay_record])[0]
                overlay_details[normalized_candidate_id] = {
                    "status": "loaded",
                    "target_company": str(
                        overlay_payload.get("target_company")
                        or candidate_source.get("target_company")
                        or (request.target_company if isinstance(request, JobRequest) else "")
                        or ""
                    ).strip(),
                    "company_key": normalize_company_key(
                        str(
                            overlay_payload.get("target_company")
                            or candidate_source.get("target_company")
                            or (request.target_company if isinstance(request, JobRequest) else "")
                            or ""
                        ).strip()
                    ),
                    "snapshot_id": str(
                        overlay_payload.get("snapshot_id") or candidate_source.get("snapshot_id") or ""
                    ).strip(),
                    "asset_view": str(
                        overlay_payload.get("asset_view") or candidate_source.get("asset_view") or "canonical_merged"
                    ).strip()
                    or "canonical_merged",
                    "source_kind": "job_asset_population_overlay",
                    "candidate": self._candidate_from_overlay_record(overlay_record),
                    "materialized_record": dict(overlay_record),
                    "evidence_records": build_evidence_records_from_payloads(
                        list(evidence_lookup.get(normalized_candidate_id) or [])
                    ),
                    "evidence": [
                        dict(item)
                        for item in list(evidence_lookup.get(normalized_candidate_id) or [])
                        if isinstance(item, dict)
                    ],
                }
            if overlay_details:
                return overlay_details
        target_company = str(
            (request.target_company if isinstance(request, JobRequest) else "")
            or candidate_source.get("target_company")
            or ""
        ).strip()
        snapshot_id = str(candidate_source.get("snapshot_id") or "").strip()
        asset_view = (
            str(
                candidate_source.get("asset_view")
                or (request.asset_view if isinstance(request, JobRequest) else "")
                or "canonical_merged"
            ).strip()
            or "canonical_merged"
        )
        if not target_company or not snapshot_id:
            return {}
        try:
            return load_authoritative_candidate_details(
                runtime_dir=str(self.runtime_dir),
                target_company=target_company,
                candidate_ids=list(candidate_ids or []),
                snapshot_id=snapshot_id,
                asset_view=asset_view,
                store=self.store,
                allow_candidate_documents_fallback=False,
            )
        except CandidateArtifactError:
            return {}

    def get_job_candidate_detail(
        self,
        job_id: str,
        candidate_id: str,
        *,
        allow_legacy_profile_timeline_hydration: bool = False,
    ) -> dict[str, Any] | None:
        job = self.store.get_job(job_id)
        if job is None:
            return None
        normalized_candidate_id = str(candidate_id or "").strip()
        if not normalized_candidate_id:
            return None
        context = self._build_job_candidate_api_context(job)
        request = context.get("request")
        candidate_source = dict(context.get("candidate_source") or {})
        effective_execution_semantics = dict(context.get("effective_execution_semantics") or {})
        publishable_email_lookup = context.get("publishable_email_lookup")
        authoritative_detail = self._load_authoritative_candidate_detail_for_source(
            request=request,
            candidate_source=candidate_source,
            candidate_id=normalized_candidate_id,
        )
        authoritative_record = dict(authoritative_detail.get("materialized_record") or {})
        result_records = self.store.get_job_results_for_candidates(
            job_id,
            [normalized_candidate_id],
            include_evidence=False,
        )
        raw_result_record = result_records[0] if result_records else None
        detail_base_record = self._merge_authoritative_detail_and_result_record(
            authoritative_record=authoritative_record,
            raw_result_record=raw_result_record,
        )
        raw_materialized_detail_available = self._candidate_record_has_materialized_profile_detail(detail_base_record)
        should_load_legacy_profile_timeline = (
            bool(allow_legacy_profile_timeline_hydration) and not raw_materialized_detail_available
        )
        result_record = (
            self._serialize_candidate_api_record(
                detail_base_record,
                load_profile_timeline=should_load_legacy_profile_timeline,
                publishable_email_lookup=publishable_email_lookup,
            )
            if detail_base_record
            else None
        )
        manual_review_items = [
            item
            for item in self.store.list_manual_review_items(job_id=job_id, status="", limit=200)
            if str(item.get("candidate_id") or "").strip() == normalized_candidate_id
        ]
        asset_population_record = None
        if result_record is None:
            asset_population_record = self._load_job_asset_population_candidate_record(
                job=job,
                candidate_id=normalized_candidate_id,
                load_profile_timeline=False,
                publishable_email_lookup=publishable_email_lookup,
            )
            if asset_population_record is not None:
                result_record = asset_population_record
                raw_materialized_detail_available = self._candidate_record_has_materialized_profile_detail(
                    asset_population_record
                )
        candidate = authoritative_detail.get("candidate")
        if not isinstance(candidate, Candidate) and not candidate_source_is_snapshot_authoritative(candidate_source):
            candidate = self.store.get_candidate(normalized_candidate_id)
        if result_record is None and candidate is None and not manual_review_items:
            return None
        candidate_payload = self._build_job_candidate_api_payload(
            normalized_candidate_id=normalized_candidate_id,
            result_record=result_record,
            candidate=candidate,
            load_profile_timeline=(
                bool(allow_legacy_profile_timeline_hydration) and not raw_materialized_detail_available
            ),
            publishable_email_lookup=publishable_email_lookup,
        )
        evidence = [dict(item) for item in list(authoritative_detail.get("evidence") or []) if isinstance(item, dict)]
        if not evidence and not candidate_source_is_snapshot_authoritative(candidate_source):
            evidence = self.store.list_evidence(normalized_candidate_id)
        if not evidence and asset_population_record is not None:
            shard_payload = self._load_asset_population_candidate_shard_payload(
                request=request,
                candidate_source=candidate_source,
                effective_execution_semantics=effective_execution_semantics,
                candidate_id=normalized_candidate_id,
            )
            if shard_payload is not None:
                evidence = [dict(item) for item in list(shard_payload.get("evidence") or []) if isinstance(item, dict)]
        return {
            "job": job,
            "candidate": candidate_payload,
            "result": result_record or {},
            "evidence": evidence,
            "manual_review_items": manual_review_items,
            "request_preview": _load_job_request_preview(job),
        }

    def get_job_candidate_details_batch(self, job_id: str, candidate_ids: list[str]) -> dict[str, Any] | None:
        job = self.store.get_job(job_id)
        if job is None:
            return None
        normalized_candidate_ids: list[str] = []
        seen_candidate_ids: set[str] = set()
        for item in list(candidate_ids or []):
            normalized_candidate_id = str(item or "").strip()
            if not normalized_candidate_id or normalized_candidate_id in seen_candidate_ids:
                continue
            seen_candidate_ids.add(normalized_candidate_id)
            normalized_candidate_ids.append(normalized_candidate_id)
        if not normalized_candidate_ids:
            return {"candidates": [], "not_found_candidate_ids": []}
        context = self._build_job_candidate_api_context(job)
        request = context.get("request")
        candidate_source = dict(context.get("candidate_source") or {})
        publishable_email_lookup = context.get("publishable_email_lookup")
        raw_result_records = self.store.get_job_results_for_candidates(
            job_id,
            normalized_candidate_ids,
            include_evidence=False,
        )
        raw_result_map = {
            str(record.get("candidate_id") or "").strip(): record
            for record in raw_result_records
            if str(record.get("candidate_id") or "").strip()
        }
        authoritative_details = self._load_authoritative_candidate_details_for_source(
            request=request,
            candidate_source=candidate_source,
            candidate_ids=normalized_candidate_ids,
        )
        candidates_payload: list[dict[str, Any]] = []
        not_found_candidate_ids: list[str] = []
        for candidate_id in normalized_candidate_ids:
            raw_result_record = raw_result_map.get(candidate_id)
            authoritative_detail = dict(authoritative_details.get(candidate_id) or {})
            authoritative_record = dict(authoritative_detail.get("materialized_record") or {})
            detail_base_record = self._merge_authoritative_detail_and_result_record(
                authoritative_record=authoritative_record,
                raw_result_record=raw_result_record,
            )
            result_record = (
                self._serialize_candidate_api_record(
                    detail_base_record,
                    load_profile_timeline=False,
                    publishable_email_lookup=publishable_email_lookup,
                )
                if detail_base_record
                else None
            )
            if result_record is None:
                asset_population_record = self._load_job_asset_population_candidate_record(
                    job=job,
                    candidate_id=candidate_id,
                    load_profile_timeline=False,
                    publishable_email_lookup=publishable_email_lookup,
                )
                if asset_population_record is not None:
                    result_record = asset_population_record
            candidate = authoritative_detail.get("candidate")
            if not isinstance(candidate, Candidate):
                candidate = self.store.get_candidate(candidate_id)
            if result_record is None and candidate is None:
                not_found_candidate_ids.append(candidate_id)
                continue
            candidates_payload.append(
                self._build_job_candidate_api_payload(
                    normalized_candidate_id=candidate_id,
                    result_record=result_record,
                    candidate=candidate,
                    load_profile_timeline=False,
                    publishable_email_lookup=publishable_email_lookup,
                )
            )
        return {
            "candidates": candidates_payload,
            "not_found_candidate_ids": not_found_candidate_ids,
        }

    def get_job_progress(self, job_id: str) -> dict[str, Any] | None:
        job = self.store.get_job(job_id)
        if job is None:
            return None
        job = self._maybe_promote_workflow_job_to_completed_from_final_results(job)
        event_summary = self.store.get_job_progress_event_summary(job_id, hydrate_if_missing=True)
        workers = self._safe_list_persisted_job_workers(job_id)
        result_count = self._public_progress_result_count(
            job_id=job_id,
            job=job,
            ranked_result_count=self.store.count_job_results(job_id),
        )
        manual_review_count = self.store.count_manual_review_items(job_id=job_id, status="")
        runtime_controls = self._build_live_runtime_controls_payload(job, use_poll_cache=True)
        auto_recovery = self._maybe_auto_recover_workflow_on_progress(
            job=job,
            events=[],
            workers=workers,
            runtime_controls=runtime_controls,
        )
        if str(auto_recovery.get("status") or "") in {"triggered_inline", "completed"}:
            job = self.store.get_job(job_id) or job
            event_summary = self.store.get_job_progress_event_summary(job_id, hydrate_if_missing=True)
            workers = self._safe_list_persisted_job_workers(job_id)
            result_count = self._public_progress_result_count(
                job_id=job_id,
                job=job,
                ranked_result_count=self.store.count_job_results(job_id),
            )
            manual_review_count = self.store.count_manual_review_items(job_id=job_id, status="")
            runtime_controls = self._build_live_runtime_controls_payload(job, use_poll_cache=False)
        payload = _build_job_progress_payload(
            job=job,
            events=[],
            event_summary=event_summary,
            workers=workers,
            result_count=result_count,
            manual_review_count=manual_review_count,
            runtime_controls=runtime_controls,
        )
        if auto_recovery:
            payload["auto_recovery"] = auto_recovery
        workflow_stage_summaries = self._load_workflow_stage_summaries(job=job)
        request = JobRequest.from_payload(dict(job.get("request") or {}))
        plan_payload = dict(job.get("plan") or {})
        lifecycle_row = self.store.get_job_result_lifecycle(job_id) or {}
        job_summary = dict(job.get("summary") or {})
        stage1_preview_summary = dict(
            dict(workflow_stage_summaries.get("summaries") or {}).get("stage_1_preview") or {}
        )
        linkedin_stage_1_progress = (
            self._stage1_progress_payload_from_lifecycle_row(
                lifecycle_row,
                dynamic_progress=dict(job_summary.get("linkedin_stage_1") or {}),
            )
            or self._build_public_linkedin_stage1_progress_payload(
                job=job,
                workers=workers,
            )
        )
        result_view_lifecycle = self._load_job_result_lifecycle(
            job_id=job_id,
            job=job,
            request=request,
            candidate_source={},
            result_view={},
            asset_population={},
            linkedin_stage_1_progress=linkedin_stage_1_progress,
            effective_execution_semantics={},
        )
        lifecycle_stage1_progress = self._stage1_progress_payload_from_lifecycle_row(
            result_view_lifecycle,
            dynamic_progress=linkedin_stage_1_progress,
        )
        if lifecycle_stage1_progress:
            linkedin_stage_1_progress = lifecycle_stage1_progress
        ranked_result_count = self.store.count_job_results(job_id)
        candidate_source, result_view = self._resolve_job_candidate_source(
            job=job,
            request=request,
            job_summary=job_summary,
            stage1_preview_summary=stage1_preview_summary,
            linkedin_stage_1_progress=linkedin_stage_1_progress,
        )
        organization_execution_profile = self._organization_execution_profile_from_plan_payload(
            plan_payload=plan_payload,
            request=request,
            candidate_source=candidate_source,
        )
        effective_execution_semantics = self._build_effective_execution_semantics(
            request=request,
            organization_execution_profile=organization_execution_profile,
            asset_reuse_plan=dict(plan_payload.get("asset_reuse_plan") or {}),
            candidate_source=candidate_source,
        )
        public_projection = self._build_public_board_runtime_projection(
            job_id=job_id,
            context={
                "job": job,
                "workflow_stage_summaries": workflow_stage_summaries,
                "plan_payload": plan_payload,
                "job_summary": job_summary,
                "stage1_preview_summary": stage1_preview_summary,
                "request": request,
                "candidate_source": candidate_source,
                "result_view": result_view,
                "effective_execution_semantics": effective_execution_semantics,
                "linkedin_stage_1_progress": linkedin_stage_1_progress,
            },
            ranked_result_count=ranked_result_count,
        )
        result_view_lifecycle = dict(public_projection.get("result_view_lifecycle") or result_view_lifecycle)
        board_runtime_state = dict(public_projection.get("board_runtime_state") or {})
        linkedin_stage_1_progress = dict(
            public_projection.get("linkedin_stage_1_progress") or linkedin_stage_1_progress
        )
        execution_phase_contract = self._build_execution_phase_contract(
            job=job,
            workflow_stage_summaries=workflow_stage_summaries,
            linkedin_stage_1_progress=linkedin_stage_1_progress,
            result_view_lifecycle=result_view_lifecycle,
        )
        result_count = self._public_progress_result_count(
            job_id=job_id,
            job=job,
            ranked_result_count=ranked_result_count,
            result_view_lifecycle=result_view_lifecycle,
            board_runtime_state=board_runtime_state,
            linkedin_stage_1_progress=linkedin_stage_1_progress,
        )
        excel_intake_progress = self._build_excel_intake_progress_payload(job=job)
        public_linkedin_stage_1_progress = _compact_public_workflow_payload(linkedin_stage_1_progress)
        payload["workflow_stage_summaries"] = _compact_public_workflow_stage_summaries(workflow_stage_summaries)
        payload["linkedin_stage_1_progress"] = public_linkedin_stage_1_progress
        payload["result_view_lifecycle"] = result_view_lifecycle
        payload["board_runtime_state"] = board_runtime_state
        payload["execution_phase_contract"] = execution_phase_contract
        if excel_intake_progress:
            payload["excel_intake_progress"] = excel_intake_progress
        provider_execution_manifest = _provider_execution_manifest_from_plan_payload(dict(job.get("plan") or {}))
        if provider_execution_manifest:
            payload["provider_execution_manifest"] = provider_execution_manifest
        progress_payload = dict(payload.get("progress") or {})
        counters_payload = dict(progress_payload.get("counters") or {})
        counters_payload["result_count"] = int(result_count or 0)
        progress_payload["counters"] = counters_payload
        latest_metrics_payload = dict(progress_payload.get("latest_metrics") or {})
        latest_metrics_payload["result_count"] = int(result_count or 0)
        progress_payload["latest_metrics"] = latest_metrics_payload
        progress_payload["linkedin_stage_1_progress"] = public_linkedin_stage_1_progress
        progress_payload["result_view_lifecycle"] = result_view_lifecycle
        progress_payload["board_runtime_state"] = board_runtime_state
        progress_payload["execution_phase_contract"] = execution_phase_contract
        if excel_intake_progress:
            progress_payload["excel_intake_progress"] = excel_intake_progress
        if provider_execution_manifest:
            progress_payload["provider_execution_manifest"] = provider_execution_manifest
        payload["progress"] = progress_payload
        return payload

    def _public_progress_result_count(
        self,
        *,
        job_id: str,
        job: dict[str, Any],
        ranked_result_count: int,
        result_view_lifecycle: dict[str, Any] | None = None,
        board_runtime_state: dict[str, Any] | None = None,
        linkedin_stage_1_progress: dict[str, Any] | None = None,
    ) -> int:
        """Return the user-visible board count, not only ranked-result rows."""

        result_view = self.store.get_job_result_view(job_id=job_id) or {}
        result_view_metadata = dict(result_view.get("metadata") or {})
        job_summary = dict(job.get("summary") or {})
        lifecycle = self.store.get_job_result_lifecycle(job_id) or {}

        def _count(value: Any) -> int:
            try:
                return max(int(value or 0), 0)
            except (TypeError, ValueError):
                return 0

        def _add_source_counts(counts: list[int], source: dict[str, Any]) -> None:
            for key in (
                "expected_candidate_count",
                "served_candidate_count",
                "returned_matches",
                "total_matches",
                "candidate_count",
                "published_candidate_count",
                "display_ready_candidate_count",
                "row_hydration_target_count",
                "candidate_discovery_count",
                "deduped_candidate_count",
                "deduped_profile_url_count",
                "profile_fetch_required_count",
                "profile_url_total_count",
            ):
                value = _count(source.get(key))
                if value > 0:
                    counts.append(value)

        def _stage1_deduped_public_count(*sources: dict[str, Any]) -> int:
            values: list[int] = []
            for source in sources:
                payload = dict(source or {})
                public_canonicalization = dict(payload.get("public_board_canonicalization") or {})
                for key in (
                    "public_candidate_count",
                    "canonical_candidate_count",
                    "deduped_candidate_count",
                    "stage1_deduped_candidate_count",
                    "deduped_profile_url_count",
                    "stage1_deduped_profile_url_count",
                    "profile_fetch_required_count",
                    "stage1_profile_fetch_required_count",
                    "profile_url_total_count",
                ):
                    value = _count(payload.get(key))
                    if value > 0:
                        values.append(value)
                    public_value = _count(public_canonicalization.get(key))
                    if public_value > 0:
                        values.append(public_value)
            return max(values or [0])

        request_payload = dict(job.get("request") or {})
        full_company_scope = str(request_payload.get("target_scope") or "").strip().lower() == "full_company_asset"
        stage1_deduped_count = _stage1_deduped_public_count(
            dict(board_runtime_state or {}),
            dict(result_view_lifecycle or {}),
            lifecycle,
            dict(result_view_metadata.get("result_view_lifecycle") or {}),
            dict(linkedin_stage_1_progress or {}),
            dict(job_summary.get("linkedin_stage_1_progress") or {}),
            dict(job_summary.get("linkedin_stage_1") or {}),
            dict(job_summary.get("stage1_preview") or {}),
            dict(dict(job_summary.get("stage1_preview") or {}).get("stage1_preview") or {}),
            dict(job_summary.get("candidate_source") or {}),
        )

        def _baseline_count_from_sources(*sources: dict[str, Any]) -> int:
            return max(_count(dict(source or {}).get("baseline_candidate_count")) for source in sources)

        def _delta_progress_applicable_from_sources(*sources: dict[str, Any]) -> bool | None:
            for source in sources:
                payload = dict(source or {})
                if "delta_profile_progress_applicable" in payload:
                    return bool(payload.get("delta_profile_progress_applicable") is not False)
            return None

        baseline_count = _baseline_count_from_sources(
            dict(board_runtime_state or {}),
            dict(result_view_lifecycle or {}),
            lifecycle,
            dict(result_view_metadata.get("result_view_lifecycle") or {}),
        )
        delta_progress_applicable = _delta_progress_applicable_from_sources(
            dict(result_view_lifecycle or {}),
            lifecycle,
            dict(result_view_metadata.get("result_view_lifecycle") or {}),
        )
        no_baseline_full_company_live_roster = bool(
            full_company_scope
            and baseline_count <= 0
            and delta_progress_applicable is False
        )
        if no_baseline_full_company_live_roster:
            if stage1_deduped_count > 0:
                return stage1_deduped_count
            result_view_count = _count(dict(result_view.get("summary") or {}).get("candidate_count"))
            if result_view_count > 0:
                return result_view_count

        canonical_projection_counts: list[int] = []
        public_board_state = dict(board_runtime_state or {})
        for key in (
            "expected_candidate_count",
            "served_candidate_count",
            "row_hydration_target_count",
            "published_candidate_count",
        ):
            board_count = _count(public_board_state.get(key))
            if board_count > 0:
                canonical_projection_counts.append(board_count)

        public_lifecycle = dict(result_view_lifecycle or {})
        if public_lifecycle:
            served_count = _count(public_lifecycle.get("served_candidate_count"))
            expected_count = _count(public_lifecycle.get("expected_candidate_count"))
            if max(served_count, expected_count) > 0:
                canonical_projection_counts.append(max(served_count, expected_count))
            lifecycle_state = str(public_lifecycle.get("state") or public_lifecycle.get("phase") or "").strip()
            if lifecycle_state in {"current_snapshot_serving", "post_result_layering", "current_serving"}:
                if expected_count > 0:
                    canonical_projection_counts.append(expected_count)

        if canonical_projection_counts:
            return max(canonical_projection_counts)

        if full_company_scope:
            if stage1_deduped_count > 0:
                return stage1_deduped_count

        if full_company_scope:
            # Full-company roster discovery can hold raw source rows before
            # public board canonicalization has deduped current/former evidence.
            # Expose validated board/result-view projection counts, but do not
            # fall through to raw lifecycle/ranked rows when no public projection
            # has been established.
            result_view_count = _count(dict(result_view.get("summary") or {}).get("candidate_count"))
            if result_view_count > 0:
                return result_view_count
            return 0

        result_view_metadata_gap = dict(result_view_metadata.get("serving_publication_gap") or {})
        if result_view_metadata_gap:
            result_view_served_count = _count(dict(result_view.get("summary") or {}).get("candidate_count"))
            if result_view_served_count > 0:
                return result_view_served_count

        if str(lifecycle.get("source_validation_status") or "").strip() == "validated":
            lifecycle_count = max(
                _count(lifecycle.get("served_candidate_count")),
                _count(lifecycle.get("expected_candidate_count")),
            )
            if lifecycle_count > 0:
                return lifecycle_count
            lifecycle_state = str(lifecycle.get("state") or lifecycle.get("phase") or "").strip()
            if lifecycle_state in {"current_snapshot_serving", "post_result_layering", "current_serving"}:
                expected_count = _count(lifecycle.get("expected_candidate_count"))
                if expected_count > 0:
                    return expected_count

        if stage1_deduped_count > 0:
            return stage1_deduped_count

        count_candidates: list[int] = []
        for source in (
            dict(board_runtime_state or {}),
            dict(result_view_lifecycle or {}),
            dict(linkedin_stage_1_progress or {}),
            dict(result_view_metadata.get("result_view_lifecycle") or {}),
            dict(job_summary.get("result_view_lifecycle") or {}),
            dict(job_summary.get("candidate_source") or {}),
            dict(dict(job_summary.get("candidate_source") or {}).get("result_view_summary") or {}),
            dict(dict(dict(job_summary.get("candidate_source") or {}).get("result_view") or {}).get("summary") or {}),
            dict(job_summary.get("stage1_preview") or {}),
            dict(dict(job_summary.get("stage1_preview") or {}).get("candidate_source") or {}),
            dict(dict(job_summary.get("stage1_preview") or {}).get("stage1_preview") or {}),
            dict(job_summary.get("linkedin_stage_1_progress") or {}),
            dict(job_summary.get("linkedin_stage_1") or {}),
            dict(job_summary.get("asset_population_overlay") or {}),
            dict(job_summary.get("latest_metrics") or {}),
            job_summary,
            dict(result_view.get("summary") or {}),
        ):
            _add_source_counts(count_candidates, source)
        ranked_count = _count(ranked_result_count)
        if ranked_count > 0:
            count_candidates.append(ranked_count)
        return max(count_candidates or [0])

    def _workflow_requested_execution_mode(
        self, job: dict[str, Any], *, events: list[dict[str, Any]] | None = None
    ) -> str:
        summary = dict(job.get("summary") or {})
        summary_mode = str(summary.get("runtime_execution_mode") or "").strip().lower()
        if summary_mode:
            return summary_mode

        request_payload = dict(job.get("request") or {})
        request_mode = str(request_payload.get("runtime_execution_mode") or "").strip().lower()
        if request_mode:
            return request_mode

        runtime_controls = dict(summary.get("runtime_controls") or {})
        if runtime_controls:
            if runtime_controls.get("hosted_runtime_watchdog"):
                return "hosted"
            if runtime_controls.get("workflow_runner") or runtime_controls.get("workflow_runner_control"):
                return "managed_subprocess"

        planning_events = list(events or self.store.list_job_events(str(job.get("job_id") or ""), stage="planning"))
        for event in planning_events:
            payload = dict(event.get("payload") or {})
            event_mode = str(payload.get("runtime_execution_mode") or "").strip().lower()
            if event_mode:
                return event_mode
        return ""

    def _workflow_prefers_hosted_execution(
        self, job: dict[str, Any], *, events: list[dict[str, Any]] | None = None
    ) -> bool:
        mode = self._workflow_requested_execution_mode(job, events=events)
        if mode in {"managed_subprocess", "runner_managed", "detached_sidecar"}:
            return False
        if mode == "hosted":
            return True

        summary = dict(job.get("summary") or {})
        runtime_controls = dict(summary.get("runtime_controls") or {})
        if runtime_controls.get("workflow_runner") or runtime_controls.get("workflow_runner_control"):
            return False
        return True

    def _maybe_auto_recover_workflow_on_progress(
        self,
        *,
        job: dict[str, Any],
        events: list[dict[str, Any]],
        workers: list[dict[str, Any]],
        runtime_controls: dict[str, Any],
    ) -> dict[str, Any]:
        if str(job.get("job_type") or "") != "workflow":
            return {}
        job_id = str(job.get("job_id") or "").strip()
        if not job_id:
            return {}
        if self._job_is_terminal(job):
            return {}

        worker_summary = _job_worker_summary(workers)
        runtime_health = _classify_job_runtime_health(
            job=job,
            workers=workers,
            worker_summary=worker_summary,
            runtime_controls=runtime_controls,
            blocked_task=str(dict(job.get("summary") or {}).get("blocked_task") or ""),
        )
        classification = str(runtime_health.get("classification") or "").strip()
        remote_wait_guard = _progress_auto_takeover_remote_wait_guard(
            job=job,
            workers=workers,
            runtime_health=runtime_health,
            blocked_task=str(dict(job.get("summary") or {}).get("blocked_task") or ""),
        )
        if remote_wait_guard:
            return remote_wait_guard
        if classification not in {
            "runner_not_alive",
            "runner_takeover_pending",
            "blocked_on_acquisition_workers",
            "blocked_ready_for_resume",
            "queued_waiting_for_runner",
            "runner_failed_to_start",
        }:
            return {
                "status": "skipped",
                "reason": "runtime_not_takeover_eligible",
                "classification": classification,
            }

        cooldown_seconds = max(3, int(_env_int("WORKFLOW_PROGRESS_AUTO_TAKEOVER_COOLDOWN_SECONDS", 15)))
        recent_events = self.store.list_job_events(
            job_id,
            stage="runtime_control",
            limit=20,
            descending=True,
        )
        for event in recent_events:
            payload = dict(event.get("payload") or {})
            if str(payload.get("control") or "") != "progress_auto_takeover":
                continue
            created_at = _parse_timestamp(str(event.get("created_at") or ""))
            if created_at is None:
                break
            age_seconds = max(int((datetime.now(timezone.utc) - created_at).total_seconds()), 0)
            if age_seconds < cooldown_seconds:
                return {
                    "status": "skipped",
                    "reason": "cooldown_active",
                    "classification": classification,
                    "cooldown_seconds": cooldown_seconds,
                    "seconds_until_retry": max(cooldown_seconds - age_seconds, 0),
                }
            break

        recovery_payload = {
            "job_id": job_id,
            "workflow_stale_scope_job_id": job_id,
            "workflow_resume_explicit_job": True,
            "workflow_auto_resume_enabled": True,
            "workflow_resume_stale_after_seconds": 0,
            "workflow_resume_limit": 1,
            "workflow_queue_auto_takeover_enabled": True,
            "workflow_queue_resume_stale_after_seconds": 0,
            "workflow_queue_resume_limit": 1,
            "runtime_heartbeat_source": "progress_poll",
            "runtime_heartbeat_interval_seconds": 0,
        }
        if classification in {
            "runner_not_alive",
            "runner_takeover_pending",
            "blocked_on_acquisition_workers",
            "runner_failed_to_start",
        }:
            recovery_payload["stale_after_seconds"] = 0

        requested_execution_mode = self._workflow_requested_execution_mode(job, events=events)
        effective_execution_mode = (
            "hosted" if self._workflow_prefers_hosted_execution(job, events=events) else "managed_subprocess"
        )
        inflight = self._get_progress_takeover_inflight(job_id)
        if inflight:
            queued_at = str(inflight.get("queued_at") or "").strip()
            return {
                "status": "skipped",
                "reason": "already_inflight",
                "classification": classification,
                "requested_execution_mode": requested_execution_mode,
                "effective_execution_mode": effective_execution_mode,
                "queued_at": queued_at,
            }

        return self._queue_progress_auto_takeover(
            job_id=job_id,
            classification=classification,
            requested_execution_mode=requested_execution_mode,
            effective_execution_mode=effective_execution_mode,
            recovery_payload=recovery_payload,
        )

    def _get_progress_takeover_inflight(self, job_id: str) -> dict[str, Any]:
        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        with self._progress_takeover_lock:
            current = dict(self._progress_takeover_inflight.get(normalized_job_id) or {})
        if not current:
            return {}
        queued_at_raw = str(current.get("queued_at") or "").strip()
        queued_at = _parse_timestamp(queued_at_raw)
        max_age_seconds = max(15, int(_env_int("WORKFLOW_PROGRESS_AUTO_TAKEOVER_INFLIGHT_STALE_SECONDS", 60)))
        if queued_at is not None:
            age_seconds = max(int((datetime.now(timezone.utc) - queued_at).total_seconds()), 0)
            if age_seconds >= max_age_seconds:
                with self._progress_takeover_lock:
                    latest = dict(self._progress_takeover_inflight.get(normalized_job_id) or {})
                    if str(latest.get("queued_at") or "").strip() == queued_at_raw:
                        self._progress_takeover_inflight.pop(normalized_job_id, None)
                self.store.append_job_event(
                    normalized_job_id,
                    stage="runtime_control",
                    status="failed",
                    detail="Cleared stale progress auto takeover inflight marker after timeout.",
                    payload={
                        "control": "progress_auto_takeover_reset",
                        "queued_at": queued_at_raw,
                        "age_seconds": age_seconds,
                        "timeout_seconds": max_age_seconds,
                    },
                )
                return {}
        return current

    def _queue_progress_auto_takeover(
        self,
        *,
        job_id: str,
        classification: str,
        requested_execution_mode: str,
        effective_execution_mode: str,
        recovery_payload: dict[str, Any],
    ) -> dict[str, Any]:
        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {"status": "skipped", "reason": "invalid_job_id", "classification": classification}
        queued_at = datetime.now(timezone.utc).isoformat()
        control_payload = {
            "control": "progress_auto_takeover",
            "classification": classification,
            "requested_execution_mode": requested_execution_mode,
            "effective_execution_mode": effective_execution_mode,
            "recovery_status": "queued",
            "queued_at": queued_at,
        }
        with self._progress_takeover_lock:
            if normalized_job_id in self._progress_takeover_inflight:
                current = dict(self._progress_takeover_inflight.get(normalized_job_id) or {})
                return {
                    "status": "skipped",
                    "reason": "already_inflight",
                    "classification": classification,
                    "requested_execution_mode": requested_execution_mode,
                    "effective_execution_mode": effective_execution_mode,
                    "queued_at": str(current.get("queued_at") or ""),
                }
            self._progress_takeover_inflight[normalized_job_id] = {
                "classification": classification,
                "requested_execution_mode": requested_execution_mode,
                "effective_execution_mode": effective_execution_mode,
                "queued_at": queued_at,
            }

        self.store.append_job_event(
            normalized_job_id,
            stage="runtime_control",
            status="running",
            detail=f"Progress polling queued automatic workflow takeover for `{classification}`.",
            payload=control_payload,
        )
        thread = threading.Thread(
            target=self._run_progress_auto_takeover,
            kwargs={
                "job_id": normalized_job_id,
                "classification": classification,
                "requested_execution_mode": requested_execution_mode,
                "effective_execution_mode": effective_execution_mode,
                "recovery_payload": dict(recovery_payload),
                "queued_at": queued_at,
            },
            name=f"progress-auto-takeover-{normalized_job_id}",
            daemon=True,
        )
        thread.start()
        return {
            "status": "queued",
            "classification": classification,
            "requested_execution_mode": requested_execution_mode,
            "effective_execution_mode": effective_execution_mode,
            "recovery_status": "queued",
            "queued_at": queued_at,
        }

    def _run_progress_auto_takeover(
        self,
        *,
        job_id: str,
        classification: str,
        requested_execution_mode: str,
        effective_execution_mode: str,
        recovery_payload: dict[str, Any],
        queued_at: str,
    ) -> None:
        try:
            recovery = self.run_worker_recovery_once(recovery_payload)
            workflow_resume = self._extract_progress_takeover_workflow_resume(job_id=job_id, recovery=recovery)
            self.store.append_job_event(
                job_id,
                stage="runtime_control",
                status="running",
                detail=f"Progress auto takeover finished for `{classification}`.",
                payload={
                    "control": "progress_auto_takeover_result",
                    "classification": classification,
                    "requested_execution_mode": requested_execution_mode,
                    "effective_execution_mode": effective_execution_mode,
                    "queued_at": queued_at,
                    "recovery_status": str(recovery.get("status") or ""),
                    "workflow_resume": workflow_resume,
                },
            )
        except Exception as exc:
            self.store.append_job_event(
                job_id,
                stage="runtime_control",
                status="failed",
                detail=f"Progress auto takeover failed for `{classification}`: {exc}",
                payload={
                    "control": "progress_auto_takeover_result",
                    "classification": classification,
                    "requested_execution_mode": requested_execution_mode,
                    "effective_execution_mode": effective_execution_mode,
                    "queued_at": queued_at,
                    "recovery_status": "failed",
                    "error": str(exc),
                },
            )
        finally:
            with self._progress_takeover_lock:
                self._progress_takeover_inflight.pop(str(job_id or "").strip(), None)

    def _extract_progress_takeover_workflow_resume(
        self,
        *,
        job_id: str,
        recovery: dict[str, Any],
    ) -> list[dict[str, str]]:
        normalized_job_id = str(job_id or "").strip()
        return [
            {
                "job_id": str(item.get("job_id") or ""),
                "status": str(item.get("status") or ""),
                "reason": str(item.get("reason") or ""),
                "resume_mode": str(item.get("resume_mode") or ""),
                "job_status": str(item.get("job_status") or ""),
                "job_stage": str(item.get("job_stage") or ""),
            }
            for item in list(recovery.get("workflow_resume") or [])
            if str(item.get("job_id") or "").strip() == normalized_job_id
        ]

    def get_job_trace(self, job_id: str) -> dict[str, Any] | None:
        job = self.store.get_job(job_id)
        if job is None:
            return None
        persisted_workers = self._safe_list_persisted_job_workers(job_id)
        return {
            "job_id": job_id,
            "agent_runtime_session": self.store.get_agent_runtime_session(job_id=job_id) or {},
            "agent_trace_spans": self.store.list_agent_trace_spans(job_id=job_id),
            "agent_workers": persisted_workers,
        }

    def get_job_workers(self, job_id: str) -> dict[str, Any] | None:
        job = self.store.get_job(job_id)
        if job is None:
            return None
        persisted_workers = self._safe_list_persisted_job_workers(job_id)
        return {
            "job_id": job_id,
            "agent_runtime_session": self.store.get_agent_runtime_session(job_id=job_id) or {},
            "agent_workers": persisted_workers,
        }

    def get_job_materialization_items(self, job_id: str) -> dict[str, Any] | None:
        job = self.store.get_job(job_id)
        if job is None:
            return None
        items = self.store.list_job_materialization_items(job_id=job_id, limit=500)
        workflow_run_id = legacy_job_workflow_run_id(job_id)
        workflow_commands = self.store.list_workflow_commands(workflow_run_id=workflow_run_id, limit=500)
        patches = self.store.list_job_board_visible_patches(job_id=job_id, limit=500)
        status_counts = Counter(str(item.get("status") or "").strip().lower() for item in items)
        kind_counts = Counter(str(item.get("item_kind") or "").strip() for item in items)
        command_status_counts = Counter(
            str(command.get("status") or "").strip().lower() for command in workflow_commands
        )
        command_type_counts = Counter(
            str(command.get("command_type") or "").strip() for command in workflow_commands
        )
        command_owner_counts = Counter(str(command.get("owner") or "").strip() for command in workflow_commands)
        patch_kind_counts = Counter(str(item.get("patch_kind") or "").strip() for item in patches)
        patch_phase_counts = Counter(str(item.get("patch_phase") or "").strip() for item in patches)
        return {
            "job_id": job_id,
            "workflow_run_id": workflow_run_id,
            "job_materialization_items": [
                _compact_public_materialization_item_payload(dict(item))
                for item in items
                if isinstance(item, dict)
            ],
            "item_count": len(items),
            "status_counts": {key: int(value) for key, value in sorted(status_counts.items()) if key},
            "kind_counts": {key: int(value) for key, value in sorted(kind_counts.items()) if key},
            "workflow_commands": [
                _compact_public_workflow_command_payload(dict(command))
                for command in workflow_commands
                if isinstance(command, dict)
            ],
            "workflow_command_count": len(workflow_commands),
            "workflow_command_status_counts": {
                key: int(value) for key, value in sorted(command_status_counts.items()) if key
            },
            "workflow_command_type_counts": {
                key: int(value) for key, value in sorted(command_type_counts.items()) if key
            },
            "workflow_command_owner_counts": {
                key: int(value) for key, value in sorted(command_owner_counts.items()) if key
            },
            "job_board_visible_patches": [
                _compact_public_board_visible_patch_payload(dict(patch))
                for patch in patches
                if isinstance(patch, dict)
            ],
            "patch_count": len(patches),
            "patch_kind_counts": {key: int(value) for key, value in sorted(patch_kind_counts.items()) if key},
            "patch_phase_counts": {key: int(value) for key, value in sorted(patch_phase_counts.items()) if key},
        }

    def convert_legacy_job_materialization_items_to_workflow_commands(
        self,
        payload: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Plan typed workflow commands from migration-era materialization rows.

        This adapter is intentionally one-way and non-executing: it turns old
        `job_materialization_items` rows into reducer-owned command plans, then
        typed command owners do the actual work. It exists so historical or
        in-flight rows can be lifted into the durable runtime without keeping
        the legacy item queue as a second normal execution path.
        """

        payload = dict(payload or {})
        explicit_job_id = str(payload.get("job_id") or "").strip()
        limit = max(1, _coerce_int(payload.get("limit") or payload.get("legacy_materialization_adapter_limit"), 100))
        statuses = [
            str(status or "").strip().lower()
            for status in list(payload.get("statuses") or _LEGACY_MATERIALIZATION_ADAPTER_DEFAULT_STATUSES)
            if str(status or "").strip()
        ]
        if not statuses:
            statuses = list(_LEGACY_MATERIALIZATION_ADAPTER_DEFAULT_STATUSES)
        requested_kinds = [
            str(item or "").strip()
            for item in list(payload.get("item_kinds") or _LEGACY_MATERIALIZATION_ADAPTER_SUPPORTED_ITEM_KINDS)
            if str(item or "").strip()
        ]
        if not requested_kinds:
            requested_kinds = list(_LEGACY_MATERIALIZATION_ADAPTER_SUPPORTED_ITEM_KINDS)

        inspected_count = 0
        converted_count = 0
        already_converted_count = 0
        unsupported_count = 0
        invalid_scope_count = 0
        failed_count = 0
        skipped_count = 0
        runtime_namespace_skipped_count = 0
        by_kind: dict[str, dict[str, int]] = {}
        converted_commands: list[dict[str, Any]] = []
        items: list[dict[str, Any]] = []

        def _increment(kind: str, key: str) -> None:
            normalized_kind = str(kind or "unknown").strip() or "unknown"
            bucket = by_kind.setdefault(normalized_kind, {})
            bucket[key] = _coerce_int(bucket.get(key), 0) + 1

        def _existing_command_for_item(item_payload: dict[str, Any], command_type: str) -> dict[str, Any]:
            workflow_run_id = legacy_job_workflow_run_id(str(item_payload.get("job_id") or ""))
            if not workflow_run_id or not command_type:
                return {}
            item_id = str(item_payload.get("item_id") or "").strip()
            for command in self.store.list_workflow_commands(
                workflow_run_id=workflow_run_id,
                limit=0,
            ):
                command_payload = dict(command.get("payload") or {})
                legacy_ref = dict(command_payload.get("legacy_materialization_item") or {})
                if str(command.get("command_type") or "") != command_type:
                    continue
                if str(command_payload.get("item_id") or legacy_ref.get("item_id") or "").strip() == item_id:
                    return dict(command or {})
            return {}

        for item_kind in requested_kinds:
            if inspected_count >= limit:
                break
            command_type = _LEGACY_MATERIALIZATION_ADAPTER_ITEM_COMMAND_TYPES.get(item_kind, "")
            if not command_type:
                unsupported_count += 1
                _increment(item_kind, "unsupported_count")
                items.append(
                    {
                        "status": "unsupported",
                        "reason": "legacy_materialization_item_kind_unsupported",
                        "item_kind": item_kind,
                    }
                )
                continue
            remaining = limit - inspected_count
            try:
                materialization_items = self.store.list_job_materialization_items(
                    job_id=explicit_job_id,
                    item_kind=item_kind,
                    statuses=statuses,
                    limit=remaining,
                )
            except Exception as exc:
                failed_count += 1
                _increment(item_kind, "failed_count")
                items.append(
                    {
                        "status": "failed",
                        "reason": "legacy_materialization_item_scan_failed",
                        "item_kind": item_kind,
                        "error": str(exc),
                    }
                )
                continue
            for item_payload in [dict(item or {}) for item in materialization_items]:
                if inspected_count >= limit:
                    break
                inspected_count += 1
                item_id = str(item_payload.get("item_id") or "").strip()
                item_job_id = str(item_payload.get("job_id") or "").strip()
                item_kind = str(item_payload.get("item_kind") or item_kind).strip()
                _increment(item_kind, "inspected_count")
                if not item_id or not item_job_id:
                    invalid_scope_count += 1
                    _increment(item_kind, "invalid_scope_count")
                    items.append(
                        {
                            "status": "invalid_scope",
                            "reason": "legacy_materialization_item_scope_missing",
                            "item_id": item_id,
                            "job_id": item_job_id,
                            "item_kind": item_kind,
                        }
                    )
                    continue
                namespace_mismatch = self._runtime_namespace_mismatch_for_durable_payload(item_payload)
                if namespace_mismatch:
                    runtime_namespace_skipped_count += 1
                    _increment(item_kind, "runtime_namespace_skipped_count")
                    items.append(
                        {
                            **namespace_mismatch,
                            "status": "skipped",
                            "item_id": item_id,
                            "job_id": item_job_id,
                            "item_kind": item_kind,
                        }
                    )
                    continue
                existing_command = _existing_command_for_item(item_payload, command_type)
                if existing_command:
                    already_converted_count += 1
                    _increment(item_kind, "already_converted_count")
                    observation = self._workflow_command_observation(
                        existing_command,
                        migration_phase="W4_legacy_materialization_adapter",
                    )
                    converted_commands.append(observation)
                    items.append(
                        {
                            "status": "already_converted",
                            "reason": "workflow_command_already_planned_for_legacy_item",
                            "item_id": item_id,
                            "job_id": item_job_id,
                            "item_kind": item_kind,
                            "workflow_command": observation,
                        }
                    )
                    continue
                try:
                    if item_kind == _LOCAL_APPLY_CLOSURE_ITEM_KIND:
                        command = self._plan_local_profile_delta_apply_command_for_item(
                            item=item_payload,
                            request=JobRequest.from_payload(
                                dict(dict(item_payload.get("metadata") or {}).get("request_payload") or {})
                            ),
                            source="legacy_job_materialization_adapter",
                            reason="phase_w4_legacy_item_conversion",
                        )
                    elif item_kind == _BOARD_VISIBLE_DELTA_APPLY_ITEM_KIND:
                        command = self._plan_board_visible_patch_publish_command_for_item(
                            item=item_payload,
                            request=JobRequest.from_payload(
                                dict(dict(item_payload.get("metadata") or {}).get("request_payload") or {})
                            ),
                            source="legacy_job_materialization_adapter",
                            reason="phase_w4_legacy_item_conversion",
                        )
                    elif item_kind == _PROJECTION_PERSON_SEARCH_INDEX_ITEM_KIND:
                        command = self._plan_projection_person_search_index_build_command_for_item(
                            item=item_payload,
                            source="legacy_job_materialization_adapter",
                            reason="phase_w4_legacy_item_conversion",
                        )
                    elif item_kind == _COLLECTION_AUTHORITATIVE_MERGE_ITEM_KIND:
                        command = self._plan_collection_authoritative_merge_command_for_item(
                            item=item_payload,
                            source="legacy_job_materialization_adapter",
                            reason="phase_w4_legacy_item_conversion",
                        )
                    elif item_kind == SEARCH_SEED_DISCOVERY_QUERY_ITEM_KIND:
                        command = self._plan_search_seed_discovery_query_run_command_for_item(
                            item=item_payload,
                            source="legacy_job_materialization_adapter",
                            reason="phase_w4_legacy_item_conversion",
                        )
                    elif item_kind == _PROJECTION_FACET_LAYERING_ITEM_KIND:
                        command = self._plan_projection_facet_layering_build_command_for_item(
                            item=item_payload,
                            request=JobRequest.from_payload(
                                dict(dict(item_payload.get("metadata") or {}).get("request_payload") or {})
                            ),
                            source="legacy_job_materialization_adapter",
                            reason="phase_w4_legacy_item_conversion",
                        )
                    elif item_kind == "snapshot_full_materialization":
                        command = self._plan_snapshot_compaction_run_command_for_item(
                            item=item_payload,
                            source="legacy_job_materialization_adapter",
                            reason="phase_w4_legacy_item_conversion",
                        )
                    else:
                        command = {}
                except Exception as exc:
                    failed_count += 1
                    _increment(item_kind, "failed_count")
                    items.append(
                        {
                            "status": "failed",
                            "reason": "legacy_materialization_item_conversion_failed",
                            "item_id": item_id,
                            "job_id": item_job_id,
                            "item_kind": item_kind,
                            "command_type": command_type,
                            "error": str(exc),
                        }
                    )
                    continue
                if command:
                    converted_count += 1
                    _increment(item_kind, "converted_count")
                    observation = self._workflow_command_observation(
                        command,
                        migration_phase="W4_legacy_materialization_adapter",
                    )
                    converted_commands.append(observation)
                    items.append(
                        {
                            "status": "converted",
                            "reason": "workflow_command_planned_for_legacy_item",
                            "item_id": item_id,
                            "job_id": item_job_id,
                            "item_kind": item_kind,
                            "command_type": command_type,
                            "workflow_command": observation,
                        }
                    )
                    continue
                invalid_scope_count += 1
                _increment(item_kind, "invalid_scope_count")
                items.append(
                    {
                        "status": "invalid_scope",
                        "reason": "workflow_command_not_planned_for_legacy_item",
                        "item_id": item_id,
                        "job_id": item_job_id,
                        "item_kind": item_kind,
                        "command_type": command_type,
                    }
                )

        skipped_count = max(
            0,
            inspected_count
            - converted_count
            - already_converted_count
            - invalid_scope_count
            - failed_count
            - runtime_namespace_skipped_count,
        )
        open_unconverted_count = max(
            0,
            inspected_count
            - converted_count
            - already_converted_count
            - runtime_namespace_skipped_count,
        )
        status = "active" if converted_count > 0 else "idle"
        if failed_count > 0:
            status = "failed" if inspected_count == failed_count else "active"
        return {
            "status": status,
            "reason": (
                "legacy_materialization_items_converted"
                if converted_count > 0
                else "legacy_materialization_items_already_converted"
                if already_converted_count > 0 and open_unconverted_count == 0
                else "legacy_materialization_items_require_review"
                if open_unconverted_count > 0
                else "no_convertible_legacy_materialization_items"
            ),
            "migration_phase": "W4_legacy_materialization_adapter",
            "migration_bridge": "job_materialization_items_to_workflow_commands",
            "job_id": explicit_job_id,
            "inspected_count": inspected_count,
            "converted_count": converted_count,
            "already_converted_count": already_converted_count,
            "unsupported_count": unsupported_count,
            "invalid_scope_count": invalid_scope_count,
            "failed_count": failed_count,
            "skipped_count": skipped_count,
            "runtime_namespace_skipped_count": runtime_namespace_skipped_count,
            "open_unconverted_count": open_unconverted_count,
            "by_kind": by_kind,
            "converted_commands": [
                command for command in converted_commands if command
            ][:20],
            "items": items[:50],
        }

    def get_job_scheduler(self, job_id: str) -> dict[str, Any] | None:
        job = self.store.get_job(job_id)
        if job is None:
            return None
        session = self.store.get_agent_runtime_session(job_id=job_id) or {}
        workers = self._safe_list_persisted_job_workers(job_id)
        plan_payload = dict(job.get("plan") or {})
        return {
            "job_id": job_id,
            "agent_runtime_session": session,
            "scheduler": summarize_scheduler(plan_payload=plan_payload, workers=workers),
        }

    def interrupt_agent_worker(self, payload: dict[str, Any]) -> dict[str, Any]:
        worker_id = int(payload.get("worker_id") or 0)
        if worker_id <= 0:
            return {"status": "invalid", "reason": "worker_id is required"}
        worker = self.agent_runtime.interrupt_worker(worker_id)
        if worker is None:
            return {"status": "not_found", "worker_id": worker_id}
        return {"status": "interrupt_requested", "worker": worker}

    def list_recoverable_agent_workers(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = dict(payload or {})
        workers = self.store.list_recoverable_agent_workers(
            limit=int(payload.get("limit") or 100),
            stale_after_seconds=int(payload.get("stale_after_seconds") or 180),
            lane_id=str(payload.get("lane_id") or ""),
            job_id=str(payload.get("job_id") or ""),
        )
        return {
            "recoverable_workers": workers,
            "count": len(workers),
            "stale_after_seconds": int(payload.get("stale_after_seconds") or 180),
            "lane_id": str(payload.get("lane_id") or ""),
            "job_id": str(payload.get("job_id") or ""),
        }

    def cleanup_recoverable_workers(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = dict(payload or {})
        stale_after_seconds = max(1, int(payload.get("stale_after_seconds") or 180))
        limit = max(1, int(payload.get("limit") or 200))
        dry_run = _coerce_bool(payload.get("dry_run"), False)
        terminal_workflows_only = _coerce_bool(payload.get("terminal_workflows_only"), True)
        include_missing_jobs = _coerce_bool(payload.get("include_missing_jobs"), False)
        target_company_filter = str(payload.get("target_company") or "").strip().lower()
        parent_job_statuses = {
            str(item or "").strip().lower()
            for item in list(payload.get("parent_job_statuses") or [])
            if str(item or "").strip()
        }
        override_status = str(payload.get("status") or "").strip().lower()
        reason = str(payload.get("reason") or "").strip() or "Retired stale recoverable worker during operator cleanup."

        recoverable_workers = self.store.list_recoverable_agent_workers(
            limit=limit,
            stale_after_seconds=stale_after_seconds,
            lane_id=str(payload.get("lane_id") or ""),
            job_id=str(payload.get("job_id") or ""),
        )

        candidates: list[dict[str, Any]] = []
        skipped: list[dict[str, Any]] = []
        for worker in recoverable_workers:
            job_id = str(worker.get("job_id") or "").strip()
            job = self.store.get_job(job_id) or {}
            job_type = str(job.get("job_type") or "").strip().lower()
            job_status = str(job.get("status") or "").strip().lower()
            job_stage = str(job.get("stage") or "").strip().lower()
            request_payload = dict(job.get("request") or {})
            target_company = str(request_payload.get("target_company") or "").strip()

            if target_company_filter and target_company.lower() != target_company_filter:
                continue

            parent_missing = not bool(job)
            terminal_workflow = job_type == "workflow" and self._job_is_terminal(job)
            if terminal_workflows_only and not terminal_workflow:
                if include_missing_jobs and parent_missing:
                    pass
                else:
                    skipped.append(
                        {
                            "worker_id": int(worker.get("worker_id") or 0),
                            "job_id": job_id,
                            "reason": "parent_job_not_terminal_workflow",
                            "parent_job_status": job_status,
                            "parent_job_stage": job_stage,
                        }
                    )
                    continue

            if parent_job_statuses and job_status not in parent_job_statuses:
                skipped.append(
                    {
                        "worker_id": int(worker.get("worker_id") or 0),
                        "job_id": job_id,
                        "reason": "parent_job_status_filtered",
                        "parent_job_status": job_status,
                        "parent_job_stage": job_stage,
                    }
                )
                continue

            cleanup_status = override_status or ("superseded" if job_status == "superseded" else "cancelled")
            candidates.append(
                {
                    "worker_id": int(worker.get("worker_id") or 0),
                    "job_id": job_id,
                    "lane_id": str(worker.get("lane_id") or ""),
                    "worker_key": str(worker.get("worker_key") or ""),
                    "worker_status": str(worker.get("status") or ""),
                    "wait_stage": str(worker.get("wait_stage") or ""),
                    "updated_at": str(worker.get("updated_at") or ""),
                    "parent_job_type": job_type,
                    "parent_job_status": job_status,
                    "parent_job_stage": job_stage,
                    "target_company": target_company,
                    "cleanup_status": cleanup_status,
                    "cleanup_reason": reason,
                }
            )

        if dry_run:
            return {
                "status": "preview",
                "candidate_count": len(candidates),
                "skipped_count": len(skipped),
                "candidates": candidates,
                "skipped": skipped[:50],
            }

        retired_results: list[dict[str, Any]] = []
        grouped_worker_ids: dict[str, list[int]] = {}
        for candidate in candidates:
            grouped_worker_ids.setdefault(str(candidate["cleanup_status"]), []).append(int(candidate["worker_id"]))

        retired_by_worker_id: dict[int, dict[str, Any]] = {}
        for cleanup_status, worker_ids in grouped_worker_ids.items():
            retired_workers = self.store.retire_agent_workers(
                worker_ids=worker_ids,
                status=cleanup_status,
                reason=reason,
                cleanup_metadata={"source": "recoverable_worker_cleanup"},
            )
            for worker in retired_workers:
                retired_by_worker_id[int(worker.get("worker_id") or 0)] = worker

        for candidate in candidates:
            worker_id = int(candidate["worker_id"])
            retired = retired_by_worker_id.get(worker_id)
            if retired is None:
                retired_results.append({**candidate, "cleanup_result": "not_found"})
                continue
            retired_results.append(
                {
                    **candidate,
                    "cleanup_result": "retired",
                    "final_worker_status": str(retired.get("status") or ""),
                }
            )

        runtime_metrics = self._refresh_runtime_metrics_snapshot(source="cleanup_recoverable_workers")
        return {
            "status": "completed",
            "retired_count": len([item for item in retired_results if item.get("cleanup_result") == "retired"]),
            "skipped_count": len(skipped),
            "results": retired_results,
            "skipped": skipped[:50],
            "runtime_metrics": {
                "status": str(runtime_metrics.get("status") or ""),
                "observed_at": str(runtime_metrics.get("observed_at") or ""),
                "metrics": dict(runtime_metrics.get("metrics") or {}),
            },
        }

    def _workflow_recovery_settings(self, payload: dict[str, Any]) -> dict[str, Any]:
        return {
            "workflow_stale_scope_job_id": str(payload.get("workflow_stale_scope_job_id") or ""),
            "workflow_resume_explicit_job": _coerce_bool(
                payload.get("workflow_resume_explicit_job"),
                True,
            ),
            "workflow_resume_stale_after_seconds": _coerce_int(
                payload.get("workflow_resume_stale_after_seconds"),
                _env_int("WORKFLOW_AUTO_RESUME_STALE_SECONDS", 60),
            ),
            "workflow_resume_limit": _coerce_int(
                payload.get("workflow_resume_limit"),
                _env_int("WORKFLOW_AUTO_RESUME_LIMIT", 50),
            ),
            "workflow_auto_resume_enabled": _coerce_bool(
                payload.get("workflow_auto_resume_enabled"),
                _env_bool("WORKFLOW_AUTO_RESUME_ENABLED", True),
            ),
            "workflow_queue_resume_stale_after_seconds": _coerce_int(
                payload.get("workflow_queue_resume_stale_after_seconds"),
                _env_int("WORKFLOW_QUEUE_AUTO_TAKEOVER_STALE_SECONDS", 60),
            ),
            "workflow_queue_resume_limit": _coerce_int(
                payload.get("workflow_queue_resume_limit"),
                _env_int("WORKFLOW_QUEUE_AUTO_TAKEOVER_LIMIT", 50),
            ),
            "workflow_queue_auto_takeover_enabled": _coerce_bool(
                payload.get("workflow_queue_auto_takeover_enabled"),
                _env_bool("WORKFLOW_QUEUE_AUTO_TAKEOVER_ENABLED", True),
            ),
        }

    def _resume_workflows_after_recovery_summary(
        self,
        summary: dict[str, Any],
        *,
        explicit_job_id: str,
        settings: dict[str, Any],
        skip_job_ids: set[str] | None = None,
    ) -> list[dict[str, Any]]:
        return self._resume_blocked_workflows_after_recovery(
            summary,
            explicit_job_id=explicit_job_id if bool(settings.get("workflow_resume_explicit_job")) else "",
            stale_job_scope_job_id=str(settings.get("workflow_stale_scope_job_id") or ""),
            include_stale_acquiring=bool(settings.get("workflow_auto_resume_enabled")),
            stale_after_seconds=_coerce_int(settings.get("workflow_resume_stale_after_seconds"), 60),
            resume_limit=_coerce_int(settings.get("workflow_resume_limit"), 50),
            include_stale_queued=bool(settings.get("workflow_queue_auto_takeover_enabled")),
            queued_stale_after_seconds=_coerce_int(settings.get("workflow_queue_resume_stale_after_seconds"), 60),
            queued_resume_limit=_coerce_int(settings.get("workflow_queue_resume_limit"), 50),
            skip_job_ids=skip_job_ids,
        )

    def _run_remote_event_followup_rounds(
        self,
        *,
        payload: dict[str, Any],
        summary: dict[str, Any],
        workflow_resume: list[dict[str, Any]],
        post_completion_reconcile: list[dict[str, Any]],
        explicit_job_id: str,
        explicit_job_followup_rounds: int,
        recovery_stale_after_seconds: int,
        workflow_recovery_settings: dict[str, Any],
        skip_workflow_resume_job_ids: set[str] | None = None,
    ) -> tuple[dict[str, Any], list[dict[str, Any]], list[dict[str, Any]], dict[str, Any]]:
        if explicit_job_id.strip() and explicit_job_followup_rounds > 0:
            return (
                summary,
                workflow_resume,
                post_completion_reconcile,
                {"status": "skipped", "reason": "explicit_job_followup_handles_job_scope"},
            )
        if not _coerce_bool(
            payload.get("remote_event_followup_enabled"),
            _env_bool("WORKFLOW_REMOTE_EVENT_FOLLOWUP_ENABLED", True),
        ):
            return (
                summary,
                workflow_resume,
                post_completion_reconcile,
                {"status": "skipped", "reason": "remote_event_followup_disabled"},
            )
        max_rounds = max(
            0,
            _coerce_int(
                payload.get("remote_event_followup_rounds"),
                _env_int("WORKFLOW_REMOTE_EVENT_FOLLOWUP_ROUNDS", 1),
            ),
        )
        if max_rounds <= 0:
            return (
                summary,
                workflow_resume,
                post_completion_reconcile,
                {"status": "skipped", "reason": "remote_event_followup_rounds_zero"},
            )
        try:
            sleep_seconds = max(0.0, float(payload.get("remote_event_followup_sleep_seconds") or 0.0))
        except (TypeError, ValueError):
            sleep_seconds = 0.0
        enabled_lanes = _remote_event_followup_enabled_lanes(payload)
        recovery_daemon_limit = max(10, int(payload.get("total_limit") or 4) * 10)
        recovery_owner_id = str(summary.get("owner_id") or payload.get("owner_id") or "").strip()
        rounds: list[dict[str, Any]] = []
        for round_index in range(max_rounds):
            recoverable_workers = self.store.list_recoverable_agent_workers(
                limit=recovery_daemon_limit,
                stale_after_seconds=recovery_stale_after_seconds,
                job_id=explicit_job_id,
            )
            targets = collect_remote_event_followup_targets(
                recoverable_workers,
                enabled_lanes=enabled_lanes,
            )
            target_job_ids = [
                str(item or "").strip() for item in list(targets.get("job_ids") or []) if str(item).strip()
            ]
            if not target_job_ids:
                break
            target_worker_ids_by_job = {
                str(job_key or "").strip(): [
                    _coerce_int(worker_id, 0)
                    for worker_id in list(worker_ids or [])
                    if _coerce_int(worker_id, 0) > 0
                ]
                for job_key, worker_ids in dict(targets.get("worker_ids_by_job") or {}).items()
                if str(job_key or "").strip()
            }
            if sleep_seconds > 0:
                time.sleep(sleep_seconds)
            round_summaries: list[dict[str, Any]] = []
            round_claimed = 0
            round_executed = 0
            for job_id in target_job_ids:
                target_worker_ids_for_job = list(target_worker_ids_by_job.get(job_id) or [])
                followup_payload = dict(payload)
                followup_payload["job_id"] = job_id
                if target_worker_ids_for_job:
                    followup_payload["explicit_worker_ids"] = target_worker_ids_for_job
                    followup_payload["force_release_explicit_worker_leases"] = True
                    followup_payload["total_limit"] = max(1, min(
                        _coerce_int(payload.get("total_limit"), 4),
                        len(target_worker_ids_for_job),
                    ))
                if recovery_owner_id:
                    followup_payload["owner_id"] = recovery_owner_id
                followup_daemon = self._build_worker_recovery_daemon(followup_payload)
                followup_summary = followup_daemon.run_once()
                summary = self._merge_worker_recovery_daemon_summaries(summary, followup_summary)
                round_claimed += int(followup_summary.get("claimed_count") or 0)
                round_executed += int(followup_summary.get("executed_count") or 0)
                round_summaries.append(
                    {
                        "job_id": job_id,
                        "target_worker_ids": target_worker_ids_for_job,
                        "claimed_count": int(followup_summary.get("claimed_count") or 0),
                        "executed_count": int(followup_summary.get("executed_count") or 0),
                    }
                )
            rounds.append(
                {
                    "round": round_index + 1,
                    "target_worker_count": int(targets.get("worker_count") or 0),
                    "target_worker_ids": list(targets.get("worker_ids") or []),
                    "target_job_ids": target_job_ids,
                    "lane_counts": dict(targets.get("lane_counts") or {}),
                    "recovery_kind_counts": dict(targets.get("recovery_kind_counts") or {}),
                    "claimed_count": round_claimed,
                    "executed_count": round_executed,
                    "jobs": round_summaries,
                }
            )
            if round_claimed <= 0 and round_executed <= 0:
                break
        if not rounds:
            return (
                summary,
                workflow_resume,
                post_completion_reconcile,
                {"status": "skipped", "reason": "no_remote_event_followup_targets"},
            )
        summary["remote_event_followup_rounds_executed"] = int(
            summary.get("remote_event_followup_rounds_executed") or 0
        ) + len(rounds)
        observed_lanes = sorted(
            {
                str(lane or "").strip()
                for round_payload in rounds
                for lane in dict(round_payload.get("lane_counts") or {}).keys()
                if str(lane or "").strip()
            }
        )
        return (
            summary,
            workflow_resume,
            post_completion_reconcile,
            {
                "status": "completed",
                "round_count": len(rounds),
                "scope": ",".join(observed_lanes) if observed_lanes else "remote_event_registry",
                "enabled_lanes": sorted(enabled_lanes),
                "rounds": rounds,
            },
        )

    def handle_remote_provider_event(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = dict(payload or {})
        recovery_mode = str(
            payload.get("recovery_mode")
            or payload.get("remote_provider_event_recovery_mode")
            or "job_scoped_recovery"
        ).strip().lower()
        inline_recovery = recovery_mode in {"inline", "sync", "sync_recovery", "direct", "direct_recovery"}
        event = normalize_remote_provider_event(payload, provider=str(payload.get("provider") or "apify"))
        local_event_seen_at = _utc_now_iso()
        remote_completed_at = str(event.get("remote_completed_at") or "").strip()
        remote_to_local_event_lag_ms = _milliseconds_between_iso(remote_completed_at, local_event_seen_at)
        actor_run_duration_ms = _milliseconds_between_iso(
            str(event.get("run_started_at") or "").strip(),
            str(event.get("run_finished_at") or "").strip(),
        )
        event_metrics = {
            "source": str(payload.get("source") or "provider_webhook").strip() or "provider_webhook",
            "remote_completed_at": remote_completed_at,
            "local_event_seen_at": local_event_seen_at,
            "remote_to_local_event_lag_ms": remote_to_local_event_lag_ms,
        }
        if actor_run_duration_ms is not None:
            event_metrics["actor_run_duration_ms"] = actor_run_duration_ms
        if not str(event.get("run_id") or "").strip() and not str(event.get("dataset_id") or "").strip():
            return {
                "status": "invalid",
                "reason": "remote_provider_event_missing_run_or_dataset_id",
                "event": event,
                "event_metrics": event_metrics,
            }
        scan_limit = max(25, min(_coerce_int(payload.get("worker_scan_limit"), 500), 2000))
        recoverable_workers = self.store.list_recoverable_agent_workers(
            limit=scan_limit,
            stale_after_seconds=0,
        )
        duplicate_terminal_workers: list[dict[str, Any]] = []
        actionable_recoverable_workers: list[dict[str, Any]] = []
        for worker in [dict(item) for item in list(recoverable_workers or []) if isinstance(item, dict)]:
            if (
                bool(event.get("is_terminal"))
                and _worker_has_remote_provider_terminal_event(worker)
                and remote_provider_event_matches_worker(event, worker)
                and remote_event_lane_for_worker(worker) == "linkedin_stage_1"
            ):
                duplicate_terminal_workers.append(worker)
                continue
            actionable_recoverable_workers.append(worker)
        targets = collect_remote_provider_event_targets(
            actionable_recoverable_workers,
            event,
            enabled_lanes={"linkedin_stage_1"},
            lane_resolver=remote_event_lane_for_worker,
        )
        target_job_ids = [str(item or "").strip() for item in list(targets.get("job_ids") or []) if str(item).strip()]
        if not target_job_ids and duplicate_terminal_workers:
            duplicate_job_ids: list[str] = []
            duplicate_worker_ids: list[int] = []
            duplicate_status_counts: dict[str, int] = {}
            duplicate_lane_counts: dict[str, int] = {}
            for worker in duplicate_terminal_workers:
                job_id = str(worker.get("job_id") or "").strip()
                worker_id = _coerce_int(worker.get("worker_id"), 0)
                status = str(worker.get("status") or "").strip().lower() or "unknown"
                lane = str(remote_event_lane_for_worker(worker) or "").strip()
                if job_id and job_id not in duplicate_job_ids:
                    duplicate_job_ids.append(job_id)
                if worker_id > 0 and worker_id not in duplicate_worker_ids:
                    duplicate_worker_ids.append(worker_id)
                duplicate_status_counts[status] = int(duplicate_status_counts.get(status) or 0) + 1
                if lane:
                    duplicate_lane_counts[lane] = int(duplicate_lane_counts.get(lane) or 0) + 1
            released_provider_limiter_worker_ids = _release_remote_provider_terminal_limiter_slots(
                self.store,
                worker_ids=duplicate_worker_ids,
                event_metrics=event_metrics,
            )
            duplicate_targets = {
                "job_ids": duplicate_job_ids,
                "worker_ids": duplicate_worker_ids,
                "worker_count": len(duplicate_worker_ids),
                "lane_counts": duplicate_lane_counts,
                "status_counts": duplicate_status_counts,
                "source": "recoverable_workers_with_terminal_event_marker",
            }
            for job_id in duplicate_job_ids:
                self.store.append_job_event(
                    job_id,
                    "remote_provider_event",
                    "received_in_flight",
                    (
                        "Received duplicate remote provider terminal event after the same remote run "
                        "was already marked locally; no new recovery was started."
                    ),
                    {
                        "event": {key: value for key, value in event.items() if key != "raw_payload"},
                        "target_worker_ids": duplicate_worker_ids,
                        "status_counts": duplicate_status_counts,
                        "released_provider_limiter_worker_ids": released_provider_limiter_worker_ids,
                        "event_metrics": event_metrics,
                    },
                )
            return {
                "status": "accepted",
                "reason": "remote_provider_terminal_event_already_recorded",
                "event": event,
                "event_metrics": event_metrics,
                "targets": duplicate_targets,
                "recovery_count": 0,
                "recoveries": [],
                "recovery_dispatch_count": 0,
                "recovery_dispatches": [],
                "released_provider_limiter_worker_ids": released_provider_limiter_worker_ids,
            }
        if not target_job_ids:
            known_workers: list[dict[str, Any]] = []
            list_known_workers = getattr(self.store, "list_agent_workers_by_remote_provider_identifiers", None)
            if callable(list_known_workers):
                known_workers = [
                    dict(worker)
                    for worker in list(
                        list_known_workers(
                            run_id=str(event.get("run_id") or ""),
                            dataset_id=str(event.get("dataset_id") or ""),
                            limit=scan_limit,
                        )
                        or []
                    )
                ]
            known_job_ids: list[str] = []
            known_worker_ids: list[int] = []
            known_status_counts: dict[str, int] = {}
            known_lane_counts: dict[str, int] = {}
            wake_job_ids: list[str] = []
            wake_worker_ids: list[int] = []
            wake_status_counts: dict[str, int] = {}
            wake_lane_counts: dict[str, int] = {}
            in_flight_job_ids: list[str] = []
            in_flight_worker_ids: list[int] = []
            in_flight_status_counts: dict[str, int] = {}
            in_flight_lane_counts: dict[str, int] = {}
            for worker in known_workers:
                event_lane = remote_event_lane_for_known_provider_worker(worker)
                if event_lane != "linkedin_stage_1":
                    continue
                job_id = str(worker.get("job_id") or "").strip()
                worker_id = int(worker.get("worker_id") or 0)
                status = str(worker.get("status") or "").strip().lower() or "unknown"
                if job_id and job_id not in known_job_ids:
                    known_job_ids.append(job_id)
                if worker_id > 0:
                    known_worker_ids.append(worker_id)
                known_status_counts[status] = int(known_status_counts.get(status) or 0) + 1
                known_lane_counts[event_lane] = int(known_lane_counts.get(event_lane) or 0) + 1
                if bool(event.get("is_terminal")) and status != "completed":
                    if _worker_has_remote_provider_terminal_event(worker):
                        if job_id and job_id not in in_flight_job_ids:
                            in_flight_job_ids.append(job_id)
                        if worker_id > 0 and worker_id not in in_flight_worker_ids:
                            in_flight_worker_ids.append(worker_id)
                        in_flight_status_counts[status] = int(in_flight_status_counts.get(status) or 0) + 1
                        in_flight_lane_counts[event_lane] = int(in_flight_lane_counts.get(event_lane) or 0) + 1
                        continue
                    if job_id and job_id not in wake_job_ids:
                        wake_job_ids.append(job_id)
                    if worker_id > 0 and worker_id not in wake_worker_ids:
                        wake_worker_ids.append(worker_id)
                    wake_status_counts[status] = int(wake_status_counts.get(status) or 0) + 1
                    wake_lane_counts[event_lane] = int(wake_lane_counts.get(event_lane) or 0) + 1
            if wake_job_ids:
                targets = {
                    "job_ids": wake_job_ids,
                    "worker_ids": wake_worker_ids,
                    "worker_count": len(wake_worker_ids),
                    "lane_counts": wake_lane_counts,
                    "status_counts": wake_status_counts,
                    "source": "known_remote_provider_workers",
                }
                target_job_ids = list(wake_job_ids)
            elif in_flight_job_ids:
                in_flight_targets = {
                    "job_ids": in_flight_job_ids,
                    "worker_ids": in_flight_worker_ids,
                    "worker_count": len(in_flight_worker_ids),
                    "lane_counts": in_flight_lane_counts,
                    "status_counts": in_flight_status_counts,
                    "source": "known_remote_provider_workers_in_flight",
                }
                if bool(event.get("is_terminal")):
                    released_provider_limiter_worker_ids = _release_remote_provider_terminal_limiter_slots(
                        self.store,
                        worker_ids=in_flight_worker_ids,
                        event_metrics=event_metrics,
                    )
                else:
                    released_provider_limiter_worker_ids = []
                for job_id in in_flight_job_ids:
                    self.store.append_job_event(
                        job_id,
                        "remote_provider_event",
                        "received_in_flight",
                        (
                            "Received duplicate remote provider event while matching worker recovery "
                            "already holds an active lease; no new recovery was started."
                        ),
                        {
                            "event": {key: value for key, value in event.items() if key != "raw_payload"},
                            "target_worker_ids": in_flight_worker_ids,
                            "status_counts": in_flight_status_counts,
                            "released_provider_limiter_worker_ids": released_provider_limiter_worker_ids,
                            "event_metrics": event_metrics,
                        },
                    )
                return {
                    "status": "accepted",
                    "reason": "remote_provider_event_recovery_already_in_flight",
                    "event": event,
                    "event_metrics": event_metrics,
                    "targets": in_flight_targets,
                    "recovery_count": 0,
                    "recoveries": [],
                    "released_provider_limiter_worker_ids": released_provider_limiter_worker_ids,
                }
            elif known_job_ids:
                late_targets = {
                    "job_ids": known_job_ids,
                    "worker_ids": known_worker_ids,
                    "worker_count": len(known_worker_ids),
                    "lane_counts": known_lane_counts,
                    "status_counts": known_status_counts,
                }
                for job_id in known_job_ids:
                    self.store.append_job_event(
                        job_id,
                        "remote_provider_event",
                        "received_late",
                        (
                            "Received remote provider event after matching worker was no longer recoverable; "
                            "no recovery was started."
                        ),
                        {
                            "event": {key: value for key, value in event.items() if key != "raw_payload"},
                            "target_worker_ids": known_worker_ids,
                            "status_counts": known_status_counts,
                            "event_metrics": event_metrics,
                        },
                    )
                return {
                    "status": "accepted",
                    "reason": "matching_remote_provider_workers_not_recoverable",
                    "event": event,
                    "event_metrics": event_metrics,
                    "targets": late_targets,
                    "recovery_count": 0,
                    "recoveries": [],
                }
            else:
                return {
                    "status": "accepted",
                    "reason": "no_matching_remote_wait_workers",
                    "event": event,
                    "event_metrics": event_metrics,
                    "targets": targets,
                }
        owner_id = (
            str(payload.get("owner_id") or "").strip()
            or f"remote-provider-event-{str(event.get('provider') or 'provider')}-{uuid.uuid4().hex[:8]}"
        )
        target_worker_ids = [
            _coerce_int(worker_id, 0)
            for worker_id in list(targets.get("worker_ids") or [])
            if _coerce_int(worker_id, 0) > 0
        ]
        remote_event_recovery_total_limit = _remote_provider_event_recovery_total_limit(
            payload.get("remote_provider_event_recovery_total_limit"),
            payload.get("job_recovery_total_limit"),
        )
        if bool(event.get("is_terminal")):
            _mark_remote_provider_terminal_event_on_workers(
                self.store,
                worker_ids=target_worker_ids,
                event=event,
                event_metrics=event_metrics,
            )
            released_provider_limiter_worker_ids = _release_remote_provider_terminal_limiter_slots(
                self.store,
                worker_ids=target_worker_ids,
                event_metrics=event_metrics,
            )
            released_worker_ids = _release_remote_provider_event_worker_leases(
                self.store,
                worker_ids=target_worker_ids,
            )
        else:
            released_provider_limiter_worker_ids = []
            released_worker_ids = []
        recoveries: list[dict[str, Any]] = []
        recovery_dispatches: list[dict[str, Any]] = []
        for job_id in target_job_ids:
            self.store.append_job_event(
                job_id,
                "remote_provider_event",
                "received",
                f"Received remote provider event for run {event.get('run_id') or event.get('dataset_id')}.",
                {
                    "event": {key: value for key, value in event.items() if key != "raw_payload"},
                    "target_worker_ids": target_worker_ids,
                    "released_worker_ids": released_worker_ids,
                    "released_provider_limiter_worker_ids": released_provider_limiter_worker_ids,
                    "status_counts": dict(targets.get("status_counts") or {}),
                    "target_source": str(targets.get("source") or "recoverable_agent_workers"),
                    "event_metrics": event_metrics,
                },
            )
            recovery_payload = {
                "job_id": job_id,
                "owner_id": owner_id,
                "stale_after_seconds": 0,
                "total_limit": remote_event_recovery_total_limit,
                "explicit_job_followup_rounds": _coerce_int(payload.get("explicit_job_followup_rounds"), 1),
                "search_seed_discovery_enabled": False,
                "post_completion_reconcile_enabled": True,
                "post_recovery_housekeeping_enabled": False,
                "profile_prefetch_refill_enabled": True,
                "remote_event_followup_enabled": False,
                "snapshot_full_materialization_enabled": False,
                "excel_intake_recovery_enabled": False,
                "workflow_auto_resume_enabled": True,
                "workflow_queue_auto_takeover_enabled": False,
                "workflow_queue_resume_stale_after_seconds": 0,
                "workflow_stale_scope_job_id": job_id,
                "explicit_worker_ids": target_worker_ids,
                "force_release_explicit_worker_leases": True,
                "profile_prefetch_refill_before_worker_recovery": True,
            }
            if inline_recovery:
                recovery = self.run_worker_recovery_once(recovery_payload)
                recoveries.append(
                    {
                        "job_id": job_id,
                        "daemon": dict(recovery.get("daemon") or {}),
                        "workflow_resume": list(recovery.get("workflow_resume") or []),
                        "post_completion_reconcile": list(recovery.get("post_completion_reconcile") or []),
                    }
                )
            else:
                dispatch_payload = {
                    "source": "remote_provider_event",
                    "auto_job_daemon": True,
                    "recovery_bootstrap_enabled": False,
                    "explicit_worker_ids": target_worker_ids,
                    "force_release_explicit_worker_leases": True,
                    "profile_prefetch_nonblocking_submit": True,
                    "profile_prefetch_refill_enabled": True,
                    "profile_prefetch_refill_before_worker_recovery": True,
                    "remote_event_followup_enabled": False,
                    "search_seed_discovery_enabled": False,
                    "snapshot_full_materialization_enabled": False,
                    "excel_intake_recovery_enabled": False,
                    "post_recovery_housekeeping_enabled": False,
                    "workflow_auto_resume_enabled": True,
                    "workflow_queue_auto_takeover_enabled": False,
                    "job_recovery_poll_seconds": max(
                        0.5,
                        float(payload.get("job_recovery_poll_seconds") or 0.5),
                    ),
                    "job_recovery_max_ticks": max(1, _coerce_int(payload.get("job_recovery_max_ticks"), 900)),
                    "job_recovery_idle_stop_ticks": max(1, _coerce_int(payload.get("job_recovery_idle_stop_ticks"), 3)),
                    "job_recovery_stale_after_seconds": 0,
                    "job_recovery_total_limit": remote_event_recovery_total_limit,
                    "workflow_queue_resume_stale_after_seconds": 0,
                    "workflow_stale_scope_job_id": job_id,
                    "remote_provider_event_worker_ids": target_worker_ids,
                    "remote_provider_event_owner_id": owner_id,
                }
                dispatch = self.ensure_job_scoped_recovery(job_id, dispatch_payload)
                recovery_service_name = str(dict(dispatch or {}).get("service_name") or "").strip()
                if not recovery_service_name:
                    try:
                        recovery_service_name = str(
                            _build_job_scoped_recovery_config(job_id, dispatch_payload).get("service_name") or ""
                        ).strip()
                    except Exception:
                        recovery_service_name = f"job-recovery-{job_id}"
                wakeup = request_service_wakeup(
                    self.runtime_dir,
                    recovery_service_name,
                    reason="remote_provider_event",
                    requested_by=owner_id,
                    callback_payload={
                        "source": "remote_provider_event",
                        "explicit_worker_ids": target_worker_ids,
                        "remote_provider_event_worker_ids": target_worker_ids,
                        "force_release_explicit_worker_leases": True,
                        "total_limit": remote_event_recovery_total_limit,
                        "profile_prefetch_nonblocking_submit": True,
                        "profile_prefetch_refill_enabled": True,
                        "profile_prefetch_refill_before_worker_recovery": True,
                        "remote_event_followup_enabled": False,
                        "search_seed_discovery_enabled": False,
                        "snapshot_full_materialization_enabled": False,
                        "excel_intake_recovery_enabled": False,
                        "post_recovery_housekeeping_enabled": False,
                        "workflow_auto_resume_enabled": True,
                        "workflow_queue_auto_takeover_enabled": False,
                        "workflow_queue_resume_stale_after_seconds": 0,
                        "workflow_stale_scope_job_id": job_id,
                        "remote_provider_event_owner_id": owner_id,
                    },
                )
                recovery_dispatches.append({"job_id": job_id, **dict(dispatch or {})})
                if recovery_dispatches:
                    recovery_dispatches[-1]["wakeup"] = wakeup
        return {
            "status": "accepted",
            "event": event,
            "event_metrics": event_metrics,
            "targets": targets,
            "recovery_count": len(recoveries),
            "recoveries": recoveries,
            "recovery_dispatch_count": len(recovery_dispatches),
            "recovery_dispatches": recovery_dispatches,
            "mode": "sync_recovery" if inline_recovery else "job_scoped_recovery",
            "released_worker_ids": released_worker_ids,
            "released_provider_limiter_worker_ids": released_provider_limiter_worker_ids,
        }

    def repair_dead_local_recovery_leases(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = dict(payload or {})
        explicit_job_id = str(payload.get("job_id") or "").strip()
        source = str(payload.get("source") or "recovery_tick_preflight").strip() or "recovery_tick_preflight"
        scan_limit = max(1, min(_coerce_int(payload.get("limit"), 500), 5000))
        if explicit_job_id:
            job_payload = self.store.get_job(explicit_job_id)
            jobs = [dict(job_payload)] if job_payload else []
        else:
            jobs = list(
                self.store.list_jobs(
                    job_type="workflow",
                    statuses=["queued", "running", "blocked", "completed"],
                    limit=scan_limit,
                )
                or []
            )

        repaired_worker_ids: list[int] = []
        released_workflow_job_ids: list[str] = []
        skipped_runtime_namespace_count = 0

        for job in jobs:
            job_id = str(dict(job or {}).get("job_id") or "").strip()
            if not job_id:
                continue
            artifact_path = str(dict(job or {}).get("artifact_path") or "").strip()
            if artifact_path and not runtime_namespace_ownership_for_path(
                artifact_path,
                configured_runtime_dir=self.runtime_dir,
            ).matches:
                skipped_runtime_namespace_count += 1
                continue

            lease = dict(self.store.get_workflow_job_lease(job_id) or {})
            workflow_owner = str(lease.get("lease_owner") or "").strip()
            if workflow_owner and workflow_job_lease_owner_is_dead_local_process(workflow_owner):
                self.store.release_workflow_job_lease(
                    job_id,
                    lease_owner=workflow_owner,
                    lease_token=str(lease.get("lease_token") or "").strip(),
                )
                released_workflow_job_ids.append(job_id)
                self.store.append_job_event(
                    job_id,
                    "runtime_control",
                    "recovered",
                    "Released workflow job lease held by a dead local recovery owner.",
                    {
                        "event_family": "dead_local_recovery_lease_repair",
                        "source": source,
                        "lease_owner": workflow_owner,
                        "lease_token": str(lease.get("lease_token") or "").strip(),
                    },
                )

            for worker in list(self.store.list_agent_workers(job_id=job_id) or []):
                worker_payload = dict(worker or {})
                worker_id = _coerce_int(worker_payload.get("worker_id"), 0)
                if worker_id <= 0:
                    continue
                lease_owner = str(worker_payload.get("lease_owner") or "").strip()
                if not lease_owner or not worker_lease_owner_is_dead_local_process(lease_owner):
                    continue
                if self._runtime_namespace_mismatch_for_durable_payload(
                    {
                        "job_id": job_id,
                        "metadata": dict(worker_payload.get("metadata") or {}),
                        "checkpoint": dict(worker_payload.get("checkpoint") or {}),
                        "output": dict(worker_payload.get("output") or {}),
                    }
                ):
                    skipped_runtime_namespace_count += 1
                    continue
                released = self.store.release_agent_worker_lease(
                    worker_id,
                    lease_owner=lease_owner,
                    error_text=f"Released dead local recovery lease owner {lease_owner}",
                )
                if released is not None:
                    repaired_worker_ids.append(worker_id)

        if repaired_worker_ids:
            job_ids = sorted(
                {
                    str(dict(self.store.get_agent_worker(worker_id=worker_id) or {}).get("job_id") or "").strip()
                    for worker_id in repaired_worker_ids
                }
                - {""}
            )
            for job_id in job_ids:
                self.store.append_job_event(
                    job_id,
                    "runtime_control",
                    "recovered",
                    "Released agent worker leases held by dead local recovery owners.",
                    {
                        "event_family": "dead_local_recovery_lease_repair",
                        "source": source,
                        "worker_ids": repaired_worker_ids,
                    },
                )

        repaired_count = len(repaired_worker_ids) + len(released_workflow_job_ids)
        return {
            "status": "active" if repaired_count > 0 else "idle",
            "reason": "dead_local_recovery_leases_released" if repaired_count > 0 else "no_dead_local_recovery_leases",
            "source": source,
            "worker_lease_released_count": len(repaired_worker_ids),
            "workflow_job_lease_released_count": len(released_workflow_job_ids),
            "repaired_count": repaired_count,
            "worker_ids": repaired_worker_ids,
            "workflow_job_ids": released_workflow_job_ids,
            "skipped_runtime_namespace_count": skipped_runtime_namespace_count,
        }

    def run_worker_recovery_once(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = dict(payload or {})
        recovery_tick_started_at = _utc_now_iso()
        recovery_tick_started_monotonic = time.perf_counter()
        recovery_phase_metrics: dict[str, dict[str, Any]] = {}
        recovery_tick_total_budget_ms = max(
            0,
            _coerce_int(
                payload.get("recovery_tick_total_budget_ms"),
                _env_int("RECOVERY_TICK_TOTAL_BUDGET_MS", 30000),
            ),
        )
        recovery_tick_budget_exhausted = False
        durable_work_handoff_yield_requested = False

        def _recovery_tick_elapsed_ms() -> int:
            return int(max(0.0, (time.perf_counter() - recovery_tick_started_monotonic) * 1000))

        def _tick_budget_exhausted() -> bool:
            return recovery_tick_total_budget_ms > 0 and _recovery_tick_elapsed_ms() >= recovery_tick_total_budget_ms

        def _request_durable_work_handoff_yield() -> None:
            nonlocal durable_work_handoff_yield_requested
            durable_work_handoff_yield_requested = True

        def _phase_status(result: Any) -> tuple[str, str, dict[str, int]]:
            counts: dict[str, int] = {}
            if isinstance(result, dict):
                status = str(result.get("status") or "completed").strip() or "completed"
                reason = str(result.get("reason") or "").strip()
                for key in (
                    "item_count",
                    "group_count",
                    "claimed_count",
                    "completed_count",
                    "partial_count",
                    "failed_count",
                    "skipped_count",
                    "executed_count",
                    "recoverable_count",
                    "dispatched_url_count",
                    "queued_worker_count",
                    "deferred_url_count",
                    "recovered_count",
                    "repaired_count",
                    "worker_lease_released_count",
                    "workflow_job_lease_released_count",
                    "round_count",
                    "candidate_count",
                    "card_count",
                    "command_count",
                    "executed_command_count",
                    "recorded_count",
                    "planned_command_count",
                    "planned_worker_count",
                    "planned_url_count",
                    "inspected_count",
                    "converted_count",
                    "already_converted_count",
                    "unsupported_count",
                    "invalid_scope_count",
                    "open_unconverted_count",
                    "admitted_member_count",
                    "visible_member_count",
                ):
                    if key in result:
                        counts[key] = _coerce_int(result.get(key), 0)
                return status, reason, counts
            if isinstance(result, list):
                return "completed", "", {"item_count": len(result)}
            return "completed", "", {}

        def _run_recovery_phase(
            name: str,
            *,
            owner: str,
            max_sync_work: str,
            callback: Callable[[], Any],
            default_result: Any | None = None,
        ) -> Any:
            nonlocal recovery_tick_budget_exhausted
            if _tick_budget_exhausted():
                recovery_tick_budget_exhausted = True
                phase_started_at = _utc_now_iso()
                if default_result is None:
                    result = {"status": "skipped", "reason": "recovery_tick_budget_exhausted"}
                elif isinstance(default_result, dict):
                    result = {
                        "status": "skipped",
                        "reason": "recovery_tick_budget_exhausted",
                        **dict(default_result),
                    }
                    result["status"] = "skipped"
                    result["reason"] = "recovery_tick_budget_exhausted"
                else:
                    result = default_result
                status, reason, counts = _phase_status(result)
                recovery_phase_metrics[name] = {
                    "phase": name,
                    "owner": owner,
                    "max_sync_work": max_sync_work,
                    "started_at": phase_started_at,
                    "finished_at": _utc_now_iso(),
                    "elapsed_ms": 0,
                    "status": status if status != "completed" else "skipped",
                    "reason": reason or "recovery_tick_budget_exhausted",
                    "counts": counts,
                    "budget_exhausted": True,
                    "tick_elapsed_ms": _recovery_tick_elapsed_ms(),
                    "tick_total_budget_ms": recovery_tick_total_budget_ms,
                }
                return result
            phase_started_at = _utc_now_iso()
            phase_started_monotonic = time.perf_counter()
            try:
                result = callback()
            except Exception as exc:
                recovery_phase_metrics[name] = {
                    "phase": name,
                    "owner": owner,
                    "max_sync_work": max_sync_work,
                    "started_at": phase_started_at,
                    "finished_at": _utc_now_iso(),
                    "elapsed_ms": int(max(0.0, (time.perf_counter() - phase_started_monotonic) * 1000)),
                    "status": "failed",
                    "reason": f"{type(exc).__name__}: {exc}",
                    "counts": {},
                    "budget_exhausted": False,
                    "tick_elapsed_ms": _recovery_tick_elapsed_ms(),
                    "tick_total_budget_ms": recovery_tick_total_budget_ms,
                }
                raise
            else:
                phase_finished_at = _utc_now_iso()
                status, reason, counts = _phase_status(result)
                phase_crossed_tick_budget = _tick_budget_exhausted()
                if phase_crossed_tick_budget:
                    recovery_tick_budget_exhausted = True
                recovery_phase_metrics[name] = {
                    "phase": name,
                    "owner": owner,
                    "max_sync_work": max_sync_work,
                    "started_at": phase_started_at,
                    "finished_at": phase_finished_at,
                    "elapsed_ms": int(max(0.0, (time.perf_counter() - phase_started_monotonic) * 1000)),
                    "status": status,
                    "reason": reason or ("recovery_tick_budget_exhausted" if phase_crossed_tick_budget else ""),
                    "counts": counts,
                    "budget_exhausted": phase_crossed_tick_budget,
                    "tick_elapsed_ms": _recovery_tick_elapsed_ms(),
                    "tick_total_budget_ms": recovery_tick_total_budget_ms,
                }
                return result

        def _skipped_phase(name: str, *, owner: str, reason: str, max_sync_work: str) -> dict[str, Any]:
            skipped = {"status": "skipped", "reason": reason}
            recovery_phase_metrics[name] = {
                "phase": name,
                "owner": owner,
                "max_sync_work": max_sync_work,
                "started_at": _utc_now_iso(),
                "finished_at": _utc_now_iso(),
                "elapsed_ms": 0,
                "status": "skipped",
                "reason": reason,
                "counts": {},
                "budget_exhausted": False,
                "tick_elapsed_ms": _recovery_tick_elapsed_ms(),
                "tick_total_budget_ms": recovery_tick_total_budget_ms,
            }
            return skipped

        def _phase_work_observed(*results: Any) -> bool:
            for result in results:
                if isinstance(result, dict):
                    for key in (
                        "claimed_count",
                        "completed_count",
                        "failed_count",
                        "dispatched_url_count",
                        "queued_worker_count",
                        "executed_count",
                        "executed_command_count",
                        "recorded_count",
                        "planned_command_count",
                        "planned_worker_count",
                        "planned_url_count",
                        "converted_count",
                        "round_count",
                    ):
                        if _coerce_int(result.get(key), 0) > 0:
                            return True
                    continue
                if isinstance(result, list) and result:
                    return True
            return False

        def _profile_refill_owner_drain_payload(result: Any) -> dict[str, Any]:
            if not isinstance(result, dict):
                return {}
            direct = dict(result.get("profile_command_owner_drain") or {})
            if direct:
                return direct
            merged: dict[str, Any] = {}
            for group in list(result.get("groups") or []):
                if not isinstance(group, dict):
                    continue
                group_drain = dict(group.get("profile_command_owner_drain") or {})
                if not group_drain:
                    continue
                merged.setdefault("status", group_drain.get("status"))
                merged.setdefault("reason", group_drain.get("reason"))
                merged["command_count"] = _coerce_int(merged.get("command_count"), 0) + _coerce_int(
                    group_drain.get("command_count"),
                    0,
                )
                merged["executed_command_count"] = _coerce_int(
                    merged.get("executed_command_count"),
                    0,
                ) + _coerce_int(group_drain.get("executed_command_count"), 0)
                merged["dispatched_url_count"] = _coerce_int(
                    merged.get("dispatched_url_count"),
                    0,
                ) + _coerce_int(group_drain.get("dispatched_url_count"), 0)
                merged["queued_worker_count"] = _coerce_int(
                    merged.get("queued_worker_count"),
                    0,
                ) + _coerce_int(group_drain.get("queued_worker_count"), 0)
                merged["deferred_url_count"] = _coerce_int(
                    merged.get("deferred_url_count"),
                    0,
                ) + _coerce_int(group_drain.get("deferred_url_count"), 0)
            return merged

        def _worker_phase_handoff_required(result: Any) -> bool:
            """True when this recovery tick consumed worker terminal evidence.

            The worker-recovery owner may record terminal state and enqueue
            deterministic durable work, but it must not also perform the heavy
            local-apply / board-visible / full-materialization drains in the
            same tick. Yielding keeps recovery cooperative under long provider
            and large-shard pressure while preserving the slot-refill
            opportunity immediately after terminal workers are observed.
            """

            if not _coerce_bool(payload.get("defer_daemon_work_after_worker_recovery"), True):
                return False
            if not isinstance(result, dict):
                return False

            def _callback_requires_handoff(callback_result: Any) -> bool:
                if not isinstance(callback_result, dict):
                    return False
                callback_status = str(callback_result.get("status") or "").strip().lower()
                callback_reason = str(callback_result.get("reason") or "").strip().lower()
                if callback_status and callback_status not in {"skipped", "idle", "noop"}:
                    return True
                return callback_reason in {
                    "harvest_profile_terminal_without_materializable_payload",
                    "local_apply_closure_item_enqueued",
                }

            for job_summary in list(result.get("jobs") or []):
                if not isinstance(job_summary, dict):
                    continue
                callback_results = [
                    dict(item)
                    for item in list(job_summary.get("completion_callback_results") or [])
                    if isinstance(item, dict)
                ]
                if any(_callback_requires_handoff(item) for item in callback_results):
                    return True
                if callback_results:
                    # A remote-wait worker can be claimed and rechecked before its
                    # provider terminal event arrives. Its callback reports
                    # `worker_not_completed`; that poll must not suppress already
                    # ready board-visible work in this same recovery tick.
                    continue
                terminal_events = [
                    dict(item)
                    for item in list(job_summary.get("daemon_events") or [])
                    if isinstance(item, dict)
                ]
                if any(
                    str(item.get("status") or "").strip().lower()
                    in {"completed", "failed", "cancelled", "canceled"}
                    for item in terminal_events
                ):
                    return True
            return False

        def _phase_budget_yield_requested(value: Any) -> bool:
            if isinstance(value, dict):
                if bool(value.get("elapsed_budget_exhausted")) or bool(value.get("candidate_budget_exhausted")):
                    return True
                reason = str(value.get("reason") or "").strip()
                if reason.endswith("_budget_exhausted") or "phase_budget_exhausted" in reason:
                    return True
                for nested in value.values():
                    if _phase_budget_yield_requested(nested):
                        return True
                return False
            if isinstance(value, list):
                return any(_phase_budget_yield_requested(item) for item in value)
            return False

        def _merge_profile_refill_results(primary: Any, secondary: Any) -> dict[str, Any]:
            primary_payload = dict(primary or {}) if isinstance(primary, dict) else {}
            secondary_payload = dict(secondary or {}) if isinstance(secondary, dict) else {}
            if not primary_payload:
                return secondary_payload
            if not secondary_payload:
                return primary_payload
            merged = dict(secondary_payload)
            groups = list(primary_payload.get("groups") or []) + list(secondary_payload.get("groups") or [])
            if groups:
                merged["groups"] = groups
            selected_states = []
            for value in list(primary_payload.get("selected_refill_states") or []) + list(
                secondary_payload.get("selected_refill_states") or []
            ):
                normalized = str(value or "").strip()
                if normalized and normalized not in selected_states:
                    selected_states.append(normalized)
            if selected_states:
                merged["selected_refill_states"] = selected_states
            for key in (
                "group_count",
                "inspected_group_count",
                "active_group_count",
                "retry_wait_blocked_group_count",
                "dispatched_url_count",
                "queued_worker_count",
                "deferred_url_count",
                "planned_command_count",
                "planned_worker_count",
                "planned_url_count",
            ):
                merged[key] = _coerce_int(primary_payload.get(key), 0) + _coerce_int(
                    secondary_payload.get(key),
                    0,
                )
            for key in (
                "phase_budget_ms",
                "dispatch_worker_limit",
                "refill_item_limit",
                "refill_durable_unit_max_urls",
                "refill_provider_envelope_max_urls",
            ):
                primary_value = primary_payload.get(key)
                secondary_value = secondary_payload.get(key)
                if secondary_value not in (None, ""):
                    merged[key] = secondary_value
                elif primary_value not in (None, ""):
                    merged[key] = primary_value
            if "nonblocking_submit" in primary_payload or "nonblocking_submit" in secondary_payload:
                merged["nonblocking_submit"] = bool(
                    secondary_payload.get("nonblocking_submit", primary_payload.get("nonblocking_submit"))
                )
            status_values = {
                str(primary_payload.get("status") or "").strip().lower(),
                str(secondary_payload.get("status") or "").strip().lower(),
            }
            if "failed" in status_values:
                merged["status"] = "failed"
            elif _phase_work_observed(primary_payload, secondary_payload):
                merged["status"] = "active"
            elif "skipped" in status_values and len(status_values - {"", "skipped"}) == 0:
                merged["status"] = "skipped"
            else:
                merged["status"] = "idle"
            reasons = [
                str(primary_payload.get("reason") or "").strip(),
                str(secondary_payload.get("reason") or "").strip(),
            ]
            if str(primary_payload.get("status") or "").strip().lower() == "skipped" and reasons[0] in {
                "pre_worker_refill_not_requested",
                "job_scope_missing",
            }:
                reasons[0] = ""
            if str(secondary_payload.get("status") or "").strip().lower() == "skipped" and reasons[1] in {
                "post_worker_refill_not_requested",
                "job_scope_missing",
            }:
                reasons[1] = ""
            merged["reason"] = "+".join(reason for reason in reasons if reason) or str(
                merged.get("reason") or ""
            )
            merged["pre_worker_recovery"] = primary_payload
            merged["post_worker_recovery"] = secondary_payload
            return merged

        def _runtime_heartbeat_summary(value: Any) -> dict[str, Any]:
            if isinstance(value, dict):
                payload = dict(value)
                items = [dict(item) for item in list(payload.get("items") or []) if isinstance(item, dict)]
                payload["items"] = items
                payload["item_count"] = _coerce_int(payload.get("item_count"), len(items))
                payload.setdefault(
                    "emitted_count",
                    sum(1 for item in items if str(item.get("status") or "") == "emitted"),
                )
                payload.setdefault(
                    "skipped_count",
                    sum(1 for item in items if str(item.get("status") or "") == "skipped"),
                )
                payload.setdefault("status", "idle" if not items else "completed")
                payload.setdefault("reason", "")
                return payload
            items = [dict(item) for item in list(value or []) if isinstance(item, dict)] if isinstance(value, list) else []
            emitted_count = sum(1 for item in items if str(item.get("status") or "") == "emitted")
            skipped_count = sum(1 for item in items if str(item.get("status") or "") == "skipped")
            if emitted_count > 0:
                status = "active"
                reason = ""
            elif skipped_count > 0:
                status = "skipped"
                reason = str(next((item.get("reason") for item in items if item.get("reason")), "") or "")
            else:
                status = "idle"
                reason = "no_runtime_heartbeat_targets"
            return {
                "status": status,
                "reason": reason,
                "item_count": len(items),
                "emitted_count": emitted_count,
                "skipped_count": skipped_count,
                "items": items,
            }

        def _daemon_owned_workflow_resume_barrier(reason: str) -> dict[str, Any]:
            if not explicit_job_id.strip():
                return {}
            if not _coerce_bool(payload.get("workflow_resume_requires_daemon_quiescent"), True):
                return {}
            open_work = self._job_scoped_recovery_open_work_summary(job_id=explicit_job_id)
            daemon_owned_open_work_count = _coerce_int(open_work.get("daemon_owned_open_work_count"), 0)
            if daemon_owned_open_work_count <= 0:
                return {}
            return {
                "status": "blocked",
                "reason": reason,
                "job_id": explicit_job_id,
                "daemon_owned_open_work_count": daemon_owned_open_work_count,
                "open_work": open_work,
            }

        def _provider_control_open_work_summary() -> dict[str, Any]:
            if not explicit_job_id.strip():
                return {}
            open_work = self._job_scoped_recovery_open_work_summary(job_id=explicit_job_id)
            return {
                "pending_worker_count": _coerce_int(open_work.get("pending_worker_count"), 0),
                "profile_refill_open_item_count": _coerce_int(open_work.get("profile_refill_open_item_count"), 0),
                "profile_refill_state_counts": dict(open_work.get("profile_refill_state_counts") or {}),
                "job_recovery_open_work": open_work,
            }

        def _provider_control_work_is_open(open_work: dict[str, Any]) -> bool:
            if not open_work:
                return False
            return (
                _coerce_int(open_work.get("pending_worker_count"), 0) > 0
                or _coerce_int(open_work.get("profile_refill_open_item_count"), 0) > 0
            )

        def _provider_control_visibility_limits(
            open_work: dict[str, Any],
            *,
            local_apply_limit: int,
            board_visible_limit: int,
        ) -> tuple[int, int]:
            if not _provider_control_work_is_open(open_work):
                return max(1, local_apply_limit), max(1, board_visible_limit)
            return (
                max(1, min(max(1, local_apply_limit), _coerce_int(payload.get("provider_open_event_level_local_apply_limit"), 1))),
                max(1, min(max(1, board_visible_limit), _coerce_int(payload.get("provider_open_event_level_board_visible_limit"), 1))),
            )

        def _ready_board_visible_apply_item_exists() -> bool:
            if not explicit_job_id.strip():
                return False
            try:
                ready_items = self.store.list_ready_job_materialization_items(
                    job_id=explicit_job_id,
                    item_kind=_BOARD_VISIBLE_DELTA_APPLY_ITEM_KIND,
                    limit=1,
                )
            except Exception:
                return False
            return bool(ready_items)

        recovery_stale_after_seconds = _coerce_int(payload.get("stale_after_seconds"), 180)
        dead_local_recovery_lease_repair = _run_recovery_phase(
            "dead_local_recovery_lease_repair",
            owner="recovery_lease_repair",
            max_sync_work="release leases held by dead local recovery owner processes only",
            callback=lambda: self.repair_dead_local_recovery_leases(
                {
                    "job_id": str(payload.get("job_id") or "").strip(),
                    "source": "run_worker_recovery_once_preflight",
                    "limit": payload.get("dead_local_recovery_lease_repair_limit") or payload.get("total_limit") or 500,
                }
            ),
        )
        if _coerce_bool(payload.get("search_seed_discovery_enabled"), True):
            search_seed_discovery = _run_recovery_phase(
                "search_seed_discovery",
                owner="search_seed_discovery_query_queue",
                max_sync_work="bounded durable search-seed discovery items only",
                callback=lambda: self._run_search_seed_discovery_query_queue_once(payload),
            )
        else:
            search_seed_discovery = _skipped_phase(
                "search_seed_discovery",
                owner="search_seed_discovery_query_queue",
                reason="search_seed_discovery_disabled_by_payload",
                max_sync_work="no search-seed discovery work",
            )
        search_seed_resume_skip_job_ids: set[str] = set()
        if not _coerce_bool(payload.get("search_seed_discovery_allow_same_tick_workflow_resume"), False):
            search_seed_resume_skip_job_ids = self._search_seed_discovery_resume_skip_job_ids(search_seed_discovery)
        explicit_job_id = str(payload.get("job_id") or "").strip()
        profile_prefetch_refill_enabled = _coerce_bool(payload.get("profile_prefetch_refill_enabled"), True)
        profile_refill_submit_observed_this_tick = False
        profile_refill_command_planned_this_tick = False
        profile_refill_command_owner_enabled = _coerce_bool(
            payload.get("profile_refill_command_owner_enabled"),
            _env_bool("LINKEDIN_PROFILE_REFILL_COMMAND_OWNER_ENABLED", True),
        )
        profile_url_terminal_record_command_owner_enabled = _coerce_bool(
            payload.get("profile_url_terminal_record_command_owner_enabled"),
            _env_bool("LINKEDIN_PROFILE_URL_TERMINAL_RECORD_COMMAND_OWNER_ENABLED", True),
        )

        def _profile_refill_worker_submit_observed(result: Any) -> bool:
            if not isinstance(result, dict):
                return False
            owner_drain = _profile_refill_owner_drain_payload(result)
            return (
                _coerce_int(result.get("queued_worker_count"), 0) > 0
                or _coerce_int(result.get("dispatched_url_count"), 0) > 0
                or _coerce_int(owner_drain.get("queued_worker_count"), 0) > 0
                or _coerce_int(owner_drain.get("dispatched_url_count"), 0) > 0
            )

        def _profile_refill_command_planned_observed(result: Any) -> bool:
            if not isinstance(result, dict):
                return False
            return (
                _coerce_int(result.get("planned_command_count"), 0) > 0
                or _coerce_int(result.get("planned_worker_count"), 0) > 0
                or _coerce_int(result.get("planned_url_count"), 0) > 0
            )

        pre_worker_profile_prefetch_refill = {"status": "skipped", "reason": "pre_worker_refill_not_requested"}
        if (
            explicit_job_id
            and profile_prefetch_refill_enabled
            and _coerce_bool(payload.get("profile_prefetch_refill_before_worker_recovery"), False)
        ):
            pre_worker_profile_prefetch_refill = _run_recovery_phase(
                "pre_worker_profile_prefetch_refill",
                owner="profile_refill_daemon",
                max_sync_work=(
                    "remote-provider slot release handoff: registry scan/replan/claim/provider submit "
                    "before worker completion callbacks"
                ),
                callback=lambda: self._run_profile_prefetch_refill_queue_once(
                    {
                        **payload,
                        "profile_prefetch_refill_phase": "pre_worker_profile_prefetch_refill",
                    }
                ),
            )
        else:
            pre_worker_profile_prefetch_refill = _skipped_phase(
                "pre_worker_profile_prefetch_refill",
                owner="profile_refill_daemon",
                reason=(
                    "profile_prefetch_refill_disabled_by_payload"
                    if explicit_job_id and not profile_prefetch_refill_enabled
                    else "pre_worker_refill_not_requested"
                    if explicit_job_id
                    else "job_scope_missing"
                ),
                max_sync_work="no pre-worker profile refill",
            )
        profile_refill_submit_observed_this_tick = _profile_refill_worker_submit_observed(
            pre_worker_profile_prefetch_refill
        )
        profile_refill_command_planned_this_tick = _profile_refill_command_planned_observed(
            pre_worker_profile_prefetch_refill
        )
        daemon = self._build_worker_recovery_daemon(payload)
        summary = _run_recovery_phase(
            "worker_recovery",
            owner="worker_recovery_daemon",
            max_sync_work="recover selected workers and invoke completion callbacks serially",
            callback=daemon.run_once,
        )
        worker_recovery_handoff_required = _worker_phase_handoff_required(summary)
        if worker_recovery_handoff_required:
            _request_durable_work_handoff_yield()
        workflow_recovery_settings = self._workflow_recovery_settings(payload)
        workflow_stale_scope_job_id = str(workflow_recovery_settings.get("workflow_stale_scope_job_id") or "")
        workflow_resume_explicit_job = bool(workflow_recovery_settings.get("workflow_resume_explicit_job"))
        workflow_resume_stale_after_seconds = _coerce_int(
            workflow_recovery_settings.get("workflow_resume_stale_after_seconds"),
            60,
        )
        workflow_resume_limit = _coerce_int(workflow_recovery_settings.get("workflow_resume_limit"), 50)
        workflow_auto_resume_enabled = bool(workflow_recovery_settings.get("workflow_auto_resume_enabled"))
        workflow_queue_resume_stale_after_seconds = _coerce_int(
            workflow_recovery_settings.get("workflow_queue_resume_stale_after_seconds"),
            60,
        )
        workflow_queue_resume_limit = _coerce_int(
            workflow_recovery_settings.get("workflow_queue_resume_limit"),
            50,
        )
        workflow_queue_auto_takeover_enabled = bool(
            workflow_recovery_settings.get("workflow_queue_auto_takeover_enabled")
        )
        blocked_workflow_cleanup = {"status": "skipped", "reason": "not_requested", "results": []}
        if not explicit_job_id:
            blocked_workflow_cleanup = _run_recovery_phase(
                "blocked_workflow_cleanup",
                owner="blocked_workflow_residue_cleanup",
                max_sync_work="bounded blocked workflow cleanup only",
                callback=lambda: self.cleanup_blocked_workflow_residue(
                    {
                        "active_limit": max(
                            20,
                            int(payload.get("blocked_workflow_cleanup_limit") or workflow_resume_limit or 50),
                        ),
                    }
                ),
            )
