    def _workflow_command_execution_summary(
        self,
        command: dict[str, Any],
        *,
        sample_limit: int = 20,
    ) -> dict[str, Any]:
        record = dict(command or {})
        command_id = str(record.get("command_id") or "").strip()
        if not command_id:
            return {
                "source": "workflow_activity_runs+workflow_activity_attempts+workflow_entity_deltas",
                "fallback_status": "fail_closed",
                "fallback_used": False,
                "module_state_mutated": False,
                "activity_count": 0,
                "attempt_count": 0,
                "entity_delta_count": 0,
                "sample_limit": max(1, int(sample_limit or 1)),
                "sample_truncated": False,
            }
        payload = dict(record.get("payload") or {})
        workspace_id = str(payload.get("workspace_id") or record.get("workspace_id") or "default").strip() or "default"
        bounded_limit = max(1, min(50, int(sample_limit or 20)))
        activities = self.store.list_workflow_activity_runs(
            workspace_id=workspace_id,
            command_id=command_id,
            limit=bounded_limit,
        )
        attempts = self.store.list_workflow_activity_attempts(
            workspace_id=workspace_id,
            command_id=command_id,
            limit=bounded_limit,
        )
        deltas = self.store.list_workflow_entity_deltas(
            workspace_id=workspace_id,
            command_id=command_id,
            limit=bounded_limit,
        )

        def _count_by(rows: list[dict[str, Any]], key: str) -> dict[str, int]:
            counts: dict[str, int] = {}
            for row in rows:
                value = str(row.get(key) or "").strip() or "unknown"
                counts[value] = counts.get(value, 0) + 1
            return counts

        latest_activity = self._workflow_activity_api_record(activities[0]) if activities else {}
        latest_attempt = self._workflow_activity_attempt_api_record(attempts[0]) if attempts else {}
        latest_delta = self._workflow_entity_delta_api_record(deltas[0]) if deltas else {}
        latest_effect_status = (
            str(latest_delta.get("status") or "").strip()
            or str(latest_attempt.get("status") or "").strip()
            or str(latest_activity.get("status") or "").strip()
            or str(record.get("status") or "").strip()
        )
        return {
            "source": "workflow_activity_runs+workflow_activity_attempts+workflow_entity_deltas",
            "fallback_status": "fail_closed",
            "fallback_used": False,
            "module_state_mutated": False,
            "activity_count": len(activities),
            "attempt_count": len(attempts),
            "entity_delta_count": len(deltas),
            "activity_status_counts": _count_by(activities, "status"),
            "attempt_status_counts": _count_by(attempts, "status"),
            "entity_delta_status_counts": _count_by(deltas, "status"),
            "entity_delta_kind_counts": _count_by(deltas, "delta_kind"),
            "latest_effect_status": latest_effect_status,
            "latest_activity": latest_activity,
            "latest_attempt": latest_attempt,
            "latest_entity_delta": latest_delta,
            "sample_limit": bounded_limit,
            "sample_truncated": any(
                len(rows) >= bounded_limit for rows in (activities, attempts, deltas)
            ),
        }

