    def list_workflow_commands_api(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = dict(payload or {})
        statuses = payload.get("statuses")
        if statuses is None and payload.get("status") not in {None, ""}:
            statuses = [payload.get("status")]
        if isinstance(statuses, str):
            status_values = [item.strip() for item in statuses.split(",") if item.strip()]
        else:
            status_values = [str(item or "").strip() for item in list(statuses or []) if str(item or "").strip()]
        command_type = str(payload.get("command_type") or "").strip()
        commands = self.store.list_workflow_commands(
            workflow_run_id=str(payload.get("workflow_run_id") or "").strip(),
            operation_id=str(payload.get("operation_id") or "").strip(),
            owner=str(payload.get("owner") or "").strip(),
            statuses=status_values,
            limit=max(1, min(500, _coerce_int(payload.get("limit"), 100))),
        )
        if command_type:
            commands = [command for command in commands if str(command.get("command_type") or "").strip() == command_type]
        include_execution_summary = _coerce_bool(payload.get("include_execution_summary"), False)
        return {
            "status": "ok",
            "workflow_commands": [
                (
                    self._workflow_command_api_record_with_execution_summary(command)
                    if include_execution_summary
                    else self._workflow_command_api_record(command)
                )
                for command in commands
            ],
            "module_state_mutated": False,
            "contract": "w11_workflow_command_list_v1",
        }

