    def list_acquisition_discovery_lanes_api(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = dict(payload or {})
        statuses = payload.get("statuses")
        if statuses is None and payload.get("status") not in {None, ""}:
            statuses = [payload.get("status")]
        if isinstance(statuses, str):
            status_values = [item.strip() for item in statuses.split(",") if item.strip()]
        else:
            status_values = [str(item or "").strip() for item in list(statuses or []) if str(item or "").strip()]
        target_company = str(payload.get("target_company") or "").strip().casefold()
        provider = str(payload.get("provider") or "").strip().casefold()
        query_text = str(payload.get("query") or "").strip().casefold()
        lanes = self.store.list_acquisition_discovery_lanes(
            workspace_id=str(payload.get("workspace_id") or "default").strip() or "default",
            acquisition_run_id=str(payload.get("acquisition_run_id") or "").strip(),
            workflow_run_id=str(payload.get("workflow_run_id") or "").strip(),
            operation_run_id=str(payload.get("operation_run_id") or payload.get("operation_id") or "").strip(),
            source_command_id=str(payload.get("source_command_id") or payload.get("command_id") or "").strip(),
            activity_run_id=str(payload.get("activity_run_id") or "").strip(),
            statuses=status_values,
            limit=max(1, min(500, _coerce_int(payload.get("limit"), 100))),
        )
        if target_company:
            lanes = [lane for lane in lanes if str(lane.get("target_company") or "").strip().casefold() == target_company]
        if provider:
            lanes = [lane for lane in lanes if str(lane.get("provider") or "").strip().casefold() == provider]
        if query_text:
            lanes = [lane for lane in lanes if query_text in str(lane.get("query") or "").strip().casefold()]
        return {
            "status": "ok",
            "acquisition_discovery_lanes": [
                self._acquisition_discovery_lane_api_record(lane) for lane in lanes
            ],
            "module_state_mutated": False,
            "contract": "w11_acquisition_discovery_lane_list_v1",
        }

    def get_acquisition_discovery_lane_api(self, lane_id: str) -> dict[str, Any]:
        normalized_lane_id = str(lane_id or "").strip()
        lane = self.store.get_acquisition_discovery_lane(normalized_lane_id) if normalized_lane_id else {}
        if not lane:
            return {"status": "not_found", "lane_id": normalized_lane_id}
        return {
            "status": "ok",
            "acquisition_discovery_lane": self._acquisition_discovery_lane_api_record(lane),
            "module_state_mutated": False,
            "contract": "w11_acquisition_discovery_lane_query_v1",
        }

    def _cancel_running_crm_public_web_phase_command(
        self,
        command: dict[str, Any],
        *,
        payload: dict[str, Any],
    ) -> dict[str, Any]:
        return self._crm_public_web_owner._cancel_running_crm_public_web_phase_command(command, payload=payload)

    def _cancel_running_excel_intake_command(
        self,
        command: dict[str, Any],
        *,
        payload: dict[str, Any],
    ) -> dict[str, Any]:
        command_payload = dict(command or {})
        body = dict(command_payload.get("payload") or {})
        command_id = str(command_payload.get("command_id") or "").strip()
        job_id = str(body.get("job_id") or "").strip()
        actor = str(payload.get("actor") or payload.get("operator") or "api").strip() or "api"
        reason = str(payload.get("reason") or "cancelled_by_owner_specific_command_control").strip()
        if not job_id:
            return {
                "status": "invalid",
                "reason": "excel_intake_running_cancel_missing_job_id",
                "workflow_command": self._workflow_command_api_record(command_payload),
                **self._workflow_command_control_response_policy_records(command_payload),
                "module_state_mutated": False,
                "owner_specific_control": True,
                "contract": "w11_workflow_command_owner_specific_control_v1",
            }
        result = self._record_excel_intake_command_cancelled_terminal(
            command_id=command_id,
            job_id=job_id,
            reason=reason,
            actor=actor,
        )
        if result.get("workflow_command"):
            result["workflow_command"] = self._workflow_command_api_record(
                self.store.get_workflow_command(command_id) or command_payload
            )
        result.update(self._workflow_command_control_response_policy_records(self.store.get_workflow_command(command_id) or command_payload))
        return result

    def _cancel_running_workflow_command_via_owner(
        self,
        command: dict[str, Any],
        *,
        payload: dict[str, Any],
    ) -> dict[str, Any]:
        command_payload = dict(command or {})
        command_type = str(command_payload.get("command_type") or "").strip()
        owner = str(command_payload.get("owner") or "").strip()
        if owner == CRM_PUBLIC_WEB_PHASE_OWNER and command_type in set(CRM_PUBLIC_WEB_PHASE_COMMAND_TYPES):
            return self._cancel_running_crm_public_web_phase_command(command_payload, payload=payload)
        if command_type in {EXPORT_PROJECTION_GENERATE_COMMAND_TYPE, EXPORT_CRM_PUBLIC_WEB_GENERATE_COMMAND_TYPE}:
            return self._cancel_running_export_command(command_payload, payload=payload)
        if command_type == EXCEL_INTAKE_RUN_COMMAND_TYPE and owner == EXCEL_INTAKE_RUN_OWNER:
            return self._cancel_running_excel_intake_command(command_payload, payload=payload)
        if command_type in {
            ACQUISITION_RUN_CREATE_COMMAND_TYPE,
            ACQUISITION_INTENT_RESOLVE_COMMAND_TYPE,
            ACQUISITION_PLAN_BUILD_COMMAND_TYPE,
            COMPANY_PUBLIC_WEB_REFRESH_COMMAND_TYPE,
        }:
            return self._cancel_running_orchestration_before_downstream(command_payload, payload=payload)
        if command_type == ACQUISITION_PLAN_COMMIT_COMMAND_TYPE and owner == ACQUISITION_PLAN_COMMIT_OWNER:
            return self._cancel_running_acquisition_plan_commit_before_probe(command_payload, payload=payload)
        if command_type == ACQUISITION_SCALE_PLAN_COMMAND_TYPE and owner == ACQUISITION_SCALE_PLAN_OWNER:
            return self._cancel_running_acquisition_scale_plan_before_discovery(command_payload, payload=payload)
        if command_type == CRM_PUBLIC_WEB_QUEUE_BATCH_COMMAND_TYPE and owner == CRM_PUBLIC_WEB_QUEUE_BATCH_OWNER:
            return self._cancel_running_crm_public_web_queue_batch_before_phase_commands(command_payload, payload=payload)
        if command_type in set(PROVIDER_ATTEMPT_COMMAND_TYPES):
            return self._cancel_running_provider_attempt_command_before_attempt(command_payload, payload=payload)
        if owner == COMPANY_PUBLIC_WEB_REFRESH_OWNER and command_type == COMPANY_PUBLIC_WEB_ASSETS_MATERIALIZE_COMMAND_TYPE:
            return self._cancel_running_company_public_web_assets_materialize_before_sync(
                command_payload,
                payload=payload,
            )
        if (
            command_type == LINKEDIN_PROFILE_FETCH_ACTIVITY_RUN_COMMAND_TYPE
            and owner == LINKEDIN_PROFILE_FETCH_ACTIVITY_OWNER
        ):
            return self._cancel_running_profile_fetch_activity_before_cache_lookup_attempt(command_payload, payload=payload)
        if command_type == MEDIA_ASSET_CACHE_COMMAND_TYPE and owner == MEDIA_ASSET_OWNER:
            return self._cancel_running_media_asset_cache_command_before_fetch_upload_attempt(
                command_payload,
                payload=payload,
            )
        if command_type in set(CRM_WRITER_COMMAND_TYPES) and owner == CRM_WRITER_OWNER:
            return self._cancel_running_crm_writer_command_before_mutation_attempt(command_payload, payload=payload)
        if command_type == ACQUISITION_PLAN_REVIEW_REQUEST_COMMAND_TYPE and owner == ACQUISITION_PLAN_REVIEW_REQUEST_OWNER:
            return self._cancel_running_acquisition_plan_review_request_command(command_payload, payload=payload)
        if command_type in set(DOMAIN_MUTATION_COMMAND_TYPES):
            return self._cancel_running_domain_mutation_command_before_attempt(command_payload, payload=payload)
        return {
            "status": "invalid",
            "reason": "running_command_requires_owner_specific_cancel",
            "command_status": str(command_payload.get("status") or "").strip(),
            "command_type": command_type,
            "owner": owner,
            "workflow_command": self._workflow_command_api_record(command_payload),
            **self._workflow_command_control_response_policy_records(command_payload),
            "module_state_mutated": False,
            "owner_specific_control": False,
            "contract": "w11_workflow_command_owner_specific_control_v1",
        }

    def _cancel_running_provider_attempt_command_before_attempt(
        self,
        command: dict[str, Any],
        *,
        payload: dict[str, Any],
    ) -> dict[str, Any]:
        command_payload = dict(command or {})
        command_id = str(command_payload.get("command_id") or "").strip()
        command_type = str(command_payload.get("command_type") or "").strip()
        owner = str(command_payload.get("owner") or "").strip()
        actor = str(payload.get("actor") or payload.get("operator") or "api").strip() or "api"
        reason = str(payload.get("reason") or "cancelled_before_provider_attempt").strip()
        force = _coerce_bool(payload.get("force"), False)
        downstream = self._workflow_command_downstream_commands(command_payload)
        if downstream:
            return {
                "status": "invalid",
                "reason": "provider_attempt_cancel_blocked_after_downstream_planned",
                "downstream_command_count": len(downstream),
                "downstream_command_ids": [
                    str(row.get("command_id") or "").strip()
                    for row in downstream
                    if str(row.get("command_id") or "").strip()
                ],
                "workflow_command": self._workflow_command_api_record(command_payload),
                **self._workflow_command_control_response_policy_records(command_payload),
                "module_state_mutated": False,
                "owner_specific_control": True,
                "contract": "w11_workflow_command_owner_specific_control_v1",
            }
        if self._workflow_command_lease_active(command_payload) and not force:
            return {
                "status": "invalid",
                "reason": "workflow_command_running_cancel_requires_expired_lease_or_force",
                "workflow_command": self._workflow_command_api_record(command_payload),
                **self._workflow_command_control_response_policy_records(command_payload),
                "module_state_mutated": False,
                "owner_specific_control": True,
                "contract": "w11_workflow_command_owner_specific_control_v1",
            }
        activities = self.store.list_workflow_activity_runs(
            command_id=command_id,
            activity_type=command_type,
            limit=50,
        )
        activity_ids = [
            str(activity.get("activity_run_id") or "").strip()
            for activity in activities
            if str(activity.get("activity_run_id") or "").strip()
        ]
        attempts: list[dict[str, Any]] = []
        for activity_id in activity_ids:
            attempts.extend(self.store.list_workflow_activity_attempts(activity_run_id=activity_id, limit=50))
        attempt_count = len(attempts)
        entity_delta_count = len(self.store.list_workflow_entity_deltas(command_id=command_id, limit=1))
        if entity_delta_count:
            return {
                "status": "invalid",
                "reason": "provider_attempt_cancel_blocked_after_provider_entity_delta_recorded",
                "activity_attempt_count": attempt_count,
                "entity_delta_count": entity_delta_count,
                "workflow_command": self._workflow_command_api_record(command_payload),
                **self._workflow_command_control_response_policy_records(command_payload),
                "module_state_mutated": False,
                "owner_specific_control": True,
                "contract": "w11_workflow_command_owner_specific_control_v1",
            }
        policy_record = self._workflow_command_control_policy_record(command_type=command_type, owner=owner)
        after_start_mode = str(policy_record.get("provider_after_start_control_mode") or "").strip()
        if attempt_count and after_start_mode != PROVIDER_AFTER_START_CONTROL_MODE_POLL_CANCEL_QUARANTINE:
            return {
                "status": "invalid",
                "reason": "provider_attempt_cancel_blocked_after_provider_attempt_started",
                "activity_attempt_count": attempt_count,
                "entity_delta_count": entity_delta_count,
                "workflow_command": self._workflow_command_api_record(command_payload),
                **self._workflow_command_control_response_policy_records(command_payload),
                "module_state_mutated": False,
                "owner_specific_control": True,
                "contract": "w11_workflow_command_owner_specific_control_v1",
            }
        if attempt_count:
            cancelled_activities: list[dict[str, Any]] = []
            for activity in activities:
                metadata = dict(activity.get("metadata") or {})
                metadata.update(
                    {
                        "cancelled_by": actor,
                        "cancel_reason": reason,
                        "control_source": "api.workflow_command_owner_specific_cancel",
                        "provider_after_start_control_mode": after_start_mode,
                        "remote_cancel_attempted": False,
                        "poll_cancelled_locally": True,
                        "late_result_policy": "quarantine_as_ignored_evidence",
                        "module_state_mutated": False,
                    }
                )
                cancelled_activity = self.store.upsert_workflow_activity_run(
                    {
                        **activity,
                        "status": "cancelled_poll_stopped",
                        "phase": "cancelled",
                        "metadata": metadata,
                    }
                )
                if cancelled_activity:
                    cancelled_activities.append(cancelled_activity)
            cancelled_attempts: list[dict[str, Any]] = []
            completed_at = datetime.now(timezone.utc).isoformat()
            for attempt in attempts:
                metadata = dict(attempt.get("metadata") or {})
                metadata.update(
                    {
                        "cancelled_by": actor,
                        "cancel_reason": reason,
                        "control_source": "api.workflow_command_owner_specific_cancel",
                        "provider_after_start_control_mode": after_start_mode,
                        "remote_cancel_attempted": False,
                        "poll_cancelled_locally": True,
                        "late_result_policy": "quarantine_as_ignored_evidence",
                        "module_state_mutated": False,
                    }
                )
                error_payload = dict(attempt.get("error") or {})
                error_payload.update(
                    {
                        "reason": reason,
                        "control_action": "cancel",
                        "remote_cancel_attempted": False,
                        "late_result_policy": "quarantine_as_ignored_evidence",
                    }
                )
                output_payload = dict(attempt.get("output") or {})
                output_payload.update(
                    {
                        "control_source": "api.workflow_command_owner_specific_cancel",
                        "provider_after_start_control_mode": after_start_mode,
                        "remote_result_acceptance": "quarantined_if_late",
                    }
                )
                cancelled_attempt = self.store.upsert_workflow_activity_attempt(
                    {
                        **attempt,
                        "status": "cancelled_remote_ignored",
                        "completed_at": str(attempt.get("completed_at") or completed_at),
                        "metadata": metadata,
                        "error": error_payload,
                        "output": output_payload,
                    }
                )
                if cancelled_attempt:
                    cancelled_attempts.append(cancelled_attempt)
            updated = self.store.cancel_workflow_command(
                command_id,
                reason=reason,
                actor=actor,
                result={
                    "control_source": "api.workflow_command_owner_specific_cancel",
                    "control_action": "cancel",
                    "owner_specific_control": True,
                    "cancel_boundary": "provider_attempt_after_start_poll_cancel",
                    "provider_after_start_control_mode": after_start_mode,
                    "activity_run_cancelled_count": len(cancelled_activities),
                    "activity_attempt_cancelled_count": len(cancelled_attempts),
                    "activity_attempt_started": True,
                    "provider_entity_delta_recorded": False,
                    "downstream_command_planned": False,
                    "remote_cancel_attempted": False,
                    "poll_cancelled_locally": True,
                    "late_result_policy": "quarantine_as_ignored_evidence",
                    "module_state_mutated": False,
                    "command_type": command_type,
                    "owner": owner,
                    "force": force,
                },
                from_statuses=("claimed", "running"),
            )
            if not updated:
                latest = self.store.get_workflow_command(command_id) or command_payload
                return {
                    "status": "invalid",
                    "reason": "workflow_command_owner_specific_cancel_not_applied",
                    "workflow_command": self._workflow_command_api_record(latest),
                    **self._workflow_command_control_response_policy_records(latest),
                    "workflow_activity_runs": cancelled_activities,
                    "workflow_activity_attempts": cancelled_attempts,
                    "module_state_mutated": False,
                    "owner_specific_control": True,
                    "contract": "w11_workflow_command_owner_specific_control_v1",
                }
            operation_sync = self._sync_operation_run_from_workflow_command_control(
                updated,
                control_action="cancel",
                actor=actor,
                source="api.workflow_command_owner_specific_cancel",
            )
            return {
                "status": "cancelled",
                "workflow_command": self._workflow_command_api_record(updated),
                "operation_sync": operation_sync,
                "workflow_activity_runs": cancelled_activities,
                "workflow_activity_attempts": cancelled_attempts,
                **self._workflow_command_control_response_policy_records(updated),
                "module_state_mutated": False,
                "owner_specific_control": True,
                "contract": "w11_workflow_command_owner_specific_control_v1",
            }
        cancelled_activities: list[dict[str, Any]] = []
        for activity in activities:
            metadata = dict(activity.get("metadata") or {})
            metadata.update(
                {
                    "cancelled_by": actor,
                    "cancel_reason": reason,
                    "control_source": "api.workflow_command_owner_specific_cancel",
                    "provider_activity_attempt_started": False,
                    "provider_entity_delta_recorded": False,
                }
            )
            cancelled_activity = self.store.upsert_workflow_activity_run(
                {
                    **activity,
                    "status": "cancelled_before_provider_attempt",
                    "phase": "cancelled",
                    "metadata": metadata,
                }
            )
            if cancelled_activity:
                cancelled_activities.append(cancelled_activity)
        updated = self.store.cancel_workflow_command(
            command_id,
            reason=reason,
            actor=actor,
            result={
                "control_source": "api.workflow_command_owner_specific_cancel",
                "control_action": "cancel",
                "owner_specific_control": True,
                "cancel_boundary": "provider_attempt_before_activity_attempt",
                "activity_run_cancelled_count": len(cancelled_activities),
                "activity_attempt_started": False,
                "provider_entity_delta_recorded": False,
                "downstream_command_planned": False,
                "command_type": command_type,
                "owner": owner,
                "force": force,
            },
            from_statuses=("claimed", "running"),
        )
        if not updated:
            latest = self.store.get_workflow_command(command_id) or command_payload
            return {
                "status": "invalid",
                "reason": "workflow_command_owner_specific_cancel_not_applied",
                "workflow_command": self._workflow_command_api_record(latest),
                **self._workflow_command_control_response_policy_records(latest),
                "workflow_activity_runs": cancelled_activities,
                "module_state_mutated": bool(cancelled_activities),
                "owner_specific_control": True,
                "contract": "w11_workflow_command_owner_specific_control_v1",
            }
        operation_sync = self._sync_operation_run_from_workflow_command_control(
            updated,
            control_action="cancel",
            actor=actor,
            source="api.workflow_command_owner_specific_cancel",
        )
        return {
            "status": "cancelled",
            "workflow_command": self._workflow_command_api_record(updated),
            "operation_sync": operation_sync,
            "workflow_activity_runs": cancelled_activities,
            **self._workflow_command_control_response_policy_records(updated),
            "module_state_mutated": bool(cancelled_activities),
            "owner_specific_control": True,
            "contract": "w11_workflow_command_owner_specific_control_v1",
        }

