    def _workflow_command_downstream_commands(self, command: dict[str, Any]) -> list[dict[str, Any]]:
        command_payload = dict(command or {})
        command_id = str(command_payload.get("command_id") or "").strip()
        if not command_id:
            return []
        result_ids = [
            str(item or "").strip()
            for item in list((command_payload.get("result") or {}).get("downstream_command_ids") or [])
            if str(item or "").strip()
        ]
        causality_ids = [
            str(item or "").strip()
            for item in list(command_payload.get("downstream_command_ids") or [])
            if str(item or "").strip()
        ]
        known_ids = {item for item in [*result_ids, *causality_ids] if item}
        downstream: dict[str, dict[str, Any]] = {}
        for downstream_id in known_ids:
            row = self.store.get_workflow_command(downstream_id)
            if row:
                downstream[str(row.get("command_id") or downstream_id)] = row
            else:
                downstream[downstream_id] = {"command_id": downstream_id}
        candidate_rows: list[dict[str, Any]] = []
        workflow_run_id = str(command_payload.get("workflow_run_id") or "").strip()
        operation_id = str(command_payload.get("operation_id") or "").strip()
        if workflow_run_id:
            candidate_rows.extend(self.store.list_workflow_commands(workflow_run_id=workflow_run_id, limit=500))
        if operation_id:
            candidate_rows.extend(self.store.list_workflow_commands(operation_id=operation_id, limit=500))
        for row in candidate_rows:
            row_payload = dict(row or {})
            if str(row_payload.get("parent_command_id") or "").strip() == command_id:
                downstream[str(row_payload.get("command_id") or "")] = row_payload
        return [row for row in downstream.values() if row]

