    def _operation_run_status_summary(self, operation_run: dict[str, Any]) -> dict[str, Any]:
        record = dict(operation_run or {})
        operation_run_id = str(record.get("operation_run_id") or "").strip()
        if not operation_run_id:
            return {
                "source": "operation_runs+operation_events+workflow_commands",
                "fallback_status": "fail_closed",
                "fallback_used": False,
                "module_state_mutated": False,
                "workflow_command_count": 0,
                "operation_event_count": 0,
                "command_status_counts": {},
                "latest_event_type": "",
                "latest_workflow_command": {},
            }
        commands = self.store.list_workflow_commands(operation_id=operation_run_id, limit=100)
        workflow_ref = dict(record.get("workflow_ref") or {})
        workflow_run_id = str(workflow_ref.get("workflow_run_id") or "").strip()
        if workflow_run_id:
            command_ids = {str(command.get("command_id") or "") for command in commands}
            for command in self.store.list_workflow_commands(workflow_run_id=workflow_run_id, limit=100):
                command_id = str(command.get("command_id") or "")
                if command_id and command_id not in command_ids:
                    commands.append(command)
                    command_ids.add(command_id)
        events = self.store.list_operation_events(operation_run_id)

        command_status_counts: dict[str, int] = {}
        for command in commands:
            status = str(command.get("status") or "").strip() or "unknown"
            command_status_counts[status] = command_status_counts.get(status, 0) + 1
        latest_event = events[-1] if events else {}
        latest_command = commands[0] if commands else {}
        progress = dict(record.get("progress") or {})
        return {
            "source": "operation_runs+operation_events+workflow_commands",
            "fallback_status": "fail_closed",
            "fallback_used": False,
            "module_state_mutated": False,
            "operation_status": str(record.get("status") or "").strip(),
            "operation_phase": str(progress.get("phase") or "").strip(),
            "workflow_command_count": len(commands),
            "operation_event_count": len(events),
            "command_status_counts": command_status_counts,
            "latest_event_type": str(latest_event.get("event_type") or "").strip(),
            "latest_event": latest_event,
            "latest_workflow_command": (
                self._workflow_command_api_record_with_execution_summary(latest_command)
                if latest_command
                else {}
            ),
        }

    def _operation_action_display_contract_record(self, action: dict[str, Any]) -> dict[str, Any]:
        record = dict(action or {})
        action_type = str(record.get("action_type") or "").strip()
        if action_type:
            try:
                return DEFAULT_ACTION_REGISTRY.display_contract_for(action_type).to_record()
            except KeyError:
                pass
        return {
            "schema_version": "operation_action_display_contract_v1",
            "action_type": action_type,
            "owner_module": str(record.get("owner_module") or "").strip(),
            "operation_type": str(record.get("operation_type") or "").strip(),
            "display_label": "",
            "display_category": "",
            "description": "",
            "source_of_truth": "operation_runtime.ActionRegistry.display_contract_for",
            "fallback_status": "fail_closed",
            "reason": "unregistered_or_missing_action_type",
        }

    def _operation_action_api_record(self, action: dict[str, Any]) -> dict[str, Any]:
        record = dict(action or {})
        if record:
            record["display_contract"] = self._operation_action_display_contract_record(record)
        return record

    def _operation_run_display_contract_record(self, operation_run: dict[str, Any]) -> dict[str, Any]:
        record = dict(operation_run or {})
        action_id = str(record.get("action_id") or "").strip()
        action = self.store.get_agent_action(action_id) if action_id else {}
        if action:
            return self._operation_action_display_contract_record(action)
        metadata = dict(record.get("metadata") or {})
        action_type = str(metadata.get("source_action_type") or "").strip()
        if action_type:
            try:
                return DEFAULT_ACTION_REGISTRY.display_contract_for(action_type).to_record()
            except KeyError:
                pass
        return {
            "schema_version": "operation_action_display_contract_v1",
            "action_type": action_type,
            "owner_module": str(record.get("owner_module") or "").strip(),
            "operation_type": str(record.get("operation_type") or "").strip(),
            "display_label": "",
            "display_category": "",
            "description": "",
            "source_of_truth": "operation_runtime.ActionRegistry.display_contract_for",
            "fallback_status": "fail_closed",
            "reason": "missing_linked_agent_action",
        }

    def _operation_run_control_state_record(self, operation_run: dict[str, Any]) -> dict[str, Any]:
        record = dict(operation_run or {})
        action_id = str(record.get("action_id") or "").strip()
        action = self.store.get_agent_action(action_id) if action_id else {}
        progress = dict(record.get("progress") or {})
        return operation_run_control_state(
            operation_status=str(record.get("status") or "").strip(),
            action_status=str((action or {}).get("status") or "").strip(),
            operation_phase=str(progress.get("phase") or "").strip(),
        ).to_record()

    def _operation_run_api_record(self, operation_run: dict[str, Any]) -> dict[str, Any]:
        record = dict(operation_run or {})
        record["display_contract"] = self._operation_run_display_contract_record(operation_run)
        record["control_state"] = self._operation_run_control_state_record(operation_run)
        return record

    def _operation_run_control_response_record(self, response: dict[str, Any]) -> dict[str, Any]:
        record = dict(response or {})
        action = record.get("action")
        if isinstance(action, dict) and action:
            record["action"] = self._operation_action_api_record(action)
        for key in ("operation_run", "parent_operation_run"):
            value = record.get(key)
            if isinstance(value, dict) and value:
                record[key] = self._operation_run_api_record_with_status_summary(value)
        operation_run = record.get("operation_run")
        if isinstance(operation_run, dict) and operation_run.get("control_state"):
            record["control_state"] = operation_run["control_state"]
        if isinstance(operation_run, dict) and operation_run.get("display_contract"):
            record["display_contract"] = operation_run["display_contract"]
        elif isinstance(record.get("action"), dict) and record["action"].get("display_contract"):
            record["display_contract"] = record["action"]["display_contract"]
        return record

    def _operation_run_api_record_with_status_summary(
        self,
        operation_run: dict[str, Any],
    ) -> dict[str, Any]:
        record = self._operation_run_api_record(operation_run)
        record["status_summary"] = self._operation_run_status_summary(operation_run)
        return record

