    def dispatch_operation_run_api(
        self,
        operation_run_id: str,
        payload: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        payload = dict(payload or {})
        operation_run = self.store.get_operation_run(operation_run_id)
        if not operation_run:
            return {"status": "not_found", "operation_run_id": str(operation_run_id or "").strip()}
        action = self.store.get_agent_action(str(operation_run.get("action_id") or ""))
        if not action:
            return {
                "status": "invalid",
                "reason": "operation action not found",
                "operation_run_id": str(operation_run_id or "").strip(),
            }
        action_type = str(action.get("action_type") or "").strip()
        if action_type in {ACTION_FILTER_PROJECTION, ACTION_SEARCH_PROJECTION}:
            return self._operation_run_control_response_record(
                self._dispatch_projection_read_operation(
                    operation_run=operation_run,
                    action=action,
                    actor=str(payload.get("actor") or "api").strip() or "api",
                )
            )
        if action_type == ACTION_ENRICH_PERSON_PUBLIC_WEB:
            return self._operation_run_control_response_record(
                self._dispatch_person_public_web_enrichment_operation(
                    operation_run=operation_run,
                    action=action,
                    actor=str(payload.get("actor") or "api").strip() or "api",
                )
            )
        if action_type == ACTION_EXPORT_CANDIDATES:
            return self._operation_run_control_response_record(
                self._dispatch_export_candidates_operation(
                    operation_run=operation_run,
                    action=action,
                    actor=str(payload.get("actor") or "api").strip() or "api",
                )
            )
        if action_type in {
            ACTION_START_ACQUISITION_RUN,
            ACTION_FETCH_PROFILE_SAMPLE,
            ACTION_CONTINUE_ACQUISITION_RUN,
            ACTION_REFRESH_COMPANY_PUBLIC_WEB,
        }:
            return self._operation_run_control_response_record(
                self._dispatch_agent_callable_workflow_command_operation(
                    operation_run=operation_run,
                    action=action,
                    actor=str(payload.get("actor") or "api").strip() or "api",
                )
            )
        if action_type in {ACTION_ADD_TO_CRM, ACTION_SET_CRM_STAGE, ACTION_ADD_CRM_NOTE, ACTION_CREATE_CRM_TASK}:
            return self._operation_run_control_response_record(
                self._dispatch_crm_writer_operation(
                    operation_run=operation_run,
                    action=action,
                    actor=str(payload.get("actor") or "api").strip() or "api",
                )
            )
        return self._operation_run_control_response_record(
            {
                "status": "unsupported",
                "reason": f"operation action {action_type!r} has no W9b owner adapter",
                "operation_run": operation_run,
                "action": action,
                "module_state_mutated": False,
                "contract": "w9_operation_run_dispatch_v1",
            }
        )

    def _dispatch_agent_callable_workflow_command_operation(
        self,
        *,
        operation_run: dict[str, Any],
        action: dict[str, Any],
        actor: str,
    ) -> dict[str, Any]:
        if str(action.get("approval_policy") or "").strip() == "required" and str(
            action.get("approval_status") or ""
        ).strip() != "approved":
            return {
                "status": "approval_required",
                "action": action,
                "operation_run": operation_run,
                "module_state_mutated": False,
                "contract": "w11_agent_callable_workflow_command_dispatch_v1",
            }
        if str(operation_run.get("status") or "").strip() in {"completed", "failed", "cancelled"}:
            return {
                "status": "invalid",
                "reason": f"terminal operation cannot be dispatched: {operation_run.get('status')}",
                "operation_run": operation_run,
                "action": action,
                "module_state_mutated": False,
                "contract": "w11_agent_callable_workflow_command_dispatch_v1",
            }
        plan = self._build_agent_callable_workflow_command_plan(operation_run=operation_run, action=action)
        if str(plan.get("status") or "") != "ok":
            return {
                "status": str(plan.get("status") or "invalid"),
                "reason": str(plan.get("reason") or "agent_callable_workflow_command_invalid"),
                "operation_run": operation_run,
                "action": action,
                "module_state_mutated": False,
                "contract": "w11_agent_callable_workflow_command_dispatch_v1",
            }
        command = self._plan_agent_callable_workflow_command(
            operation_run=operation_run,
            action=action,
            command_type=str(plan.get("command_type") or ""),
            command_payload=dict(plan.get("command_payload") or {}),
            workflow_run_id=str(plan.get("workflow_run_id") or ""),
            actor=actor,
            max_attempts=max(1, _coerce_int(plan.get("max_attempts"), 5)),
            retry_policy=dict(plan.get("retry_policy") or {}),
        )
        if not command:
            return {
                "status": "failed",
                "reason": "agent_callable_workflow_command_enqueue_failed",
                "operation_run": operation_run,
                "action": action,
                "module_state_mutated": False,
                "contract": "w11_agent_callable_workflow_command_dispatch_v1",
            }
        workflow_ref = {
            "workflow_run_id": str(command.get("workflow_run_id") or ""),
            "command_id": str(command.get("command_id") or ""),
            "command_type": str(command.get("command_type") or ""),
            "owner": str(command.get("owner") or ""),
        }
        next_operation = self.store.update_operation_run_state(
            str(operation_run.get("operation_run_id") or ""),
            status="planned",
            progress_patch={
                "phase": "workflow_command_planned",
                "action_type": str(action.get("action_type") or ""),
                **workflow_ref,
            },
            workflow_ref_patch=workflow_ref,
            result_ref_patch={"workflow_command": {**workflow_ref, "status": str(command.get("status") or "")}},
            metadata_patch={"last_planned_command_id": workflow_ref["command_id"], "dispatch_actor": actor},
        )
        self.store.update_agent_action_state(
            str(action.get("action_id") or ""),
            status="planned",
            metadata_patch={"last_operation_run_id": operation_run.get("operation_run_id")},
        )
        event = self.store.append_operation_event(
            workspace_id=str(operation_run.get("workspace_id") or "default").strip() or "default",
            event_stream_id=str(operation_run.get("operation_run_id") or ""),
            operation_run_id=str(operation_run.get("operation_run_id") or ""),
            action_id=str(action.get("action_id") or ""),
            event_family="operation_event",
            event_type="OperationCommandPlanned",
            idempotency_key=(
                f"{operation_run.get('idempotency_key')}:OperationCommandPlanned:{workflow_ref['command_id']}"
            ),
            actor=actor,
            source="api.operation_run_dispatch",
            payload={**workflow_ref, "module_state_mutated": False, "migration_phase": "W11_agent_callable_workflow_command"},
        )
        return {
            "status": "planned",
            "action": self.store.get_agent_action(str(action.get("action_id") or "")) or action,
            "operation_run": next_operation,
            "workflow_command": self._workflow_command_api_record(command),
            "events": [event],
            "module_state_mutated": False,
            "contract": "w11_agent_callable_workflow_command_dispatch_v1",
        }

    @staticmethod
    def _agent_callable_workflow_command_types_for_action(action_type: str) -> set[str]:
        normalized_action = str(action_type or "").strip()
        try:
            spec = DEFAULT_ACTION_REGISTRY.spec_for(normalized_action)
        except KeyError:
            return set()
        return {str(command_type).strip() for command_type in spec.allowed_workflow_command_types if str(command_type).strip()}

    @staticmethod
    def _acquisition_decomposition_downstream_command_types() -> list[str]:
        return [
            ACQUISITION_INTENT_RESOLVE_COMMAND_TYPE,
            ACQUISITION_PLAN_BUILD_COMMAND_TYPE,
            ACQUISITION_PLAN_REVIEW_REQUEST_COMMAND_TYPE,
            ACQUISITION_PLAN_COMMIT_COMMAND_TYPE,
            ACQUISITION_PROBE_SUBMIT_COMMAND_TYPE,
            ACQUISITION_PROBE_COLLECT_COMMAND_TYPE,
            ACQUISITION_SCALE_PLAN_COMMAND_TYPE,
            LINKEDIN_DISCOVERY_QUERY_RUN_COMMAND_TYPE,
            LINKEDIN_PROFILE_FETCH_ACTIVITY_RUN_COMMAND_TYPE,
            LINKEDIN_PROFILE_FETCH_PROVIDER_COMMAND_TYPE,
            LINKEDIN_PROFILE_TERMINAL_ADMIT_COMMAND_TYPE,
            LINKEDIN_PROFILE_REFILL_SUBMIT_BATCH_COMMAND_TYPE,
            LINKEDIN_PROFILE_URL_TERMINAL_RECORD_COMMAND_TYPE,
            LINKEDIN_LOCAL_PROFILE_DELTA_APPLY_COMMAND_TYPE,
            PROJECTION_BOARD_VISIBLE_PATCH_PUBLISH_COMMAND_TYPE,
            PROJECTION_PROFILE_ADMISSION_APPLY_COMMAND_TYPE,
            PROJECTION_RUN_SCOPE_FINALIZE_COMMAND_TYPE,
            PROJECTION_PERSON_SEARCH_INDEX_BUILD_COMMAND_TYPE,
            PROJECTION_FACET_LAYERING_BUILD_COMMAND_TYPE,
            COLLECTION_AUTHORITATIVE_MERGE_COMMAND_TYPE,
            SNAPSHOT_COMPACTION_RUN_COMMAND_TYPE,
        ]

    def _build_agent_callable_workflow_command_plan(
        self,
        *,
        operation_run: dict[str, Any],
        action: dict[str, Any],
    ) -> dict[str, Any]:
        action_type = str(action.get("action_type") or "").strip()
        input_payload = dict(action.get("input") or {})
        target_ref = dict(action.get("target_ref") or {})
        allowed_types = self._agent_callable_workflow_command_types_for_action(action_type)
        try:
            spec = DEFAULT_ACTION_REGISTRY.spec_for(action_type)
            default_type = str(spec.default_workflow_command_type or "").strip()
        except KeyError:
            default_type = ""
        command_type = str(input_payload.get("command_type") or target_ref.get("command_type") or default_type).strip()
        if command_type not in allowed_types:
            return {
                "status": "invalid",
                "reason": "unsupported_agent_callable_workflow_command_type",
                "command_type": command_type,
                "allowed_command_types": sorted(allowed_types),
            }
        try:
            owner = DEFAULT_COMMAND_OWNER_REGISTRY.owner_for(command_type)
        except KeyError:
            return {"status": "invalid", "reason": "unknown_workflow_command_type", "command_type": command_type}
        workspace_id = str(operation_run.get("workspace_id") or target_ref.get("workspace_id") or "default").strip()
        workspace_id = workspace_id or "default"
        explicit_command_payload = dict(input_payload.get("command_payload") or {})
        operation_run_id = str(operation_run.get("operation_run_id") or "").strip()
        job_id = str(input_payload.get("job_id") or target_ref.get("job_id") or "").strip()
        workflow_run_id = (
            str(input_payload.get("workflow_run_id") or target_ref.get("workflow_run_id") or "").strip()
            or legacy_job_workflow_run_id(job_id)
        )
        if command_type == ACQUISITION_RUN_CREATE_COMMAND_TYPE:
            if not workflow_run_id:
                workflow_run_id = f"wf_operation_{hashlib.sha1(operation_run_id.encode('utf-8')).hexdigest()[:24]}"
            explicit_workflow_payload = dict(
                input_payload.get("workflow_payload")
                or target_ref.get("workflow_payload")
                or explicit_command_payload.get("workflow_payload")
                or {}
            )
            target_company = str(
                input_payload.get("target_company")
                or target_ref.get("target_company")
                or explicit_workflow_payload.get("target_company")
                or ""
            ).strip()
            query_text = str(
                input_payload.get("query")
                or input_payload.get("raw_user_request")
                or target_ref.get("query")
                or explicit_workflow_payload.get("raw_user_request")
                or explicit_workflow_payload.get("query")
                or ""
            ).strip()
            plan_review_id = str(
                input_payload.get("plan_review_id")
                or target_ref.get("plan_review_id")
                or explicit_workflow_payload.get("plan_review_id")
                or ""
            ).strip()
            if not plan_review_id and not target_company and not query_text:
                return {
                    "status": "invalid",
                    "reason": "start_acquisition_run requires plan_review_id, target_company, or query",
                    "command_type": command_type,
                }
            workflow_payload = {
                **explicit_workflow_payload,
                "runtime_execution_mode": str(
                    explicit_workflow_payload.get("runtime_execution_mode") or "operation_command"
                ).strip()
                or "operation_command",
                "requester_id": str(input_payload.get("requester_id") or target_ref.get("requester_id") or "").strip(),
                "tenant_id": str(input_payload.get("tenant_id") or target_ref.get("tenant_id") or workspace_id).strip()
                or workspace_id,
                "idempotency_key": str(operation_run.get("idempotency_key") or action.get("idempotency_key") or "").strip(),
            }
            if target_company:
                workflow_payload.setdefault("target_company", target_company)
            if query_text:
                workflow_payload.setdefault("raw_user_request", query_text)
                workflow_payload.setdefault("query", query_text)
            if plan_review_id:
                workflow_payload["plan_review_id"] = plan_review_id
            command_payload = {
                **explicit_command_payload,
                "workflow_payload": workflow_payload,
                "target_company": target_company,
                "query": query_text,
                "plan_review_id": plan_review_id,
                "run_count": 1,
                "operation_run_id": operation_run_id,
                "action_id": str(action.get("action_id") or ""),
                "workspace_id": workspace_id,
                "source": "operation_run_dispatch",
                "migration_phase": "W11a_acquisition_run_create_root",
                "decomposition_contract": {
                    "root_command_type": ACQUISITION_RUN_CREATE_COMMAND_TYPE,
                    "owner": owner,
                    "normal_path_executes_queue_workflow_inline": False,
                    "downstream_phases": self._acquisition_decomposition_downstream_command_types(),
                },
            }
            return {
                "status": "ok",
                "command_type": command_type,
                "owner": owner,
                "workflow_run_id": workflow_run_id,
                "command_payload": command_payload,
                "max_attempts": max(1, _coerce_int(input_payload.get("max_attempts"), 5)),
                "retry_policy": {"kind": "operation_acquisition_run_create", "retry_delay_seconds": 30},
            }
        if command_type == COMPANY_PUBLIC_WEB_REFRESH_COMMAND_TYPE:
            if not workflow_run_id:
                workflow_run_id = f"wf_company_public_web_{hashlib.sha1(operation_run_id.encode('utf-8')).hexdigest()[:24]}"
            target_company = str(
                input_payload.get("target_company")
                or target_ref.get("target_company")
                or input_payload.get("company")
                or target_ref.get("company")
                or explicit_command_payload.get("target_company")
                or explicit_command_payload.get("company")
                or ""
            ).strip()
            company_key = str(
                input_payload.get("company_key")
                or target_ref.get("company_key")
                or explicit_command_payload.get("company_key")
                or ""
            ).strip()
            if not target_company:
                return {
                    "status": "invalid",
                    "reason": "refresh_company_public_web_assets requires target_company",
                    "command_type": command_type,
                }
            explicit_options = (
                explicit_command_payload.get("options") if isinstance(explicit_command_payload, dict) else {}
            )
            input_options = input_payload.get("options") if isinstance(input_payload, dict) else {}
            options = {
                **(dict(explicit_options) if isinstance(explicit_options, dict) else {}),
                **(dict(input_options) if isinstance(input_options, dict) else {}),
            }
            collection_mode = str(
                input_payload.get("collection_mode")
                or target_ref.get("collection_mode")
                or explicit_command_payload.get("collection_mode")
                or options.get("collection_mode")
                or "seed_url_only"
            ).strip().lower() or "seed_url_only"
            options["collection_mode"] = collection_mode
            seed_urls = _dedupe_texts(
                input_payload.get("seed_urls")
                or input_payload.get("urls")
                or target_ref.get("seed_urls")
                or explicit_command_payload.get("seed_urls")
                or explicit_command_payload.get("urls")
                or []
            )
            source_families = _dedupe_texts(
                input_payload.get("source_families")
                or target_ref.get("source_families")
                or explicit_command_payload.get("source_families")
                or []
            )
            collector_inputs_source = (
                input_payload.get("collector_inputs")
                if isinstance(input_payload.get("collector_inputs"), dict)
                else explicit_command_payload.get("collector_inputs")
                if isinstance(explicit_command_payload.get("collector_inputs"), dict)
                else {}
            )
            collector_documents_source = (
                input_payload.get("collector_documents")
                if isinstance(input_payload.get("collector_documents"), list)
                else input_payload.get("collector_payloads")
                if isinstance(input_payload.get("collector_payloads"), list)
                else explicit_command_payload.get("collector_documents")
                if isinstance(explicit_command_payload.get("collector_documents"), list)
                else []
            )
            collector_sources_source = (
                input_payload.get("collector_sources")
                if isinstance(input_payload.get("collector_sources"), list)
                else input_payload.get("collector_source_urls")
                if isinstance(input_payload.get("collector_source_urls"), list)
                else explicit_command_payload.get("collector_sources")
                if isinstance(explicit_command_payload.get("collector_sources"), list)
                else []
            )
            command_payload = {
                **explicit_command_payload,
                "target_company": target_company,
                "company": target_company,
                "company_key": company_key,
                "workspace_id": workspace_id,
                "seed_urls": seed_urls,
                "source_families": source_families,
                "collector_inputs": dict(collector_inputs_source),
                "collector_documents": list(collector_documents_source),
                "collector_sources": list(collector_sources_source),
                "options": options,
                "collection_mode": collection_mode,
                "force_refresh": _coerce_bool(
                    input_payload.get("force_refresh", explicit_command_payload.get("force_refresh")),
                    False,
                ),
                "operation_run_id": operation_run_id,
                "action_id": str(action.get("action_id") or ""),
                "source": "operation_run_dispatch",
                "migration_phase": "W11_company_public_web_refresh_command",
                "company_asset_write_owner": COMPANY_PUBLIC_WEB_REFRESH_OWNER,
                "normal_path_executes_api_refresh_inline": False,
                "produced_entity_counts": {"company_public_web_run": 1},
            }
            return {
                "status": "ok",
                "command_type": command_type,
                "owner": owner,
                "workflow_run_id": workflow_run_id,
                "command_payload": command_payload,
                "max_attempts": max(1, _coerce_int(input_payload.get("max_attempts"), 3)),
                "retry_policy": {"kind": "company_public_web_refresh", "retry_delay_seconds": 30},
            }
        if not workflow_run_id and command_type not in {
            LINKEDIN_DISCOVERY_QUERY_RUN_COMMAND_TYPE,
            LINKEDIN_PROFILE_FETCH_ACTIVITY_RUN_COMMAND_TYPE,
            LINKEDIN_PROFILE_FETCH_PROVIDER_COMMAND_TYPE,
            LINKEDIN_PROFILE_TERMINAL_ADMIT_COMMAND_TYPE,
            PROJECTION_PROFILE_ADMISSION_APPLY_COMMAND_TYPE,
        }:
            return {"status": "invalid", "reason": "workflow_run_id_or_job_id_required", "command_type": command_type}
        if command_type == PROJECTION_PROFILE_ADMISSION_APPLY_COMMAND_TYPE:
            activity_run_id = str(
                input_payload.get("source_profile_terminal_activity_run_id")
                or target_ref.get("source_profile_terminal_activity_run_id")
                or explicit_command_payload.get("source_profile_terminal_activity_run_id")
                or input_payload.get("activity_run_id")
                or target_ref.get("activity_run_id")
                or explicit_command_payload.get("activity_run_id")
                or ""
            ).strip()
            source_delta_ids = _dedupe_texts(
                input_payload.get("source_entity_delta_ids")
                or target_ref.get("source_entity_delta_ids")
                or explicit_command_payload.get("source_entity_delta_ids")
                or []
            )
            if activity_run_id and not source_delta_ids:
                delta_rows = self.store.list_workflow_entity_deltas(
                    activity_run_id=activity_run_id,
                    entity_type="profile",
                    statuses=["recorded"],
                    limit=max(1, min(500, _coerce_int(input_payload.get("limit"), 100))),
                )
                source_delta_ids = _dedupe_texts(
                    [
                        str(delta.get("delta_id") or "").strip()
                        for delta in delta_rows
                        if str(delta.get("delta_kind") or "") == "profile_terminal_recorded"
                    ]
                )
            activity = self.store.get_workflow_activity_run(activity_run_id) if activity_run_id else {}
            acquisition_run_id = str(
                input_payload.get("acquisition_run_id")
                or target_ref.get("acquisition_run_id")
                or explicit_command_payload.get("acquisition_run_id")
                or activity.get("acquisition_run_id")
                or ""
            ).strip()
            acquisition_run = self.store.get_acquisition_run(acquisition_run_id) if acquisition_run_id else {}
            workflow_run_id = (
                workflow_run_id
                or str(activity.get("workflow_run_id") or "").strip()
                or str(acquisition_run.get("workflow_run_id") or "").strip()
            )
            if not workflow_run_id or not activity_run_id or not source_delta_ids:
                return {
                    "status": "invalid",
                    "reason": "projection_profile_admission requires workflow_run_id, activity_run_id, and profile_terminal_recorded deltas",
                    "command_type": command_type,
                }
            profile_urls = _dedupe_texts(
                input_payload.get("profile_urls")
                or target_ref.get("profile_urls")
                or explicit_command_payload.get("profile_urls")
                or []
            )
            command_payload = {
                **explicit_command_payload,
                "runtime_execution_mode": "operation_native_projection_admission",
                "source_profile_terminal_activity_run_id": activity_run_id,
                "acquisition_run_id": acquisition_run_id,
                "target_company": str(
                    input_payload.get("target_company")
                    or target_ref.get("target_company")
                    or explicit_command_payload.get("target_company")
                    or acquisition_run.get("target_company")
                    or ""
                ).strip(),
                "profile_urls": profile_urls,
                "profile_url_count": len(profile_urls),
                "source_entity_delta_ids": source_delta_ids,
                "source_entity_delta_count": len(source_delta_ids),
                "operation_run_id": str(operation_run.get("operation_run_id") or ""),
                "action_id": str(action.get("action_id") or ""),
                "workspace_id": workspace_id,
                "source": "operation_run_dispatch",
                "legacy_job_shell_created": False,
                "queue_workflow_called": False,
                "projection_write_owner": PROJECTION_PROFILE_ADMISSION_APPLY_OWNER,
                "migration_phase": "W11g_operation_native_projection_admission",
                "produced_entity_counts": {"profile_url": max(len(profile_urls), len(source_delta_ids))},
            }
            return {
                "status": "ok",
                "command_type": command_type,
                "owner": owner,
                "workflow_run_id": workflow_run_id,
                "command_payload": command_payload,
                "max_attempts": max(1, _coerce_int(input_payload.get("max_attempts"), 3)),
                "retry_policy": {"kind": "operation_native_projection_admission", "retry_delay_seconds": 30},
            }
        if command_type == LINKEDIN_PROFILE_TERMINAL_ADMIT_COMMAND_TYPE:
            activity_run_id = str(
                input_payload.get("source_profile_activity_run_id")
                or target_ref.get("source_profile_activity_run_id")
                or explicit_command_payload.get("source_profile_activity_run_id")
                or input_payload.get("activity_run_id")
                or target_ref.get("activity_run_id")
                or explicit_command_payload.get("activity_run_id")
                or ""
            ).strip()
            source_delta_ids = _dedupe_texts(
                input_payload.get("source_entity_delta_ids")
                or target_ref.get("source_entity_delta_ids")
                or explicit_command_payload.get("source_entity_delta_ids")
                or []
            )
            if activity_run_id and not source_delta_ids:
                delta_rows = self.store.list_workflow_entity_deltas(
                    activity_run_id=activity_run_id,
                    entity_type="profile",
                    statuses=["recorded"],
                    limit=max(1, min(500, _coerce_int(input_payload.get("limit"), 100))),
                )
                source_delta_ids = _dedupe_texts(
                    [
                        str(delta.get("delta_id") or "").strip()
                        for delta in delta_rows
                        if str(delta.get("delta_kind") or "") in {"profile_cache_hit", "profile_provider_fetched"}
                    ]
                )
            activity = self.store.get_workflow_activity_run(activity_run_id) if activity_run_id else {}
            acquisition_run_id = str(
                input_payload.get("acquisition_run_id")
                or target_ref.get("acquisition_run_id")
                or explicit_command_payload.get("acquisition_run_id")
                or activity.get("acquisition_run_id")
                or ""
            ).strip()
            acquisition_run = self.store.get_acquisition_run(acquisition_run_id) if acquisition_run_id else {}
            workflow_run_id = (
                workflow_run_id
                or str(activity.get("workflow_run_id") or "").strip()
                or str(acquisition_run.get("workflow_run_id") or "").strip()
            )
            profile_urls = _dedupe_texts(
                input_payload.get("profile_urls")
                or target_ref.get("profile_urls")
                or explicit_command_payload.get("profile_urls")
                or []
            )
            if source_delta_ids and not profile_urls:
                source_deltas = [
                    self.store.get_workflow_entity_delta(delta_id)
                    for delta_id in source_delta_ids
                    if str(delta_id or "").strip()
                ]
