    def get_target_candidate_profile(self, record_id: str) -> dict[str, Any]:
        normalized_record_id = str(record_id or "").strip()
        if not normalized_record_id:
            return {"status": "invalid", "reason": "record_id is required"}
        record = self.store.get_target_candidate(normalized_record_id)
        if record is None:
            return {
                "status": "not_found",
                "reason": "target_candidate_not_found",
                "record_id": normalized_record_id,
            }
        public_web_detail = self.get_target_candidate_public_web_search_detail(normalized_record_id)
        if public_web_detail.get("status") != "ok":
            public_web_detail = {
                "status": "not_found",
                "record_id": normalized_record_id,
                "signals": [],
                "email_candidates": [],
                "profile_links": [],
                "evidence_links": [],
                "promotions": [],
                "promotion_summary": {},
                "latest_run": None,
                "person_asset": None,
                "raw_asset_policy": {
                    "raw_assets_included_by_default": False,
                    "default_export_surface": "model_safe_summary_signals_and_evidence_links",
                },
            }
        profile = _build_target_candidate_profile_composition(
            record=record,
            public_web_detail=dict(public_web_detail),
        )
        return {
            "status": "ok",
            "record_id": normalized_record_id,
            "target_candidate": _public_web_target_candidate_summary(record),
            "profile": profile,
            "public_web_detail": public_web_detail,
            "raw_asset_policy": {
                "raw_assets_included_by_default": False,
                "default_surface": "model_safe_composed_target_candidate_profile",
            },
        }

