    def backfill_company_public_web_assets_to_company_asset_layer_api(self, payload: dict[str, Any]) -> dict[str, Any]:
        normalized = dict(payload or {})
        workspace_id = str(normalized.get("workspace_id") or "default").strip() or "default"
        collection_id = str(normalized.get("collection_id") or normalized.get("collectionId") or "").strip()
        target_company = str(normalized.get("target_company") or normalized.get("company") or "").strip()
        company_key = str(normalized.get("company_key") or normalized.get("companyKey") or "").strip()
        if collection_id and (not target_company or not company_key):
            registry = self._collection_registry_summary(collection_id)
            target_company = target_company or str(registry.get("target_company") or "").strip()
            company_key = company_key or str(registry.get("company_key") or "").strip()
        company_key = company_key or normalize_company_key(target_company)
        limit = min(max(_coerce_int(normalized.get("limit"), 1000), 1), 10_000)
        dry_run = _coerce_bool(normalized.get("dry_run"), True)
        reviewed = _coerce_bool(normalized.get("reviewed"), False)
        if not self.store.control_plane_postgres_is_postgres_only():
            return {
                "status": "failed",
                "reason": "postgres_required_for_company_asset_layer",
                "workspace_id": workspace_id,
                "collection_id": collection_id,
                "target_company": target_company,
                "company_key": company_key,
                "migration_path": True,
                "module_state_mutated": False,
                "read_contract": {
                    "source": "company_public_web_assets",
                    "target": "CompanyAsset+CompanyEvidence",
                    "fallback_used": False,
                    "fail_closed": True,
                    "normal_reader_repair": False,
                },
            }
        source_assets = [
            dict(item or {})
            for item in self.store.list_company_public_web_assets(
                target_company=target_company,
                company_key=company_key,
                limit=limit,
            )
        ]
        eligible_assets = [asset for asset in source_assets if str(asset.get("asset_id") or "").strip()]
        if dry_run:
            source_families = sorted(
                {
                    str(asset.get("source_family") or "").strip()
                    for asset in eligible_assets
                    if str(asset.get("source_family") or "").strip()
                }
            )
            run_ids = _dedupe_texts(
                str(asset.get("latest_run_id") or "").strip()
                for asset in eligible_assets
                if str(asset.get("latest_run_id") or "").strip()
            )
            return {
                "status": "dry_run",
                "reason": "company_public_web_asset_backfill_preview",
                "workspace_id": workspace_id,
                "collection_id": collection_id,
                "target_company": target_company,
                "company_key": company_key,
                "source_asset_count": len(source_assets),
                "eligible_asset_count": len(eligible_assets),
                "source_families": source_families,
                "run_ids": run_ids[:100],
                "limit": limit,
                "migration_path": True,
                "module_state_mutated": False,
                "read_contract": {
                    "source": "company_public_web_assets",
                    "target": "CompanyAsset+CompanyEvidence",
                    "fallback_used": False,
                    "fail_closed": True,
                    "normal_reader_repair": False,
                },
            }
        if not reviewed:
            return {
                "status": "invalid",
                "reason": "operator_review_required",
                "workspace_id": workspace_id,
                "collection_id": collection_id,
                "target_company": target_company,
                "company_key": company_key,
                "migration_path": True,
                "module_state_mutated": False,
                "read_contract": {
                    "source": "company_public_web_assets",
                    "target": "CompanyAsset+CompanyEvidence",
                    "fallback_used": False,
                    "fail_closed": True,
                    "normal_reader_repair": False,
                    "apply_requires_reviewed": True,
                },
            }
        if not eligible_assets:
            return {
                "status": "backfilled",
                "reason": "no_eligible_company_public_web_assets",
                "workspace_id": workspace_id,
                "collection_id": collection_id,
                "target_company": target_company,
                "company_key": company_key,
                "source_asset_count": len(source_assets),
                "eligible_asset_count": 0,
                "synced_asset_count": 0,
                "synced_evidence_count": 0,
                "migration_path": True,
                "module_state_mutated": False,
                "read_contract": {
                    "source": "company_public_web_assets",
                    "target": "CompanyAsset+CompanyEvidence",
                    "fallback_used": False,
                    "fail_closed": True,
                    "normal_reader_repair": False,
                },
            }
        assets_by_run_id: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for asset in eligible_assets:
            run_id = str(asset.get("latest_run_id") or "").strip()
            if not run_id:
                source_run_ids = [str(item or "").strip() for item in list(asset.get("source_run_ids") or [])]
                run_id = next((item for item in source_run_ids if item), "historical-company-public-web-assets")
            assets_by_run_id[run_id].append(asset)
        aggregate = {
            "synced_asset_count": 0,
            "synced_evidence_count": 0,
            "company_asset_ids": [],
            "company_evidence_ids": [],
        }
        results: list[dict[str, Any]] = []
        for run_id, assets in assets_by_run_id.items():
            run = self.store.get_company_public_web_asset_run(run_id=run_id) or {
                "run_id": run_id,
                "workspace_id": workspace_id,
                "target_company": target_company,
                "company_key": company_key,
            }
            result = sync_company_public_web_assets_to_company_asset_layer(
                store=self.store,
                run=run,
                assets=assets,
            )
            results.append(result)
            aggregate["synced_asset_count"] += int(result.get("synced_asset_count") or 0)
            aggregate["synced_evidence_count"] += int(result.get("synced_evidence_count") or 0)
            aggregate["company_asset_ids"].extend(list(result.get("company_asset_ids") or []))
            aggregate["company_evidence_ids"].extend(list(result.get("company_evidence_ids") or []))
        return {
            "status": "backfilled",
            "reason": "company_public_web_assets_backfilled_to_company_asset_layer",
            "workspace_id": workspace_id,
            "collection_id": collection_id,
            "target_company": target_company,
            "company_key": company_key,
            "source_asset_count": len(source_assets),
            "eligible_asset_count": len(eligible_assets),
            "run_count": len(assets_by_run_id),
            "synced_asset_count": aggregate["synced_asset_count"],
            "synced_evidence_count": aggregate["synced_evidence_count"],
            "company_asset_ids": aggregate["company_asset_ids"][:500],
            "company_evidence_ids": aggregate["company_evidence_ids"][:500],
            "results": results[:50],
            "migration_path": True,
            "module_state_mutated": True,
            "read_contract": {
                "source": "company_public_web_assets",
                "target": "CompanyAsset+CompanyEvidence",
                "fallback_used": False,
                "fail_closed": True,
                "normal_reader_repair": False,
            },
        }

