    def _get_crm_record_profile_from_owner(self, crm_record_id: str) -> dict[str, Any]:
        normalized_record_id = str(crm_record_id or "").strip()
        if not normalized_record_id:
            return {"status": "invalid", "reason": "crm_record_id is required"}
        crm_record = self.store.get_crm_record(normalized_record_id)
        if not crm_record:
            return {
                "status": "not_found",
                "reason": "crm_record_not_found",
                "record_id": normalized_record_id,
                "crm_record_id": normalized_record_id,
            }
        record = self._public_crm_record_payload(crm_record)
        public_web_detail = self._get_crm_record_public_web_search_detail_from_owner(normalized_record_id)
        if public_web_detail.get("status") != "ok":
            public_web_detail = {
                "status": "not_found",
                "record_id": normalized_record_id,
                "crm_record_id": normalized_record_id,
                "signals": [],
                "email_candidates": [],
                "profile_links": [],
                "evidence_links": [],
                "promotions": [],
                "promotion_summary": {},
                "latest_run": None,
                "person_asset": None,
                "raw_asset_policy": {
                    "raw_assets_included_by_default": False,
                    "default_export_surface": "model_safe_summary_signals_and_evidence_links",
                },
            }
        profile = _build_target_candidate_profile_composition(
            record=record,
            public_web_detail=dict(public_web_detail),
        )
        return {
            "status": "ok",
            "record_id": normalized_record_id,
            "crm_record_id": normalized_record_id,
            "target_candidate": _public_web_target_candidate_summary(record),
            "crm_record": record,
            "profile": profile,
            "public_web_detail": public_web_detail,
            "raw_asset_policy": {
                "raw_assets_included_by_default": False,
                "default_surface": "model_safe_composed_crm_record_profile",
            },
        }

