def _compact_public_runtime_diagnostic_payload(value: dict[str, Any]) -> dict[str, Any]:
    source = dict(value or {})
    compacted = _compact_public_progress_dict(source)
    scalar_allowlist = {
        "activity_attempt_id",
        "applied_at",
        "batch_id",
        "candidate_count",
        "claimed_at",
        "collection_id",
        "command_id",
        "command_type",
        "completed_at",
        "completion_policy",
        "cumulative_candidate_count",
        "display_ready_candidate_count",
        "elapsed_ms",
        "error",
        "explicit_profile_capture_candidate_count",
        "finished_at",
        "idempotency_key",
        "item_id",
        "job_id",
        "lane_id",
        "low_profile_richness_candidate_count",
        "needs_profile_completion_candidate_count",
        "operation_id",
        "overlay_fallback_reason",
        "overlay_fast_path_eligible",
        "overlay_fast_path_used",
        "overlay_write_mode",
        "owner",
        "phase",
        "preview_candidate_count",
        "profile_detail_candidate_count",
        "projection_id",
        "published_at",
        "quality_fields_available",
        "recovery_kind",
        "reason",
        "sequence_index",
        "snapshot_id",
        "source",
        "source_kind",
        "stage_key",
        "started_at",
        "status",
        "target_company",
        "updated_at",
        "worker_kind",
        "workflow_run_id",
    }
    list_count_key_map = {
        "candidate_ids": "candidate_id_count",
        "cumulative_candidate_ids": "cumulative_candidate_id_count",
        "delta_candidate_ids": "delta_candidate_id_count",
        "failed_candidate_ids": "failed_candidate_id_count",
        "patch_candidate_ids": "patch_candidate_id_count",
        "profile_urls": "profile_url_count",
        "requested_urls": "requested_url_count",
    }
    small_list_allowlist = {"source_worker_ids", "worker_ids", "target_worker_ids"}
    for key in sorted(scalar_allowlist):
        value_for_key = source.get(key)
        if value_for_key not in (None, "", [], {}):
            compacted[key] = _compact_public_workflow_leaf(value_for_key)
    for key in sorted(small_list_allowlist):
        raw_value = source.get(key)
        if isinstance(raw_value, list):
            compacted[key] = _compact_public_small_scalar_list(raw_value)
            compacted[f"{key[:-1]}_count"] = len(raw_value)
    for key, count_key in list_count_key_map.items():
        raw_value = source.get(key)
        if isinstance(raw_value, list):
            compacted[count_key] = len(raw_value)
    metadata = dict(source.get("metadata") or {})
    contract = dict(
        source.get("legacy_materialization_write_contract")
        or metadata.get("legacy_materialization_write_contract")
        or {}
    )
    if contract:
        compacted_contract = {
            key: _compact_public_workflow_leaf(value_for_key)
            for key, value_for_key in contract.items()
            if value_for_key not in (None, "", [], {})
        }
        if "legacy_materialization_write_contract" in source:
            compacted["legacy_materialization_write_contract"] = compacted_contract
        else:
            compacted_metadata = dict(compacted.get("metadata") or {})
            compacted_metadata["legacy_materialization_write_contract"] = compacted_contract
            compacted["metadata"] = compacted_metadata
    return compacted


def _compact_public_card_materialization_summary(value: dict[str, Any] | None) -> dict[str, Any]:
    source = dict(value or {})
    keys = {
        "candidate_count",
        "display_ready_candidate_count",
        "explicit_profile_capture_candidate_count",
        "low_profile_richness_candidate_count",
        "needs_profile_completion_candidate_count",
        "preview_candidate_count",
        "profile_detail_candidate_count",
        "quality_fields_available",
    }
    return {
        key: _compact_public_workflow_leaf(source.get(key))
        for key in sorted(keys)
        if source.get(key) not in (None, "", [], {})
    }


def _compact_public_board_visible_patch_metadata(metadata: dict[str, Any] | None) -> dict[str, Any]:
    source = dict(metadata or {})
    compacted: dict[str, Any] = {}
    card_summary = _compact_public_card_materialization_summary(
        dict(source.get("card_materialization_summary") or {})
    )
    if card_summary:
        compacted["card_materialization_summary"] = card_summary
    for key in (
        "partial_board_visible_patch",
        "result_view_metadata_mirror",
        "asset_population_patch",
    ):
        raw_value = source.get(key)
        if not isinstance(raw_value, dict):
            continue
        nested = _compact_public_runtime_diagnostic_payload(raw_value)
        nested_card_summary = _compact_public_card_materialization_summary(
            dict(raw_value.get("card_materialization_summary") or {})
        )
        if nested_card_summary:
            nested["card_materialization_summary"] = nested_card_summary
        if nested:
            compacted[key] = nested
    contract = dict(source.get("legacy_materialization_write_contract") or {})
    if contract:
        compacted["legacy_materialization_write_contract"] = {
            key: _compact_public_workflow_leaf(value)
            for key, value in contract.items()
            if value not in (None, "", [], {})
        }
    return compacted


