def _has_non_empty_value(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _has_non_empty_list(value: Any) -> bool:
    return isinstance(value, list) and any(str(item or "").strip() for item in value)


def _has_non_empty_dict(value: Any) -> bool:
    return isinstance(value, dict) and bool(value)


def _merge_unique_string_values(*sources: Any) -> list[str]:
    merged: list[str] = []
    seen: set[str] = set()
    for source in sources:
        if isinstance(source, str):
            items = [source]
        else:
            items = list(source or [])
        for item in items:
            value = " ".join(str(item or "").split()).strip()
            if not value:
                continue
            key = value.lower()
            if key in seen:
                continue
            seen.add(key)
            merged.append(value)
    return merged


def _merge_unique_request_string_values(*sources: Any, target_company: str = "") -> list[str]:
    return _shared_merge_unique_request_string_values(*sources, target_company=target_company)


def _build_request_preview_payload(
    *,
    request: JobRequest | dict[str, Any],
    effective_request: JobRequest | dict[str, Any] | None = None,
) -> dict[str, Any]:
    return _shared_build_request_preview_payload(request=request, effective_request=effective_request)


def _load_job_request_preview(job: dict[str, Any]) -> dict[str, Any]:
    execution_bundle = dict(job.get("execution_bundle") or {})
    bundle_preview = dict(execution_bundle.get("request_preview") or {})
    if bundle_preview:
        return bundle_preview
    artifact_path = str(job.get("artifact_path") or "").strip()
    if artifact_path:
        artifact_payload = _read_json_dict(Path(artifact_path))
        preview = dict(artifact_payload.get("request_preview") or {})
        if preview:
            return preview
        request_payload = dict(artifact_payload.get("request") or {})
        effective_request_payload = dict(artifact_payload.get("effective_request") or {})
        if request_payload:
            return _build_request_preview_payload(
                request=request_payload,
                effective_request=effective_request_payload or request_payload,
            )
    request_payload = dict(execution_bundle.get("request") or job.get("request") or {})
    if not request_payload:
        return {}
    effective_request_payload = dict(execution_bundle.get("effective_request") or {})
    if effective_request_payload:
        return _build_request_preview_payload(
            request=request_payload,
            effective_request=effective_request_payload,
        )
    plan_payload = dict(job.get("plan") or {})
    if plan_payload:
        try:
            plan = hydrate_sourcing_plan(plan_payload)
        except Exception:
            plan = None
        if plan is not None:
            request = JobRequest.from_payload(request_payload)
            return _build_request_preview_payload(
                request=request,
                effective_request=_build_effective_retrieval_request(request, plan),
            )
    return _build_request_preview_payload(request=request_payload)


def _compact_crm_overlay_summary(record: dict[str, Any]) -> dict[str, Any]:
    if not record:
        return {
            "in_crm": False,
            "stage": "",
            "owner_user_id": "",
            "crm_record_id": "",
            "last_event_at": "",
        }
    metadata = dict(record.get("metadata") or {})
    return {
        "in_crm": True,
        "crm_record_id": str(record.get("crm_record_id") or "").strip(),
        "person_identity_key": str(record.get("person_identity_key") or "").strip(),
        "lifecycle_status": str(record.get("lifecycle_status") or "").strip(),
        "visibility_status": str(record.get("visibility_status") or "").strip(),
        "owner_user_id": str(record.get("owner_user_id") or "").strip(),
        "stage": str(metadata.get("current_stage") or "").strip(),
        "source_projection_id": str(record.get("source_projection_id") or "").strip(),
        "updated_at": str(record.get("updated_at") or "").strip(),
    }


def _crm_stage_to_target_follow_up_status(stage: str) -> str:
    normalized = str(stage or "").strip().lower()
    if normalized == "contacted_waiting":
        return "contacted_waiting"
    if normalized == "interview_completed":
        return "interview_completed"
    if normalized == "accepted":
        return "accepted"
    if normalized == "rejected":
        return "rejected"
    return "pending_outreach"


def _select_primary_email_assertion(assertions: list[dict[str, Any]]) -> dict[str, Any]:
    if not assertions:
        return {}
    authority_rank = {
        "operator_confirmed": 0,
        "human_promoted": 0,
        "legacy_migrated": 1,
        "llm_reviewed": 2,
        "provider_observed": 3,
    }
    status_rank = {
        "active": 0,
        "verified": 0,
        "needs_review": 1,
        "llm_reviewed_not_human_promoted": 2,
    }

    def sort_key(assertion: dict[str, Any]) -> tuple[int, int, str]:
        return (
            status_rank.get(str(assertion.get("verification_status") or "").strip(), 9),
            authority_rank.get(str(assertion.get("authority") or "").strip(), 9),
            str(assertion.get("updated_at") or assertion.get("created_at") or ""),
        )

    candidates = [
        assertion
        for assertion in assertions
        if "@" in str(assertion.get("value") or assertion.get("normalized_value") or "")
        and str(assertion.get("verification_status") or "").strip() not in {"rejected", "suppressed", "inactive"}
    ]
    if not candidates:
        return {}
    return sorted(candidates, key=sort_key)[0]


