_PROJECTION_EXPORT_ASSERTION_TYPES = {
    "primary_email",
    "homepage_url",
    "github_url",
    "x_url",
    "substack_url",
    "scholar_url",
}


def _projection_export_assertion_values(
    assertions: list[dict[str, Any]],
    *,
    include_unconfirmed: bool = False,
) -> tuple[dict[str, str], list[dict[str, Any]], list[dict[str, Any]]]:
    values: dict[str, str] = {}
    provenance: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for assertion in assertions:
        assertion_type = str(assertion.get("assertion_type") or "").strip()
        if assertion_type not in _PROJECTION_EXPORT_ASSERTION_TYPES:
            continue
        value = str(assertion.get("value") or assertion.get("normalized_value") or "").strip()
        if not value:
            skipped.append(
                {
                    "assertion_id": str(assertion.get("assertion_id") or ""),
                    "assertion_type": assertion_type,
                    "reason": "empty_assertion_value",
                }
            )
            continue
        authority = str(assertion.get("authority") or "").strip()
        verification_status = str(assertion.get("verification_status") or "").strip()
        default_exportable = authority == "operator_confirmed" and verification_status == "active"
        optional_exportable = (
            include_unconfirmed
            and authority in {"agent_suggested", "provider_observed", "legacy_migrated"}
            and verification_status in {"needs_review", "active"}
        )
        if not default_exportable and not optional_exportable:
            skipped.append(
                {
                    "assertion_id": str(assertion.get("assertion_id") or ""),
                    "assertion_type": assertion_type,
                    "authority": authority,
                    "verification_status": verification_status,
                    "reason": "assertion_not_exportable_by_policy",
                }
            )
            continue
        values.setdefault(assertion_type, value)
        provenance.append(
            {
                "assertion_id": str(assertion.get("assertion_id") or ""),
                "assertion_type": assertion_type,
                "authority": authority,
                "verification_status": verification_status,
                "source_evidence_id": str(assertion.get("source_evidence_id") or ""),
                "source_crm_event_id": str(assertion.get("source_crm_event_id") or ""),
                "source_run_id": str(assertion.get("source_run_id") or ""),
                "confidence_score": assertion.get("confidence_score"),
                "export_surface": "default" if default_exportable else "optional_llm_reviewed",
            }
        )
    return values, provenance, skipped


def _build_target_candidate_profile_composition(
    *,
    record: dict[str, Any],
    public_web_detail: dict[str, Any],
) -> dict[str, Any]:
    email_candidates = [
        dict(item) for item in list(public_web_detail.get("email_candidates") or []) if isinstance(item, dict)
    ]
    profile_links = [
        dict(item) for item in list(public_web_detail.get("profile_links") or []) if isinstance(item, dict)
    ]
    evidence_links = [
        dict(item) for item in list(public_web_detail.get("evidence_links") or []) if isinstance(item, dict)
    ]
    promotions = [
        dict(item) for item in list(public_web_detail.get("promotions") or []) if isinstance(item, dict)
    ]
    latest_run = dict(public_web_detail.get("latest_run") or {})
    primary_email = str(record.get("primary_email") or "").strip()
    promoted_email = _target_candidate_profile_promoted_email(email_candidates)
    best_public_web_email = _target_candidate_profile_best_email(email_candidates)
    selected_email = primary_email or promoted_email or str(best_public_web_email.get("normalized_value") or best_public_web_email.get("value") or "")
    clean_profile_links = [
        signal
        for signal in profile_links
        if bool(signal.get("clean_profile_link")) and bool(signal.get("publishable"))
    ]
    promoted_profile_links = [
        signal for signal in profile_links if str(signal.get("promotion_status") or "") == "manually_promoted"
    ]
    public_web_status = str(latest_run.get("status") or public_web_detail.get("status") or "not_started").strip()
    manually_promoted_export_signals = [
        signal
        for signal in [*email_candidates, *profile_links]
        if str(signal.get("promotion_status") or "") == "manually_promoted"
    ]
    ai_publishable_unconfirmed_signals = [
        signal
        for signal in [*email_candidates, *profile_links]
        if str(signal.get("promotion_status") or "") != "manually_promoted"
        and not _public_web_signal_is_rejected(signal)
        and bool(signal.get("publishable"))
        and not str(signal.get("suppression_reason") or "").strip()
    ]
    default_export_signal_count = len(manually_promoted_export_signals)
    explicit_ai_publishable_signal_count = len(ai_publishable_unconfirmed_signals)
    contact_methods = []
    if selected_email:
        contact_methods.append(
            {
                "kind": "email",
                "value": selected_email,
                "status": "primary" if primary_email else ("manually_promoted" if promoted_email else "public_web_candidate"),
                "source": "target_candidate_primary_email" if primary_email else "public_web_search",
            }
        )
    if str(record.get("linkedin_url") or "").strip():
        contact_methods.append(
            {
                "kind": "linkedin",
                "value": str(record.get("linkedin_url") or "").strip(),
                "status": "profile_url",
                "source": "target_candidate_record",
            }
        )
    for signal in promoted_profile_links[:5]:
        url = str(signal.get("url") or signal.get("normalized_value") or signal.get("value") or "").strip()
        if not url:
            continue
        contact_methods.append(
            {
                "kind": str(signal.get("signal_type") or "profile_link"),
                "value": url,
                "status": "manually_promoted",
                "source": "public_web_search",
            }
        )
    completeness_score = 0
    completeness_reasons: list[str] = []
    for condition, reason, points in (
        (bool(str(record.get("candidate_name") or "").strip()), "identity", 15),
        (bool(str(record.get("headline") or "").strip()), "headline", 10),
        (bool(str(record.get("current_company") or "").strip()), "company", 10),
        (bool(str(record.get("linkedin_url") or "").strip()), "linkedin", 15),
        (bool(selected_email), "contact_email", 20),
        (bool(clean_profile_links or promoted_profile_links), "public_profile_links", 15),
        (bool(evidence_links), "public_evidence", 15),
    ):
        if condition:
            completeness_score += points
            completeness_reasons.append(reason)
    review_flags: list[str] = []
    if public_web_status in {"completed_with_errors", "needs_review", "failed", "cancelled"}:
        review_flags.append(f"public_web_{public_web_status}")
    if email_candidates and not (primary_email or promoted_email):
        review_flags.append("email_candidates_need_review")
    if any(not bool(signal.get("clean_profile_link", True)) for signal in profile_links):
        review_flags.append("profile_link_shape_review")
    export_ready = default_export_signal_count > 0 or bool(primary_email)
    return {
        "schema_version": 1,
        "identity": {
            "record_id": str(record.get("id") or record.get("record_id") or ""),
            "candidate_id": str(record.get("candidate_id") or ""),
            "candidate_name": str(record.get("candidate_name") or ""),
            "headline": str(record.get("headline") or ""),
            "current_company": str(record.get("current_company") or ""),
            "linkedin_url": str(record.get("linkedin_url") or ""),
        },
        "contact": {
            "primary_email": primary_email,
            "selected_email": selected_email,
            "selected_email_source": "target_candidate_primary_email"
            if primary_email
            else ("manual_public_web_promotion" if promoted_email else ("public_web_candidate" if selected_email else "")),
            "method_count": len(contact_methods),
            "methods": contact_methods,
        },
        "public_web": {
            "status": public_web_status,
            "latest_run_id": str(latest_run.get("run_id") or ""),
            "email_candidate_count": len(email_candidates),
            "profile_link_count": len(profile_links),
            "clean_profile_link_count": len(clean_profile_links),
            "evidence_link_count": len(evidence_links),
            "promotion_count": len(promotions),
            "promoted_signal_count": len(
                [item for item in [*email_candidates, *profile_links] if str(item.get("promotion_status") or "") == "manually_promoted"]
            ),
        },
        "review": {
            "follow_up_status": str(record.get("follow_up_status") or "pending_outreach"),
            "quality_score": record.get("quality_score"),
            "comment": str(record.get("comment") or ""),
            "flags": review_flags,
            "needs_review": bool(review_flags),
        },
        "export_readiness": {
            "ready": export_ready,
            "exportable_signal_count": default_export_signal_count,
            "promoted_exportable_signal_count": default_export_signal_count,
            "ai_publishable_unconfirmed_signal_count": explicit_ai_publishable_signal_count,
            "reason": "ready" if export_ready else "no_primary_email_or_exportable_public_web_signal",
            "default_public_web_export_mode": "promoted_only",
            "expanded_public_web_export_mode": "promoted_and_publishable",
        },
        "completeness": {
            "score": min(completeness_score, 100),
            "reasons": completeness_reasons,
        },
        "evidence_sources": evidence_links[:20],
        "raw_asset_policy": {
            "raw_assets_included_by_default": False,
            "default_surface": "model_safe_composed_target_candidate_profile",
        },
    }


def _target_candidate_profile_promoted_email(email_candidates: list[dict[str, Any]]) -> str:
    for signal in email_candidates:
        if str(signal.get("promotion_status") or "") != "manually_promoted":
            continue
        value = str(signal.get("promoted_value") or signal.get("normalized_value") or signal.get("value") or "").strip()
        if value:
            return value
    return ""


def _target_candidate_profile_best_email(email_candidates: list[dict[str, Any]]) -> dict[str, Any]:
    candidates = [
        signal
        for signal in email_candidates
        if bool(signal.get("publishable")) and not str(signal.get("suppression_reason") or "").strip()
    ]
    candidates.sort(
        key=lambda item: (
            _coerce_public_web_float(item.get("confidence_score")),
            _coerce_public_web_float(item.get("identity_match_score")),
        ),
        reverse=True,
    )
    return candidates[0] if candidates else {}


def _build_csv_bytes(rows: list[dict[str, str]], fieldnames: list[str]) -> bytes:
    output = io.StringIO(newline="")
    writer = csv.DictWriter(output, fieldnames=fieldnames)
    writer.writeheader()
    for row in rows:
        writer.writerow({field_name: str(row.get(field_name) or "") for field_name in fieldnames})
    return output.getvalue().encode("utf-8-sig")


def _remote_event_followup_enabled_lanes(payload: dict[str, Any]) -> set[str]:
    raw = dict(payload or {}).get("remote_event_followup_lanes")
    if raw is None:
        raw = os.getenv("WORKFLOW_REMOTE_EVENT_FOLLOWUP_LANES", "")
    if isinstance(raw, (list, tuple, set)):
        lanes = {str(item or "").strip() for item in raw if str(item or "").strip()}
    else:
        lanes = {item.strip() for item in str(raw or "").replace(";", ",").split(",") if item.strip()}
    return lanes or set(DEFAULT_REMOTE_EVENT_FOLLOWUP_LANES)


def _env_bool(name: str, default: bool) -> bool:
    raw = str(os.getenv(name) or "").strip().lower()
    if not raw:
        return default
    if raw in {"1", "true", "yes", "on"}:
        return True
    if raw in {"0", "false", "no", "off"}:
        return False
    return default


