def _legacy_materialization_adapter_enabled_for_payload(payload: dict[str, Any] | None) -> bool:
    """Return true only for explicit historical migration conversion.

    After W6 signoff, normal recovery must not scan `job_materialization_items`
    as a default source of work. Operators/tests that intentionally lift
    historical rows can opt in through the payload or the explicit env flag.
    """

    payload = dict(payload or {})
    if "legacy_materialization_adapter_enabled" in payload:
        return _coerce_bool(payload.get("legacy_materialization_adapter_enabled"), False)
    return _env_bool("LEGACY_JOB_MATERIALIZATION_ADAPTER_ENABLED", False)


