def _coerce_bool(value: Any, default: bool) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    raw = str(value).strip().lower()
    if not raw:
        return default
    if raw in {"1", "true", "yes", "on"}:
        return True
    if raw in {"0", "false", "no", "off"}:
        return False
    return bool(value)


def _coerce_int(value: Any, default: int) -> int:
    if value is None:
        return default
    if isinstance(value, bool):
        return int(value)
    raw = str(value).strip()
    if not raw:
        return default
    try:
        return int(raw)
    except (TypeError, ValueError):
        return default


def _env_int(name: str, default: int) -> int:
    raw = str(os.getenv(name) or "").strip()
    if not raw:
        return default
    try:
        return int(raw)
    except ValueError:
        return default


def _env_optional_int(name: str) -> int | None:
    raw = str(os.getenv(name) or "").strip()
    if not raw:
        return None
    try:
        return int(raw)
    except ValueError:
        return None


def _env_float(name: str, default: float) -> float:
    raw = str(os.getenv(name) or "").strip()
    if not raw:
        return default
    try:
        return float(raw)
    except ValueError:
        return default


def _has_manual_review_resolution_payload(payload: dict[str, Any]) -> bool:
    if not isinstance(payload, dict):
        return False
    if payload.get("apply_resolution") is True:
        return True
    for key in ["source_links", "links", "candidate_patch", "candidate"]:
        value = payload.get(key)
        if isinstance(value, dict) and value:
            return True
        if isinstance(value, list) and value:
            return True
    for key in ["candidate_id", "candidate_name"]:
        value = payload.get(key)
        if isinstance(value, str) and value.strip():
            return True
    return False


def _display_name_from_collection_id(collection_id: str) -> str:
    normalized = str(collection_id or "").strip()
    if not normalized:
        return ""
    slug = normalized.split(":", 1)[1] if ":" in normalized else normalized
    words = [part for part in re.split(r"[-_\s]+", slug) if part]
    if not words:
        return slug
    return " ".join(part[:1].upper() + part[1:] for part in words)


def _collection_initials(name: str) -> str:
    normalized = str(name or "").strip()
    tokens = [part for part in re.split(r"[^A-Za-z0-9\u4e00-\u9fa5]+", normalized) if part]
    if len(tokens) >= 2:
        return f"{tokens[0][:1]}{tokens[1][:1]}".upper()
    if tokens:
        return tokens[0][:2].upper()
    return "??"


def _candidate_avatar_media_source_url(public_summary: dict[str, Any], metadata: dict[str, Any]) -> str:
    payload = dict(public_summary or {})
    payload_metadata = {
        **dict(payload.get("metadata") or {}),
        **dict(metadata or {}),
    }
    for source in (payload, payload_metadata):
        for field_name in ("avatar_url", "photo_url", "media_url", "profile_photo_url", "avatarUrl"):
            value = str(dict(source).get(field_name) or "").strip()
            if value.startswith(("http://", "https://", "file://")):
                return value
    return ""


def _media_source_url_allowed(value: str) -> bool:
    normalized = str(value or "").strip()
    return normalized.startswith(("http://", "https://", "file://"))


def _coerce_string_list(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, (list, tuple, set)):
        raw_values = [str(item or "") for item in value]
    else:
        raw_values = str(value or "").replace(";", ",").split(",")
    return [item.strip() for item in raw_values if item.strip()]


def _company_logo_media_asset_is_stable(asset: dict[str, Any]) -> bool:
    payload = dict(asset or {})
    if str(payload.get("asset_type") or "").strip() != "logo_media":
        return False
    metadata = dict(payload.get("metadata") or {})
    content_ref = str(payload.get("content_ref") or "").strip()
    return bool(str(metadata.get("object_key") or "").strip() or content_ref.startswith(("file://", "/api/media/assets/")))


def _company_logo_experience_candidates_from_profile_payload(
    profile_payload: Any,
    *,
    company_key: str,
    target_company: str,
    now_epoch: int,
    min_ttl_seconds: int,
    limit: int,
) -> list[dict[str, Any]]:
    target_key = normalize_company_key(target_company) or normalize_company_key(company_key)
    normalized_company_key = normalize_company_key(company_key) or target_key
    candidates: list[dict[str, Any]] = []
    seen: set[str] = set()
    for node in _walk_dicts(profile_payload):
        logo_payload = node.get("companyLogo") or node.get("company_logo") or node.get("logo")
        if not isinstance(logo_payload, dict):
            continue
        company_name = _company_name_from_experience_node(node)
        if not _company_experience_name_matches(
            company_name,
            company_key=normalized_company_key,
            target_company_key=target_key,
        ):
            continue
        logo_candidates = _logo_urls_from_company_logo_payload(logo_payload)
        for logo_candidate in logo_candidates:
            source_url = str(logo_candidate.get("source_url") or "").strip()
            if not source_url or source_url in seen:
                continue
            seen.add(source_url)
            expiry_epoch = _company_logo_url_expiry_epoch(
                source_url,
                explicit_expires_at=logo_candidate.get("expires_at"),
            )
            rejection_reason = ""
            if not _media_source_url_allowed(source_url):
                rejection_reason = "unsupported_source_url"
            elif expiry_epoch is not None and expiry_epoch <= int(now_epoch or 0) + int(min_ttl_seconds or 0):
                rejection_reason = "expired_or_insufficient_ttl"
            candidates.append(
                {
                    "source_url": source_url,
                    "company_name": company_name,
                    "logo_kind": str(logo_candidate.get("logo_kind") or "").strip(),
                    "expires_at_epoch": expiry_epoch,
                    "expires_at": str(logo_candidate.get("expires_at") or ""),
                    "eligible": not bool(rejection_reason),
                    "rejection_reason": rejection_reason,
                    "evidence_excerpt": json.dumps(
                        {
                            "company_name": company_name,
                            "source": "profile_experience.companyLogo",
                            "logo_kind": str(logo_candidate.get("logo_kind") or "").strip(),
                        },
                        ensure_ascii=False,
                        sort_keys=True,
                    ),
                }
            )
            if len(candidates) >= max(1, int(limit or 10)):
                return candidates
    return candidates


def _walk_dicts(value: Any) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    stack: list[Any] = [value]
    while stack:
        current = stack.pop()
        if isinstance(current, dict):
            items.append(current)
            stack.extend(current.values())
        elif isinstance(current, list):
            stack.extend(current)
    return items


def _company_name_from_experience_node(node: dict[str, Any]) -> str:
    for field_name in (
        "companyName",
        "company_name",
        "company",
        "organizationName",
        "organization_name",
        "employer",
    ):
        value = node.get(field_name)
        if isinstance(value, dict):
            nested_name = str(value.get("name") or value.get("companyName") or "").strip()
            if nested_name:
                return nested_name
        normalized = str(value or "").strip()
        if normalized:
            return normalized
    return ""


def _company_experience_name_matches(
    company_name: str,
    *,
    company_key: str,
    target_company_key: str,
) -> bool:
    observed_key = normalize_company_key(company_name)
    expected_keys = {normalize_company_key(company_key), normalize_company_key(target_company_key)}
    expected_keys.discard("")
    if not observed_key or not expected_keys:
        return False
    if observed_key in expected_keys:
        return True
    return any(observed_key.startswith(expected_key) or expected_key.startswith(observed_key) for expected_key in expected_keys)


def _logo_urls_from_company_logo_payload(logo_payload: dict[str, Any]) -> list[dict[str, Any]]:
    candidates: list[dict[str, Any]] = []

    def add_candidate(source_url: Any, *, logo_kind: str, expires_at: Any = None) -> None:
        normalized_url = str(source_url or "").strip()
        if not normalized_url:
            return
        candidates.append(
            {
                "source_url": normalized_url,
                "logo_kind": str(logo_kind or "").strip(),
                "expires_at": expires_at,
            }
        )

    add_candidate(
        logo_payload.get("url") or logo_payload.get("source_url") or logo_payload.get("sourceUrl"),
        logo_kind="primary",
        expires_at=logo_payload.get("expiresAt") or logo_payload.get("expires_at") or logo_payload.get("expires"),
    )
    for field_name in ("sizes", "variants", "images"):
        variants = logo_payload.get(field_name)
        if not isinstance(variants, list):
            continue
        for index, variant in enumerate(variants):
            if not isinstance(variant, dict):
                continue
            add_candidate(
                variant.get("url") or variant.get("source_url") or variant.get("sourceUrl"),
                logo_kind=f"{field_name}[{index}]",
                expires_at=variant.get("expiresAt")
                or variant.get("expires_at")
                or variant.get("expires")
                or logo_payload.get("expiresAt")
                or logo_payload.get("expires_at")
                or logo_payload.get("expires"),
            )
    deduped: list[dict[str, Any]] = []
    seen: set[str] = set()
    for candidate in candidates:
        source_url = str(candidate.get("source_url") or "").strip()
        if not source_url or source_url in seen:
            continue
        seen.add(source_url)
        deduped.append(candidate)
    return deduped


def _company_logo_url_expiry_epoch(source_url: str, *, explicit_expires_at: Any = None) -> int | None:
    parsed_explicit = _coerce_expiry_epoch(explicit_expires_at)
    if parsed_explicit is not None:
        return parsed_explicit
    query_values = parse_qs(urlparse(str(source_url or "")).query)
    for field_name in ("e", "expires", "expires_at", "expiresAt"):
        values = query_values.get(field_name) or []
        for value in values:
            parsed = _coerce_expiry_epoch(value)
            if parsed is not None:
                return parsed
    return None


def _coerce_expiry_epoch(value: Any) -> int | None:
    if value is None:
        return None
    if isinstance(value, str) and not value.strip():
        return None
    if isinstance(value, (int, float)):
        number = int(value)
    else:
        text = str(value or "").strip()
        if not text:
            return None
        if text.isdigit():
            number = int(text)
        else:
            try:
                return int(datetime.fromisoformat(text.replace("Z", "+00:00")).timestamp())
            except ValueError:
                return None
    if number > 10_000_000_000:
        return int(number / 1000)
    return number


def _source_domain_from_url(source_url: str) -> str:
    parsed = urlparse(str(source_url or "").strip())
    return str(parsed.netloc or "").lower().removeprefix("www.")


def _profile_payload_profile_url_key(profile_payload: Any) -> str:
    payload = dict(profile_payload or {}) if isinstance(profile_payload, dict) else {}
    item = dict(payload.get("item") or {}) if isinstance(payload.get("item"), dict) else {}
    for source in (item, payload, dict(payload.get("_harvest_request") or {})):
        for field_name in ("linkedinUrl", "linkedin_url", "profileUrl", "profile_url", "url"):
            value = str(dict(source).get(field_name) or "").strip()
            key = normalize_linkedin_profile_url_key(value)
            if key:
                return key
    return ""


def _origin_favicon_url(value: str) -> str:
    normalized = str(value or "").strip()
    if not normalized.startswith(("http://", "https://")):
        return ""
    parsed = urlparse(normalized)
    if not parsed.scheme or not parsed.netloc:
        return ""
    return f"{parsed.scheme}://{parsed.netloc}/favicon.ico"


def _should_use_local_anthropic_assets(request: JobRequest) -> bool:
    execution_preferences = dict(request.execution_preferences or {})
    if bool(execution_preferences.get("allow_local_bootstrap_fallback")):
        return True
    return not bool(execution_preferences.get("force_fresh_run"))
